        public bool ForceClosePurchaseOrder(string PONumber, ref string Message)
        {
            string rMessage = "";
            using (clsLinqDataContext ctx = new clsLinqDataContext())
            {
                ctx.IFSPurchaseOrderForceClose(PONumber, UserName, ref rMessage);
                if (rMessage.Substring(0, 6) == "Error:")
                {
                    Message = "Success";
                    return false;
                }
                Message = "Success";
                return true;
            }
        }
        public bool ForceSetPurchaseOrderLineReceivedCount(string PONumber, string POLineNumber, decimal POLineQty, ref string Message)
        {
            string rMessage = "";
            using (clsLinqDataContext ctx = new clsLinqDataContext())
            {
                ctx.IFSPurchaseOrderForceSetLineQTY(PONumber,POLineNumber,POLineQty, UserName, ref rMessage);
                if (rMessage.Substring(0, 6) == "Error:")
                {
                    Message = "Success";
                    return false;
                }
                Message = "Success";
                return true;
            }
        }
    }

