        public List<GetOrderEntryList_TemplateRawData_SearchGrid_01Result> GetOrderEntryList(string Status, string IFSOrderNumber, string OrderNumber, string CustomerPO, string WayBillNumber, string ProjectTag, string CompanyName,
            string City, string PostalCode, string PhoneNumber, string EmailAddress, string OrderBeginDate, string OrderEndDate)
        {
            string Country = "";
            return GetOrderEntryList(Status, IFSOrderNumber, OrderNumber, CustomerPO, WayBillNumber, ProjectTag, CompanyName,
        City, PostalCode, Country, PhoneNumber, EmailAddress, OrderBeginDate, OrderEndDate);
        }
        public List<GetOrderEntryList_TemplateRawData_SearchGrid_01Result> GetOrderEntryList(string Status, string IFSOrderNumber, string OrderNumber, string CustomerPO, string WayBillNumber, string ProjectTag, string CompanyName,
        string City, string PostalCode, string Country, string PhoneNumber, string EmailAddress, string OrderBeginDate, string OrderEndDate)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                var rd = ctx.GetOrderEntryList_TemplateRawData_SearchGrid_01(Status, IFSOrderNumber, OrderNumber, CustomerPO, WayBillNumber, ProjectTag, CompanyName, City, PostalCode, PhoneNumber, EmailAddress, UserName);
                if (rd != null)
                {
                    DateTime bd = DateTime.Now;
                    DateTime ed = DateTime.Now;
                    if (DateTime.TryParse(OrderBeginDate, out bd) == false || DateTime.TryParse(OrderEndDate, out ed) == false)
                    {
                        return rd.ToList();
                    }
                    ed.AddDays(1);   // advance the end date by one day to include off of yesterday, not just yesterday till default time on date.
                    return rd.Where(x => x.OrderDate >= bd && x.OrderDate < ed).ToList();
                }
            }
            return null;
        }
        public string TrashOrder(decimal OrderHeaderID)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                return TrashOrder(ctx, OrderHeaderID);
            }
        }
        public string TrashOrder(clsLinqDataContext ctx, decimal OrderHeaderID)
        {
            ctx.DeleteSalesOrder(OrderHeaderID, UserName);
            return "Order moved to trash/all devices removed from order";
        }
        public string RecordIFSPickIMEI(decimal OrderHeaderID
                                            , string IFSLocation
                                            , string CartonNumber
                                            , string IMEI, string UserName)
