        public void ApplyReceiveDetail(decimal OrderDetailID, string ESNData)
        {
            if (ESNData.Length == 0) { return; }
            using (clsLinqDataContext ctx = new clsLinqDataContext())
            {
                ApplyReceiveDetail(ctx, OrderDetailID, ESNData);
            }
        }
        public void ApplyReceiveDetail(clsLinqDataContext ctx, decimal OrderDetailID, string ESNData)
        {
            if (ESNData.Length == 0) { return; }
            string[] ESN = ESNData.Split(' ');
            var xesn = ESN.Distinct();
            decimal OrderHeaderID = -1;
            OrderDetail od = ctx.OrderDetails.FirstOrDefault(x => x.OrderDetailID == OrderDetailID);
            if (od != null)
            {
                OrderHeaderID = od.OrderHeaderID;
                foreach (string rawesn in xesn)
                {
                    if (rawesn.Length > 0)
                    {
                        string[] esnraw = rawesn.Split(':');
                        string esn = MaxSize(esnraw[1], 50);
                        string CartonNumber = esnraw[0];
                        OrderDetailReceiveDetail RD = ctx.OrderDetailReceiveDetails.FirstOrDefault(x => x.ESN.Trim() == esn.Trim()
                                                                                                     && x.OrderDetail.OrderHeaderID == OrderHeaderID);
                        if (RD == null)
                        {
                            clsOrderDetailLineReceive ORL = new clsOrderDetailLineReceive();
                            ORL.UserName = UserName;
                            ORL.OrderDetailID = OrderDetailID;
                            ORL.SKU = MaxSize(CartonNumber, 20);
                            ORL.ESN = esn; ORL.Message = "";
                            ORL.ReceiveDetailID = null;
                            ORL.isDirty = true;
                            ORL.Save(ctx);
                        }
                    }
                }
                ctx.SubmitChanges();
            }
        }

