        public string UpdateOrderESNAttribute(clsLinqDataContext ctx, decimal HeaderID, string AttributeName, string Value)
        {
            OrderHeader OH = ctx.OrderHeaders.FirstOrDefault(x => x.OrderHeaderID == HeaderID);
            if (OH != null)
            {
                ReceiveDetailManager dm = new ReceiveDetailManager(UserName);
                clsOrderHeader coh = new clsOrderHeader(UserName);
                var drl = ctx.OrderDetailReceiveDetails.Where(x => x.OrderDetail.OrderHeaderID == OH.OrderHeaderID);
                foreach (OrderDetailReceiveDetail rd in drl)
                {
                    if (rd.ReceiveDetailID != null && rd.ReceiveDetailID > 0)
                    {
                        dm.UpdateESNAttribute((decimal)rd.ReceiveDetailID, AttributeName, Value);
                    }
                }
            }
            JsonString rString = new JsonString("Result", "Not Updated");
            string rstring = "Updated";
            return rstring;
        }

        public string MoveOrder(clsLinqDataContext ctx, string OrderNumber, string MoveTo, string Courier, TimeLogManager Log)
        {
            OrderHeader OH = ctx.OrderHeaders.FirstOrDefault(x => x.OrderNumber == OrderNumber);

            if (OH != null)
            {
                decimal ID = OH.OrderHeaderID;
                string from = OH.OrderStatus.Status;
                OH = null;
                if (from.ToUpper() == "DONE" || from.ToUpper() == "TRASH")
                {
                    return "You are not allowed to return a Sales Order from Done or Trash.";
                }
                else
                {
                    // because i use ctx to get the OH to get the from and id, when I call MoveOrder with the ctx, i get an error.
                    //         If I allow it to use a different ctx, the errors go away.
                    return MoveOrder(ID, MoveTo, from, Courier, Log);
                }
            }
            else
            {
                return "Order Number Not found";
            }
        }



