        public string MoveOrder(clsLinqDataContext ctx, OrderHeader OH, string MoveTo, string MoveFrom, string Courier, TimeLogManager Log)
        {
            bool OKToMove = false;
            string Message = "";

            Log.LogIt("Inside Move to " + MoveTo + " from:" + MoveFrom);

            //OrderHeader OH = ctx.OrderHeaders.FirstOrDefault(x => x.OrderHeaderID == HeaderID);
            if (OH != null)
            {
                Log.LogIt("Move to " + MoveTo + " from:" + MoveFrom);
                #region TRASH
                if (MoveTo.Trim().ToUpper() == "TRASH")
                {
                    OrderManager om = new OrderManager(UserName);
                    return om.TrashOrder(OH.OrderHeaderID);
                }
                #endregion
                decimal MoveToStatusID = 0;
                clsOrderHeader coh = new clsOrderHeader(UserName);
                MoveToStatusID = coh.GetOrderStatusID(ctx, MoveTo);

                OrderMoveLog oml = new OrderMoveLog();
                oml.OrderHeaderID = OH.OrderHeaderID;
                oml.MoveToStatusID = MoveToStatusID;
                oml.CreateDate = DateTime.Now;
                oml.CreateUser = UserName;
                oml.LastUpdateDate = DateTime.Now;
                oml.LastUpdateUser = UserName;

                oml.CustomerPO = OH.CustomerPO;
                oml.MiscDesc = OH.MiscDesc;
                oml.OrderDate = OH.OrderDate;
                oml.OrderNumber = OH.OrderNumber;
                oml.Paid = OH.Paid;
                oml.PickPackDate = OH.PickPackDate;
                oml.PickProjectID = OH.PickProjectID;
                oml.PostPaid = OH.PostPaid;
                oml.ProjectID = OH.ProjectID;
                oml.ShippedDate = OH.ShippedDate;
                oml.StatusID = OH.StatusID;
                oml.WayBillNumber = OH.WayBillNumber;


                ctx.OrderMoveLogs.InsertOnSubmit(oml);
                OH.StatusID = MoveToStatusID;

                #region PICK/SHIP
                if (MoveFrom.ToUpper() == "NEW" && MoveTo.ToUpper() == "PICK/PACK")
                {
                    OKToMove = true;
                }
                if (MoveFrom.ToUpper() == "PICK/PACK" && MoveTo.ToUpper() == "NEW")
                {
                    OKToMove = true;
                }
                if (MoveFrom.ToUpper() == "PICK/PACK" && MoveTo.ToUpper() == "SHIP")
                {
                    Log.LogIt("Inside Pick/Pack");
                    OH.PickPackDate = DateTime.Now;
                    OKToMove = true;
                }
                #endregion
                #region SHIP/Pick
                if (MoveFrom.ToUpper() == "SHIP" && MoveTo.ToUpper() == "PICK/PACK")
                {
                    Log.LogIt("Inside Pick/Pack");
                    //OH.PickPackDate = DateTime.Now;
                    OKToMove = true;
                }
                if (MoveFrom.ToUpper() == "SHIP" && MoveTo.ToUpper() == "INVOICE")
                {
                    Log.LogIt("Inside Ship/Invoice");
                    //OH.PickPackDate = DateTime.Now;
                    OKToMove = true;
                }
                if (MoveFrom.ToUpper() == "SHIP" && MoveTo.ToUpper() == "DONE")
                {
                    Log.LogIt("Inside Ship/Done");
                    //OH.PickPackDate = DateTime.Now;
                    OKToMove = true;
                }
                if (MoveFrom.ToUpper() == "INVOICE" && MoveTo.ToUpper() == "DONE")
                {
                    Log.LogIt("Inside Invoice/Done");
                    //OH.PickPackDate = DateTime.Now;
                    OKToMove = true;
                }
                #endregion

                #region Ship Bill Done
                if ((MoveFrom.Trim().ToUpper() == "INVOICE" || MoveFrom.Trim().ToUpper() == "SHIP") && (MoveTo.Trim().ToUpper() == "BILL" || MoveTo.Trim().ToUpper() == "DONE"))
                {
                    Log.LogIt("Inside Ship/Invoice/Bill/Done");
                    OH.Courier = Courier;
                    OH.ShippedDate = DateTime.Now;
                    // We need to update the data so we can allow the SP to do it's work
                    ctx.SubmitChanges();
                    Log.LogIt("Inside Invoice/Bill/Done -- OH Saved.");
                    if (MoveTo.Trim().ToUpper() == "DONE")
                    {
                        ctx.Update_OrderEntry_Shipped_WithRerun(OH.OrderHeaderID, UserName, 0);
                        //ctx.SubmitChanges();
                        //if (System.Configuration.ConfigurationManager.AppSettings["OrderEntryAutoUpdateDone"].ToUpper() == "TRUE")
                        //{
                        //    Log.LogIt("Starting to run Update_OrderEntry Shipped");
                        //    ctx.CommandTimeout = 480;        // 8 minutes = 8 * 60 = 480 seconds
                        //    ctx.Job_UpdateShippedUnits();
                        //    Log.LogIt("EXEC Job_UpdateShippedUnits");
                        //}
                        //
                    }
                    Log.LogIt("Done run Update_OrderEntry Shipped");
                    //OKToMove = true;
               }
                #endregion

                #region xxx
                //if (MoveFrom.Trim().ToUpper() == "SHIP" && (MoveTo.Trim().ToUpper() == "BILL" || MoveTo.Trim().ToUpper() == "DONE"))
                //{
                //    Log.LogIt("Inside Ship/Bill/Done");
                //    OH.Courier = Courier;
                //    OH.ShippedDate = DateTime.Now;


                //    ClientLocation cl = ctx.ClientLocations.FirstOrDefault(x => x.ClientLocationID == OH.OrderCompanies.FirstOrDefault(y => y.CompanyType.ToUpper() == "CLIENT").ClientLocationID);
                //    ReceiveDetailManager dm = new ReceiveDetailManager(UserName);
                //    //decimal ShippedProcessID = dm.GetProcessidFromName("Shipped");
                //    decimal ShippedProcessID = dm.GetProcessidFromName("Shipping");

                //    // Loop through all the ESN numbers and add to the units processing log.
                //    if (ShippedProcessID > 0)
                //    {
                //        Log.LogIt("Shipped ProcessID = " + ShippedProcessID.ToString());
                //        var drl = ctx.OrderDetailReceiveDetails.Where(x => x.OrderDetail.OrderHeaderID == OH.OrderHeaderID);
                //        foreach (OrderDetailReceiveDetail rd in drl)
                //        {

                //            if (rd.ReceiveDetailID != null && rd.ReceiveDetailID > 0)
                //            {
                //                decimal RDID = (decimal)rd.ReceiveDetailID;
                //                Log.LogIt("Record Shipped Attributes");
                //                ReceiveDetail r = dm.ReceiveDetail(RDID);

                //                SM.OrderShipped(ctx, RDID, -1, r.ClientLocationID, (decimal)r.ProjectID, ShippedProcessID, UserName);
                //                dm.AddDetailProcessLog(ctx, RDID, ShippedProcessID);
                //                dm.AddBillingPoint(ctx, RDID, r.ClientLocationID, (decimal)r.ProjectID, ShippedProcessID);

                //dm.UpdateESNAttribute(ctx, RDID, "Out-Bound Waybill-S", OH.WayBillNumber);
                //dm.UpdateESNAttribute(ctx, RDID, "Shipment Date", string.Format("{0:MM/dd/yyyy}", OH.ShippedDate));
                //dm.UpdateESNAttribute(ctx, RDID, "Carton No", rd.SKU);

                //if (cl != null) { dm.UpdateESNAttribute(ctx, RDID, "ShipTo OE", cl.Client.CompanyName); }

                //dm.UpdateESNAttribute(ctx, RDID, "Courier Out", OH.Courier);
                //dm.UpdateESNAttribute(ctx, RDID, "PO No", OH.CustomerPO);

                //dm.UpdateESNAttribute_Blank(ctx, RDID, "Bin");
                //dm.UpdateESNAttribute(ctx, RDID, "Location", "None");
                //                dm.AdvanceESNVersion_FromThisOne(ctx, RDID);
                //                Log.LogIt("Record Shipped Attributes - bumped ESN Version");
                //            }
                //        }
                //    }
                //}
                #endregion
                if (OKToMove == true)
                {
                    ctx.SubmitChanges();
                    //if (MoveTo.ToUpper() == "DONE" && MoveFrom.ToUpper() == "SHIP")
                    //{
                    //    if (System.Configuration.ConfigurationManager.AppSettings["OrderEntryAutoUpdateDone"].ToUpper() == "TRUE")
                    //    {
                    //        ctx.Job_UpdateShippedUnits();
                    //        Log.LogIt("EXEC Job_UpdateShippedUnits");
                    //    }
                    //}

                    Log.LogIt("Leaving Move Order.");
                    return "";
                }
                else { return "Order not Moved, there were errors:" + Message; }
            }
            return "Unable to find Order";
        }

        private string GetUserIPAddress()
        {
            string ip = System.Web.HttpContext.Current.Request.ServerVariables["HTTP_X_FORWARDED_FOR"];
            if (string.IsNullOrEmpty(ip))
            {
                ip = System.Web.HttpContext.Current.Request.ServerVariables["REMOTE_ADDR"];
            }
            return ip;
        }

        public clsOrderHeader GetNewOrderHeader(int DetailLines)
        {
            clsOrderHeader oh = new clsOrderHeader(UserName);
            for (int i = 0; i < DetailLines; i++)
            {
                clsOrderDetailLine od = new clsOrderDetailLine();
                od.OrderDetailID = (i + 1) * -1;
                od.isNew = true;
                od.isDirty = false;
                od.Desc_Text = "desc" + i.ToString();
                od.Desc_Code = "Code" + i.ToString();
                oh.OrderDetailLine = od;
            }
            return oh;
        }

