        public string[] CodeDetailLine(clsLinqDataContext ctx, string Manufacturer, string Model, string Colour, string Grade, string Carrier)
        {
            string[] rValue = { "", "" };

            StringBuilder sb = new StringBuilder();
            string Code = (from x in ctx.Options where x.Question.Name.ToUpper() == "CARRIER" && x.OptionText.ToUpper() == Carrier.ToUpper() select x.ScanKey).FirstOrDefault();
            if (Code != null && Code.Length > 0) { sb.Append(Code); sb.Append(" "); }
            Code = (from x in ctx.Options where x.Question.Name.ToUpper() == "MANUFACTURER" && x.OptionText.ToUpper() == Manufacturer.ToUpper() select x.ScanKey).FirstOrDefault();
            if (Code != null && Code.Length > 0) { sb.Append(Code); sb.Append(" "); }
            Code = (from x in ctx.Options where x.Question.Name.ToUpper() == "MODEL" && x.OptionText.ToUpper() == Model.ToUpper() select x.ScanKey).FirstOrDefault();
            if (Code != null && Code.Length > 0) { sb.Append(Code); sb.Append(" "); }
            Code = (from x in ctx.Options where x.Question.Name.ToUpper() == "COLOUR" && x.OptionText.ToUpper() == Colour.ToUpper() select x.ScanKey).FirstOrDefault();
            if (Code != null && Code.Length > 0) { sb.Append(Code); sb.Append(" "); }
            Code = (from x in ctx.Options where x.Question.Name.ToUpper() == "GRADE" && x.OptionText.ToUpper() == Grade.ToUpper() select x.ScanKey).FirstOrDefault();
            if (Code != null && Code.Length > 0) { sb.Append(Code); sb.Append(" "); }
            rValue[0] = sb.ToString();

            sb.Clear();
            if (Carrier.Length > 0 && Carrier != "Blank") { sb.Append(Carrier); sb.Append(" "); }
            if (Manufacturer.Length > 0 && Manufacturer != "Blank") { sb.Append(Manufacturer); sb.Append(" "); }
            if (Model.Length > 0 && Model != "Blank") { sb.Append(Model); sb.Append(" "); }
            if (Colour.Length > 0 && Colour != "Blank") { sb.Append(Colour); sb.Append(" "); }
            if (Grade.Length > 0 && Grade != "Blank") { sb.Append(Grade); sb.Append(" "); }
            rValue[1] = sb.ToString();
            return rValue;
        }

        public string CodeDetailLineSKU(clsLinqDataContext ctx, string Manufacturer, string Model, string Colour, string Grade, string Carrier)
        {
            decimal CarrierID = -1;
            decimal ModelID = -1;
            decimal ManufacturerID = -1;
            decimal ColourID = -1;
            CarrierID = (from x in ctx.Options where x.Question.Name.ToUpper() == "CARRIER" && x.OptionText.ToUpper() == Carrier.ToUpper() select x.OptionID).FirstOrDefault();
            ManufacturerID = (from x in ctx.Options where x.Question.Name.ToUpper() == "MANUFACTURER" && x.OptionText.ToUpper() == Manufacturer.ToUpper() select x.OptionID).FirstOrDefault();
            ModelID = (from x in ctx.Options where x.Question.Name.ToUpper() == "MODEL" && x.OptionText.ToUpper() == Model.ToUpper() select x.OptionID).FirstOrDefault();
            ColourID = (from x in ctx.Options where x.Question.Name.ToUpper() == "COLOUR" && x.OptionText.ToUpper() == Colour.ToUpper() select x.OptionID).FirstOrDefault();
            string rValue = ctx.GetSKU(CarrierID, ManufacturerID, ModelID, ColourID);
            return rValue;
        }


