    [DataObject]
    public class IFSLocationQueue
    {
        List<IFSLocation> MasterList = new List<IFSLocation>();
        IFSLocation _LastLocation = null;
        public IFSLocation LastLocation { get { return _LastLocation; } }
        public IFSLocationQueue()
        {
        }

        public IFSLocation GetLocation(string Location)
        {
            if (_LastLocation != null && _LastLocation.Text == Location) { return _LastLocation; }
            _LastLocation = MasterList.FirstOrDefault(x => x.Text == Location);
            if (_LastLocation == null)
            {
                _LastLocation = new IFSLocation(Location);
                MasterList.Add(_LastLocation);
            }
            return _LastLocation;
        }
    }

    [DataObject]
    public class IFSLocation
    {
        MasterIFSLocation LocationRecord = null;
        string _LocationText = "";
        decimal _ID = -1;
        string _Status = "";
        string _FrozenMessage = "";
        decimal _StatusID = -1;
        bool _ISWhip = false;

        IFSLocation _AltIFSLocation = null;
        //bool _isFrozen = false;
        bool _isValid = false;
        //string DeviceRollup = "";
        //string PartRollup = "";
        //IFSLocation AltIFSLocation = null;
        public bool IsWhip { get { return _ISWhip; } }
        public decimal ID { get { return _ID; } }
        public String Text { get { return _LocationText.Trim().ToUpper(); } }
        public string FrozemMessage { get { if (_FrozenMessage.Length > 0) { return _FrozenMessage;} else {return "Location Frozen. Unable to complete at this time.";} } }

        public String DeviceRollup { 
