        public void Freeze(clsLinqDataContext ctx, string UserName)
        {
                MasterIFSLocation L = null;
                L = ctx.MasterIFSLocations.FirstOrDefault(x => x.MasterIFSLocationID == LocationRecord.MasterIFSLocationID);
                L.IsFrozen = true;
                L.LastUpdateUser = UserName;
                L.LastUpdateDate = DateTime.Now; 
                ctx.SubmitChanges();
        }
        public void UnFreeze(clsLinqDataContext ctx, string UserName)
        {
                MasterIFSLocation L = null;
                L = ctx.MasterIFSLocations.FirstOrDefault(x => x.MasterIFSLocationID == LocationRecord.MasterIFSLocationID);
                L.IsFrozen = false;
                L.LastUpdateUser = UserName;
                L.LastUpdateDate = DateTime.Now;
                ctx.SubmitChanges();
        }
        public bool IsThisFrozen(string UserName)
        {
            if (LocationRecord == null) { return true; }

            if (LocationRecord.IsFrozen != null && LocationRecord.IsFrozen == true) { return true; }
            return false;
            //using (clsLinqDataContext ctx = new clsLinqDataContext())
            //{
            //    _FrozenMessage = ctx.IsThisFrozen(-1, ID, -1);
            //    if (_FrozenMessage.Length == 0 || Roles.IsUserInRole(UserName, "ThawFreeze") == true)
            //    {
            //        return false;
            //    }
                 
            //    return true;
            //}
        }
        public void Refresh()
        {
            using (clsLinqDataContext ctx = new clsLinqDataContext())
            {
                LocationRecord = ctx.MasterIFSLocations.FirstOrDefault(x => x.MasterIFSLocationID == ID);
                Load();
            }
        }
        private void Load()
        {
            string s = "";
            if (LocationRecord == null)
            {
                using (clsLinqDataContext ctx = new clsLinqDataContext())
                {
                    LocationRecord = ctx.MasterIFSLocations.FirstOrDefault(x => x.IFSLocation == "TMP-TMP-TMP-TMP");
                    s = "Error";
                    if (LocationRecord != null) { s = LocationRecord.MasterIFSLocationStatus.Status; }
                }
            }
            if (LocationRecord != null)              // && LocationRecord.IFSLocation != "TMP-TMP-TMP-TMP")
            {
                if (s.Length > 0) { _Status = s; }
                if (_Status.Length == 0) { _Status = LocationRecord.MasterIFSLocationStatus.Status; }
                _StatusID = LocationRecord.StatusID;
                _LocationText = LocationRecord.IFSLocation.Trim().ToUpper(); ;
                _ID = LocationRecord.MasterIFSLocationID;
                _isValid = _Status.ToUpper() == "ACTIVE" && LocationRecord.IFSLocation != "TMP-TMP-TMP-TMP";
                _AltIFSLocation = null;
                _ISWhip = LocationRecord.IsWip;
            }
        }
    }



