        public List<vwGridPhysicalPartInventoryCount> GetPhysicalCountDataPart(clsLinqDataContext ctx, string Type)
        {
            if (Type == "Locked")
            {
                return ctx.vwGridPhysicalPartInventoryCounts.Where(x => x.isBatchLocked == true && x.Status == "Active").OrderBy(x => x.Batch).ToList();
            }
            if (Type == "Invalid")
            {
                return ctx.vwGridPhysicalPartInventoryCounts.Where(x => x.isBatchLocked == false && x.Status == "Invalid").OrderBy(x => x.Batch).ToList();
            }
            if (Type == "Open")
            {
                return ctx.vwGridPhysicalPartInventoryCounts.Where(x => x.isBatchLocked == false && x.Status == "Active").OrderBy(x => x.Batch).ToList();
            }
            if (Type == "SentIFS")
            {
                return ctx.vwGridPhysicalPartInventoryCounts.Where(x => x.isBatchLocked == true && x.Status == "SentIFS").OrderBy(x => x.Batch).ToList();
            }
            return ctx.vwGridPhysicalPartInventoryCounts.Where(x => x.Batch == "XXXXX").ToList();
        }

