        public string LogPhysicalInventoryBatchLockedPart(string Batch)
        {
            using (clsLinqDataContext ctx = new clsLinqDataContext())
            {
                return LogPhysicalInventoryBatchLockedPart(ctx, Batch);
            }
        }
        public string LogPhysicalInventoryBatchLockedPart(clsLinqDataContext ctx, string Batch)
        {
            decimal count = 0;
            var data = ctx.PhysicalPartInventoryCounts.Where(x => x.Batch == Batch && x.Status != "Invalid");
            foreach (PhysicalPartInventoryCount r in data)
            {
                r.isBatchLocked = true;
                r.Status = "Active";
                count++;
            }
            ctx.SubmitChanges();
            return "Batch Records Locked:" + count.ToString();
        }
        public string LogPhysicalInventoryBatchInvalidPart(string Batch)
        {
            using (clsLinqDataContext ctx = new clsLinqDataContext())
            {
                return LogPhysicalInventoryBatchInvalidPart(ctx, Batch);
            }
        }
        public string LogPhysicalInventoryBatchInvalidPart(clsLinqDataContext ctx, string Batch)
        {
            decimal count = 0;
            var data = ctx.PhysicalPartInventoryCounts.Where(x => x.Batch == Batch);
            foreach (PhysicalPartInventoryCount r in data)
            {
                r.Status = "Invalid";
                r.isBatchLocked = false;
                count++;
            }
            ctx.SubmitChanges();
            return "Batch Records Marked Invalid:" + count.ToString();
        }
        public string LogPhysicalInventoryBatchOpenPart(string Batch)
