        [DataObjectMethod(DataObjectMethodType.Delete)]
        public string DeleteInvtTran_IFS(decimal ID)
        {
            string rValue = "";
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                var ml = (from q in ctx.InvtTran_IFs where q.InvtTranID == ID select q).FirstOrDefault();
                //if (uac.AllowDelete("Project", ProjectToDelete.ProjectID))
                //{
                if (ml != null)
                {
                    ctx.InvtTran_IFs.DeleteOnSubmit(ml);
                    ctx.SubmitChanges();
                    rValue = "Deleted";
                }
            }
            return rValue;
        }
        public int LogAsTaken(string Esn, string StartDate, string EndDate, string UserName)
        {
            DateTime sDate = DateTime.Now;
            DateTime eDate = DateTime.Now;

            sDate = DateTime.Parse(StartDate);
            eDate = DateTime.Parse(EndDate);
            return LogAsTaken(Esn, sDate, eDate, UserName);

        }
        public int LogAsTaken(string Esn, DateTime Startdate, DateTime EndDate, string UserName)
        {
            int Batch = 0;
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                DateTime dDate = DateTime.Now;
                var y = ctx.InvtTran_IFs.Where(x=> x.RetrievedDate == null);       // && x.CreatedDate >= Startdate && x.CreatedDate < EndDate);
                //if (Esn.Length > 0)
                //{
                //    var rd = ctx.ReceiveDetails.Where(x=> x.ESN == Esn).OrderBy(x=> x.CreateDate).FirstOrDefault();
                //    if (rd == null) {return;}
                //    y = y.Where(x => x.ReceiveDetailID == rd.ReceiveDetailID);
                //}
                if (y.Count() > 0) { Batch = GetNextIFSSequenceNumber(); }
                foreach (var x in y)
                {
                    x.RetrievedDate = dDate;
                    x.RetrievedBatch = Batch;
                    x.RetrievedUser = UserName;
                }
                ctx.SubmitChanges();
            }
            return Batch;
        }
        public int GetNextIFSSequenceNumber()
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                int Value = 0;
                SystemDataManager sdm = new SystemDataManager(UserName);
                string NextNum = sdm.GetValue("IFSBatchNumber");
                if (int.TryParse(NextNum, out Value) == false) { Value = 0; }
                Value++;
                //if (Value > 999) { Value = 1; }
                sdm.SetValue("IFSBatchNumber", (Value).ToString());
                return Value;
            }
        }

