        [DataObjectMethod(DataObjectMethodType.Select)]
        public List<vwIFS_InvtTran> GetInvtTran_IFSList(string ESN, DateTime StartDate, DateTime EndDate, bool IncludeSentToIFS)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                if (IncludeSentToIFS == false)
                {
                    // this gets the first record grouped by Manufacturer
                    var LookupList = from x in ctx.vwIFS_InvtTrans
                                     where x.ESN == ESN && x.CreatedDate >= StartDate && x.CreatedDate < EndDate.AddDays(1) && x.RetrievedDate == null
                                     orderby x.CreatedDate
                                     select x;
                    List<vwIFS_InvtTran> data = LookupList.ToList();
                    return data;
                }
                else
                {
                    var LookupList = from x in ctx.vwIFS_InvtTrans
                                     where x.ESN == ESN && x.CreatedDate >= StartDate && x.CreatedDate < EndDate.AddDays(1)
                                     orderby x.CreatedDate
                                     select x;
                    List<vwIFS_InvtTran> data = LookupList.ToList();
                    return data;
                }
            }
        }
