        public string MovePartLocation(decimal MasterPartsLinkTableID, decimal Quantity, decimal IFSLocationFromID, decimal IFSLocationToID)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                return MovePartLocation(ctx, MasterPartsLinkTableID, Quantity, IFSLocationFromID, IFSLocationToID);
            }
        }
        public string MovePartLocation(string GMPPartNumber, decimal ClientLocationID, decimal Quantity, string IFSLocationFrom, string IFSLocationTo)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                //decimal MasterPartsLinkTableID = -1;
                IFSLocationFrom = IFSLocationFrom.ToUpper();
                IFSLocationTo = IFSLocationTo.ToUpper();
                var part = ctx.MasterPartsLinkTables.FirstOrDefault(x => x.ClientLocationID == ClientLocationID && x.GMPPartNumber.ToUpper() == GMPPartNumber.ToUpper());
                if (part == null) { return "Error: Part not found!"; }
                var dataFrom = ctx.MasterIFSLocations.FirstOrDefault(x => x.IFSLocation == IFSLocationFrom && x.MasterIFSLocationStatus.Status == "Active");
                var dataTo = ctx.MasterIFSLocations.FirstOrDefault(x => x.IFSLocation == IFSLocationTo && x.MasterIFSLocationStatus.Status == "Active");
                if (dataFrom == null) { return "Error: From Location Not found"; }
                if (dataTo == null) { return "Error: To Location Not found"; }
                return MovePartLocation(ctx, part.MasterPartsLinkTableID, Quantity, dataFrom.MasterIFSLocationID, dataTo.MasterIFSLocationID);
            }
        }
        public string MovePartLocation(decimal MasterPartsLinkTableID, decimal Quantity, string IFSLocationFrom, string IFSLocationTo)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                IFSLocationFrom = IFSLocationFrom.ToUpper();
                IFSLocationTo = IFSLocationTo.ToUpper();
                var dataFrom = ctx.MasterIFSLocations.FirstOrDefault(x => x.IFSLocation == IFSLocationFrom && x.MasterIFSLocationStatus.Status == "Active");
                var dataTo = ctx.MasterIFSLocations.FirstOrDefault(x => x.IFSLocation == IFSLocationTo && x.MasterIFSLocationStatus.Status == "Active");
                if (dataFrom == null ) { return "Error: From Location Not found"; }
                if (dataTo == null) { return "Error: To Location Not found"; }
                return MovePartLocation(ctx, MasterPartsLinkTableID, Quantity, dataFrom.MasterIFSLocationID, dataTo.MasterIFSLocationID);
            }
        }
        public string MovePartLocation(clsLinqDataContext ctx, decimal MasterPartsLinkTableID, decimal Quantity, decimal IFSLocationFromID, decimal IFSLocationToID)
        {
            MasterPartManager mpm = new MasterPartManager(UserName);
            return mpm.TransferInverntory(ctx, MasterPartsLinkTableID, IFSLocationFromID, IFSLocationToID, Quantity, -1, "Site Location Transfer", false);
        }

