        public string LogPhysicalInventoryBatchLocked(string Batch)
        {
            using (clsLinqDataContext ctx = new clsLinqDataContext())
            {
                return LogPhysicalInventoryBatchLocked(ctx, Batch);
            }
        }
        public string LogPhysicalInventoryBatchLocked(clsLinqDataContext ctx, string Batch)
        {
            decimal count = 0;
            var data = ctx.PhysicalPartInventoryCounts.Where(x => x.Batch == Batch);
            foreach (PhysicalPartInventoryCount r in data)
            {
                r.isBatchLocked = true;
                count++;
            }
            ctx.SubmitChanges();
            return "Batch Records Locked:" + count.ToString();
        }
        public string LogPhysicalInventoryBatchInvalid(string Batch)
