        public void AddNewTransferLogFile01(MasterFileTransferLog log)
        {
            log.TransferType = "FILE01";
            AddNewTransferLog(log);
        }
        public void AddNewTransferLogFile02(MasterFileTransferLog log)
        {
            log.TransferType = "FILE02";
            AddNewTransferLog(log);
        }
        public void AddNewTransferLogFile04(MasterFileTransferLog log)
        {
            log.TransferType = "FILE04";
            AddNewTransferLog(log);
        }

        public void AddNewTransferLogFile04(clsLinqDataContext ctx, MasterFileTransferLog log)
        {
            log.TransferType = "FILE04";
            AddNewTransferLog(ctx, log);
        }
        public void AddNewTransferLogDetailFile04(clsLinqDataContext ctx, MasterFileTransferDetailLog log)
        {
            // look to see if there is an open FILE04 master record
            var master = ctx.MasterFileTransferLogs.FirstOrDefault(x => x.TransferDate == null && x.FileName.Length == 0 && x.TransferType.ToUpper() == "FILE04");
            if (master == null)
            {
                master = new MasterFileTransferLog();
                master.MasterFileTransferDetailLogs.Add(log);
                AddNewTransferLogFile04(ctx, master);
            }
            else
            {
                master.MasterFileTransferDetailLogs.Add(log);
                ctx.SubmitChanges();
            }
        }

        void AddNewTransferLog(MasterFileTransferLog log)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                AddNewTransferLog(ctx, log);
            }
        }
        void AddNewTransferLog(clsLinqDataContext ctx, MasterFileTransferLog log)
        {
            log.ClientID = ClientID;
            log.ClientLocationID = ClientLocationId;
            log.CreateUser = UserName;
            log.LastUpdateDate = DateTime.Now;
            log.LastUpdateUser = UserName;
            log.Status = "New";
            log.Name = "";
            foreach (MasterFileTransferDetailLog d in log.MasterFileTransferDetailLogs)
            {
                d.Status = "New";
                d.CreateUser = UserName;
                d.LastUpdateDate = DateTime.Now;
                d.LastUpdateUser = UserName;
            }
            ctx.MasterFileTransferLogs.InsertOnSubmit(log);
            ctx.SubmitChanges();
        }

        public void AddNewTransferLogReceived_OnlyIfPreceived(clsLinqDataContext ctx, ReceiveDetailPreReceive PreReceive)     // Received but needs to have been prereceived.
        {
            MasterFileTransferDetailLog detail = new MasterFileTransferDetailLog();
            detail.ESN = PreReceive.ESN;
            detail.ReceiveDetailID = PreReceive.ReceiveDetailID;
            detail.ReceiveDetailPreReceiveID = PreReceive.ReceiveDetailPreReceiveID;
            detail.RecordText = "";
            detail.StatusMessage = "New";
            AddNewTransferLogReceived_OnlyIfPreceived(ctx, detail);
        }
        void AddNewTransferLogReceived_OnlyIfPreceived(clsLinqDataContext ctx, MasterFileTransferDetailLog detail)     // Received but needs to have been prereceived.
        {
            //decimal ClientLocationId = -1;
            //decimal ClientId = -1;

            MasterFileTransferDetailLog dl = ctx.MasterFileTransferDetailLogs.FirstOrDefault(x => x.ESN == detail.ESN && x.MasterFileTransferLog.TransferType.ToUpper() == "FILE01" && x.Status.ToUpper() == "NEW");
            if (dl != null)
            //if (ctx.MasterFileTransferDetailLogs.Any(x => x.ReceiveDetailID == detail.ReceiveDetailID && x.MasterFileTransferLog.TransferType == "File01" && x.Status == "New"))
            {
                ReceiveDetail rd = ctx.ReceiveDetails.FirstOrDefault(x => x.ReceiveDetailID == detail.ReceiveDetailID);
                if (rd != null)
                {
                    _ClientID = rd.ClientLocation.ClientID;
                    _ClientLocationID = rd.ClientLocationID;
                    //detail.ClientLocationID = rd.ClientLocationID;
                }
                detail.Status = "New";
                detail.CreateUser = UserName;
                detail.LastUpdateDate = DateTime.Now;
                detail.LastUpdateUser = UserName;
                detail.ClientLocationID = _ClientLocationID;
                // see if there is an existing Log that is not sent yet.
                MasterFileTransferLog log = ctx.MasterFileTransferLogs.FirstOrDefault(x => x.TransferType.ToUpper() == "FILE02" && x.Status.ToUpper() == "OPEN");
                if (log == null)
                {
                    log = new MasterFileTransferLog();
                    log.CreateUser = UserName;
                    log.LastUpdateDate = DateTime.Now;
                    log.LastUpdateUser = UserName;
                    log.Status = "Open";
                    log.Name = "";
                    log.FileName = "";
                    log.TransferType = "FILE02";
                    //log.TransferDate = DateTime.Now;
                    log.ClientID = _ClientID;
                    log.ClientLocationID = _ClientLocationID;
                    log.MasterFileTransferDetailLogs.Add(detail);
                    ctx.MasterFileTransferLogs.InsertOnSubmit(log);
                }
                else
                {
                    log.MasterFileTransferDetailLogs.Add(detail);
                }
                dl.ClientLocationID = _ClientLocationID;
                dl.ReceiveDetailID = detail.ReceiveDetailID;
                dl.Status = "Received";
                dl.LastUpdateDate = DateTime.Now;
                dl.LastUpdateUser = UserName;
                ctx.SubmitChanges();
            }
        }


        public void AddNewTransferLogShipped_OnlyIfReceived(decimal ReceiveDetailID)
        {
            using (clsLinqDataContext ctx = new clsLinqDataContext())
            {
                ReceiveDetail rd = ctx.ReceiveDetails.FirstOrDefault(x => x.ReceiveDetailID == ReceiveDetailID);
                if (rd != null)
                {
                    MasterFileTransferDetailLog detail = new MasterFileTransferDetailLog();
                    detail.ESN = rd.ESN;
                    detail.ReceiveDetailID = rd.ReceiveDetailID;
                    detail.ReceiveDetailPreReceiveID = -1;
                    detail.RecordText = "";
                    detail.StatusMessage = "New";
                    detail.ClientLocationID = rd.ClientLocationID;
                    AddNewTransferLogShipped_OnlyIfReceived(ctx, detail);
                }
            }
        }
        public void AddNewTransferLogShipped_OnlyIfReceived(clsLinqDataContext ctx, List<decimal> ReceiveDetailIDs)
        {
            foreach (decimal ReceiveDetailID in ReceiveDetailIDs)
            {
                ReceiveDetail rd = ctx.ReceiveDetails.FirstOrDefault(x => x.ReceiveDetailID == ReceiveDetailID);
                if (rd != null)
                {
                    MasterFileTransferDetailLog detail = new MasterFileTransferDetailLog();
                    detail.ESN = rd.ESN;
                    detail.ReceiveDetailID = rd.ReceiveDetailID;
                    detail.ReceiveDetailPreReceiveID = -1;
                    detail.RecordText = "";
                    detail.StatusMessage = "New";
                    detail.ClientLocationID = rd.ClientLocationID;
                    AddNewTransferLogShipped_OnlyIfReceived(ctx, detail);
                }
            }
        }
