        void AddNewTransferLogShipped_OnlyIfReceived(clsLinqDataContext ctx, MasterFileTransferDetailLog detail)     // Shipped but needs to have been received first
        {
            if (ctx.MasterFileTransferDetailLogs.Any(x => x.ReceiveDetailID == detail.ReceiveDetailID && x.MasterFileTransferLog.TransferType.ToUpper() == "FILE02" && x.Status.ToUpper() == "SENT"))
            {
                detail.Status = "New";
                detail.CreateUser = UserName;
                detail.LastUpdateDate = DateTime.Now;
                detail.LastUpdateUser = UserName;
                string Replacement_IMEI = "";
                // see if there is an existing Log that is not sent yet.
                MasterFileTransferLog log = ctx.MasterFileTransferLogs.FirstOrDefault(x => x.FileName.Length == 0 && x.TransferType.ToUpper() == "FILE04" && x.TransferDate == null);
                if (log == null)
                {
                    log = new MasterFileTransferLog();
                    log.CreateUser = UserName;
                    log.LastUpdateDate = DateTime.Now;
                    log.LastUpdateUser = UserName;
                    log.Status = "New";
                    log.Name = "";
                    log.FileName = "";
                    log.TransferType = "FILE04";
                    log.ClientID = ClientID;
                    log.ClientLocationID = ClientLocationId;
                    log.MasterFileTransferDetailLogs.Add(detail);

                    ReceiveDetailManager rdm = new ReceiveDetailManager(UserName);
                    Replacement_IMEI = rdm.GetReceiveDetailItem_DataElement(ctx, (decimal)detail.ReceiveDetailID, "Replacement IMEI");
                    if (Replacement_IMEI.Length > 0)
                    {
                        // we have a prelacement IMEI, a second record needs to be generated
                        MasterFileTransferDetailLog detailReplace = new MasterFileTransferDetailLog();
                        detailReplace.ClientLocationID = detail.ClientLocationID;
                        detailReplace.CreateUser = detail.CreateUser;
                        detailReplace.ESN = detail.ESN;
                        detailReplace.LastUpdateDate = detail.LastUpdateDate;
                        detailReplace.LastUpdateUser = detail.LastUpdateUser;
                        detailReplace.ReceiveDetailID = detail.ReceiveDetailID;
                        detailReplace.RecordText = "";
                        detailReplace.Status = "New";
                        detailReplace.StatusMessage = "Replacement IMEI";
                        log.MasterFileTransferDetailLogs.Add(detailReplace);
                    }


                    ctx.MasterFileTransferLogs.InsertOnSubmit(log);
                }
                else
                {
                    log.MasterFileTransferDetailLogs.Add(detail);
                }
                ctx.SubmitChanges();
            }
        }

