        public void ExecutePreReceiveFile01Record(clsLinqDataContext ctx, MasterFileTransferDetailLog logDetail)
        {
            if (ctx.ReceiveDetailPreReceives.Any(x => x.ESN == logDetail.ESN && x.Status.ToUpper() == "OPEN"))
            {
                logDetail.StatusMessage = "ESN already in Prereceive file waiting for arrival.";
                logDetail.Status = "Error";
                return;
            }
            if (ctx.ReceiveDetails.Any(x => x.ESN == logDetail.ESN && x.Version == "000"))
            {
                logDetail.StatusMessage = "ESN already active version 000 record.";
                logDetail.Status = "Error";
                return;
            }
            ReceiveDetailPreReceive pr = new ReceiveDetailPreReceive();
            pr.Status = "Open";
            pr.CreateUser = UserName;
            pr.ESN = logDetail.ESN;
            pr.LastUpdateDate = DateTime.Now;
            pr.LastUpdateUser = UserName;
            pr.ProjectName = "";
            pr.ProjectTag = "";
            pr.RMANumber = "";
            pr.OnSite = false;
            // We should now add any of the attributes.
            List<string> dta = logDetail.RecordText.Split(';').ToList();
            //string sDate = "";              0 - 
            //string StoreCode = "";          1 - 
            //string WHSCode = "";            2 - 
            //string RMANumber = "";          3 - Question: RMA_Number
            //string ProductSKU = "";         4 - Question: SKU
            //string QTY = "";                5 - 
            //string WAC = "";                6 - 
            //string SerialNumber = "";       7 - ESN
            //pr.RMANumber = dta[3];

            // get the RMA Number OptionID
            // get the SKU OptionID
            Option RMANumber = ctx.Options.FirstOrDefault(x => x.Question.Name.ToUpper() == "RMA NUMBER");
            Option SKU = ctx.Options.FirstOrDefault(x => x.Question.Name.ToUpper() == "SKU");
            if (RMANumber != null)
            {
                ReceiveDetailPreReceiveAttribute pa = new ReceiveDetailPreReceiveAttribute();
                pa.CreateUser = UserName;
                pa.LastUpdateDate = DateTime.Now;
                pa.LastUpdateUser = UserName;
                pa.OptionID = RMANumber.OptionID;
                pa.Value = dta[3];
                pr.ReceiveDetailPreReceiveAttributes.Add(pa);
            }
            if (SKU != null)
            {
                ReceiveDetailPreReceiveAttribute pa = new ReceiveDetailPreReceiveAttribute();
                pa.CreateUser = UserName;
                pa.LastUpdateDate = DateTime.Now;
                pa.LastUpdateUser = UserName;
                pa.OptionID = SKU.OptionID;
                pa.Value = dta[4];
                pr.ReceiveDetailPreReceiveAttributes.Add(pa);
            }
            ctx.ReceiveDetailPreReceives.InsertOnSubmit(pr);
            ctx.SubmitChanges();
            logDetail.ReceiveDetailPreReceiveID = pr.ReceiveDetailPreReceiveID;
            logDetail.StatusMessage = "Done";
            logDetail.Status = "DoneGood";
        }
        public void TriggerToRunPMITransfer()
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                SystemDataManager sdm = new SystemDataManager(UserName);
                sdm.SetValue("RunPMITransfer", "Y");
            }
        }
        public bool DoManuallyRunPMITransfer()
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                SystemDataManager sdm = new SystemDataManager(UserName);
                string RunPMITransfer = sdm.GetValue("RunPMITransfer");
                if (RunPMITransfer == "Y")
                {
                    sdm.SetValue("RunPMITransfer", "N");
                    return true;
                }
                return false;
            }
        }

        public decimal GetNextSequenceNumber()
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                decimal Value = 0;
                SystemDataManager sdm = new SystemDataManager(UserName);
                string NextNum = sdm.GetValue("PMIFILESEQNUM");
                if (decimal.TryParse(NextNum, out Value) == false) { Value = 0; }
                Value++;
                if (Value > 999) { Value = 1; }
                sdm.SetValue("PMIFILESEQNUM", (Value + 1).ToString());
                return Value;
            }
        }

    }

