        public void Add(string ESN, string IDC_BIN, string WayBill, string Location, string MasterClientID, string MasterClientName, string Courier, decimal ReceiveDetailID, string UserName, string IP, string Status)
        {
            using (clsLinqDataContext ctx = new clsLinqDataContext())
            {
                Add(ctx, ESN, IDC_BIN, WayBill, Location, MasterClientID, MasterClientName, Courier, ReceiveDetailID, UserName, IP, Status);
            }
        }
        public void Add(clsLinqDataContext ctx, string ESN, string IDC_BIN, string Location, decimal ReceiveDetailID, string UserName, string IP, string Status)
        {
            string WayBill = "";
            string MasterClientID = "";
            string MasterClientName = "";
            string Courier = "";
            LocationLog log = ctx.LocationLogs.OrderByDescending(x => x.LocationLogID).FirstOrDefault(x => x.ESN == ESN && (x.Status == "PREREC" || x.Status == "BLINDREC"));
            if (log != null)
            {
                WayBill = log.WayBillNumber;
                MasterClientID = log.ClientID.ToString();
                MasterClientName = log.ClientName;
                //if (Location.Length == 0) { Location = log.Location; }
            }
            else if (ReceiveDetailID > 0)
            {
                // We need to add a new "BLINDREC" to the flow.
                // Get the Source Record.
                ReceiveDetail rd = ctx.ReceiveDetails.FirstOrDefault(x => x.ReceiveDetailID == ReceiveDetailID);
                if (rd == null) { return; }
                WayBill = "";
                ESN = rd.ESN;
                IDC_BIN = "";
                //Location = "";
                MasterClientID = rd.ClientLocation.ClientID.ToString();
                MasterClientName = rd.ClientLocation.Client.CompanyName;
                //if (Location.Length == 0) { Location = log.Location; }

                logManager.ReportMessage("Add BLINDREC:" + ESN + " b:" + IDC_BIN + " l:" + IP + " s:" + "BLINDREC" + " rd:" + ReceiveDetailID);
                Add(ctx, ESN, "", "", IP, MasterClientID, MasterClientName, Courier, ReceiveDetailID, UserName, "", "BLINDREC");
            }
            Add(ctx, ESN, IDC_BIN, WayBill, Location, MasterClientID, MasterClientName, Courier, ReceiveDetailID, UserName, "", Status);
        }
        public void Add(clsLinqDataContext ctx, string ESN, string IDC_BIN, string WayBill, string Location, string MasterClientID, string MasterClientName, string Courier, decimal ReceiveDetailID, string UserName, string IP, string Status)
        {
            logManager.ReportMessage("Add e:" + ESN + " b:" + IDC_BIN + " l:" + Location + " s:" + Status + " rd:" + ReceiveDetailID);
            if (Location.Length == 0) { return; }

            //string rMessage = "";
            decimal clientid = -1;
            if (decimal.TryParse(MasterClientID, out clientid) == false) { clientid = -1; }
            LocationLog log = null;

            //log = ctx.LocationLogs.OrderByDescending(x => x.LocationLogID).FirstOrDefault(x => x.ESN == ESN && x.ReceiveDetailID == -1 && x.Status == "PREREC");
            //if (log != null)
            //{
            //    log.ClientID = clientid;
            //    log.ClientLocationID = -1;
            //    log.ClientName = MasterClientName;
            //    log.Create_IP = IP;
            //    log.IDC_Bin = IDC_BIN;
            //    log.Location = Location;
            //    if (WayBill.Length > 0)
            //    {
            //        log.WayBillNumber = WayBill;
            //    }
            //    log.LastUpdateDate = DateTime.Now;
            //    log.LastUpdateUser = UserName;
            //}
            //else
            //{
            log = new LocationLog();
            log.ClientID = clientid;
            log.ClientLocationID = -1;
            log.ClientName = MasterClientName;
            log.Create_IP = IP;
            log.CreateUser = UserName;
            log.ESN = ESN;
            log.IDC_Bin = IDC_BIN;
            log.WayBillNumber = WayBill;
            log.LastUpdateDate = DateTime.Now;
            log.LastUpdateUser = UserName;
            log.Location = Location;
            log.ReceiveDetailID = ReceiveDetailID;
            log.Status = Status;
            ctx.LocationLogs.InsertOnSubmit(log);
            //}
            ctx.SubmitChanges();
            if (ReceiveDetailID > 0)
            {
                UpdateReceiveDetailID(ctx, ESN, ReceiveDetailID);
            }
        }

        public string RecordShippedRecord(clsLinqDataContext ctx, string ESN, decimal ReceiveDetailID, string IDC_BIN, string Location, string IP)
        {
            logManager.ReportMessage("UpdateReceiveDetailID e:" + ESN + " rd:" + ReceiveDetailID + " b:" + IDC_BIN + " l:" + Location + " s:" + "COMPLETE");
            Add(ctx, ESN, IDC_BIN, Location, ReceiveDetailID, UserName, IP, "COMPLETE");
            return "";
        }
        public string UpdateReceiveDetailID(clsLinqDataContext ctx, string ESN, decimal ReceiveDetailID)
        {
            int count = 0;
            var data = from x in ctx.LocationLogs
                       where x.ESN == ESN && (x.ReceiveDetailID == null || x.ReceiveDetailID < 1)
                       select x;
            foreach (LocationLog l in data)
            {
                count++;
                l.ReceiveDetailID = ReceiveDetailID;
            }
            ctx.SubmitChanges();
            logManager.ReportMessage("UpdateReceiveDetailID e:" + ESN + " rd:" + ReceiveDetailID + "count:" + count.ToString());
            return count.ToString() + " prior records updated";
        }

        public List<LocationLog> GetPreReleaseIDCBinDetails(string IDC_BIN)
        {
            using (clsLinqDataContext ctx = new clsLinqDataContext())
            {
                return GetPreReleaseIDCBinDetails(ctx, IDC_BIN);
            }
        }
        public List<LocationLog> GetPreReleaseIDCBinDetails(clsLinqDataContext ctx, string IDC_BIN)
        {
            List<LocationLog> lg = (from x in ctx.LocationLogs
                      where x.Status == "PREREC" && x.IDC_Bin == IDC_BIN && x.ReceiveDetailID == -1
                      orderby x.ESN
                      select x).ToList();
            return lg;
        }


    }







































