        public decimal AutoProcessLoggedButNotSentEmails(string UserName)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                decimal count = 0;
                SendEmail EU = new SendEmail();
                var emails = from x in ctx.EmailLogs where x.Status == "New" select x;
                DateTime timestamp = DateTime.Now;
                foreach (var e in emails)
                {
                    count++;
                    e.Status = "Sent";
                    e.SendDate = timestamp;
                    e.LastUpdateDate = timestamp;
                    e.EmailSendReturnMessage = EU.Email(e.To, e.Body, e.Subject);
                }
                ctx.SubmitChanges();
                return count;

                //return Description(ctx, ID);
            }
        }

        public void SendEmail(string Source, string To, string Subject, string Body)
        {
            SendEmail(Source, To, Subject, Body, -1);
        }
        public void SendEmail(string Source, string To, string Subject, string Body, decimal ReceiveDetailID)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                EmailLog el = new EmailLog();
                DateTime timestamp = DateTime.Now;
                el.Body = Body;
                el.CreateDate = timestamp;
                el.CreateUser = UserName;
                el.EmailSendReturnMessage = "";
                el.LastUpdateDate = timestamp;
                el.LastUpdateUser = UserName;
                el.ReceiveDetailID = ReceiveDetailID;
                el.Source = Source;
                el.Status = "New";
                el.Subject = Subject;
                el.To = To;
                ctx.SubmitChanges();
            }
        }
    }




