            }
            Log.LogIt("*** Inside ClientRestrictionsList");

            List<PairIDValue> RQ = new List<PairIDValue>();
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                var restrictions = from x in ctx.ClientQuestionRestricts
                                   where x.ClientID == ClientID && x.ProjectID == ProjectID
                                   select x;
                if (restrictions != null)
                {
                    foreach (var y in restrictions)
                    {
                        Log.LogIt("Inside ClientRestrictionsList loop - " + y.QuestionID.ToString());

                        RQ.Add(new PairIDValue { ID = y.QuestionID, Desc = "1" });

                    }
                }
                Log.LogIt(" Done loop" + RQ.Count.ToString());
            }
            return RQ;
        }

