        public bool DeleteClientProcessDependencies(decimal ClientProcessDependenciesID)
        {
            if (ClientProcessDependenciesID < 1) { return false; }
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                var CBPoint = ctx.ClientProcessDependencies.FirstOrDefault(x => x.ClientProcessDependenciesID == ClientProcessDependenciesID);
                if (CBPoint != null)
                {
                    ctx.ClientProcessDependencies.DeleteOnSubmit(CBPoint);
                    ctx.SubmitChanges();
                }
            }
            return true;
        }

        public decimal AddUpdateDeleteClientProcessDependencies(
            decimal ClientProcessDependenciesID,
            decimal ClientID,
            decimal ProcessID)
        {
            decimal ID = -1;
            //if (ClientProcessDependenciesID < 1) { return ID; }
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                var CBPoint = ctx.ClientProcessDependencies.FirstOrDefault(x => x.ClientProcessDependenciesID == ClientProcessDependenciesID);
                if (CBPoint == null)
                {
                    ClientProcessDependenciesID = -1;
                    CBPoint = new ClientProcessDependency();
                    CBPoint.ClientID = ClientID;
