        [DataObjectMethod(DataObjectMethodType.Select)]
        public List<ClientLocation> SearchLocationsList(clsLinqDataContext ctx, string ClientName, string LocationName, string Streat, string PostalCode)
        {
            var clientLocations = from x in ctx.ClientLocations
                                  where (
                                         ((ClientName.Length == 0 || x.Client.CompanyName.StartsWith(ClientName)) &&
                                         (LocationName.Length == 0 || x.CompanyName.StartsWith(LocationName)) &&
                                         (Streat.Length == 0 || x.AddressLine1.StartsWith(Streat) || x.AddressLine2.StartsWith(Streat)) &&
                                         (PostalCode.Length == 0 || x.PostalCode.StartsWith(PostalCode)))

                                        ||

                                         ((ClientName.Length == 0 || x.Client.CompanyName.StartsWith(ClientName)) &&
                                         (LocationName.Length == 0 || x.ScanKey.ToUpper() == LocationName.ToUpper()) &&
                                         (Streat.Length == 0 || x.AddressLine1.StartsWith(Streat) || x.AddressLine2.StartsWith(Streat)) &&
                                         (PostalCode.Length == 0 || x.PostalCode.StartsWith(PostalCode)))
                                        )

                                        && x.ClientLocationStatus.Status == "Active"
                                  orderby x.Client.CompanyName, x.CompanyName
                                  select x;
            //return clientLocations.ToList();
            return UserRestrict.GetRestricted(clientLocations, ctx).ToList();
        }
        [DataObjectMethod(DataObjectMethodType.Select)]
        public List<Client> SearchMasterClientList(clsLinqDataContext ctx, string ClientName, string LocationName, string Streat, string PostalCode)
        {
            var clients = from x in ctx.Clients
                                  where (ClientName.Length == 0 || x.CompanyName.StartsWith(ClientName)) &&
                                        (LocationName.Length == 0 || x.CompanyName.StartsWith(LocationName)) &&
                                        (Streat.Length == 0 || x.AddressLine1.StartsWith(Streat) || x.AddressLine2.StartsWith(Streat)) &&
                                        (PostalCode.Length == 0 || x.PostalCode.StartsWith(PostalCode))
                                  orderby x.CompanyName
                                  select x;
            //return clientLocations.ToList();
            return UserRestrict.GetRestricted(clients, ctx).ToList();
        }
        [DataObjectMethod(DataObjectMethodType.Select)]
        public List<Client> SearchMasterClientPreReceiveList(clsLinqDataContext ctx, string ClientName, string LocationName, string Streat, string PostalCode)
        {
            var clients = from x in ctx.Clients
                          where (ClientName.Length == 0 || x.CompanyName.StartsWith(ClientName)) &&
                                (LocationName.Length == 0 || x.CompanyName.StartsWith(LocationName)) &&
                                (Streat.Length == 0 || x.AddressLine1.StartsWith(Streat) || x.AddressLine2.StartsWith(Streat)) &&
                                (PostalCode.Length == 0 || x.PostalCode.StartsWith(PostalCode)) &&
                                (x.HideOnPreReceiveList == null || x.HideOnPreReceiveList == false)
