        [DataObjectMethod(DataObjectMethodType.Insert)]
        public decimal InsertClient(Client client)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                client.Name = "";    // This field is no longer used.
                client.LastUpdateDate = DateTime.Now;
                client.LastUpdateUser = UserName;
                client.CreateDate = DateTime.Now;
                client.CreateUser = UserName;
                ctx.Clients.InsertOnSubmit(client);
                ctx.SubmitChanges();
                return client.ClientID;
            }
        }

        [DataObjectMethod(DataObjectMethodType.Insert)]
        public decimal InsertClientLocation(ClientLocation clientlocation)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                clientlocation.IFSSite = clientlocation.IFSSite.ToUpper();
                clientlocation.IFSProject = clientlocation.IFSProject.ToUpper();
                clientlocation.IFSPOVendor = clientlocation.IFSPOVendor.ToUpper();
                clientlocation.LocationSegment = clientlocation.LocationSegment.ToUpper();
                clientlocation.Name = "";    // This field is no longer used.
                clientlocation.LastUpdateDate = DateTime.Now;
                clientlocation.LastUpdateUser = UserName;
                clientlocation.CreateDate = DateTime.Now;
                clientlocation.CreateUser = UserName;
                ctx.ClientLocations.InsertOnSubmit(clientlocation);
                ctx.SubmitChanges();
                return clientlocation.ClientID;
            }
        }

        [DataObjectMethod(DataObjectMethodType.Update)]
        public void UpdateClient(Client client)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                var existingClient = (from q in ctx.Clients where q.ClientID == client.ClientID select q).FirstOrDefault();
                if (existingClient != null)
                {
                    existingClient.Name = "";    // this field is not being used.
                    existingClient.RMASuffix = client.RMASuffix;
                    existingClient.AddressLine1 = client.AddressLine1;
                    existingClient.AddressLine2 = client.AddressLine2;
                    existingClient.AddressLine3 = client.AddressLine3;
                    existingClient.AddressLine4 = client.AddressLine4;
                    existingClient.City = client.City;
                    existingClient.Country = client.Country;
                    existingClient.ContactName = client.ContactName;
                    existingClient.CompanyName = client.CompanyName;
                    existingClient.BillingAddress = client.BillingAddress;
                    existingClient.Username = client.Username;
                    existingClient.EmailAddress = client.EmailAddress;
                    existingClient.ScanKey = client.ScanKey;
                    existingClient.StatusID = client.StatusID;
                    existingClient.Notes = client.Notes;
                    existingClient.PhoneNumber = client.PhoneNumber;
                    existingClient.FaxNumber = client.FaxNumber;
                    existingClient.PostalCode = client.PostalCode;
                    existingClient.StateOrProvince = client.StateOrProvince;
                    existingClient.StatusID = client.StatusID;
                    existingClient.LastUpdateDate = DateTime.Now;
                    existingClient.LastUpdateUser = UserName;
                    existingClient.isVendorGroup = client.isVendorGroup;
                    existingClient.ProductTag = client.ProductTag;
                    existingClient.RepairForm = client.RepairForm;
                    existingClient.PortalName = client.PortalName;
                    existingClient.WarrentyDayLimit = client.WarrentyDayLimit;
                    existingClient.InWarrentyPricing = client.InWarrentyPricing;
                    existingClient.HideOnPreReceiveList = client.HideOnPreReceiveList;
                    existingClient.OOW_WHS = client.OOW_WHS;
                    ctx.SubmitChanges();
                }
            }
        }

        [DataObjectMethod(DataObjectMethodType.Update)]
        public void UpdateClientLocation(ClientLocation clientlocation)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                var existingClientLocation = (from q in ctx.ClientLocations where q.ClientLocationID == clientlocation.ClientLocationID select q).FirstOrDefault();
                if (existingClientLocation != null)
                {
                    existingClientLocation.Name = "";    // this field is not being used.
                    existingClientLocation.StoreNumber = clientlocation.StoreNumber;
                    existingClientLocation.StoreSuffix = clientlocation.StoreSuffix;
                    existingClientLocation.BillingAddress = clientlocation.BillingAddress;
                    existingClientLocation.AddressLine1 = clientlocation.AddressLine1;
                    existingClientLocation.AddressLine2 = clientlocation.AddressLine2;
                    existingClientLocation.AddressLine3 = clientlocation.AddressLine3;
                    existingClientLocation.AddressLine4 = clientlocation.AddressLine4;
                    existingClientLocation.City = clientlocation.City;
                    existingClientLocation.Country = clientlocation.Country;
                    existingClientLocation.ContactName = clientlocation.ContactName;
                    existingClientLocation.CompanyName = clientlocation.CompanyName;
                    existingClientLocation.ScanKey = clientlocation.ScanKey;
                    existingClientLocation.StatusID = clientlocation.StatusID;
                    existingClientLocation.Notes = clientlocation.Notes;
