        [DataObjectMethod(DataObjectMethodType.Delete)]
        public void DeleteClient(decimal clientID)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                var a = from x in ctx.ClientQuestionRestricts where x.ClientID == clientID select x;
                foreach (ClientQuestionRestrict d1 in a)
                {
                    ctx.ClientQuestionRestricts.DeleteOnSubmit(d1);
                }

                var c = from x in ctx.ClientBillingPoints where x.ClientID == clientID select x;
                foreach (ClientBillingPoint d1 in c)
                {
                    ctx.ClientBillingPoints.DeleteOnSubmit(d1);
                }

                var d = from x in ctx.ClientProjectDependencies where x.ClientID == clientID select x;
                foreach (ClientProjectDependency d1 in d)
                {
                    ctx.ClientProjectDependencies.DeleteOnSubmit(d1);
                }

                var b = from x in ctx.ClientLocations where x.ClientID == clientID select x;
                foreach (ClientLocation d1 in b)
                {
                    ctx.ClientLocations.DeleteOnSubmit(d1);
                }

                var e = from x in ctx.Clients where x.ClientID == clientID select x;
                foreach (Client d1 in e)
                {
                    ctx.Clients.DeleteOnSubmit(d1);
                }

                ctx.SubmitChanges();
                return;
            }
        }
        #endregion

    }

