        public string TranslateOptionScanCodes(clsLinqDataContext ctx, decimal ProjectID, string ScanCodes)
        {
            if (ScanCodes.Trim().Length == 0) { return ""; }
            ScanCodes = ScanCodes.Replace(System.Environment.NewLine, " ");
            string[] Codes = ScanCodes.Trim().Split(' ');

            List<string> SCodes = new List<string>(Codes);
            string rString = "";

            #region Restrict question to valid Project
            //var processes = from x in ctx.ProjectProcesses
            //                where ProjectID < 1 || x.ProjectID == ProjectID
            //                select x;
            //List<decimal> PID = new List<decimal>();
            //foreach (ProjectProcess p in processes)
            //{
            //    PID.Add(p.ProcessID);
            //}

            //var questions = from x in ctx.ProcessQuestions
            //                where PID.Contains(x.ProcessID)
            //                select x;
            //List<decimal> QID = new List<decimal>();
            //foreach (ProcessQuestion p in questions)
            //{
            //    QID.Add(p.QuestionID);
            //}

            //var options = from x in ctx.Options
            //              where QID.Contains(x.QuestionID) && SCodes.Contains(x.ScanKey)
            //              orderby x.Question.Sequence
            //              select x;
            #endregion

            var options = from x in ctx.Options
                          where SCodes.Contains(x.ScanKey)
                          orderby x.Question.Sequence
                          select x;

            foreach (Option o in options)
            {
                rString += o.OptionText + " ";                           // Environment.NewLine;
            }


            if (rString.Length == 0)
            {
                rString = ScanCodes;
            }
            return rString;
        }
