        {
            decimal ReturnValue = -1;
            if (question != null)
            {
                using (clsLinqDataContext ctx = GetDataContext(UserName))
                {
                    question.LastUpdateDate = DateTime.Now;
                    question.LastUpdateUser = UserName;
                    question.CreateDate = DateTime.Now;
                    question.CreateUser = UserName;
                    ctx.Questions.InsertOnSubmit(question);
                    ctx.SubmitChanges();
                    return question.QuestionID;
                }
            }
            return ReturnValue;
        }

        [DataObjectMethod(DataObjectMethodType.Update)]
        public void UpdateQuestion(Question question)
        {
            if (question != null)
            {
                using (clsLinqDataContext ctx = GetDataContext(UserName))
                {
                    var existingQuestion = (from q in ctx.Questions where q.QuestionID == question.QuestionID select q).FirstOrDefault();
                    if (existingQuestion != null)
                    {
                        existingQuestion.Sequence = question.Sequence;
                        existingQuestion.QuestionTypeID = question.QuestionTypeID;
                        existingQuestion.QuestionStatusID = question.QuestionStatusID;
                        ////existingQuestion.ProcessQuestions = question.ProcessQuestions;
                        ////existingQuestion.Options = question.Options;
                        existingQuestion.isManditory = question.isManditory;
                        existingQuestion.Name = question.Name;
                        existingQuestion.TableName = question.TableName;
                        existingQuestion.HelpText = question.HelpText;
                        existingQuestion.Description = question.Description;
                        existingQuestion.isReadOnly = question.isReadOnly;
                        existingQuestion.IsHeaderQuestion = question.IsHeaderQuestion;
                        existingQuestion.ShowVertical = question.ShowVertical;
                        existingQuestion.isTimeSpread = question.isTimeSpread;
                        existingQuestion.isManditory = question.isManditory;
                        existingQuestion.isSearchable = question.isSearchable;
                        existingQuestion.IFS_Condition = question.IFS_Condition;
                        existingQuestion.IFS_Condition_Sequence = question.IFS_Condition_Sequence;
                        existingQuestion.isKeyQuestion = question.isKeyQuestion;
                        existingQuestion.DisplayColumn = question.DisplayColumn;
                        existingQuestion.BucketCount = question.BucketCount;

                        existingQuestion.BucketCountOffset = question.BucketCountOffset;
                        existingQuestion.LastUpdateDate = DateTime.Now;
                        existingQuestion.LastUpdateUser = UserName;
                        ctx.SubmitChanges();
                    }
                }
            }
        }

