        [DataObjectMethod(DataObjectMethodType.Delete)]
        public void DeleteQuestion(decimal QuestionID)
        {
            CompanyDemographics dem = new CompanyDemographics(UserName);
            if (dem.AllowMasterTableDelete == false) { return; }
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                var QuestionToDelete = (from q in ctx.Questions where q.QuestionID == QuestionID select q).FirstOrDefault();
                if (QuestionToDelete != null)
                {
                    IQueryable<ReceiveDetailItemBulk> bi = from x in ctx.ReceiveDetailItemBulks where x.Option.QuestionID == QuestionID select x;
                    if (bi != null)
                    {
                        foreach (ReceiveDetailItemBulk i in bi)
                        {
                            ctx.ReceiveDetailItemBulks.DeleteOnSubmit(i);
                        }
                    }

                    IQueryable<ReceiveDetailItem> ri = from x in ctx.ReceiveDetailItems where x.Option.QuestionID == QuestionID select x;
                    if (ri != null)
                    {
                        foreach (ReceiveDetailItem i in ri)
                        {
                            ctx.ReceiveDetailItems.DeleteOnSubmit(i);
                        }
                    }


                    IQueryable<ProcessQuestion> pq = from x in ctx.ProcessQuestions where x.QuestionID == QuestionID select x;
                    if (pq != null)
                    {
                        foreach (ProcessQuestion p in pq)
                        {
                            ctx.ProcessQuestions.DeleteOnSubmit(p);
                        }
                    }

                    IQueryable<Option> ops = from x in ctx.Options where x.QuestionID == QuestionID select x;
                    if (ops != null)
                    {
                        foreach (Option op in ops)
                        {
                            ctx.Options.DeleteOnSubmit(op);
                        }
                    }
                    ctx.Questions.DeleteOnSubmit(QuestionToDelete);
                    ctx.SubmitChanges();
                }
            }
        }
        #endregion
    }

