        [DataObjectMethod(DataObjectMethodType.Update)]
        public void UpdateDependencies(decimal SourceQuestionID, decimal TargetQuestionID, decimal SourceOptionID, List<decimal> TargetIDOn, List<decimal> TargetIDOff)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                // Delete the Off Elements
                QuestionDependency q = null;
                foreach (decimal id in TargetIDOff)
                {
                    q = ctx.QuestionDependencies.FirstOrDefault(x =>
                                                 x.SourceQuestionID == SourceQuestionID
                                              && x.SourceOptionID == SourceOptionID
                                              && x.TargetQuestionID == TargetQuestionID
                                              && x.TargetOptionID == id);
                    if (q != null)
                    {
                        ctx.QuestionDependencies.DeleteOnSubmit(q);
                    }
                }
                // Insert the ON Elements
                foreach (decimal id in TargetIDOn)
                {
                    q = ctx.QuestionDependencies.FirstOrDefault(x =>
                                                 x.SourceQuestionID == SourceQuestionID
                                              && x.SourceOptionID == SourceOptionID
                                              && x.TargetQuestionID == TargetQuestionID
                                              && x.TargetOptionID == id);
                    if (q == null)
                    {
                        q = new QuestionDependency();
                        q.SourceQuestionID = SourceQuestionID;
                        q.SourceOptionID = SourceOptionID;
                        q.TargetQuestionID = TargetQuestionID;
                        q.TargetOptionID = id;
                        q.CreateUser = UserName;
                        q.LastUpdateUser = UserName;
                        q.CreateDate = DateTime.Now;
                        q.LastUpdateDate = DateTime.Now;
                        ctx.QuestionDependencies.InsertOnSubmit(q);
                    }
                }
                ctx.SubmitChanges();
            }
        }

