        public List<string> VerifyOptionOKToAdd(string QuestionName, string Abbreviation, string Description)
        {
            decimal QuestionID = GetQuestionID(QuestionName);
            return VerifyOptionOKToAdd(QuestionID, Abbreviation, Description);
        }
        public List<string> VerifyOptionOKToAdd(decimal QuestionID, string Abbreviation, string Description)
        {
            List<string> rMessages = new List<string>();
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                string Message = "";
                if (_AnyAbbrInvalidCharacters(Abbreviation, ref Message) == false)
                {
                    rMessages.Add("Abbreviation (" + Abbreviation + ") Invalid character: " + Message + ".");
                }

                else
                {
                    var x = ctx.Options.FirstOrDefault(y => y.QuestionID == QuestionID && y.Name.ToUpper() == Abbreviation.ToUpper());
                    if (x != null) { rMessages.Add("Abbreviation (" + Abbreviation + ") already set up for " + x.OptionText + "."); }
                    else
                    {
                        x = ctx.Options.FirstOrDefault(y => y.Name.ToUpper() == Abbreviation.ToUpper());
                        if (x != null) { rMessages.Add("Abbreviation (" + Abbreviation + ") is used by some other question (" + x.Question.Name + "-" + x.OptionText + ")."); }

                    }
                    x = ctx.Options.FirstOrDefault(y => y.QuestionID == QuestionID && y.OptionText.ToUpper() == Description.ToUpper());
                    if (x != null) { rMessages.Add("Description (" + Description + ") already set up for " + x.Name + "."); }
                }
            }
            if (rMessages.Count > 0) { rMessages.Insert(0,"Error:");}
            else { rMessages.Insert(0, "Success:"); }
            return rMessages;
        }

        public bool AnyAbbrInvalidCharacters(string Abbreviation, ref string Message)
        {
            if (_AnyAbbrInvalidCharacters(Abbreviation, ref Message) == true)
            {
                Message = "Abbreviation (" + Abbreviation + ") Invalid character: " + Message + ".";
                return true;
            }
            return false;
        }

        private bool _AnyAbbrInvalidCharacters(string dta, ref string Message)
        {
            char[] InvalidCharacters = new char[] { '"', '\'', '[', ']', '\\', '+' };
            foreach (char c in InvalidCharacters)
            {
                if (dta.Contains(c.ToString()) == true)
                {
                    Message += c.ToString();
                }
            }
            return Message.Length > 0;
        }

        public List<string> AddNewAttributeSegment(string QuestionName, string ScanKey, string ABBR, string Value, string Seq)
