        [DataObjectMethod(DataObjectMethodType.Delete)]
        public void DeleteAnswer(decimal AnswerID)
        {
            CompanyDemographics dem = new CompanyDemographics(UserName);
            if (dem.AllowMasterTableDelete == false) { return; }
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                var AnswerToDelete = (from q in ctx.Options where q.OptionID == AnswerID select q).FirstOrDefault();
                if (AnswerToDelete != null)
                {

                    // We can not delete if there are any units that link to this Answer via the carrier, colour, manufacturer, model.
                    var units = from x in ctx.ReceiveDetails where (x.CarrierID == AnswerToDelete.OptionID || x.ColourID == AnswerToDelete.OptionID || x.ManufacturerID == AnswerToDelete.OptionID || x.ModelID == AnswerToDelete.OptionID) select x;
                    if (units != null && units.Count() > 0) { return; }

                    var a1 = from x in ctx.MasterBucketTransactions where x.OptionID == AnswerToDelete.OptionID select x;
                    if (a1 != null) { foreach (MasterBucketTransaction i in a1) { ctx.MasterBucketTransactions.DeleteOnSubmit(i); } }

                    var a2 = from x in ctx.ClientAnswerRestricts where x.OptionID == AnswerToDelete.OptionID select x;
                    if (a2 != null) { foreach (ClientAnswerRestrict i in a2) { ctx.ClientAnswerRestricts.DeleteOnSubmit(i); } }

                    var a3 = from x in ctx.QuestionDependencies where x.SourceOptionID == AnswerToDelete.OptionID select x;
                    if (a3 != null) { foreach (QuestionDependency i in a3) { ctx.QuestionDependencies.DeleteOnSubmit(i); } }

                    var a4 = from x in ctx.QuestionDependencies where x.TargetOptionID == AnswerToDelete.OptionID select x;
                    if (a4 != null) { foreach (QuestionDependency i in a4) { ctx.QuestionDependencies.DeleteOnSubmit(i); } }

                    var a5 = from x in ctx.QuestionDependencies where x.TargetOptionID == AnswerToDelete.OptionID select x;
                    if (a5 != null) { foreach (QuestionDependency i in a5) { ctx.QuestionDependencies.DeleteOnSubmit(i); } }

                    IQueryable<ReceiveDetailItemBulk> bi = from x in ctx.ReceiveDetailItemBulks where x.OptionID == AnswerToDelete.OptionID select x;
                    if (bi != null) { foreach (ReceiveDetailItemBulk i in bi) { ctx.ReceiveDetailItemBulks.DeleteOnSubmit(i); } }

                    var ri = from x in ctx.ReceiveDetailItems where x.OptionID == AnswerToDelete.OptionID select x;
                    if (ri != null) { foreach (ReceiveDetailItem i in ri) { ctx.ReceiveDetailItems.DeleteOnSubmit(i); } }

                    ctx.Options.DeleteOnSubmit(AnswerToDelete);
                    ctx.SubmitChanges();
                }
            }
            return;
        }
        #endregion

    }
