        public StringWriter GetSamsungExtract(string BeginDate, string EndDate)
        {
            StringWriter sb = new StringWriter();
            using (clsLinqDataContext ctx = new clsLinqDataContext())
            {
                var data = ctx.Utility_Extract_Samsung(BeginDate, EndDate);
                foreach (var r in data.OrderBy(x => x.SEQ).ThenBy(x => x.ESN))
