        #region Frozen
        public bool IsThisFrozen(decimal ReceiveDetailID, ref string Message)
        {
            using (clsLinqDataContext ctx = new clsLinqDataContext())
            {
                return IsThisFrozen(ctx, ReceiveDetailID, ref Message);
            }
