        public bool IsThisFrozen(clsLinqDataContext ctx, decimal ReceiveDetailID, ref string Message)
        {
            Message = ctx.IsThisFrozen(ReceiveDetailID, -1, -1);
            if (Message.Length == 0 || Roles.IsUserInRole(UserName, "ThawFreeze") == true)
            {
                return false;
            }
            return true;
        }
        public bool IsThisFrozen(string Data, ref string Message)
        {
            using (clsLinqDataContext ctx = new clsLinqDataContext())
            {
                string Site = "";
                string Project = "";
                string Condition = "";
                string Location = "";
                string SKU = "";
                GetExpectedValues(ctx, Data, ref Site, ref Project, ref Location, ref SKU, ref Condition);
                Message = ctx.IsThisFrozenLookUp(Site, Project, SKU, Location, Condition);
                if (Message.Length == 0 || Roles.IsUserInRole(UserName, "ThawFreeze") == true)
                {
                    return false;
                }
                return true;
            }
        }

        //public void GetIFSKeyValues(string ESN, ref 

        public void GetExpectedValues(clsLinqDataContext ctx, string RawData,  ref string Site, ref string Project, ref string Location, ref string SKU, ref string Condition)
        {
            JsonString ScreenData = new JsonString(RawData, true);
            SKU = ScreenData.GetSKU(ctx);
            decimal ClientLocationID = ScreenData.GetValueDecimal("ClientLocationID", -1);
            string CurProcess = ScreenData.GetValue("CurProcess");
            string Data = "";
            List<JsonStringOptionKeyList> dl = ScreenData.GetQuestionList(ctx, "IFS Conditions");
            if (dl != null && dl.Count > 0)
            {
                foreach (JsonStringOptionKeyList k in dl)
                {
                    Data = ScreenData.GetValue(k.jCoded);
                    if (Data.Length > 0)
                    {
                        Condition = k.Abbr;
                    }
                }
            }
            ClientLocation cl = ctx.ClientLocations.FirstOrDefault(x => x.ClientLocationID == ClientLocationID);
            if (cl == null) { Site = "xxxx"; Project = "xxxx"; }
            else { Site = cl.IFSSite; Project = cl.IFSProject; }

            if (Condition.Length == 0) { Condition = "GEN"; }
            Location = ctx.GetIFSLocation_ExpectedValue(CurProcess, ClientLocationID, Location);
        }
