        public List<ReceiveDetailHobbleList> GetHobbleList(clsLinqDataContext ctx, string Key, string UserName)
        {
            List<ReceiveDetailHobbleList> HobbleList = ctx.ReceiveDetailHobbleLists.Where(x => x.CreateUser == UserName && x.Key.ToUpper() == Key.ToUpper()).OrderBy(x => x.Seq).ThenBy(x => x.ESN).ToList();
            return HobbleList;
