            {
                short UDPick = IFSDirective("Inv_Adj");
                ctx.IFS_GenerateInvtTran_B(rd.ReceiveDetailID, UDPick, rd.SKU, rd.IFSLocation, rd.IFSCondition, rd.SKU, rd.IFSLocation, rd.IFSCondition, UserName, -1, ReasonCode);
