        public bool AdjustIn(decimal ReceiveDetailID, string Location, string Condition, string ReasonCode, string Reason, bool TellIFS, ref string Message)
        {
            using (clsLinqDataContext ctx = new clsLinqDataContext())
            {
                ReceiveDetail rd = ctx.ReceiveDetails.FirstOrDefault(x => x.ReceiveDetailID == ReceiveDetailID);
                if (rd == null) { Message = "Device not found"; return false; }
                return AdjustIn(ctx, rd, Location, Condition, ReasonCode, Reason,TellIFS, ref Message);
            }
        }
        public bool AdjustIn(clsLinqDataContext ctx, ReceiveDetail rd, string Location,string Condition, string ReasonCode, string Reason, bool TellIFS, ref string Message)
        {
            if (rd != null)
            {
                UpdateESNAttribute(ctx, rd.ReceiveDetailID, "IFS Conditions", Condition);
                UpdateESNAttribute(ctx, rd.ReceiveDetailID, "AdjustInReason  ", Reason);


                ctx.Refresh(RefreshMode.OverwriteCurrentValues, rd);
                rd.IFSLocation = Location;
                rd.SKU = GetSku(rd.ManufacturerID, rd.ModelID, rd.CarrierID, rd.ColourID);
                rd.isIFSLocked = true;
                rd.ISFTransactionDirective = IFSDirective("Ignore");
                ctx.SubmitChanges();
                ctx.Refresh(RefreshMode.OverwriteCurrentValues, rd);
                rd.isIFSLocked = false;
                rd.Version = "000";
                rd.LastUpdateDate = DateTime.Now;
                rd.LastUpdateUser = UserName;
                ctx.SubmitChanges();
                if (TellIFS == true)
                {
                    short UDPick = IFSDirective("Inv_Adj");
                    ctx.IFS_GenerateInvtTran_B(rd.ReceiveDetailID, UDPick, rd.SKU, rd.IFSLocation, rd.IFSCondition, rd.SKU, rd.IFSLocation, rd.IFSCondition, UserName, -1, ReasonCode);
                }
                return true;
            }
            return false;
        }

