        public bool IFSMOVEShippedC1CONShipped(decimal ReceiveDetailID,string Courier_Out, string Carton_No, string Out_Bound_Waybill_S, string ShipTo, string PO_No, string Vendor_RMA, string Unit_Destination, string Replacement_SKU, string RQ4_Transfer_Out,  ref string Message)
        {
            using (clsLinqDataContext ctx = new clsLinqDataContext())
            {
                ReceiveDetail rd = ctx.ReceiveDetails.FirstOrDefault(x => x.ReceiveDetailID == ReceiveDetailID);
                if (rd == null) { return false; }
                return IFSMOVEShippedC1CONShipped(ctx, rd, Courier_Out, Carton_No, Out_Bound_Waybill_S, ShipTo, PO_No, Vendor_RMA, Unit_Destination, Replacement_SKU, RQ4_Transfer_Out, ref Message);
