        public bool IFSMOVEShippedC1CONShipped(clsLinqDataContext ctx, ReceiveDetail rd,string Courier_Out, string Carton_No, string Out_Bound_Waybill_S
                                             , string ShipTo, string PO_No, string Vendor_RMA, string Unit_Destination, string Replacement_SKU, string RQ4_Transfer_Out, ref string Message)
        {
            if (rd != null)
            {
                string IFSLocation = "";
                if (rd.IFSLocation != null) { IFSLocation = rd.IFSLocation; }

                UpdateESNAttribute_Blank(ctx, rd.ReceiveDetailID, "Bin");
                UpdateESNAttribute(ctx, rd.ReceiveDetailID, "Location", "None");

                UpdateESNAttribute(ctx, rd.ReceiveDetailID, "Courier Out", Courier_Out);
                UpdateESNAttribute(ctx, rd.ReceiveDetailID, "Carton No", Carton_No);
                UpdateESNAttribute(ctx, rd.ReceiveDetailID, "Out-Bound Waybill-S", Out_Bound_Waybill_S);
                UpdateESNAttribute(ctx, rd.ReceiveDetailID, "ShipTo", ShipTo);
                UpdateESNAttribute(ctx, rd.ReceiveDetailID, "PO No", PO_No);
                UpdateESNAttribute(ctx, rd.ReceiveDetailID, "Vendor RMA", Vendor_RMA);
                UpdateESNAttribute(ctx, rd.ReceiveDetailID, "Unit Destination", Unit_Destination);
                UpdateESNAttribute(ctx, rd.ReceiveDetailID, "Replacement SKU", Replacement_SKU);
                UpdateESNAttribute(ctx, rd.ReceiveDetailID, "RQ4 Transfer Out", RQ4_Transfer_Out);

                ////////////////////////////////////////////////////////////////////////////////////////////
                // As Per Jody's Instruction June 1, 2012 (Add SwapIMEI process to Shipping)
                ////////////////////////////////////////////////////////////////////////////////////////////
                //rdm.SM.OrderShipped(ctx, rec.ReceiveDetailID, -1, rec.ClientLocationID, (decimal)rec.ProjectID, CurrentProcessID, CurUserName);
                FileTransferLogManager ftlm = new FileTransferLogManager(UserName);
                ftlm.AddNewTransferLogShipped_OnlyIfReceived(ctx, rd);
                RecordAssignedPartsShipped(ctx, rd.ReceiveDetailID);
                IDC_LocationLogManager logman = new IDC_LocationLogManager(UserName);
                logman.RecordShippedRecord(ctx, rd.ESN, rd.ReceiveDetailID, "", "", "");

                if (ProcessShippedID < 1)
                {
                    Process P = ctx.Processes.FirstOrDefault(x => x.Name.ToUpper() == "SHIPPING");
                    if (P != null) { ProcessShippedID = P.ProcessID; ProcessShippedName = P.Name; }
                }
                if (ProcessShippedID > 0)
                {
                    ReceiveDetailProcessLog P = new ReceiveDetailProcessLog();
                    P.ReceiveDetailID = rd.ReceiveDetailID;
                    P.CreateUser = UserName;
                    //P.CreateDate = DateTime.Now;
                    P.ProcessID = ProcessShippedID;
                    P.MiscText = "";
                    P.ProcessText = ProcessShippedName;
                    ctx.ReceiveDetailProcessLogs.InsertOnSubmit(P);
                    ctx.SubmitChanges();
                }


                short UDPick = IFSDirective("CO_PICK");
                ctx.IFS_GenerateInvtTran_B(rd.ReceiveDetailID, UDPick, rd.SKU, IFSLocation, rd.IFSCondition, rd.SKU, IFSLocation, rd.IFSCondition, UserName, -1, "");
                AdvanceESNVersion(ctx, rd.ESN, UserName, "Upload Shipping");
                
                
                /////////////////////////////////////////////////////////////////////
                // This needs to happen after the AdvanceESN because if the swap is done first
                //      The Advance does not find it.
                try { bool isSwapped = SwapIMEI(ctx, rd.ReceiveDetailID); }
                catch (Exception ex)
                {
                }
                /////////////////////////////////////////////////////////////////////////////////////////
                // Bring Back From MSC if it is a MSC Unit
                CloneFromMSC(ctx, rd.ReceiveDetailID, (decimal)rd.ProjectID, GetReceiveDetailCurrentProcessID(rd.ReceiveDetailID));
                Message = "Shipped";
                return true;
            }
            Message = "Error: Device Not Found";
            return false;
        }


        public void RecordAssignedPartsShipped(clsLinqDataContext ctx, decimal ReceiveDetailID)
        {
            JimErrorLogManager logManager = new JimErrorLogManager(UserName, "RecordAssignedPartsShipped");
            logManager.ReportMessage("Step 0 Start of attribute list save:" + ReceiveDetailID.ToString());
            ReceiveDetail rd = ctx.ReceiveDetails.FirstOrDefault(x => x.ReceiveDetailID == ReceiveDetailID);
            if (rd == null) { return; }
            MasterPartManager pm = new MasterPartManager(UserName);
            foreach (ReceiveDetailItem item in rd.ReceiveDetailItems)
            {
                if (item.Option.Question.Name.Length > 4 && item.Option.Question.Name.Substring(0, 5).ToUpper() == "PART ")
                {
                    string rValue = "";
                    logManager.ReportMessage("MasterPartsTechAssignedLog_Shipped(" + ReceiveDetailID.ToString() + "," + item.ReceiveDetailItemID.ToString() + ")");
                    rValue = pm.MasterPartsTechAssignedLog_Shipped(ReceiveDetailID, item.ReceiveDetailItemID);
                    logManager.ReportMessage("Return Value:" + rValue);
                }
            }
        }

