        public bool IsPODataValid(string originalData, ref decimal IFSPurchaseOrderDetailID, ref string NewData, ref string rMessage)
        {
            using (clsLinqDataContext ctx = new clsLinqDataContext())
            {
                rMessage = "";
                NewData = originalData;
                IFSPurchaseOrderDetailID = -1;
                decimal? id = -1;
                JsonString ScreenData = new JsonString(originalData, true);
                string SKU = ScreenData.GetSKU(ctx);
                string Vendor = ScreenData.GetTextData(ctx, "IFS Vendor");
                string PONumber = ScreenData.GetTextData(ctx, "IFS PO Number");
                string POLine = ScreenData.GetTextData(ctx, "IFS PO Line Number");
                string POLneCondition = ScreenData.GetTextData(ctx, "IFS Conditions");
                string POCost = "";
                string POConditionABBR = "";
                if (SKU.Length == 0) { rMessage = "Error, invalid sku"; return false; }

                if (Vendor.Length == 0) { rMessage = "Error, invalid IFS Supplier"; return true; }                    // We do not want to stop here, just move on.
                if (PONumber.Length == 0) { rMessage = "Error, invalid IFS PO Number"; return true; }                 // We do not want to stop here, j ust move on.

                //string TestSQU = "ACES100ATTBLK";
                //string TestSQU2 = "ACES100ATTBLK";
                //ctx.UpdateIFSPO(TestSQU, Vendor, PONumber, ref id, ref POLine, ref POCost, ref POConditionABBR, ref rMessage);
                //ctx.UpdateIFSPO(SKU, Vendor, PONumber, ref id, ref POLine, ref POCost, ref POConditionABBR, ref rMessage);
                ctx.IFS_UpdateIFSPO(SKU, Vendor, PONumber, POLine, ref id, ref POLine, ref POCost, ref POConditionABBR, ref rMessage);

                if (rMessage.Length == 0) { return true; }    // there was no po found, let it calculate its own

                if (rMessage.Substring(0, 5).ToUpper() == "ERROR:MORE THAN ONE CONDITION LINE") {
                    rMessage = rMessage + ":" + ScreenData.GetAttributeKeyByValue("IFS PO Line Number", "");
                    ScreenData.SetAttributeValue("IFS PO Line Number", "");      // Make Room for them to send the data back
                    NewData = ScreenData.ToString();
                    return false; 
                }

                if (rMessage.Substring(0, 5).ToUpper() == "ERROR") { return false; }
                ScreenData.SetAttributeValue("IFS PO Line Number", POLine);
                ScreenData.SetAttributeValue("IFS PO Unit Cost", POCost);
                ScreenData.SetAttributeDDByABBR("IFS Conditions", POConditionABBR);
                NewData = ScreenData.ToString();
                //string yNewData = ScreenData.dList.ToString();
                //NewData = ScreenData.GetNewDataString();
                return true;
            }
        }
