        public string UtilityChangeIMEI(decimal ReceiveDetailID, string Version, string NewIMEI)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                ReceiveDetail rd = ctx.ReceiveDetails.FirstOrDefault(x => x.ReceiveDetailID == ReceiveDetailID);
                if (rd != null)
                {
                    return UtilityChangeIMEI(ctx, rd, NewIMEI);
                }
                return "IMEI Not found";
            }
        }
        public string UtilityChangeIMEI(string OriginalIMEI, string Version, string NewIMEI)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                ReceiveDetail rd = ctx.ReceiveDetails.FirstOrDefault(x => x.ESN == OriginalIMEI && x.Version == Version);
                if (rd != null)
                {
                    return UtilityChangeIMEI(ctx, rd, NewIMEI);
                }
                return "IMEI Not found";
            }
        }
        public string UtilityChangeIMEI(clsLinqDataContext ctx, ReceiveDetail rd, string NewIMEI)
        {
            //  Is there one there now?
            ReceiveDetail newone = ctx.ReceiveDetails.FirstOrDefault(x => x.ESN == NewIMEI && x.Version == rd.Version);
            if (newone != null)
            {
                return "IMEI NOT Changed. Device already exists!";
            }
            string OriginalIMEI = rd.ESN;
            rd.ESN = NewIMEI;
            rd.LastUpdateDate = DateTime.Now;
            rd.LastUpdateUser = UserName;

            ReceiveDetailIMEIChangedLog ChangeLog = new ReceiveDetailIMEIChangedLog();
            ChangeLog.CreateUser = UserName;
            ChangeLog.NewIMEI = NewIMEI;
            ChangeLog.OriginalIMEI = OriginalIMEI;
            ChangeLog.ReceiveDetailID = rd.ReceiveDetailID;
            ctx.ReceiveDetailIMEIChangedLogs.InsertOnSubmit(ChangeLog);
            ctx.SubmitChanges();
            return "IMEI changed from " + OriginalIMEI + " To " + NewIMEI;
        }

