        #region Translations
        public string TranslateGrade(string Grade)
        {
            string rText = "";
            switch (Grade.ToUpper())
            {
                case "A":
                    rText = "A";
                    break;
                case "B":
                    rText = "B";
                    break;
                case "C":
                    rText = "C";
                    break;
                case "NEW":
                    rText = "N";
                    break;
                case "BLANK":
                case "":
                    rText = "NG";
                    break;
                default:
                    rText = Grade;
                    break;
            }
            return rText;
        }
