            }
        }
        public string GetKittingDateCoded(clsLinqDataContext ctx, decimal ReceiveDetailID)
        {
            string rValue = "";
            var dta = (from x in ctx.ReceiveDetailProcessLogs where x.ReceiveDetailID == ReceiveDetailID && x.Process.Name.ToUpper() == "KITTING" select x).OrderByDescending(x=> x.CreateDate).FirstOrDefault();
            if (dta == null) { return rValue; }
            int Year = dta.CreateDate.Year;
            int Month = dta.CreateDate.Month;
            int Day = dta.CreateDate.Day;
            string sMonth = "";
            if (Month == 1) { sMonth = "A"; }
            if (Month == 2) { sMonth = "B"; }
            if (Month == 3) { sMonth = "C"; }
            if (Month == 4) { sMonth = "D"; }
            if (Month == 5) { sMonth = "E"; }
            if (Month == 6) { sMonth = "F"; }
            if (Month == 7) { sMonth = "G"; }
            if (Month == 8) { sMonth = "H"; }
            if (Month == 9) { sMonth = "I"; }
            if (Month == 10) { sMonth = "J"; }
            if (Month == 11) { sMonth = "K"; }
            if (Month == 12) { sMonth = "L"; }
            rValue = sMonth + Year.ToString() + Day.ToString() + "-" + ReceiveDetailID.ToString();
            return rValue;
        }


        #region IDC Stuff


        public string UpdateESN_IDC(string ESN, string Location, string IDC_BIN)
        {
            if (ESN.Length == 0 && IDC_BIN.Length == 0) { return "No ESN/IMEI/Bin Number Given"; }
            if (Location.Length == 0) { return "No Location Given"; }
            using (clsLinqDataContext ctx = new clsLinqDataContext())
            {
                if (ESN.Length > 0) { return UpdateESN_IDC(ctx, ESN, Location, IDC_BIN); }
                var logs = (from x in ctx.LocationLogs where x.IDC_Bin == IDC_BIN && (x.Status == "COMPLETE" || x.Status == "FOR SALE") select x).ToList();
                foreach (LocationLog l in logs)
                {
                    UpdateESN_IDC(ctx, l.ESN, Location, IDC_BIN);
                }
                return "IDCBIN Updated";
            }
        }

        public string UpdateESN_IDC(clsLinqDataContext ctx, string ESN, string Location, string IDC_BIN)
        {
            if (ESN.Length == 0 && IDC_BIN.Length == 0) { return "No ESN/IMEI/Bin Number Given"; }
            if (Location.Length == 0) { return "No Location Given"; }
            string prMessage = "";
            string WayBill = "";
            string MasterClientName = "";
            string MasterClientID = "-1";
            string Courier = "";
            decimal ReceiveDetailID = -1;
            string Status = "FOR SALE";
            LocationLog log = ctx.LocationLogs.OrderByDescending(x => x.LocationLogID).FirstOrDefault(x => x.ESN == ESN && (x.Status == "COMPLETE" || x.Status == "FOR SALE"));
            if (log == null)
            {
                return ESN + ": Non Sale ESN";
            }

            WayBill = log.WayBillNumber;
            MasterClientID = log.ClientID.ToString();
            MasterClientName = log.ClientName;
            ReceiveDetailID = log.ReceiveDetailID;

            IDC_LocationLogManager logman = new IDC_LocationLogManager(UserName);
            logman.Add(ctx, ESN, IDC_BIN, WayBill, Location, MasterClientID, MasterClientName, Courier, ReceiveDetailID, UserName, "", Status);
            return prMessage;
        }

        public string UpdateESN_LocationAndBin_Prereceive_IDC(string ESNNumber, string Location, string IDC_BIN, string IP)
        {
            if (ESNNumber.Length == 0 && IDC_BIN.Length == 0) { return "No ESN/IMEI/Bin Number Given"; }
            if (Location.Length == 0) { return "No Location Given"; }
            List<string> ProcessedIMEIRecords = new List<string>();

            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                if (ESNNumber.Length > 0)
                {
                    LocationLog d = ctx.LocationLogs.OrderByDescending(x=> x.LocationLogID).FirstOrDefault(x => x.ESN == ESNNumber && x.Status == "PREREC");
                    return UpdateESN_LocationAndBin_Prereceive_IDC(ctx, ESNNumber, Location, IDC_BIN, IP, d);
                }
                else
                {
                    int count = 0;
                    //var data = (from x in ctx.LocationLogs where x.IDC_Bin == IDC_BIN && x.ESN == ESNNumber && x.ReceiveDetailID < 1 select x).ToList();
                    //var data = (from x in ctx.LocationLogs where x.IDC_Bin == IDC_BIN && x.ReceiveDetailID < 1 && x.Status == "PREREC" select x).ToList();
                    var data = (from x in ctx.LocationLogs where (x.ReceiveDetailID == null || x.ReceiveDetailID == -1) && x.IDC_Bin == IDC_BIN && x.Status == "PREREC" select x).ToList();
                    foreach (LocationLog d in data)
                    {
                        // If statement put in to only process an IMEI once.
                        if (ProcessedIMEIRecords.Contains(d.ESN) == false)
                        {
                            count++;
                            UpdateESN_LocationAndBin_Prereceive_IDC(ctx, d.ESN, Location, IDC_BIN, IP, d);
                            ProcessedIMEIRecords.Add(d.ESN);
                        }

                    }
                    return count.ToString() + " records batch updated!";
                }
            }
        }
        public string UpdateESN_LocationAndBin_Prereceive_IDC(clsLinqDataContext ctx, string ESN, string Location, string IDC_BIN, string IP, LocationLog log )
        {
            if (ESN.Length == 0 && IDC_BIN.Length == 0) { return "No ESN/IMEI/Bin Number Given"; }
            if (Location.Length == 0) { return "No Location Given"; }
            string prMessage = "";
            string WayBill = "";
            string MasterClientName = "";
            string MasterClientID = "-1";
            string Courier = "";
            decimal ReceiveDetailID = -1;
            string Status = "TRANSIT";

            // Look to see that we have a PreRec record that is still open  (Open means it has not been received yet, There is no ReceivedetailID on the record.)
            //LocationLog log = ctx.LocationLogs.OrderByDescending(x => x.LocationLogID).FirstOrDefault(x => x.ESN == ESN && x.Status == "PREREC" && ReceiveDetailID < 1);
            if (log.ReceiveDetailID > 1) 
            {
                LocationLog alog = ctx.LocationLogs.OrderByDescending(x => x.LocationLogID).FirstOrDefault(x => x.ReceiveDetailID == log.ReceiveDetailID && x.Status == "ACTIVE");
                if (alog != null)
                {
                    IDC_BIN = alog.IDC_Bin;
                }
                //return "Error:No open PreRec record found!"; 
            }         // Open means there is no Receivedetail Attached to it.

            // If there is a 000 record, then we are dealing with an "ACTIVE" status.
            ReceiveDetail rd = ctx.ReceiveDetails.FirstOrDefault(x => x.ESN == ESN && x.Version == "000");
            if (rd != null)
            {
                Status = "ACTIVE";
                ReceiveDetailID = rd.ReceiveDetailID;
            }
            if (Status == "TRANSIT")
            {
                UpdateESNPreReceiveAttribute(ctx, ESN, "Location", Location);
                //UpdateESNPreReceiveAttribute(ctx, ESN, "IDC Bin", IDC_BIN);
            }
            if (Status == "ACTIVE")
            {
                UpdateESNAttribute(ctx, ReceiveDetailID, "Location", Location);
                //UpdateESNAttribute(ctx, ReceiveDetailID, "Bin", IDC_BIN);
            }
            // get an earlier one so I have the proper waybill, client etc values for the next to add log transaction
             if (log != null)
            {
                WayBill = log.WayBillNumber;
                MasterClientID = log.ClientID.ToString();
                MasterClientName = log.ClientName;
                if (ReceiveDetailID < 1)
                {
                    ReceiveDetailID = log.ReceiveDetailID;
                }
            }
            IDC_LocationLogManager logman = new IDC_LocationLogManager(UserName);
            logman.Add(ctx, ESN, IDC_BIN, WayBill, Location, MasterClientID, MasterClientName, Courier, ReceiveDetailID, UserName, IP, Status);
            prMessage = ESN + " Updated";
            return prMessage;
        }

        public string UpdateESN_LocationAndBinValue_IDC(string ESNNumber,string Location, string Bin, string IP)
        {
            if (ESNNumber.Length == 0 && Bin.Length == 0) { return "No ESN/IMEI/Bin Number Given"; }
            if (Location.Length == 0) { return "No Location Given"; }

            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                string WayBill = "";
                string MasterClientName = "";
                string MasterClientID = "-1";
                string Courier = "";
                string Status = "ACTIVE";


                if (ESNNumber.Length > 0)
                {
                    ReceiveDetail d = (from x in ctx.ReceiveDetails where x.ESN == ESNNumber && x.Version == "000" select x).FirstOrDefault();
                    if (d == null) { return "ESN not found"; }
                    else 
                    {
                        UpdateESNAttribute(ctx, d.ReceiveDetailID, "Location", Location);
                        // get an earlier one so I have the proper waybill, client etc values for the next to add log transaction
                        LocationLog log = ctx.LocationLogs.OrderByDescending(x => x.LocationLogID).FirstOrDefault(x => x.ESN == d.ESN && x.Status == "PREREC");
                        if (log != null)
                        {
                            WayBill = log.WayBillNumber;
                            MasterClientID = log.ClientID.ToString();
                            MasterClientName = log.ClientName;
                        }
                        else
                        {
                            MasterClientID = d.ClientLocation.ClientID.ToString();
                            MasterClientName = d.ClientLocation.Client.CompanyName;
                        }
                        IDC_LocationLogManager logman = new IDC_LocationLogManager(UserName);
                        logman.Add(ctx, d.ESN, Bin, WayBill, Location, MasterClientID, MasterClientName, Courier, d.ReceiveDetailID, UserName, IP, Status);
                        return ESNNumber + " updated"; 
                    }
                }
                else
                {
                    int count = 0;
                    var data = (from x in ctx.ReceiveDetailItems where x.Value == Bin && x.Option.Question.Name == "Bin" && x.ReceiveDetail.Version == "000" select x.ReceiveDetail).ToList();
                    foreach (ReceiveDetail d in data)
                    {
                        count++;
                        UpdateESNAttribute(ctx, d.ReceiveDetailID, "Location", Location);
                        // get an earlier one so I have the proper waybill, client etc values for the next to add log transaction
                        LocationLog log = ctx.LocationLogs.OrderByDescending(x => x.LocationLogID).FirstOrDefault(x => x.ESN == d.ESN && x.Status == "PREREC");
                        if (log != null)
                        {
                            WayBill = log.WayBillNumber;
                            MasterClientID = log.ClientID.ToString();
                            MasterClientName = log.ClientName;
                        }
                        IDC_LocationLogManager logman = new IDC_LocationLogManager(UserName);
                        logman.Add(ctx, d.ESN, Bin, WayBill, Location, MasterClientID, MasterClientName, Courier, d.ReceiveDetailID, UserName, IP, Status);
                    }
                    return count.ToString() + " records batch updated!"; 
                }
            }
        }

