        public void ProcessIFSUpdates(decimal ReceiveDetailID, string Process)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                ProcessIFSUpdates(ctx, ReceiveDetailID, Process);
                return;
            }
        }
        public void ProcessIFSUpdates(clsLinqDataContext ctx, decimal ReceiveDetailID, string Process)
        {
            ctx.Update_IMEI_Unlock(ReceiveDetailID);
            string IFSCondition = ctx.GetIFSCondtion_B(ReceiveDetailID);
            if (IFSCondition.ToUpper() == "XXX" || IFSCondition.Trim().Length == 0)
            {
                // We want to do this update before we open the record.
                IFSCondition = "GEN";
                UpdateESNAttribute(ctx, ReceiveDetailID, "IFS Conditions", IFSCondition);
            }
            ReceiveDetail rd = ctx.ReceiveDetails.FirstOrDefault(x => x.ReceiveDetailID == ReceiveDetailID);
            if (rd != null)
            {
                //bool SaveData = false;
                rd.ISFTransactionDirective = -1;
                string IFSLocation = ctx.GetIFSLocation_B(ReceiveDetailID, Process, rd.ClientLocationID, rd.IFSLocation);
                string IFSSKU = ctx.GetIFSSKU(ReceiveDetailID);
                if (rd.IFSLocation == null) { rd.IFSLocation = ""; }
                if (rd.IFSCondition == null) { rd.IFSCondition = ""; }
                if (rd.SKU == null) { rd.SKU = ""; }

                if (rd.IFSLocation != IFSLocation || (Process.Length > 7 && Process.Substring(0, 8).ToUpper() == "SHIPPING")) {
                    if (IFSLocation.Length == 0 || (Process.Length > 11 && Process.ToUpper() == "SHIPPINGNOCO")) { rd.ISFTransactionDirective = IFSDirective(ctx, "DeviceAdjustOut"); }
                    else if (IFSLocation.Length == 0 || (Process.Length > 7 && Process.Substring(0, 8).ToUpper() == "SHIPPING")) { rd.ISFTransactionDirective = IFSDirective(ctx, "CO_Pick"); }
                    //rd.IFSLocation = IFSLocation; SaveData = true; 
                }

                if (rd.IFSLocation != IFSLocation) { rd.IFSLocation = IFSLocation; }
                if (rd.IFSCondition != IFSCondition) { rd.IFSCondition = IFSCondition; }
                if (rd.SKU != IFSSKU) { rd.SKU = IFSSKU; }

                if (Process.Length >= 7 && Process.Substring(0, 7).ToUpper() == "RECEIVE")
                {
                    string rDirectiveName = ctx.GetIFSPoType(ReceiveDetailID);
                    // Inv_Adj for client owned stock
                    // PO_Initiate for redial retail
                    // PO_Receipt for Redail
                    rd.ISFTransactionDirective = IFSDirective(ctx, rDirectiveName);
                    ctx.SubmitChanges();
                    ctx.IFS_GenerateInvtTran_B(rd.ReceiveDetailID, rd.ISFTransactionDirective, rd.SKU, rd.IFSLocation, rd.IFSCondition, rd.SKU, rd.IFSLocation, rd.IFSCondition, UserName, -1, "");
                }
                ctx.SubmitChanges();
                if (Process.Length > 7 && Process.Substring(0, 8).ToUpper() == "SHIPPING")
                {
                    //ctx.IFS_GenerateInvtTran_B(rdx.ReceiveDetailID, rdm.IFSDirective(ctx, "PO_Receipt"), rdx.SKU, rdx.IFSLocation, rdx.IFSCondition, rdx.SKU, rdx.IFSLocation, rdx.IFSCondition, username, -1, "");
                    ctx.IFS_GenerateInvtTran_B(rd.ReceiveDetailID, IFSDirective(ctx, "CO_Pick"), rd.SKU, rd.IFSLocation, rd.IFSCondition, rd.SKU, rd.IFSLocation, rd.IFSCondition, UserName, -1, "");
                }
            }
        }


