        public List<string> getIMEIsInLocation_FromSitProjectSkuLocationCondition(clsLinqDataContext ctx, string Site, string Project, string Sku, string FromIFSLocation, string Condition, string ToLocation)
        {
            List<string> newlist = new List<string>();
            if (Site.Length < 1) { return newlist; }
            if (Project.Length < 1) { return newlist; }
            if (Sku.Length < 1) { return newlist; }
            if (FromIFSLocation.Length < 1) { return newlist; }
            if (Condition.Length < 1) { return newlist; }
            if (ToLocation.Length < 1) { return newlist; }
            var cond = ctx.Options.FirstOrDefault(x => x.Question.Name == "IFS Conditions" && x.OptionText == Condition);
            if (cond == null) { return newlist; }

            DeviceInventoryManager im = new DeviceInventoryManager(UserName);
            if (im.IsLocationValid(ctx, ToLocation) == false) { return newlist; }

            var Data = from x in ctx.ReceiveDetails
                       where x.Version == "000" && x.ClientLocation.IFSSite == Site && x.ClientLocation.IFSProject == Project && x.SKU == Sku && x.IFSLocation == FromIFSLocation && x.IFSCondition == cond.Name
                       select x.ESN;
            return Data.ToList();

        }
        
       
