        public string IFSBinUpdate_ESN(clsLinqDataContext ctx, string ESN, string BinNumber, string IP, ref decimal OutReceiveDetailID)
        {
            OutReceiveDetailID = -1;
            if (ESN.Length < 1) { return "Error: ESN not supplied"; }
            ReceiveDetail d = ctx.ReceiveDetails.FirstOrDefault(x => x.ESN == ESN && x.Version == "000");
            if (d == null) { return "Error:" + ESN + " not found"; }
            OutReceiveDetailID = d.ReceiveDetailID;
            string Message = "";
            if (IsThisFrozen(d.ReceiveDetailID, ref Message) == true) { return Message; }
            return IFSBinUpdate_ESN(ctx, BinNumber, d);
        }
        private string IFSBinUpdate_ESN(clsLinqDataContext ctx, string BinNumber, ReceiveDetail d)
        {
            string FromBin = "";
            ReceiveDetailItem rdi = ctx.ReceiveDetailItems.FirstOrDefault(x => x.Option.Question.Name.ToUpper() == "BIN" && x.ReceiveDetailID == d.ReceiveDetailID);
            if (rdi != null && rdi.Value != null) { FromBin = rdi.Value; }
            decimal RDID = d.ReceiveDetailID;
            UpdateESNAttribute(ctx, RDID, "Bin", BinNumber);
            return d.ESN + " Bin from:" + FromBin + " to " + BinNumber;
        }


