        public string UnSwapDevice(string ESN, string Version, string IP, ref decimal OutReceicveDetailID)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                return UnSwapDevice(ctx, ESN, Version, IP, ref OutReceicveDetailID);
            }
        }
        public string UnSwapDevice(clsLinqDataContext ctx, string SourceESN, string Version, string IP, ref decimal OutReceicveDetailID)
        {
            string TargetESN = "";
            decimal TargetRDID = -1;
            string Message = "";
            OutReceicveDetailID = -1;
            if (SourceESN.Length < 1) { return "Error: ESN not supplied"; }
            // Make sure we have the original
            ReceiveDetail Source = ctx.ReceiveDetails.FirstOrDefault(x => x.ESN == SourceESN && x.Version == "000");
            if (Source == null) { return "Error:" + SourceESN + " version:000 Not Found"; }
            OutReceicveDetailID = Source.ReceiveDetailID;
            if (IsThisFrozen(Source.ReceiveDetailID, ref Message) == true) { return "Error:" + SourceESN + " " + Message; }

            // Make sure this is a swapped device
            ReceiveDetailIMEISwappedLog SourceSwapLog = ctx.ReceiveDetailIMEISwappedLogs.FirstOrDefault(x => x.ReceiveDetailID == Source.ReceiveDetailID);
            if (SourceSwapLog == null) { return "Error:" + SourceESN + " swap record Not Found"; }
            // Make sure we found the correct swapped log record
            if (SourceSwapLog.IMEISwappedIn != Source.ESN) { return "Error:" + SourceESN + " Does not match swap record " + SourceSwapLog.IMEISwappedIn; }
            // Get the ESN that it Used to be
            TargetESN = SourceSwapLog.IMEISwappedOut;



            // Delete the swap log record
            ctx.ReceiveDetailIMEISwappedLogs.DeleteOnSubmit(SourceSwapLog);
            ctx.SubmitChanges();
            // put the source back to what it was --- TargetESN
            ctx.Update_ReceiveDetailESN(Source.ReceiveDetailID, TargetESN, UserName);

            // There may be times we dont have a second IMEI. EG the replacement came from outside. -- IT IS OK
            // OTHERWISE we want to go to the other one and flip it back
            ReceiveDetailIMEISwappedLog TargetSwapLog = ctx.ReceiveDetailIMEISwappedLogs.FirstOrDefault(x => x.IMEISwappedIn == SourceSwapLog.IMEISwappedOut);
            //if (TargetSwapLog != null) { return "Error:" + SourceESN + " swap record Not Found"; }
            if (TargetSwapLog != null)
            {
                TargetRDID = TargetSwapLog.ReceiveDetailID;
                // Delete the swap log record
                ctx.ReceiveDetailIMEISwappedLogs.DeleteOnSubmit(TargetSwapLog);
                ctx.SubmitChanges();
                // put the source back to what it was --- TargetESN
                ctx.Update_ReceiveDetailESN(TargetRDID, SourceESN, UserName);
                UpdateESNAttribute(TargetRDID, "ShipTo", "unswap:");
                return "Success: Both Devices(" + SourceESN + "/" + TargetESN + ") returned to original IMEI settings";
            }
            return "Success:" + SourceESN + " Device IMEI reset back";
        }

