        private string IFSUpdateESNLocation(clsLinqDataContext ctx, string Location, ReceiveDetail d, bool TellIFS)
        {
            bool isLocked = false;
            IFSLocation toLocation = new IFSLocation(Location);
            if (toLocation.isValid == false) { return "To Location:" + Location + " is not valid"; }
            if (toLocation.IsThisFrozen(UserName) == true) { return "Error:" + toLocation.FrozemMessage; ; }
            string FromLocation = d.IFSLocation;
            isLocked = d.isIFSLocked == null ? false : (bool)d.isIFSLocked;
            d.IFSLocation = toLocation.AssignThisLocationText();
            d.LastUpdateDate = DateTime.Now;
            d.LastUpdateUser = UserName;
            if (TellIFS == false) { d.isIFSLocked = true; }
            ctx.SubmitChanges();
            if (TellIFS == false) { d.isIFSLocked = isLocked; }
            ctx.SubmitChanges();
            return d.ESN + " moved from:" + FromLocation + " to " + Location;
        }
