        public string UpdateESN_LocationValue_ByID(string ESNNumber, decimal NewLocationID, string AttributeValue)
        {
            if (ESNNumber.Length == 0) { return "No ESN/IMEI Number Given"; }
            if (NewLocationID < 1) { return "No New Location Given"; }

            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                ReceiveDetail d = (from x in ctx.ReceiveDetails where x.ESN == ESNNumber && x.Version == "000" select x).FirstOrDefault();
                if (d == null)
                {
                    return "ESN not found";
                }
                else
                {
                    string l = GetESNAttribute(d.ReceiveDetailID, "Location");
                    UpdateESNAttribute(ctx, d.ReceiveDetailID, NewLocationID, AttributeValue);
                    return ESNNumber + " Updated. Moved from:" + l + " to " + AttributeValue;
                }
            }
        }
