        public List<AvailableStockDataDetail_Report> GetAvailableStock_Linq_ReortDetail(string Manufacturer, string Model, string Colour, string Grade)
        {
            using (clsLinqDataContext ctx = new clsLinqDataContext())
            {
                var Project = ctx.Projects.FirstOrDefault(x => x.Name.ToUpper() == Config.ProjectStockForSaleFrom);
                decimal StockForSaleProjectID = -1;
                if (Project != null) { StockForSaleProjectID = Project.ProjectID; }
                string ReceiveDateDate = "";

                //var Reserved = ctx.ReservedAvailableStocks.Where(x => x.isOpen == true).GroupBy(x => x.Grade).Select(x => new AvailableStockDataDetail("", "", "", "", x.Key, 0, x.Sum(y => y.Quantity))).ToList();
                var Reserved = ctx.OrderDetails.Where(x => x.OrderHeader.OrderStatus.Status.ToUpper() != "TRASH"
                                                        && x.OrderHeader.OrderStatus.Status.ToUpper() != "DONE"
                                                        && x.OrderHeader.ProjectID == StockForSaleProjectID);
                var Reserved1 = (from d in Reserved
                                 let manufacturer = Manufacturer.Length == 0 ? "" : d.Manufacturer.Length > 0 ? d.Manufacturer : "Blank"
                                 let model = Model.Length == 0 ? "" : d.Model.Length > 0 ? d.Model : "Blank"
                                 let colour = Colour.Length == 0 ? "" : d.Colour.Length > 0 ? d.Colour : "Blank"
                                 let carrier = d.Carrier.Length > 0 ? d.Carrier : "Blank"
                                 let gradeb = Grade.Length == 0 ? "" : d.Grade.Length > 0 ? d.Grade : "Blank"
                                 let grade = d.Grade.Length > 0 ? d.Grade : ""
                                 where gradeb == Grade && manufacturer == Manufacturer && model == Model && colour == Colour
                                 select new AvailableStockDataDetail_Report(-1, d.OrderDetailID, "", "", d.OrderHeader.OrderNumber + " (" + d.OrderHeader.OrderStatus.Status + ")", d.Manufacturer, d.Model, d.Colour, d.Carrier, d.Grade, 0, (int)d.QTY, ReceiveDateDate)).ToList();

                var data = ctx.ReceiveDetails.Where(x => x.Projects.Name.ToUpper() == Config.ProjectStockForSaleFrom && x.Version == "000" && x.ReceiveDetailStatus.Status.ToUpper() != "GRAVEYARD");
                var data1 = (from d in data
                             let manufacturer = Manufacturer.Length == 0 ? "" : d.Manufacturer.Length > 0 ? d.Manufacturer : "Blank"
                             let model = Model.Length == 0 ? "" : d.Model.Length > 0 ? d.Model : "Blank"
                             let colour = Colour.Length == 0 ? "" : d.Colour.Length > 0 ? d.Colour : "Blank"
                             let carrier = d.Carrier.Length > 0 ? d.Carrier : "Blank"
                             let gradeb = Grade.Length == 0 ? "" : d.Grade.Length > 0 ? d.Grade : "Blank"
                             let grade = d.Grade.Length > 0 ? d.Grade : ""
                             where gradeb == Grade && manufacturer == Manufacturer && model == Model && colour == Colour
                             select new AvailableStockDataDetail_Report(d.ReceiveDetailID, -1, d.ESN, d.Version, "", d.Manufacturer, d.Model, d.Colour, d.Carrier, d.Grade, 1, 0, ReceiveDateDate)).ToList();

                foreach (var x in Reserved1)
                {
                    data1.Add(x);
                }
                return data1.OrderBy(x => x.ESN).ThenBy(x => x.Version).ThenBy(x => x.OrderNumber).ToList();
            }
        }
        public List<AvailableStockDataDetail> GetAvailableStock_GradeLinq()
        {
            using (clsLinqDataContext ctx = new clsLinqDataContext())
            {
                var Project = ctx.Projects.FirstOrDefault(x => x.Name.ToUpper() == Config.ProjectStockForSaleFrom);
                decimal StockForSaleProjectID = -1;
                if (Project != null) { StockForSaleProjectID = Project.ProjectID; }


                var Reserved = ctx.OrderDetails.Where(x => x.OrderHeader.OrderStatus.Status.ToUpper() != "TRASH"
                                                        && x.OrderHeader.OrderStatus.Status.ToUpper() != "DONE"
                                                        && x.OrderHeader.ProjectID == StockForSaleProjectID).GroupBy(x => x.Grade).Select(x => new AvailableStockDataDetail("", "", "", "", x.Key, 0, x.Sum(y => y.QTY == null ? 0 : (int)y.QTY))).ToList();
                var data = ctx.ReceiveDetails.Where(x => x.Projects.Name.ToUpper() == Config.ProjectStockForSaleFrom && x.Version == "000" && x.ReceiveDetailStatus.Status.ToUpper() != "GRAVEYARD");
                var data1 = (from d in data
                             let Grade = d.Grade.Length > 0 ? d.Grade : ""
                             group d by Grade into t
                             select new AvailableStockDataDetail("", "", "", "", t.Key, t.Count(), 0)).ToList();

                foreach (var d in data1)
                {
                    var r = Reserved.FirstOrDefault(x => x.Grade == d.Grade);
                    if (r != null) { d.QTYReserved = r.QTYReserved; }
                }
                return data1;
            }
        }
