        public List<ReceiveDetailESNMessage> GetMessageQueue(bool ShowClosed)
        {
            using (clsLinqDataContext ctx = new clsLinqDataContext())
            {
                var messages = from x in ctx.ReceiveDetailESNMessages
                               where ShowClosed == true || x.StatusOpen == 1
                               select x;
                return messages.ToList();
            }
        }

        public string[] GetESNQueuedMessage(string ESN)
        {
            using (clsLinqDataContext ctx = new clsLinqDataContext())
            {
                var message = ctx.ReceiveDetailESNMessages.FirstOrDefault(x => x.ESN == ESN && x.StatusOpen == 1);
                if (message == null) { return new string[] { "", "" }; }
                return new string[] { (message.StatusStop == 1 ? "true" : "false"), message.Message + "/" + message.CreateUser };
            }
        }
        public string[] GetWayBillQueuedMessage(string WayBill)
        {
            using (clsLinqDataContext ctx = new clsLinqDataContext())
            {
                WayBill = "WB:" + WayBill.ToUpper();
                var message = ctx.ReceiveDetailESNMessages.FirstOrDefault(x => x.ESN.ToUpper() == WayBill && x.StatusOpen == 1);
                if (message == null) { return new string[] { "", "" }; }
                return new string[] { (message.StatusStop == 1 ? "true" : "false"), message.Message + "/" + message.CreateUser };
            }
        }

        public bool IsESNQueuedMessageStop(string ESN)
        {
            using (clsLinqDataContext ctx = new clsLinqDataContext())
            {
                var message = ctx.ReceiveDetailESNMessages.FirstOrDefault(x => x.ESN == ESN && x.StatusOpen == 1);
                if (message == null) { return false; }
                return (message.StatusStop == 1 ? true : false);
            }
        }

