        private List<PairIDValue> GetMasterQuestionList(string QuestionName)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                List<PairIDValue> lp = new List<PairIDValue>();
                var OptionList = from x in ctx.Options
                                 where x.Question.Name == QuestionName
                                 orderby x.Sequence
                                 select x;
                foreach (var o in OptionList.OrderBy(x => x.Sequence).ThenBy(x => x.OptionText))
                {
                    lp.Add(new PairIDValue { ID = o.OptionID, Desc = o.OptionText });
                }
                return lp;
            }
        }

        public string SwitchIMEI(decimal OriginalReceiveDetailID, string SwapWithIMEI)
        {
            using (clsLinqDataContext ctx = new clsLinqDataContext())
            {
                string rValue = "Error:" + OriginalReceiveDetailID.ToString() + ":IMEI Switch Not Done!";
                ReceiveDetail Source = ctx.ReceiveDetails.FirstOrDefault(x => x.ReceiveDetailID == OriginalReceiveDetailID);
                ReceiveDetail Target = ctx.ReceiveDetails.FirstOrDefault(x => x.ESN == SwapWithIMEI && x.Version == "000");
                ReceiveDetailStatus rds = ctx.ReceiveDetailStatus.FirstOrDefault(x => x.Status.ToUpper() == "Switched");
                if (Target == null) { return "Error:" + SwapWithIMEI + ":IMEI Not found!"; }
                if (Source == null) { return "Error:" + OriginalReceiveDetailID.ToString() + ":Defective Record Not found!"; }

                Target.ProjectTag = "Consignment Swapped";
                Target.StatusID = rds.ReceiveDetailStatusID;

                string SIMEI = Source.ESN;
                string TIMEI = Target.ESN;

                // Update the "Consign Swap" attribute for each. -- This carries the original IMEI for the record
                UpdateESNAttribute(ctx, (decimal)Source.ReceiveDetailID, "Consign Swap", SIMEI);
                UpdateESNAttribute(ctx, (decimal)Target.ReceiveDetailID, "Consign Swap", TIMEI);

                // Switch the IMEI numbers.
                Source.ESN = TIMEI;
                Target.ESN = SIMEI;

                List<string> Attributes = new List<string>();
                //// Track info
                Attributes.Add("Notes");
                //Attributes.Add("Bin");
                //Attributes.Add("Client No");
                Attributes.Add("Dealer Waybill");
                //Attributes.Add("Issue No");
                //Attributes.Add("Post Sale Reason");
                Attributes.Add("Return Reason");
                //Attributes.Add("POP Invoice");
                //Attributes.Add("RMA Number");
                Attributes.Add("SKU");
                //Attributes.Add("Customer Account No");
                //Attributes.Add("Activation Date");
                //Attributes.Add("Return to Store");
                //Attributes.Add("70p of Retail");
                //Attributes.Add("Accessories Received");
                //Attributes.Add("SWO No");
                //Attributes.Add("Handset Value");
                //Attributes.Add("SAP Code");
                //Attributes.Add("POP");
                //Attributes.Add("Return Receipt");
                Attributes.Add("Complaint");
                Attributes.Add("Send To");
                Attributes.Add("Client Reference #");
                //Attributes.Add("Exchanged IMEI");
                //Attributes.Add("Call Usage");
                //Attributes.Add("Data Usage");
                //Attributes.Add("Disposition");
                Attributes.Add("Fault Code 1");
                //Attributes.Add("Complete In The Box");
                Attributes.Add("Serial Number ");
                Attributes.Add("Warranty Expiry Date");
                //Attributes.Add("DOA Accessory");
                Attributes.Add("In-Bound Grade");
                //Attributes.Add(SysUtil.AssignedClientCode() + " Status");
                //Attributes.Add("Discrepancy");
                //Attributes.Add("Location");
                Attributes.Add("Receipt Type");
                //Attributes.Add("HEX ESN");
                //Attributes.Add("Forward To");
                Attributes.Add("Complaint 2");
                Attributes.Add("SIM Card #");
                //Attributes.Add("Warranty No.");
                ////Attributes.Add("Bin");
                //Attributes.Add("Estimate");
                Attributes.Add("Part 1");
                Attributes.Add("Part 2");
                //Attributes.Add("Repair Date");
                //Attributes.Add("Repair Fee");
                //Attributes.Add("Repair Notes");
                //Attributes.Add("Replacement IMEI");
                //Attributes.Add("Work Performed");
                //Attributes.Add("Component");
                //Attributes.Add("Cosmetic");
                //Attributes.Add("Module");
                //Attributes.Add("Authorization Status");
                //Attributes.Add("Authorized By");
                //Attributes.Add("Authorization No");
                //Attributes.Add("Authorization");
                Attributes.Add("Fault Code 2");
                Attributes.Add("Claim Declined");
                Attributes.Add("Claim Reason");
                Attributes.Add("Claim Location");
                Attributes.Add("Claim Action");
                Attributes.Add("Fault Code 3");
                //Attributes.Add("SWO No");
                //Attributes.Add("70p of Retail");
                //Attributes.Add("Disposition");
                // Get the attributes for "Tracking and Inspection" and the attributes for SysUtil.AssignedClientCode() + " REPAIR"

                foreach (string a in Attributes)
                {
                    _CloneAttribute(ctx, Source, Target, a);
                    // CloneAttribute(ctx, Brd.ReceiveDetailID, Ard.ReceiveDetailID, Attributes, true);
                }

                rValue = "Saved:" + OriginalReceiveDetailID.ToString() + ":IMEI Switch Done!";
                ctx.SubmitChanges();
                return rValue;
            }
        }




        public void RecordDocCount(string WayBill, decimal Count, decimal Actual)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                ReceiveDockingCount rdc = (from x in ctx.ReceiveDockingCounts where x.DealerWayBill.ToUpper() == WayBill.ToUpper() select x).FirstOrDefault();
                if (rdc == null)
                {
                    rdc = new ReceiveDockingCount();
                    rdc.Count = Count;
                    rdc.CountActual = Actual;
                    rdc.DealerWayBill = WayBill;
                    rdc.DocDate = DateTime.Now;
                    rdc.CreateDate = DateTime.Now;
                    rdc.CreateUser = UserName;
                    ctx.ReceiveDockingCounts.InsertOnSubmit(rdc);
                    //SM.Docked(ctx, (int)Count, UserName);
                }
                else
                {
                    // Negate the earlier count.
                    //SM.Docked(ctx, (int)rdc.Count * -1, UserName);
                    rdc.Count = Count;
                    rdc.CountActual = Actual;
                    rdc.DocDate = DateTime.Now;
                    rdc.CreateDate = DateTime.Now;
                    rdc.CreateUser = UserName;
                    //SM.Docked(ctx, (int)Count, UserName);
                }
                ctx.SubmitChanges();
            }
        }

        #region Clone
        public void CloneAttribute(decimal SourceID, decimal TargetID, string Attribute)
        {
            CloneAttribute(SourceID, TargetID, Attribute, false);
            return;
        }
        public void CloneAttribute(decimal SourceID, decimal TargetID, string Attribute, bool AdvanceVersion)
        {
            List<string> aList = new List<string>();
            aList.Add(Attribute);
            CloneAttribute(SourceID, TargetID, aList, AdvanceVersion);
            return;
        }

        public void CloneAttribute(decimal SourceID, decimal TargetID, List<string> Attributes, bool AdvanceVersion)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                CloneAttribute(ctx, SourceID, TargetID, Attributes, AdvanceVersion);
                return;
            }
        }


        public void CloneAttribute(clsLinqDataContext ctx, decimal SourceID, decimal TargetID, List<string> Attributes, bool AdvanceVersion)
        {
            ReceiveDetail Source = ctx.ReceiveDetails.FirstOrDefault(x => x.ReceiveDetailID == SourceID);
            ReceiveDetail Target = ctx.ReceiveDetails.FirstOrDefault(x => x.ReceiveDetailID == TargetID);
            CloneAttribute(ctx, Source, Target, Attributes, AdvanceVersion);
            return;
        }

        public void CloneAttribute(clsLinqDataContext ctx, string ESN, List<string> Attributes, bool AdvanceVersion)
        {
            ReceiveDetail Source = ctx.ReceiveDetails.Where(x => x.ESN == ESN && x.ReceiveDetailStatus.Status.ToUpper() != "GRAVEYARD" && x.Version != "000").OrderBy(x => x.Version).ThenByDescending(x => x.CreateDate).FirstOrDefault();
            ReceiveDetail Target = ctx.ReceiveDetails.Where(x => x.ESN == ESN && x.ReceiveDetailStatus.Status.ToUpper() != "GRAVEYARD" && x.Version == "000").OrderBy(x => x.Version).ThenByDescending(x => x.CreateDate).FirstOrDefault();
            if (Source != null && Target != null)
            {
                CloneAttribute(ctx, Source, Target, Attributes, AdvanceVersion);
            }
            return;
        }

        public void CloneAttribute(clsLinqDataContext ctx, ReceiveDetail Source, ReceiveDetail Target, List<string> Attributes, bool AdvanceVersion)
        {
            if (Source != null && Target != null)
            {
                foreach (string Attribute in Attributes)
                {
                    if (AdvanceVersion == true)
                    {
                        // we need to advance the version number here only iff the Source has the same attribute..
                        ReceiveDetailItem ri = ctx.ReceiveDetailItems.FirstOrDefault(x => x.ReceiveDetailID == Source.ReceiveDetailID && x.Option.Question.Name.ToUpper() == Attribute.ToUpper() && x.Version == 0);
                        //Option o = ctx.Options.FirstOrDefault(x=>x.Question.Name.ToUpper() == Attribute.ToUpper());
                        if (ri != null)
                        {
                            ctx.Update_ReceiveDetailItemOption_Version(Target.ReceiveDetailID, ri.OptionID);
                        }
                    }
                    _CloneAttribute(ctx, Source, Target, Attribute);
                }
            }
            ctx.SubmitChanges();
            return;
        }




        public bool Clone(string Type, decimal ReceiveDetailID, decimal ProjectID, decimal ClientLocationID, decimal ProcessID)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                return Clone(ctx, Type, ReceiveDetailID, ProjectID, ClientLocationID, ProcessID);
            }
        }
        public bool Clone(clsLinqDataContext ctx, string Type, decimal ReceiveDetailID, decimal ProjectID, decimal ClientLocationID, decimal ProcessID)
        {
            ////////////////
            //  Type   0 = Product Re-assessment
            //         1 = SysUtil.AssignedClientCode() + " Buy
            //         2 = Dealer Submission		
            //         3 = Transfer to MSC
            //         4 = Transfer From MSC	
            //         5 = Create Refurb Record
            //       
            ///////////


            ReceiveDetailManager rdm = new ReceiveDetailManager(UserName);
            ReceiveDetail rd = rdm.ReceiveDetail(ctx, ReceiveDetailID);
            if (rd == null) { return false; }
            rdm.AdvanceESNVersion_FromThisOne(ctx, ReceiveDetailID);
            ProjectManager pm = new ProjectManager(UserName);
            Project p = pm.GetProject(ctx, ProjectID);
            ProcessManager promanager = new ProcessManager(UserName);
            Decimal SaveProcessID = promanager.GetProcessidFromName(ctx, "Save");

            ReceiveDetailStatus rds = ctx.ReceiveDetailStatus.FirstOrDefault(x => x.Status.ToUpper() == "ACTIVE");
            ReceiveHeader rh = new ReceiveHeader();
            rh.ClientLocationID = rd.ClientLocationID;                    // ClientLocationID;
            rh.CreateDate = DateTime.Now;
            rh.CreateUser = UserName;
            rh.LastUpdateDate = DateTime.Now;
            rh.LastUpdateUser = UserName;
            rh.ProjectID = ProjectID;
            rh.ProjectName = p.Name;
            rh.QTYPaper = 0;
            rh.QTYRecorded = 1;
            rh.ReceiveDate = DateTime.Now;
            rh.RMANumber = "";
            rh.MiscNote = "";
            rh.StatusID = rds.ReceiveDetailStatusID;

            ReceiveDetail nrd = new ReceiveDetail();
            nrd.BinLocationID = rd.BinLocationID;
            nrd.ClientLocationID = ClientLocationID;
            nrd.CreateDate = DateTime.Now;
            nrd.CreateUser = UserName;
            nrd.LastUpdateDate = DateTime.Now;
            nrd.LastUpdateUser = UserName;

            nrd.ESN = rd.ESN;
            nrd.ICB = rd.ICB;
            nrd.MiscNote = rd.MiscNote;
            nrd.PIN = rd.PIN;
            nrd.ProcessID = SaveProcessID;
            nrd.ProjectID = ProjectID;
            nrd.ProjectName = p.Name;
            nrd.ProjectTag = rd.ProjectTag;
            nrd.QTYIntegrated = 1;
            nrd.ReceiveDate = DateTime.Now;
            nrd.RMANumber = "";
            nrd.Version = "000";

            nrd.CarrierID = rd.CarrierID;
            nrd.ColourID = rd.ColourID;
            nrd.ManufacturerID = rd.ManufacturerID;
            nrd.ModelID = rd.ModelID;
            nrd.Carrier = rd.Carrier;
            nrd.Colour = rd.Colour;
            nrd.Manufacturer = rd.Manufacturer;
            nrd.Model = rd.Model;
            nrd.Grade = rd.Grade;
            nrd.GradeID = rd.GradeID;

            nrd.StatusID = rds.ReceiveDetailStatusID;
            #region Product Re-assessment
            if (Type == "0")   // Product Re-assessment
            {
                //                    IMEI	Carrier	Manufacturer	Model	Colour	Fault	Client 	Client Location	Receive Date
                nrd.ReceiveDate = rd.ReceiveDate;
                _CloneAttribute(ctx, rd, nrd, "Carrier");
                _CloneAttribute(ctx, rd, nrd, "Manufacturer");
                _CloneAttribute(ctx, rd, nrd, "Model");
                _CloneAttribute(ctx, rd, nrd, "Colour");
                _CloneAttribute(ctx, rd, nrd, "Fault Code 1");
                _CloneAttribute(ctx, rd, nrd, "Fault Code 2");
                _CloneAttribute(ctx, rd, nrd, "Dealer Waybill");
                _CloneAttribute(ctx, rd, nrd, "Receipt Type");
                _CloneAttribute(ctx, rd, nrd, "Complaint");
                _CloneAttribute(ctx, rd, nrd, "Complaint 2");
            }
            #endregion
            #region SysUtil.AssignedClientCode() + " Buy
            if (Type == "1")   // SysUtil.AssignedClientCode() + " Buy
            {
                _CloneAttribute(ctx, rd, nrd, "Carrier");
                _CloneAttribute(ctx, rd, nrd, "Manufacturer");
                _CloneAttribute(ctx, rd, nrd, "Model");
                _CloneAttribute(ctx, rd, nrd, "Colour");
                _CloneAttribute(ctx, rd, nrd, "Fault Code 1");
                _CloneAttribute(ctx, rd, nrd, "Fault Code 2");
                _CloneAttribute(ctx, rd, nrd, "Disposition");
                _CloneAttribute(ctx, rd, nrd, "Grade");
                _CloneAttribute(ctx, rd, nrd, "Stock Type");

                // Record the "shipping" details to close the old record as being purchased and s hipped.
                AddBillingPointXXXBuy(ctx, rd.ReceiveDetailID, rd.ClientLocationID, (decimal)rd.ProjectID);


                decimal ShippedProcessID = GetProcessidFromName(ctx, "Shipping");
                // Loop through all the ESN numbers and add to the units processing log.
                if (ShippedProcessID > 0)
                {
                    //SM.OrderShipped(ctx, rd.ReceiveDetailID, -1, rd.ClientLocationID, (decimal)rd.ProjectID, ShippedProcessID, UserName);
                    // Record going through the shipping process as well as recording a billing point if required.
                    AddDetailProcessLog(ctx, (decimal)rd.ReceiveDetailID, ShippedProcessID);
                    AddBillingPoint(ctx, rd.ReceiveDetailID, rd.ClientLocationID, (decimal)rd.ProjectID, ShippedProcessID);

                    // Update the 
                    UpdateESNAttribute(ctx, (decimal)rd.ReceiveDetailID, "Out-Bound Waybill-S", "GMP BUY");
                    UpdateESNAttribute(ctx, (decimal)rd.ReceiveDetailID, "Shipment Date", string.Format("{0:MM/dd/yyyy}", DateTime.Now));
                    // these are the other fields on the Shipping process screen that should be updated when the order is shipped from the order entry screen.
                    UpdateESNAttribute(ctx, (decimal)rd.ReceiveDetailID, "Carton No", "GMP BUY");
                    UpdateESNAttribute(ctx, (decimal)rd.ReceiveDetailID, "ShipTo", "GMP BUY");
                    UpdateESNAttribute(ctx, (decimal)rd.ReceiveDetailID, "Courier Out", "GMP BUY");


                    UpdateESNAttribute(ctx, (decimal)rd.ReceiveDetailID, "PO No", "GMP BUY");
                    //UpdateESNAttribute((decimal)rd.ReceiveDetailID, "Bin", "");              //as per Greg's email.

                    //UpdateESNAttribute((decimal)rd.ReceiveDetailID, "PO", "GMP BUY");
                    //UpdateESNAttribute((decimal)rd.ReceiveDetailID, "Bell PO", "GMP BUY");
                }
            }
            #endregion
            #region Dealer Submission
            if (Type == "2")   // Dealer Submission		
            {
                // Carrier	Manufacturer	Model	Colour	Carrier	SKU	Client 	Client Location	SWO#	RMA#	Customer Account #	Activation Date	Serial Number	POP	Complaint
                nrd.ClientLocationID = rd.ClientLocationID;
                nrd.RMANumber = rd.RMANumber;
                nrd.ICB = rd.ICB;
                nrd.PIN = rd.PIN;

                _CloneAttribute(ctx, rd, nrd, "Carrier");
                _CloneAttribute(ctx, rd, nrd, "Colour");
                _CloneAttribute(ctx, rd, nrd, "Complaint");
                _CloneAttribute(ctx, rd, nrd, "Complaint 2");
                _CloneAttribute(ctx, rd, nrd, "Customer Notes");
                _CloneAttribute(ctx, rd, nrd, "Dealer Waybill");
                _CloneAttribute(ctx, rd, nrd, "Manufacturer");
                _CloneAttribute(ctx, rd, nrd, "Model");

                _CloneAttribute(ctx, rd, nrd, "Warranty Type");
                _CloneAttribute(ctx, rd, nrd, "Store Comments");
                _CloneAttribute(ctx, rd, nrd, "Service Request Num");
                _CloneAttribute(ctx, rd, nrd, "Original IMEI");
                _CloneAttribute(ctx, rd, nrd, "Customer Name");

                //_CloneAttribute(ctx, rd, nrd, "Accessories Shipping");
                //_CloneAttribute(ctx, rd, nrd, "Activation Date");
                //_CloneAttribute(ctx, rd, nrd, "Complete In The Box");
                //_CloneAttribute(ctx, rd, nrd, "Customer Account No");
                //_CloneAttribute(ctx, rd, nrd, "POP");
                //_CloneAttribute(ctx, rd, nrd, "POP Invoice");
                //_CloneAttribute(ctx, rd, nrd, "Receipt Type");
                //_CloneAttribute(ctx, rd, nrd, "RMA Number");
                //_CloneAttribute(ctx, rd, nrd, "SKU");
                //_CloneAttribute(ctx, rd, nrd, "Warranty No.");
                //_CloneAttribute(ctx, rd, nrd, "Client Reference #");
            }

            #endregion
            #region Transfer to MSC
            if (Type == "3")   // Transfer to MSC
            {
                // Carrier	Manufacturer	Model	Colour	Carrier	SKU	Client 	Client Location	SWO#	RMA#	Customer Account #	Activation Date	Serial Number	POP	Complaint
                nrd.ClientLocationID = rd.ClientLocationID;
                nrd.RMANumber = rd.RMANumber;
                nrd.ICB = rd.ICB;
                nrd.PIN = rd.PIN;

                _CloneAttribute(ctx, rd, nrd, "Accessories Shipping");
                _CloneAttribute(ctx, rd, nrd, "Activation Date");
                _CloneAttribute(ctx, rd, nrd, "Carrier");
                _CloneAttribute(ctx, rd, nrd, "Colour");
                _CloneAttribute(ctx, rd, nrd, "Complaint");
                _CloneAttribute(ctx, rd, nrd, "Complaint 2");
                _CloneAttribute(ctx, rd, nrd, "Complete In The Box");
                _CloneAttribute(ctx, rd, nrd, "Customer Account No");
                _CloneAttribute(ctx, rd, nrd, "Customer Notes");
                _CloneAttribute(ctx, rd, nrd, "Dealer Waybill");
                _CloneAttribute(ctx, rd, nrd, "Manufacturer");
                _CloneAttribute(ctx, rd, nrd, "Model");
                _CloneAttribute(ctx, rd, nrd, "POP");
                _CloneAttribute(ctx, rd, nrd, "POP Invoice");
                _CloneAttribute(ctx, rd, nrd, "Receipt Type");
                _CloneAttribute(ctx, rd, nrd, "RMA Number");
                _CloneAttribute(ctx, rd, nrd, "SKU");
                _CloneAttribute(ctx, rd, nrd, "Warranty No.");
                _CloneAttribute(ctx, rd, nrd, "Client Reference #");
            }
            #endregion
            #region Transfer From MSC
            if (Type == "4")   // Transfer From MSC	
            {
                // Carrier	Manufacturer	Model	Colour	Carrier	SKU	Client 	Client Location	SWO#	RMA#	Customer Account #	Activation Date	Serial Number	POP	Complaint
                nrd.ClientLocationID = rd.ClientLocationID;
                nrd.RMANumber = rd.RMANumber;
                nrd.ICB = rd.ICB;
                nrd.PIN = rd.PIN;

                _CloneAttribute(ctx, rd, nrd, "Accessories Shipping");
                _CloneAttribute(ctx, rd, nrd, "Activation Date");
                _CloneAttribute(ctx, rd, nrd, "Carrier");
                _CloneAttribute(ctx, rd, nrd, "Colour");
                _CloneAttribute(ctx, rd, nrd, "Complaint");
                _CloneAttribute(ctx, rd, nrd, "Complaint 2");
                _CloneAttribute(ctx, rd, nrd, "Complete In The Box");
                _CloneAttribute(ctx, rd, nrd, "Customer Account No");
                _CloneAttribute(ctx, rd, nrd, "Customer Notes");
                _CloneAttribute(ctx, rd, nrd, "Dealer Waybill");
                _CloneAttribute(ctx, rd, nrd, "Manufacturer");
                _CloneAttribute(ctx, rd, nrd, "Model");
                _CloneAttribute(ctx, rd, nrd, "POP");
                _CloneAttribute(ctx, rd, nrd, "POP Invoice");
                _CloneAttribute(ctx, rd, nrd, "Receipt Type");
                _CloneAttribute(ctx, rd, nrd, "RMA Number");
                _CloneAttribute(ctx, rd, nrd, "SKU");
                _CloneAttribute(ctx, rd, nrd, "Warranty No.");
                _CloneAttribute(ctx, rd, nrd, "Client Reference #");
            }
            #endregion
            #region Create Refurb Record
            if (Type == "5")   // Create Refurb Record
            {
                // Carrier	Manufacturer	Model	Colour	Carrier	SKU	Client 	Client Location	SWO#	RMA#	Customer Account #	Activation Date	Serial Number	POP	Complaint

                nrd.Grade = "";
                nrd.GradeID = -1;



                //nrd.ClientLocationID = rd.ClientLocationID;
                //nrd.RMANumber = rd.RMANumber;
                //nrd.ICB = rd.ICB;
                //nrd.PIN = rd.PIN;

                //_CloneAttribute(ctx, rd, nrd, "Accessories Shipping");
                //_CloneAttribute(ctx, rd, nrd, "Activation Date");
                _CloneAttribute(ctx, rd, nrd, "Carrier");
                _CloneAttribute(ctx, rd, nrd, "Colour");
                _CloneAttribute(ctx, rd, nrd, "Manufacturer");
                _CloneAttribute(ctx, rd, nrd, "Model");


                //_CloneAttribute(ctx, rd, nrd, "Complaint");
                //_CloneAttribute(ctx, rd, nrd, "Complaint 2");
                //_CloneAttribute(ctx, rd, nrd, "Complete In The Box");
                //_CloneAttribute(ctx, rd, nrd, "Customer Account No");
                //_CloneAttribute(ctx, rd, nrd, "Customer Notes");
                //_CloneAttribute(ctx, rd, nrd, "Dealer Waybill");

                //_CloneAttribute(ctx, rd, nrd, "POP");
                //_CloneAttribute(ctx, rd, nrd, "POP Invoice");
                //_CloneAttribute(ctx, rd, nrd, "Receipt Type");
                //_CloneAttribute(ctx, rd, nrd, "RMA Number");
                //_CloneAttribute(ctx, rd, nrd, "SKU");
                //_CloneAttribute(ctx, rd, nrd, "Warranty No.");
                //_CloneAttribute(ctx, rd, nrd, "Client Reference #");
            }
            #endregion
            rh.ReceiveDetails.Add(nrd);
            ctx.ReceiveHeaders.InsertOnSubmit(rh);
            ctx.SubmitChanges();
            //foreach (ReceiveDetail _rd in rh.ReceiveDetails)
            //{
            //    SM.Transfer(ctx, Type, rd.ReceiveDetailID, -1, rd.ClientLocationID, ProjectID, ProcessID, UserName);
            //}

            #region Dealer Submission
            if (Type == "2")   // Dealer Submission		
            {
                ReceiveDetailClientSubmitted RDCS = new ReceiveDetailClientSubmitted();
                RDCS.ClientReceiveDetailID = ReceiveDetailID;
                RDCS.GMPIReceiveDetailID = nrd.ReceiveDetailID;
                RDCS.CreateDate = DateTime.Now;
                RDCS.LastUpdateDate = DateTime.Now;
                RDCS.CreateUser = UserName;
                RDCS.LastUpdateUser = UserName;
                ctx.ReceiveDetailClientSubmitteds.InsertOnSubmit(RDCS);
                ctx.SubmitChanges();
            }
            #endregion

            return true;
        }




