        public List<string> GetCloneToMSCAttributeList(clsLinqDataContext ctx)
        {
            List<string> rValue = new List<string>();
            var data = ctx.SystemDatas.Where(x => x.DataKey.ToUpper() == "CLONETOMSC");
            foreach (SystemData d in data)
            {
                rValue.Add(d.Data);
            }
            return rValue;
        }
