        public bool CloneToMSC(clsLinqDataContext ctx, decimal ReceiveDetailID, decimal ProjectID, decimal ClientLocationID, decimal ProcessID)
        {
            ReceiveDetailManager rdm = new ReceiveDetailManager(UserName);
            ////rdm.AdvanceESNVersion_FromThisOne(ctx, ReceiveDetailID);
            // Get the RD And Move the version to 900
            ReceiveDetail rd = rdm.ReceiveDetail(ctx, ReceiveDetailID);
            if (rd == null) { return false; }
            rd.Version = "900";
            rd.isIFSLocked = true;
            rd.LastUpdateDate = DateTime.Now;
            rd.LastUpdateUser = UserName;
            ProjectManager pm = new ProjectManager(UserName);
            Project p = pm.GetProject(ctx, ProjectID);
            ProcessManager promanager = new ProcessManager(UserName);
            Decimal SaveProcessID = promanager.GetProcessidFromName(ctx, "Save");


            ReceiveDetailStatus rds = ctx.ReceiveDetailStatus.FirstOrDefault(x => x.Status.ToUpper() == "ACTIVE");
            ReceiveHeader rh = new ReceiveHeader();
            rh.ClientLocationID = ClientLocationID < 1 ? rd.ClientLocationID : ClientLocationID;                    // ClientLocationID;
            rh.CreateDate = DateTime.Now;
            rh.CreateUser = UserName;
            rh.LastUpdateDate = DateTime.Now;
            rh.LastUpdateUser = UserName;
            rh.ProjectID = ProjectID;
