            nrd.ModelID = rd.ModelID;
            nrd.Carrier = rd.Carrier;
            nrd.Colour = rd.Colour;
            nrd.Manufacturer = rd.Manufacturer;
            nrd.Model = rd.Model;
            nrd.GradeID = rd.GradeID;
