        }
        // Todo: Need to clean this one up to pull the last >= 900 version back to 000
        public bool CloneFromMSC(clsLinqDataContext ctx, decimal ReceiveDetailID, decimal ProjectID, decimal ProcessID)
        {
            ProjectManager pm = new ProjectManager(UserName);
            Project p = pm.GetProject(ctx, ProjectID);
            if (p.Name.ToUpper() != "GMP MSC") { return false; }

            ReceiveDetailManager rdm = new ReceiveDetailManager(UserName);
            ReceiveDetail rd = rdm.ReceiveDetail(ctx, ReceiveDetailID);
            if (rd == null) { return false; }
            ReceiveDetail original = (from x in ctx.ReceiveDetails
                                      where x.ESN == rd.ESN && (x.Version == "900" || x.Version == "901" ||
                                                                                        x.Version == "902" || x.Version == "903" ||
                                                                                        x.Version == "904" || x.Version == "905" ||
                                                                                        x.Version == "906" || x.Version == "907")
                                      select x).FirstOrDefault();
            rd = null;
            if (original == null) { return false; }
            ctx.SyncIFSDevices(ReceiveDetailID, original.ReceiveDetailID, "000", UserName);
            return true;
        }
        void _CloneAttribute(clsLinqDataContext ctx, ReceiveDetail Source, ReceiveDetail Target, string Attribute)
        {
            // string ElementValue = GetReceiveDetailItem_DataElement(Source.ReceiveDetailID, Attribute);
            var rdi = ctx.ReceiveDetailItems.Where(x => x.ReceiveDetailID == Source.ReceiveDetailID && x.Option.Question.Name.ToUpper() == Attribute.ToUpper() && x.Version == 0);
            if (rdi == null) { return; }
            foreach (var SourceRD in rdi)
            {
                if (SourceRD.Value == "0"
                    && (SourceRD.Option.Question.QuestionType.Type.ToUpper() == "CHECKBOX"
                    || SourceRD.Option.Question.QuestionType.Type.ToUpper() == "RADIALBUTTON"
                    || SourceRD.Option.Question.QuestionType.Type.ToUpper() == "DROPDOWN")) { } // Do Nothing
                else
                {
                    ReceiveDetailItem nrdi = new ReceiveDetailItem();
                    nrdi.CreateDate = Target.CreateDate;
                    nrdi.CreateUser = Target.CreateUser;
                    nrdi.LastUpdateDate = Target.LastUpdateDate;
                    nrdi.LastUpdateUser = Target.LastUpdateUser;
                    nrdi.OptionID = SourceRD.OptionID;
                    nrdi.ReceiveDate = Target.ReceiveDate;
                    nrdi.Value = SourceRD.Value;
                    nrdi.Version = SourceRD.Version;
                    Target.ReceiveDetailItems.Add(nrdi);
                }
            }
            return;
        }
