        public string MakeModelColourNickName(clsLinqDataContext ctx, decimal ReceiveDetailID)
        {
            // March 03, 2015 -- This data item is changing to SKU. For now, we will keep both, but eventually, this will change to show only sku.
            string SKU = "";
            ReceiveDetail rd = ctx.ReceiveDetails.FirstOrDefault(x => x.ReceiveDetailID == ReceiveDetailID);
            if (rd != null)
            {
                SKU = rd.SKU;
            }


            string Manufacturer = GetReceiveDetailItem_DataElement(ctx, ReceiveDetailID, "Manufacturer");
            string Model = GetReceiveDetailItem_DataElement(ctx, ReceiveDetailID, "Model");
            string Colour = GetReceiveDetailItem_DataElement(ctx, ReceiveDetailID, "Colour");
            string Carrier = GetReceiveDetailItem_DataElement(ctx, ReceiveDetailID, "Carrier");
            string NickName = GetCarrierMakeModelColour_NickName(ctx, Carrier, Manufacturer, Model, Colour);

            string sMakeModelColour = "(" + SKU + ") " + Manufacturer;
            sMakeModelColour += " " + Model;
            sMakeModelColour += " " + Colour;
            sMakeModelColour += " " + NickName;
            return sMakeModelColour;
        }
