        public string GetCarrierMakeModelColour_NickName(clsLinqDataContext ctx, string Carrier, string Manufacturer, string Model, string Colour)
        {
            var mdtable = ctx.MasterCarrierManufacturerLookups.FirstOrDefault(x => x.Carrier.ToUpper() == Carrier.ToUpper()
                                                                               && x.Manufacturer.ToUpper() == Manufacturer.ToUpper()
                                                                               && x.Model.ToUpper() == Model.ToUpper()
                                                                               && x.Colour.ToUpper() == Colour.ToUpper());
            if (mdtable == null) { return ""; } else { return mdtable.NickName; }
        }


        public void UpdaeReceiveDetailCarrierKeys(decimal ReceiveDetailID, Hashtable dList)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                UpdaeReceiveDetailCarrierKeys(ctx, ReceiveDetailID, dList);
            }
        }
        public void UpdaeReceiveDetailCarrierKeys(clsLinqDataContext ctx, decimal ReceiveDetailID, Hashtable dList)
        {
            ReceiveDetail rd = ctx.ReceiveDetails.FirstOrDefault(x => x.ReceiveDetailID == ReceiveDetailID);
            if (rd != null)
            {
                bool DoSave = false;
                foreach (DictionaryEntry item in dList)
                {
                    decimal ID = -1;
                    if (decimal.TryParse(item.Value.ToString(), out ID) == false) { ID = -1; }
                    if (item.Key.ToString() == "Carrier") { rd.CarrierID = ID; }
                    if (item.Key.ToString() == "Manufacturer") { rd.ManufacturerID = ID; }
                    if (item.Key.ToString() == "Model") { rd.ModelID = ID; }
                    if (item.Key.ToString() == "Colour") { rd.ColourID = ID; }
                    DoSave = true;
                }
                if (DoSave == true) { ctx.SubmitChanges(); }
            }
        }

