        public bool SwapIMEI(decimal ReceiveDetailID)
        {
            using (clsLinqDataContext ctx = GetDataContext())
            {
                return SwapIMEI(ctx, ReceiveDetailID);
            }
        }
        public bool SwapIMEI(clsLinqDataContext ctx, decimal ReceiveDetailID)
        {
            string ReplacementESN = GetReceiveDetailItem_DataElement(ctx, ReceiveDetailID, "Replacement IMEI");
            if (ReplacementESN.Length > 0)
            {
                // If this IMEI has already been swapped, we do not want to proceed.
                ReceiveDetailIMEISwappedLog s = ctx.ReceiveDetailIMEISwappedLogs.FirstOrDefault(x => x.ReceiveDetailID == ReceiveDetailID);
                if (s != null) { return false; }

                ReceiveDetail rd = ctx.ReceiveDetails.FirstOrDefault(x => x.ReceiveDetailID == ReceiveDetailID);
                if (rd != null && s == null)
                {
                    //decimal ReplaceIMEI_ReceiveDetailID = -1;
                    // This will advance the replacement IMEI records
                    ReceiveDetail ReplacementIMEI_RS = ctx.ReceiveDetails.FirstOrDefault(x => x.ESN == ReplacementESN && x.Version == "000");
                    if (ReplacementIMEI_RS != null)
                    {
                        //ReplaceIMEI_ReceiveDetailID = ReplacementIMEI_RS.ReceiveDetailID;
                        //ctx.AdvanceESNVersion(ReplacementESN);
                        // We need to update an attribute to show that the unit was advancecd "automatically, not via normal Shipping.
                        UpdateESNAttribute(ReplacementIMEI_RS.ReceiveDetailID, "ShipTo", "Auto Advanced because of swap:" + rd.ESN);
                        //short CO_Pick = IFSDirective("CO_Pick");
                        ////ctx.IFS_GenerateInvtTran(rd.ReceiveDetailID, UDPick, "", "", "", UserName, -1, ReasonCode);
                        //ctx.IFS_GenerateInvtTran_B(ReplacementIMEI_RS.ReceiveDetailID, CO_Pick, ReplacementIMEI_RS.SKU
                        //                         , ReplacementIMEI_RS.IFSLocation
                        //                         , ReplacementIMEI_RS.IFSCondition
                        //                         , ReplacementIMEI_RS.SKU
                        //                         , ReplacementIMEI_RS.IFSLocation
                        //                         , ReplacementIMEI_RS.IFSCondition
                        //                         , UserName, -1, "");
                        //// We may need to update some Other attributes.
                        ////UpdateESNAttribute_Blank(ctx, ReplacementIMEI_RS.ReceiveDetailID, "Bin");
                        ////UpdateESNAttribute(ctx, ReplacementIMEI_RS.ReceiveDetailID, "Location", "None");
                        ReceiveDetailIMEISwappedLog sla = new ReceiveDetailIMEISwappedLog();
                        sla.CreateDate = DateTime.Now;
                        sla.CreateUser = UserName;
                        sla.IMEISwappedIn = rd.ESN;
                        sla.IMEISwappedOut = ReplacementIMEI_RS.ESN;
                        sla.ReceiveDetailID = ReplacementIMEI_RS.ReceiveDetailID;
                        // there should be a field to carry the ReplaceIMEI ReceiveDetailID.
                        //sl.ReplaceIMEI_ReceiveDetailID = ReplaceIMEI_ReceiveDetailID
                        ctx.ReceiveDetailIMEISwappedLogs.InsertOnSubmit(sla);
                        ctx.SubmitChanges();
                        ctx.Update_ReceiveDetailESN(ReplacementIMEI_RS.ReceiveDetailID, rd.ESN, UserName);
                    }
                    //ctx.SubmitChanges();
                    //rd = ctx.ReceiveDetails.FirstOrDefault(x => x.ReceiveDetailID == ReceiveDetailID);
                    ReceiveDetailIMEISwappedLog sl = new ReceiveDetailIMEISwappedLog();
                    sl.CreateDate = DateTime.Now;
                    sl.CreateUser = UserName;
                    sl.IMEISwappedIn = ReplacementESN;
                    sl.IMEISwappedOut = rd.ESN;
                    sl.ReceiveDetailID = rd.ReceiveDetailID;
                    // there should be a field to carry the ReplaceIMEI ReceiveDetailID.
                    //sl.ReplaceIMEI_ReceiveDetailID = ReplaceIMEI_ReceiveDetailID
                    ctx.ReceiveDetailIMEISwappedLogs.InsertOnSubmit(sl);
                    ctx.SubmitChanges();
                    UpdateESNAttribute(ctx, ReceiveDetailID, "Replacement IMEI", rd.ESN);
                    ctx.Update_ReceiveDetailESN(ReceiveDetailID, ReplacementESN, UserName);
                    return true;
                }
            }
            return false;
        }

