        public string GetProjectClientLocationBinString(clsLinqDataContext ctx, decimal ReceiveDetailID)
        {
            var RD = ctx.ReceiveDetails.FirstOrDefault(x => x.ReceiveDetailID == ReceiveDetailID);
            if (RD == null) { return ""; }
            var CL = ctx.ClientLocations.FirstOrDefault(x => x.ClientLocationID == RD.ClientLocationID);
            if (CL == null) { return ""; }

            string Bin = GetReceiveDetailItem_DataElement(ReceiveDetailID, "BIN");

            string Project = RD.ProjectName;
            string Client = CL.Client.Name;
            string ClientLocation = CL.Name + " " + CL.CompanyName;
            string IFSLocation = "";
            if (RD.IFSLocation != null)
            {
                IFSLocation = RD.IFSLocation;
            }
            return Project + " " + Client + " " + ClientLocation + " " + Bin + " " + IFSLocation;
            // return "Project # Client Location BINXXXXXXXYYYYYYYYY";
        }


        public bool VersionBackFrom001(string ESN, string NewLocation, bool x00, ref string ReturnMessage, ref decimal OutReceicveDetailID)
        {
