        public bool VersionBackFrom001(clsLinqDataContext ctx, string ESN, string NewLocation, bool x00, ref string ReturnMessage, ref decimal OutReceicveDetailID)
        {
            OutReceicveDetailID = -1;
            ReceiveDetail rd = ctx.ReceiveDetails.FirstOrDefault(x => x.ESN == ESN && x.Version == "000");
            if (rd != null)
            {
                ReturnMessage = "Error:000 version already exists";
                return false;
            }
            OutReceicveDetailID = rd.ReceiveDetailID;
            IFSLocation location = new IFSLocation(NewLocation);
            if (location.isValid == false) { ReturnMessage = "Error:Location is not valid"; return false; }
            if (location.IsThisFrozen(UserName)) { ReturnMessage = "Error:Location is Frozen"; return false; }

            rd = ctx.ReceiveDetails.FirstOrDefault(x => x.ESN == ESN && x.Version == (x00 == true ? "980" : "001"));
            if (rd != null)
            {
                return VersionBackFrom001(ctx, rd.ReceiveDetailID, NewLocation, ref ReturnMessage);
            }
            else { ReturnMessage = "Error:" + (x00 == true ? "980" : "001") + " version not found."; return false; }
        }
        public bool VersionBackFrom001(clsLinqDataContext ctx, decimal ReceiveDetailID, string NewLocation, ref string ReturnMessage)
        {
            ReturnMessage = "";
            IFSLocation location = new IFSLocation(NewLocation);
            if (location.isValid == false) { ReturnMessage = "Error:Location is not valid"; return false; }
            if (location.IsThisFrozen(UserName)) { ReturnMessage = "Error:Location is Frozen"; return false; }

            ReceiveDetailStatus rs = ctx.ReceiveDetailStatus.FirstOrDefault(x => x.Status.ToUpper() == "ACTIVE");
            ReceiveDetail rd = ctx.ReceiveDetails.FirstOrDefault(x => x.ReceiveDetailID == ReceiveDetailID);
            // Only if there are no parts on the one coming back.
            //if (rs != null && rd != null && OKToGraveYard(ctx, ReceiveDetailID) == true)
            if (rs != null && rd != null)
            {
                if (IsThisFrozen(rd.ReceiveDetailID, ref ReturnMessage) == true) { return false; }

                rd.SKU = GetSku(rd.ManufacturerID, rd.ModelID, rd.CarrierID, rd.ColourID);
                rd.StatusID = rs.ReceiveDetailStatusID;
                rd.Version = "000";
                rd.IFSLocation = NewLocation;
                rd.isIFSLocked = false;
                rd.LastUpdateDate = DateTime.Now;
                rd.LastUpdateUser = UserName;
                rd.ISFTransactionDirective = IFSDirective("Ignore");
                ctx.SubmitChanges();
                //UpdateESNAttribute_Blank(ctx, rd.ReceiveDetailID, "Bin");
                //UpdateESNAttribute(ctx, rd.ReceiveDetailID, "Location", "None");
                //GraveYardStatisticData(ctx, ReceiveDetailID);
                return true;
            }
            ReturnMessage = "Error:Device not found";
            return false;
        }
 
