        public bool VersionBackForNotation(clsLinqDataContext ctx, decimal ReceiveDetailID, string NewLocation, string Comment)
        {
            ReceiveDetailStatus rs = ctx.ReceiveDetailStatus.FirstOrDefault(x => x.Status.ToUpper() == "ACTIVE");
            ReceiveDetail rd = ctx.ReceiveDetails.FirstOrDefault(x => x.ReceiveDetailID == ReceiveDetailID);
            // Only if there are no parts on the one coming back.
            //if (rs != null && rd != null && OKToGraveYard(ctx, ReceiveDetailID) == true)
            if (rs != null && rd != null)
            {
                ReceiveDetailNotationLog nl = new ReceiveDetailNotationLog();
                nl.Version = rd.Version;
                nl.ReceiveDetailID = rd.ReceiveDetailID;
                nl.MiscNote = Comment;
                nl.Process = 0;
                nl.LastUpdateDate = DateTime.Now;
                nl.LastUpdateUser = UserName;
                nl.CreateUser = UserName;
                ctx.ReceiveDetailNotationLogs.InsertOnSubmit(nl);

                rd.StatusID = rs.ReceiveDetailStatusID;
                rd.Version = "000";
                rd.IFSLocation = NewLocation;
                rd.isIFSLocked = true;
                rd.LastUpdateDate = DateTime.Now;
                rd.LastUpdateUser = UserName;
                rd.ISFTransactionDirective = IFSDirective("Ignore");
                ctx.SubmitChanges();
                //UpdateESNAttribute_Blank(ctx, rd.ReceiveDetailID, "Bin");
                //UpdateESNAttribute(ctx, rd.ReceiveDetailID, "Location", "None");
                //GraveYardStatisticData(ctx, ReceiveDetailID);
                return true;
            }
            return false;
        }



        public string XCLXProcess(string ClientLocationScanCode, string ESN, ref decimal OutReceiveDetailID)
        {
            OutReceiveDetailID = -1;
            if (ClientLocationScanCode.Trim().Length == 0) { return "Error:Client Location Scankey missing."; }
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                ReceiveDetail rd = ctx.ReceiveDetails.FirstOrDefault(x => x.ESN == ESN && x.Version == "000");
                if (rd == null) { return "Error:IMEI not found"; }
                OutReceiveDetailID = rd.ReceiveDetailID;
                return XCLXProcess(ctx, ClientLocationScanCode, rd.ReceiveDetailID);
            }
        }
        public string XCLXProcess(clsLinqDataContext ctx, string ClientLocationScanCode, decimal ReceiveDetailID)
        {
            if (ClientLocationScanCode.Trim().Length == 0 || ReceiveDetailID < 1) { return "Error:Client Location Scankey missing."; }
                ClientLocation cl = ctx.ClientLocations.FirstOrDefault(x => x.ScanKey.ToUpper() == ClientLocationScanCode.ToUpper());
                if (cl == null)
                {
                    return "Error:Client Location Scankey not found!";
                }

                ReceiveDetail rd = ctx.ReceiveDetails.FirstOrDefault(x => x.ReceiveDetailID == ReceiveDetailID);
                if (rd == null)
                {
                    return "Error:ESN/IMEI not found!";
                }
                // Removed restriction on Dec 2, 2014 after Deann needed one moved. This edit check was stopping it.
                //         The reason the restriction was here was to keep the Header Location equal with the Unit Location.
                //         The header links to many units. But it is an old thing because way back a the beginning, they wanted to group
                //         all units coming in at the same time to be identifyable. Other tools have been put in place to deal with that.
                //         Removing this requrement will cause a discrepency between the header record (No longer referenced on reports, etc)
                //         to be out of sync with the Unit that it is linked to.
                if (cl.Client != rd.ClientLocation.Client)
                {
                    return "Error:Master Client does not match!";
                }

                if (cl.IFSSite != rd.ClientLocation.IFSSite)
                {
                    return "Error:Sites (" + rd.ClientLocation.IFSSite + "/" + cl.IFSSite + ") Do not match!";
                }
                rd.ClientLocation = cl;
                ctx.SubmitChanges();
                return "";
        }

