        public bool OKToGraveYard(clsLinqDataContext ctx, decimal ReceiveDetailID)
        {
            // look to see if there are any parts assigned or parts attached.
            // If yes, do not allow graveyarding.
            // if No, then all is ok to graveyard.
            if (ctx.IsDeviceGotPart(ReceiveDetailID) == true) { return false; }
            else return true;
            //InvtTran_IF lastRec = ctx.InvtTran_IFs.FirstOrDefault(x => x.ReceiveDetailID == ReceiveDetailID);
            //if (lastRec == null) { return true; }
            //if (lastRec.Directive == IFSDirective("PO_Initiate") || lastRec.Directive == IFSDirective("PO_Receipt")) { return true; }
            //return false;
        }
