        {
            ReceiveDetail rd = ctx.ReceiveDetails.FirstOrDefault(x => x.ESN == ESN && x.Version == "000");
            if (rd != null)
            {
                return OKToGraveYardReason(ctx, rd.ReceiveDetailID);
            }
            else { return "ESN Not Found:" + ESN; }
        }
        public string OKToGraveYardReason(clsLinqDataContext ctx, decimal ReceiveDetailID)
        {
            if (ctx.IsDeviceGotPart(ReceiveDetailID) == true) { return ctx.IsDeviceGotPartHow(ReceiveDetailID); }
            else return "Unknown";
        }
        public bool MoveToGraveYard(clsLinqDataContext ctx, decimal ReceiveDetailID, string Reason)
        {
            ReceiveDetailStatus rs = ctx.ReceiveDetailStatus.FirstOrDefault(x => x.Status.ToUpper() == "GRAVEYARD");
            ReceiveDetail rd = ctx.ReceiveDetails.FirstOrDefault(x => x.ReceiveDetailID == ReceiveDetailID);
            if (IsThisFrozen(ReceiveDetailID, ref Reason) == true) { return false; }
            if (rs != null && rd != null && OKToGraveYard(ctx, ReceiveDetailID)== true)
            {
                //ctx.IFS_GenerateInvtTranRollback(ReceiveDetailID, Reason, UserName);
                rd.StatusID = rs.ReceiveDetailStatusID;
                rd.Version = "100";
                rd.isIFSLocked = true;
                rd.LastUpdateDate = DateTime.Now;
                rd.LastUpdateUser = UserName;
                rd.IFSLocation = "";
                rd.ISFTransactionDirective = IFSDirective("Ignore");
                ctx.SubmitChanges();
                UpdateESNAttribute_Blank(ctx, rd.ReceiveDetailID, "Bin");
                UpdateESNAttribute(ctx, rd.ReceiveDetailID, "Location", "None");
                GraveYardStatisticData(ctx, ReceiveDetailID);
                return true;
            }
            return false;
        }
        public void MoveBackFromGraveYard(decimal ReceiveDetailID)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                ReceiveDetailStatus rs = ctx.ReceiveDetailStatus.FirstOrDefault(x => x.Status.ToUpper() == "ACTIVE");
                ReceiveDetail rd = ctx.ReceiveDetails.FirstOrDefault(x => x.ReceiveDetailID == ReceiveDetailID);
                if (rs != null && rd != null)
                {
                    DateTime date = rd.LastUpdateDate;
                    rd.Version = "000";
                    rd.StatusID = rs.ReceiveDetailStatusID;
                    rd.LastUpdateDate = DateTime.Now;
                    rd.LastUpdateUser = UserName;
                    ctx.SubmitChanges();
                    RebuildGraveYardStatisticData(ctx, ReceiveDetailID, date);
                    // We need a way to bring back the "Graveyarded Statistics.
                }
            }
        }




