        #region GridDashBoard
        public List<GridDashboardReceiveDetail_Client> GetDashboardClientView(decimal ClientID, decimal ClientLocationID)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {

                decimal ProjectClientPortalID = ctx.Projects.Where(x => x.Name.ToUpper() == "CLIENT PORTAL").Select(x => x.ProjectID).FirstOrDefault();
                decimal ProjectClientRepairID = ctx.Projects.Where(x => x.Name.ToUpper() == "CLIENT REPAIR").Select(x => x.ProjectID).FirstOrDefault();

                // We are only interestedi n units that are these two project:"Client Portal","Client Repair"
                //    Normally there would be one "client Repair" for each "client Portal", but not all stores
                //    use the Client Portal... so there may be some in each without the other.

                var zz = from x in ctx.ReceiveDetails
                         where x.Version == "000" && x.ReceiveDetailStatus.Status.ToUpper() != "GRAVEYARD" && x.ClientLocationID == ClientLocationID &&
                         (x.ProjectID == ProjectClientPortalID || x.ProjectID == ProjectClientRepairID)
                         //where x.ClientLocationID == ClientLocationID
                         orderby x.ReceiveDate
                         select x;
                // We are not going to restrict here because the 000 record we want might be GMPI Received in place of Client Submitted.
                // var yy = UserRestrict.GetRestricted(zz, ctx);
                var xx = from x in zz
                         orderby x.ReceiveDate
                         select new GridDashboardReceiveDetail_Client(ctx, x, ProjectClientPortalID, ProjectClientRepairID)
                         {
                         };

                if (xx != null)
                {
                    return xx.ToList();
                }
                return null;
            }
        }
        public List<GridDashboardReceiveDetail_Client> GetDashboardClientViewClosed(decimal ClientID, decimal ClientLocationID)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {


                decimal ProjectClientPortalID = ctx.Projects.Where(x => x.Name.ToUpper() == "CLIENT PORTAL").Select(x => x.ProjectID).FirstOrDefault();
                decimal ProjectClientRepairID = ctx.Projects.Where(x => x.Name.ToUpper() == "CLIENT REPAIR").Select(x => x.ProjectID).FirstOrDefault();

                var zz = from x in ctx.ReceiveDetails
                         where x.Version != "000" && x.ReceiveDetailStatus.Status.ToUpper() != "GRAVEYARD" && x.ClientLocationID == ClientLocationID
                                                  && x.LastUpdateDate >= DateTime.Now.AddDays(-15) &&
                                                  (x.ProjectID == ProjectClientPortalID || x.ProjectID == ProjectClientRepairID)
                         orderby x.ReceiveDate
                         select x;
                var yy = UserRestrict.GetRestricted(zz, ctx);

                var xx = from x in yy
                         orderby x.ReceiveDate
                         select new GridDashboardReceiveDetail_Client(ctx, x, ProjectClientPortalID, ProjectClientRepairID)
                         {
                         };

                //var xx = from x in ctx.ReceiveDetails
                //         where x.Version != "000" && x.ReceiveDetailStatus.Status.ToUpper() != "GRAVEYARD" && x.ClientLocationID == ClientLocationID
                //                                  && x.LastUpdateDate >= DateTime.Now.AddDays(-15)
                //         orderby x.ReceiveDate
                //         select new GridDashboardReceiveDetail_Client(ctx, x)
                //         {
                //         };

                if (xx != null)
                {
                    var xy = xx.ToList();
                    return xy.Where(x => x.GMPIReceivedRD != null && x.GMPIReceivedRD.Version != "000").ToList();
                }
                return null;
            }
        }
