        public void UpdateESNAttribute(clsLinqDataContext ctx, decimal ReceiveDetailID, decimal OptionID, string AttributeValue)
        {
            Option o = (from x in ctx.Options where x.OptionID == OptionID select x).FirstOrDefault();
            if (o == null) { return; }
            if (ReceiveDetailID < 1 || o.Question.Name.Trim().Length < 1) { return; }
            if (o.Question.QuestionType.Type.ToUpper() == "CHECKBOX" ||
                o.Question.QuestionType.Type.ToUpper() == "RADIALBUTTON" ||
                o.Question.QuestionType.Type.ToUpper() == "DROPDOWN") { UpdateESNAttribute(ctx, ReceiveDetailID, o.Question.Name, o.OptionText); }
            else { UpdateESNAttribute(ctx, ReceiveDetailID, o.Question.Name, AttributeValue); }
        }


