        public decimal CountAttribute(string Name, string SearchFor)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                var Count = (from x in ctx.ReceiveDetailItems
                             where x.Version == 0
                                && x.Value.ToUpper() == SearchFor.ToUpper()
                                && x.ReceiveDetail.ReceiveDetailStatus.Status.ToUpper() != "GRAVEYARD"
                                && x.Option.Question.Name.ToUpper() == Name.ToUpper()
                             select x.ReceiveDetail.ESN).Distinct().Count();
                return Count;
            }
        }
