        public bool isOKToAddFromThisProcess(string Process)
        {
            switch (Process.ToUpper())
            {
                //case "BULKRECEIVE": 
                //case "BULKMOVE": 
                case "RECEIVEFROMBULK":
                case "RECEIVE":
                case "RECEIVEDOA":
                case "RECEIVEDOAB":
                case "RECEIVEWARRANTYB":
                case "RECEIVEDEFECTIVE":
                case "RECEIVEREPAIRED":
                case "RECEIVEGENERAL":
                case "RECEIVEINWARRANTY":
                case "RECEIVEEXWARRANTY":
                case "RECEIVEOOWARRANTY":
                    return true;
                default:
                    if (Process.Length >= 7 && Process.Substring(0, 7).ToUpper() == "RECEIVE") { return true; }
                    else return false;
            }
        }

