        public string GetReceiveDetailItem_DataElement(clsLinqDataContext ctx, decimal ReceiveDetailID, string FieldName)
        {

            if (FieldName.ToUpper() == "LOCKCARRIER")
            {
                string SKUSegment = "";
                ReceiveDetail rd = ctx.ReceiveDetails.FirstOrDefault(x => x.ReceiveDetailID == ReceiveDetailID);
                if (rd == null || rd.ESN == null) { return ""; }
                if (rd.SKU.Length > 6)
                {
                    //SAMI74716GUNLBLU
                    SKUSegment = rd.SKU.Substring(rd.SKU.Length - 6, 3);
                    if (SKUSegment.ToUpper() == "UNL") { return "Unlocked"; }
                }
                FieldName = "Carrier";
            }




            if (FieldName.ToUpper() == "ESN" || FieldName.ToUpper() == "IMEI")
            {
                ReceiveDetail rd = ctx.ReceiveDetails.FirstOrDefault(x => x.ReceiveDetailID == ReceiveDetailID);
                if (rd == null || rd.ESN == null) { return ""; }
                return rd.ESN;
            }
            if (FieldName.ToUpper() == "PROJECT")
            {
                ReceiveDetail rd = ctx.ReceiveDetails.FirstOrDefault(x => x.ReceiveDetailID == ReceiveDetailID);
                if (rd == null || rd.Projects.Name == null) { return ""; }
                return rd.Projects.Name;
            }
            if (FieldName.ToUpper() == "CLIENTLOCATION")
            {
                ReceiveDetail rd = ctx.ReceiveDetails.FirstOrDefault(x => x.ReceiveDetailID == ReceiveDetailID);
                if (rd == null || rd.ClientLocation.CompanyName == null) { return ""; }
                return rd.ClientLocation.CompanyName;
            }
            if (FieldName.ToUpper() == "CLIENT")
            {
                ReceiveDetail rd = ctx.ReceiveDetails.FirstOrDefault(x => x.ReceiveDetailID == ReceiveDetailID);
                if (rd == null || rd.ClientLocation.Client.CompanyName == null) { return ""; }
                return rd.ClientLocation.Client.CompanyName;
            }
            if (FieldName.ToUpper() == "SCANKEY")
            {
                ReceiveDetail rd = ctx.ReceiveDetails.FirstOrDefault(x => x.ReceiveDetailID == ReceiveDetailID);
                if (rd == null || rd.ClientLocation.ScanKey == null) { return ""; }
                return rd.ClientLocation.ScanKey;
            }
            if (FieldName.ToUpper() == "RECEIVE_DATE")
            {
                ReceiveDetail rd = ctx.ReceiveDetails.FirstOrDefault(x => x.ReceiveDetailID == ReceiveDetailID);
                if (rd == null || rd.ReceiveDate == null) { return ""; }
                return string.Format("{0:MM/dd/yyyy}", rd.ReceiveDate);
            }
            if (FieldName.ToUpper() == "REPAIR DATE")
            {
                ReceiveDetailProcessLog pl = ctx.ReceiveDetailProcessLogs.OrderBy(x => x.CreateDate).FirstOrDefault(x => x.Process.Name.ToUpper() == "LAB BILLING" && x.ReceiveDetailID == ReceiveDetailID);
                if (pl == null) { return ""; }
                return string.Format("{0:MM/dd/yyyy}", pl.CreateDate);
            }
            if (FieldName.ToUpper() == "SHIPPING_CREATED" || FieldName.ToUpper() == "SHIPPING CREATED")
            {
                ReceiveDetailProcessLog pl = ctx.ReceiveDetailProcessLogs.OrderBy(x => x.CreateDate).FirstOrDefault(x => x.Process.Name.ToUpper() == "SHIPPING" && x.ReceiveDetailID == ReceiveDetailID);
                if (pl == null) { return ""; }
                return string.Format("{0:MM/dd/yyyy}", pl.CreateDate);
            }
            if (FieldName.ToUpper() == "RMANUMBER")
            {
                ReceiveDetail rd = ctx.ReceiveDetails.FirstOrDefault(x => x.ReceiveDetailID == ReceiveDetailID);
                if (rd == null || rd.RMANumber == null) { return ""; }
                return rd.RMANumber;
            }
            if (FieldName.ToUpper() == "IFSSKU" || FieldName.ToUpper() == "ESNSKU")
            {
                ReceiveDetail rd = ctx.ReceiveDetails.FirstOrDefault(x => x.ReceiveDetailID == ReceiveDetailID);
                if (rd == null || rd.SKU == null) { return ""; }
                return rd.SKU;
            }
            if (FieldName.ToUpper() == "IFSLOCATION" || FieldName.ToUpper() == "ESNLOCATION")
            {
                ReceiveDetail rd = ctx.ReceiveDetails.FirstOrDefault(x => x.ReceiveDetailID == ReceiveDetailID);
                if (rd == null || rd.IFSLocation == null) { return ""; }
                return rd.IFSLocation;
            }
            if (FieldName.ToUpper() == "IFSCONDITION" || FieldName.ToUpper() == "ESNCONDITION")
            {
                ReceiveDetail rd = ctx.ReceiveDetails.FirstOrDefault(x => x.ReceiveDetailID == ReceiveDetailID);
                if (rd == null || rd.IFSCondition == null) { return ""; }
                return rd.IFSCondition;
            }
            if (FieldName.ToUpper() == "ML_CONDITION") { return MasterCarrierManufacturerModelColourData(ctx, ReceiveDetailID, FieldName); }
            if (FieldName.ToUpper() == "ML_BAR_FLIP") { return MasterCarrierManufacturerModelColourData(ctx, ReceiveDetailID, FieldName); }
            if (FieldName.ToUpper() == "ML_CDMA_HSPA") { return MasterCarrierManufacturerModelColourData(ctx, ReceiveDetailID, FieldName); }
            if (FieldName.ToUpper() == "ML_DESCRIPTION") { return MasterCarrierManufacturerModelColourData(ctx, ReceiveDetailID, FieldName); }
            if (FieldName.ToUpper() == "ML_DEVICE_HANDSET") { return MasterCarrierManufacturerModelColourData(ctx, ReceiveDetailID, FieldName); }
            if (FieldName.ToUpper() == "ML_NICKNAME") { return MasterCarrierManufacturerModelColourData(ctx, ReceiveDetailID, FieldName); }
            if (FieldName.ToUpper() == "ML_RETIRE") { return MasterCarrierManufacturerModelColourData(ctx, ReceiveDetailID, FieldName); }
            if (FieldName.ToUpper() == "ML_SKU_A") { return MasterCarrierManufacturerModelColourData(ctx, ReceiveDetailID, FieldName); }
            if (FieldName.ToUpper() == "ML_SKU_B") { return MasterCarrierManufacturerModelColourData(ctx, ReceiveDetailID, FieldName); }
            if (FieldName.ToUpper() == "ML_SKU_C") { return MasterCarrierManufacturerModelColourData(ctx, ReceiveDetailID, FieldName); }
            if (FieldName.ToUpper() == "ML_SKU_LOANER") { return MasterCarrierManufacturerModelColourData(ctx, ReceiveDetailID, FieldName); }
            if (FieldName.ToUpper() == "ML_Unit_OS") { return MasterCarrierManufacturerModelColourData(ctx, ReceiveDetailID, FieldName); }
            if (FieldName.ToUpper() == "ML_UPC") { return MasterCarrierManufacturerModelColourData(ctx, ReceiveDetailID, FieldName); }
            if (FieldName.ToUpper() == "ML_UPC_2") { return MasterCarrierManufacturerModelColourData(ctx, ReceiveDetailID, FieldName); }
            if (FieldName.ToUpper() == "ML_UPC_3") { return MasterCarrierManufacturerModelColourData(ctx, ReceiveDetailID, FieldName); }
            if (FieldName.ToUpper() == "ML_WARRANTYSTICKERPLACEMENT") { return MasterCarrierManufacturerModelColourData(ctx, ReceiveDetailID, FieldName); }
            return ctx.GetReceiveDetailItem_DataElement(ReceiveDetailID, FieldName);
        }

