        public string MasterCarrierManufacturerModelColourData(clsLinqDataContext ctx, decimal ReceiveDetailID, string FieldName)
        {
            ReceiveDetail rd = ctx.ReceiveDetails.FirstOrDefault(x => x.ReceiveDetailID == ReceiveDetailID);
            if (rd == null) { return ""; }
            MasterCarrierManufacturerModelColourManager mcm = new MasterCarrierManufacturerModelColourManager(UserName);
            MasterCarrierManufacturerLookup mcl = mcm.GetMasterCarrierManufacturerLookup(ctx, rd.ReceiveDetailID, rd.Carrier, rd.Manufacturer, rd.Model, rd.Colour);
            if (mcl == null) { return ""; }
            if (FieldName.ToUpper() == "ML_CONDITION") if (mcl.Condition != null) { return mcl.Condition; }
            if (FieldName.ToUpper() == "ML_BAR_FLIP") if (mcl.Bar_Flip != null) { return mcl.Bar_Flip; }
            if (FieldName.ToUpper() == "ML_CDMA_HSPA") if (mcl.CDMA_HSPA != null) { return mcl.CDMA_HSPA; }
            if (FieldName.ToUpper() == "ML_DESCRIPTION") if (mcl.Description != null) { return mcl.Description; }
            if (FieldName.ToUpper() == "ML_DEVICE_HANDSET") if (mcl.Device_Handset != null) { return mcl.Device_Handset; }
            if (FieldName.ToUpper() == "ML_NICKNAME") if (mcl.NickName != null) { return mcl.NickName; }
            if (FieldName.ToUpper() == "ML_RETIRE") if (mcl.Retire != null) { return mcl.Retire; }
            if (FieldName.ToUpper() == "ML_SKU_A") if (mcl.SKU != null) { return mcl.SKU; }
            if (FieldName.ToUpper() == "ML_SKU_B") if (mcl.SKU_B != null) { return mcl.SKU_B; }
            if (FieldName.ToUpper() == "ML_SKU_C") if (mcl.SKU_C != null) { return mcl.SKU_C; }
            if (FieldName.ToUpper() == "ML_SKU_LOANER") if (mcl.SKU_Loaner != null) { return mcl.SKU_Loaner; }
            if (FieldName.ToUpper() == "ML_Unit_OS") if (mcl.Unit_OS != null) { return mcl.Unit_OS; }
            if (FieldName.ToUpper() == "ML_UPC") if (mcl.UPC != null) { return mcl.UPC; }
            if (FieldName.ToUpper() == "ML_UPC_2") if (mcl.UPC_2 != null) { return mcl.UPC_2; }
            if (FieldName.ToUpper() == "ML_UPC_3") if (mcl.UPC_3 != null) { return mcl.UPC_3; }
            if (FieldName.ToUpper() == "ML_WARRANTYSTICKERPLACEMENT") if (mcl.WarrantyStickerPlacement != null) { return mcl.WarrantyStickerPlacement; }
            return "";
        }



