        public List<ReceiveDetailItem> GetReceiveDetailItems_ThisDataItem(clsLinqDataContext ctx, string FieldName, string FieldValue)
        {
            List<ReceiveDetailItem> rd = null;
            string QType = QuestionType(FieldName);
            List<string> QDrops = QuestionDropCheckTypes();
            if (QDrops.Contains(QType) == true)     // if the type is a dropdown, checkbox or Radial Button, we need to look at the option to make the match
            {
                rd = ctx.ReceiveDetailItems.Where(x => x.Version == 0
                                                    && x.Option.Question.Name.ToUpper() == FieldName
                                                    && x.Option.OptionText.ToUpper() == FieldValue.ToUpper()
                                                    && x.ReceiveDetail.ReceiveDetailStatus.Status.ToUpper() != "GRAVEYARD").ToList();
            }
            else                                    // Otherwise we can look at the entered value.  
            {
                rd = ctx.ReceiveDetailItems.Where(x => x.Version == 0
                                                    && x.Option.Question.Name.ToUpper() == FieldName
                                                    && x.Value.ToUpper() == FieldValue.ToUpper()
                                                    && x.ReceiveDetail.ReceiveDetailStatus.Status.ToUpper() != "GRAVEYARD").ToList();
            }
            if (rd != null)
            {
                return rd;
            }
            return null;
        }
