        public string GetMasterQuestionJsonKeyValue(Hashtable dList, string QuestionName)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                var xList = ctx.GetMasterQuestionJsonKeyList(QuestionName).ToList();
                foreach (GetMasterQuestionJsonKeyListResult x in xList)
                {
                    string key = x.JsonKey;
                    string value = x.JsonValue;
                    string xType = x.Type;
                    if (dList.ContainsKey(key))
                    {
                        switch (xType.ToUpper())
                        {
                            case "CHECKBOX":
                                if (dList[key].ToString() == "1")
                                {
                                    return value;
                                }
                                break;
                            case "RADIALBUTTON":
                                if (dList[key].ToString() == "1")
                                {
                                    return value;
                                }
                                break;
                            case "DROPDOWN":
                                if (dList[key].ToString() == "1")
                                {
                                    return value;
                                }
                                break;
                            default:                  // Keybaord, Calendar, Calc
                                return dList[key].ToString();
                        }
                    }
                }
            }
            return "";
        }
