        public void RecordHeaderChange(ReceiveDetail rec)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                ReceiveDetailHeaderChangeLog rdhc = new ReceiveDetailHeaderChangeLog();
                rdhc.BinLocationID = rec.BinLocationID;
                rdhc.ClientLocationID = rec.ClientLocationID;
                rdhc.CreateDate = DateTime.Now;
                rdhc.CreateUser = UserName;
                rdhc.ESN = rec.ESN;
                rdhc.ICB = rec.ICB;
                rdhc.LastUpdateUser = UserName;
                rdhc.LastUpdateDate = DateTime.Now;
                rdhc.PIN = rec.PIN;
                rdhc.ProcessID = rec.ProcessID;
                rdhc.ProjectID = rec.ProjectID;
                rdhc.ProjectName = rec.ProjectName;
                rdhc.ProjectTag = rec.ProjectTag;
                rdhc.ReceiveDate = rec.ReceiveDate;
                rdhc.ReceiveDetailBulkID = rec.ReceiveDetailBulkID;
                rdhc.ReceiveDetailID = rec.ReceiveDetailID;
                rdhc.ReceiveHeaderID = rec.ReceiveHeaderID;
                rdhc.RMANumber = rec.RMANumber;
                rdhc.StatusID = rec.StatusID;
                ctx.ReceiveDetailHeaderChangeLogs.InsertOnSubmit(rdhc);
                ctx.SubmitChanges();
            }
        }
