        [DataObjectMethod(DataObjectMethodType.Insert)]
        public decimal?[] InsertReceiveDetail(ReceiveDetail Detail, decimal LogProcessID)
        {
            decimal?[] rValue = { -1, -1 };
            if (Detail != null)
            {
                Detail.ReceiveDate = DateTime.Now;
                using (clsLinqDataContext ctx = GetDataContext(UserName))
