                    rValue = InsertReceiveDetail(ctx, Detail, LogProcessID);
                }
            }
            return rValue;
        }



        public decimal?[] InsertReceiveDetail(clsLinqDataContext ctx, ReceiveDetail Detail, decimal LogProcessID)
        {
            decimal?[] rValue = { -1, -1 };
            if (Detail != null)
            {
                Detail.ReceiveDate = DateTime.Now;
                ReceiveHeader header = null;
                if (Detail.ReceiveHeaderID > 0)
                {
                    header = ctx.ReceiveHeaders.FirstOrDefault(x => x.ClientLocationID == Detail.ClientLocationID
                                                                 && x.ReceiveHeaderID == Detail.ReceiveHeaderID
                                                                 && x.ProjectName == Detail.ProjectName
                                                                 && x.RMANumber == Detail.RMANumber);
                }
                if (header == null)
                {
                    header = ctx.ReceiveHeaders.FirstOrDefault(x => x.RMANumber == Detail.RMANumber
                                                                 && x.ClientLocationID == Detail.ClientLocationID
                                                                 && x.ProjectName == Detail.ProjectName
                                                                 && x.RMANumber == Detail.RMANumber);
                    if (header == null)
                    {
                        // we have to create a new header
                        header = new ReceiveHeader();
                        header.ClientLocationID = Detail.ClientLocationID;
                        header.QTYPaper = 0;
                        header.QTYRecorded = 0;
                        header.StatusID = 1;
                        header.ProjectName = Detail.ProjectName;
                        header.RMANumber = Detail.RMANumber;
                        header.MiscNote = Detail.MiscNote;
                        header.ReceiveDate = Detail.ReceiveDate;
                        header.LastUpdateDate = DateTime.Now;
                        header.LastUpdateUser = UserName;
                        header.CreateDate = DateTime.Now;
                        header.CreateUser = UserName;
                        ctx.ReceiveHeaders.InsertOnSubmit(header);
                        //ctx.SubmitChanges();
                        //Detail.ReceiveHeaderID = header.ReceiveHeaderID;
                    }
                }

                // This is needed to Not add into the header more received items because it was received in bulk;
                if (Detail.ReceiveDetailBulkID == -1)        // Not a bulk added one.
                {
                    header.QTYPaper += Detail.QTYIntegrated;
                    header.QTYRecorded += Detail.QTYIntegrated;
                }
                Detail.StatusID = 1;
                Detail.LastUpdateDate = DateTime.Now;
                Detail.LastUpdateUser = UserName;
                Detail.CreateDate = DateTime.Now;
                Detail.CreateUser = UserName;
                Detail.Version = "000";
                header.ReceiveDetails.Add(Detail);
                ctx.SubmitChanges();


                if (LogProcessID < 1) { LogProcessID = Detail.ProcessID; }
                //SM.Add(ctx, Detail.ReceiveDetailID, -1, Detail.ClientLocationID, (decimal)Detail.ProjectID, LogProcessID, UserName);

                ctx.AddDetailProcessLog(Detail.ReceiveDetailID, Detail.ProcessID);
                ctx.SubmitChanges();
                rValue = new decimal?[] { (decimal?)Detail.ReceiveHeaderID, (decimal?)Detail.ReceiveDetailID };
            }
            return rValue;
        }


