        public string PostBillingPoint(string Action, decimal ReceiveDetailBillingPointsID, string InvoiceNo, DateTime? InvoiceDate, string UserName)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                var rd = (from rdl in ctx.ReceiveDetailBillingPoints where rdl.ReceiveDetailBillingPointsID == ReceiveDetailBillingPointsID select rdl).FirstOrDefault();
                if (rd == null) { return "record Not found"; }

                ReceiveDetail rdetail = null;
                if (Action.ToUpper() == "D")
                {
                    ctx.ReceiveDetailBillingPoints.DeleteOnSubmit(rd);
                    ctx.SubmitChanges();
                    rdetail = ReceiveDetail(rd.ReceiveDetailID);
                    //if (rdetail != null) { SM.BillingPointDelete(ctx, rd.ReceiveDetailID, rd.ClientID, rdetail.ClientLocationID, (decimal)rdetail.ProjectID, rdetail.ProcessID, UserName); }
                    return "Deleted";
                }
                if (Action.ToUpper() == "P")
                {
                    rd.PostedDate = DateTime.Now;
                    rd.PostedUser = UserName;
                    rd.LastUpdateDate = DateTime.Now;
                    rd.LastUpdateUser = UserName;
                    rd.GMPInvoice = InvoiceNo;
                    rd.GMPInvoiceDate = InvoiceDate;
                    ctx.SubmitChanges();
                    rdetail = ReceiveDetail(rd.ReceiveDetailID);
                    //if (rdetail != null) { SM.BillingPointPost(ctx, rd.ReceiveDetailID, rd.ClientID, rdetail.ClientLocationID, (decimal)rdetail.ProjectID, rdetail.ProcessID, UserName); }
                    return "Updated";
                }
                return "No Action Taken";
            }
        }

