        public void OffsetPreReceive(clsLinqDataContext ctx, decimal ReceiveDetailID, string ESN, string IPAddress)
        {
            //JimErrorLogManager logManager = new JimErrorLogManager(UserName, "OffsetPreReceive");
            logManager.ReportMessage("OffsetPreReceive e:" + ESN + " id:" + ReceiveDetailID.ToString());
             // Set Bin and Location on PreReceiveRecord
            //UpdateESNPreReceiveAttribute(ctx, ESN, "IDC Bin", "Bin");
            string Location = "";
            // Get location from last location log entry and move over to the pre-receive for update.
            LocationLog log = ctx.LocationLogs.OrderByDescending(x => x.LocationLogID).FirstOrDefault(x => x.ESN == ESN);
            if (log != null)
            {
                Location = log.Location;
                //ctx.SubmitChanges();
                logManager.ReportMessage("Step 1a Offset Pre Receive:" + ESN + ":" + ReceiveDetailID.ToString());

            }

            logManager.ReportMessage("Step 1b Offset Pre Receive:" + ESN + ":" + ReceiveDetailID.ToString() + ":" + Location); 
            UpdateESNPreReceiveAttribute(ctx, ESN, "Location", Location);
            logManager.ReportMessage("Step 2 Offset Pre Receive:" + ESN + ":" + ReceiveDetailID.ToString());


            IDC_LocationLogManager logman = new IDC_LocationLogManager(UserName, logManager.IsActive);
            logman.Add(ctx, ESN, "Bin", Location, ReceiveDetailID, UserName, IPAddress, "ACTIVE");
            logManager.ReportMessage("Step 3 Offset Pre Receive:" + ESN + ":" + ReceiveDetailID.ToString());

            ReceiveDetailPreReceive rdpr = (from x in ctx.ReceiveDetailPreReceives
                                            where x.ESN == ESN && x.Status.ToUpper() == "OPEN"
                                            select x).FirstOrDefault();
            if (rdpr == null) { return; }
            rdpr.ReceiveDetailID = ReceiveDetailID;
            rdpr.Status = "Closed";
            rdpr.OnSite = true;
            rdpr.LastUpdateDate = DateTime.Now;
            rdpr.LastUpdateUser = UserName;
            ctx.SubmitChanges();
            ReceiveDetail rd = (from x in ctx.ReceiveDetails
                                where x.ReceiveDetailID == ReceiveDetailID
                                select x).FirstOrDefault();

            //if (rdpr.RMANumber.Length > 0 ) {rd.RMANumber = rdpr.RMANumber;}
            //if (rdpr.ProjectTag.Length > 0 ) {rd.ProjectTag = rdpr.ProjectTag;}
            //if (rdpr.ModelID > 0 ) {rd.ModelID = rdpr.ModelID;}
            //if (rdpr.ManufacturerID > 0 ) {rd.ManufacturerID = rdpr.ManufacturerID;}
            //if (rdpr.CarrierID > 0 ) {rd.CarrierID = rdpr.CarrierID;}
            //if (rdpr.ColourID > 0) { rd.ColourID = rdpr.ColourID; }

            foreach (ReceiveDetailPreReceiveAttribute a in rdpr.ReceiveDetailPreReceiveAttributes)
            {
                UpdateESNAttribute(ctx, ReceiveDetailID, a.OptionID, CleanData(a.Value));
            }
            ctx.SubmitChanges();

        }


        private string CleanData(string Data)
        {
            string DoubleQuote = "\"";
            StringBuilder b = new StringBuilder(Data);
            b.Replace("[", string.Empty);
            b.Replace("]", string.Empty);
            b.Replace("'", string.Empty);
            b.Replace(DoubleQuote, string.Empty);

            //b.Replace("/", string.Empty);   // This needs to be gone because it is causing problems with Dates.
            b.Replace(@"\", string.Empty);
            return b.ToString();
        }


