                rValue = "Option" + "|";
                rValue += o.OptionID.ToString() + "|";
                rValue += o.Question.Name + "|";
                rValue += o.Name + "|";
                rValue += o.ScanKey + "|";
                rValue += o.Question.QuestionType.Type + "|";
                rValue += EnteredValue + "|xx";
            }
            return rValue;
        }

