        public PreReceiveDetailHeader GetPreReceiveDetail(clsLinqDataContext ctx, string ESN)
        {
            PreReceiveDetailHeader rh = new PreReceiveDetailHeader();
            ReceiveDetailPreReceive rd = ctx.ReceiveDetailPreReceives.Where(x => x.ESN == ESN && x.Status.ToUpper() == "OPEN").FirstOrDefault();
            if (rd == null) { rh.ESN = ""; return rh; }
            rh.ESN = ESN;
            rh.RMA = rd.RMANumber;
            rh.ProjectTag = rd.ProjectTag;
            rh.ProjectName = rd.ProjectName;
            rh.Type = rd.Type;
            rh.ProjectID = -1;
            if (rd.ProjectName != null && rd.ProjectName.Length > 0)
            {
                Project p = ctx.Projects.FirstOrDefault(x => x.Name.ToUpper() == rd.ProjectName.ToUpper());
                if (p != null)
                {
                    rh.ProjectID = p.ProjectID;
                }
            }
            List<PreReceiveDetailOptions> DetailOption = new List<PreReceiveDetailOptions>() { };
            foreach (ReceiveDetailPreReceiveAttribute a in rd.ReceiveDetailPreReceiveAttributes)
            {
                PreReceiveDetailOptions o = new PreReceiveDetailOptions();
                o.OptionID = a.OptionID;
                o.Value = a.Value;
                DetailOption.Add(o);
            }
            rh.DetailOptions = DetailOption;
            return rh;
        }



