        public decimal?[] UpdateReceiveDetail(clsLinqDataContext ctx, ReceiveDetail Detail, decimal LogProcessID)
        {
            decimal?[] rValue = { -1, -1 };
            if (Detail != null)
            {
                //if (uac.AllowAdd("ReceiveDetailBulk"))
                //{
                rValue = new decimal?[] { (decimal?)Detail.ReceiveHeaderID, (decimal?)Detail.ReceiveDetailID };
                ReceiveHeader header = null;
                if (Detail.ReceiveHeaderID > 0)
                {
                    header = ctx.ReceiveHeaders.FirstOrDefault(x => x.ReceiveHeaderID == Detail.ReceiveHeaderID);
                }
                if (header == null)
                {
                    header = ctx.ReceiveHeaders.FirstOrDefault(x => x.RMANumber == Detail.RMANumber && x.ClientLocationID == Detail.ClientLocationID);
                    if (header == null)
                    {
                        // we have to create a new header
                        header = new ReceiveHeader();
                        header.ClientLocationID = Detail.ClientLocationID;
                        header.QTYPaper = 0;
                        header.QTYRecorded = 0;
                        header.StatusID = 1;
                        header.ProjectName = Detail.ProjectName;
                        header.RMANumber = Detail.RMANumber;
                        header.MiscNote = Detail.MiscNote;
                        header.ReceiveDate = Detail.ReceiveDate;
                        header.LastUpdateDate = DateTime.Now;
                        header.LastUpdateUser = UserName;
                        header.CreateDate = DateTime.Now;
                        header.CreateUser = UserName;
                        ctx.ReceiveHeaders.InsertOnSubmit(header);
                    }
                }

                ReceiveDetail rd = ctx.ReceiveDetails.FirstOrDefault(x => x.ReceiveDetailID == Detail.ReceiveDetailID);
                if (rd != null)
                {
                    rd.BinLocationID = Detail.BinLocationID;
                    rd.ReceiveDetailBulkID = Detail.ReceiveDetailBulkID;
                    rd.LastUpdateDate = DateTime.Now;
                    rd.LastUpdateUser = UserName;
                    rd.MiscNote = Detail.MiscNote;
                    rd.ProcessID = Detail.ProcessID;
                    //////////////////////////
                    if (rd.StatusID != Detail.StatusID || rd.ProjectID != Detail.ProjectID ||
                        rd.ProjectName != Detail.ProjectName || rd.ProjectTag != Detail.ProjectTag ||
                        rd.RMANumber != Detail.RMANumber || rd.ClientLocationID != Detail.ClientLocationID || rd.ESN != Detail.ESN)
                    {
                        // Header Data. --- If any of these change, we should Send out a record of the change
                        rd.StatusID = Detail.StatusID;
                        rd.ProjectID = Detail.ProjectID;
                        rd.ProjectName = Detail.ProjectName;
                        rd.ProjectTag = Detail.ProjectTag;
                        rd.RMANumber = Detail.RMANumber;
                        rd.ClientLocationID = Detail.ClientLocationID;
                        rd.ESN = Detail.ESN;
                    }
                    ///////////////////////////////////////////////////////////////

                    ctx.SubmitChanges();

                    if (LogProcessID < 1) { LogProcessID = rd.ProcessID; }
                    //SM.Update(ctx, rd.ReceiveDetailID, -1, rd.ClientLocationID, (decimal)rd.ProjectID, LogProcessID, UserName);
                    rValue = new decimal?[] { (decimal?)Detail.ReceiveHeaderID, (decimal?)Detail.ReceiveDetailID };
                }
                //}
                //else
                //{
                //    throw new UserAccessControlException("Not authorized to add new BinLocations");
                //}
            }
            return rValue;
        }


