        public int TransferUnitToNewProjecct(clsLinqDataContext ctx, decimal ReceiveDetailId, decimal NewProjectID, string ProjectName)
        {
            var RD = ctx.ReceiveDetails.FirstOrDefault(x => x.ReceiveDetailID == ReceiveDetailId);
            if (RD != null)
            {
                RD.ProjectID = NewProjectID;
                RD.ProjectName = ProjectName;
                RD.LastUpdateDate = DateTime.Now;
