        [DataObjectMethod(DataObjectMethodType.Insert)]
        public decimal?[] InsertReceiveDetailItem(clsLinqDataContext ctx, ReceiveDetailItem DetailItem, bool add)
        {
            decimal?[] rValue = { -1, -1 };
            if (DetailItem != null)
            {
                // TODO Item Version Stop version bumping.
                // Change below -- we no longer want to add, but update the one that is there now, if there is non there, we want to add it.
                // To this.

                // Change this.


                if (DetailItem.Value.Trim().Length == 0)
                {
                    return rValue;
                }
                if (DetailItem.ReceiveDetailID > 0)
                {
                    ReceiveDetail Detail = ctx.ReceiveDetails.FirstOrDefault(x => x.ReceiveDetailID == DetailItem.ReceiveDetailID);
                    if (Detail != null)
                    {
                        //DetailItem.Version = 0;
                        DetailItem.ReceiveHeaderID = Detail.ReceiveHeaderID;
                        DetailItem.LastUpdateDate = DateTime.Now;
                        DetailItem.LastUpdateUser = UserName;

                        if (add == true)
                        {
                            DetailItem.CreateDate = DateTime.Now;
                            DetailItem.CreateUser = UserName;
                            Detail.ReceiveDetailItems.Add(DetailItem);
                        }
                        ctx.SubmitChanges();

                        ctx.AddBucketCount(Detail.ReceiveDetailID, Detail.ClientLocationID, (decimal)Detail.ProjectID, -1, -1, DetailItem.OptionID);

                    }
                }
            }
            return rValue;
        }

