        public void Authorize(clsLinqDataContext ctx, decimal ReceiveDetailAuthorizationLogID, string AuthorizeUserName, string IPAddress)
        {
            ReceiveDetailAuthorizationLog log = ctx.ReceiveDetailAuthorizationLogs.FirstOrDefault(x => x.ReceiveDetailAuthorizationLogID == ReceiveDetailAuthorizationLogID);
            if (log != null)
            {
                log.DeclinedDate = null;
                log.DeclinedBy = null;
                log.AuthorizedBy = AuthorizeUserName;
                log.AuthorizedDate = DateTime.Now;
                log.AuthorizedIP = IPAddress;
                log.LastUpdateDate = DateTime.Now;
                log.LastUpdateUser = UserName;
                ReceiveDetailAuthorizationStatus ls = ctx.ReceiveDetailAuthorizationStatus.FirstOrDefault(x => x.Status.ToUpper() == "APPROVED");
                if (ls != null)
                {
                    log.ReceiveDetailAuthorizationStatus = ls;
                }
                ctx.SubmitChanges();
                UpdateESNAttribute(ctx, log.ReceiveDetailID, "Authorization Status", "Approved");
                UpdateESNAttribute(ctx, log.ReceiveDetailID, "Authorized By", AuthorizeUserName);

                ClientLocation cl = GetClientLocationFromReceiveDetailID(log.ReceiveDetailID);
                if (cl != null && cl.ApprovalPassword != null && cl.ApprovalPassword.Length > 0)
                {
                    Received(ReceiveDetailAuthorizationLogID, AuthorizeUserName);
                }
                SendEmail e = new SendEmail();
                string[] AText = GetAuthorizationTextData(ctx, ReceiveDetailAuthorizationLogID);
                e.SendESNAuthorizedEmail(AText[0], AText[1]);
            }
        }

        private string[] GetAuthorizationTextData(clsLinqDataContext ctx, decimal ReceiveDetailAuthorixationLogID)
        {
            StringBuilder Subject = new StringBuilder();
            StringBuilder Body = new StringBuilder();
            string[] aText = { "Subject", "Body" };

            ReceiveDetailAuthorizationLog log = ctx.ReceiveDetailAuthorizationLogs.FirstOrDefault(x => x.ReceiveDetailAuthorizationLogID == ReceiveDetailAuthorixationLogID);
            if (log != null)
            {
                Subject.Append("ESN:");
                Subject.Append(log.ReceiveDetail.ESN);
                Subject.Append(" has been authorized by:");
                Subject.Append(log.AuthorizedBy);
                DateTime aDate = (DateTime)log.AuthorizedDate;
                if (log.AuthorizedDate != null)
                {

                    Subject.Append(" on:");
                    Subject.Append(aDate.ToString("MM/dd/yyyy HHmmss"));
                }
                decimal ReceiveDetailID = log.ReceiveDetailID;
                ReceiveDetailManager rm = new ReceiveDetailManager(UserName);


                Body.AppendLine("Client:" + rm.GetClientName(ctx, log.ReceiveDetail.ClientLocationID));
                Body.AppendLine("ClientLocation:" + rm.GetClientLocationName(ctx, log.ReceiveDetail.ClientLocationID));
                Body.AppendLine();


                Body.AppendLine("ESN:" + log.ReceiveDetail.ESN);
                Body.AppendLine(rm.CarrierMakeModelColour(ctx, log.ReceiveDetail.ReceiveDetailID));
                Body.AppendLine("Authorized Date:" + aDate.ToString("MM/dd/yyyy HHmmss"));
                Body.AppendLine("Authorized By:" + log.AuthorizedBy);
                //Body.AppendLine("Client:" + rm.GetClientName(ctx, log.ReceiveDetail.ClientLocationID));
                //Body.AppendLine("Client:" + rm.GetClientName(ctx, log.ReceiveDetail.ClientLocationID));


            }

            aText[0] = Subject.ToString();
            aText[1] = Body.ToString();
            return aText;
        }




