        #region Select_Insert_Delete_Update


        [DataObjectMethod(DataObjectMethodType.Insert)]
        public decimal?[] InsertReceiveDetailBulk(ReceiveDetailBulk Detail)
        {
            return InsertReceiveDetailBulk(Detail, true);
        }

        [DataObjectMethod(DataObjectMethodType.Insert)]
        public decimal?[] InsertReceiveDetailBulk(ReceiveDetailBulk Detail, bool CreateChildren)
        {
            decimal?[] rValue = { -1, -1 };
            if (Detail != null)
            {
                //if (uac.AllowAdd("ReceiveDetailBulk"))
                //{
                using (clsLinqDataContext ctx = GetDataContext(UserName))
                {
                    ReceiveHeader header = null;
                    if (Detail.ReceiveHeaderID > 0)
                    {
                        header = ctx.ReceiveHeaders.FirstOrDefault(x => x.ClientLocationID == Detail.ClientLocationID
                                                                     && x.ReceiveHeaderID == Detail.ReceiveHeaderID
                                                                     && x.ProjectName == Detail.ProjectName
                                                                     && x.RMANumber == Detail.RMANumber);
                    }
                    if (header == null)
                    {
                        header = ctx.ReceiveHeaders.FirstOrDefault(x => x.RMANumber == Detail.RMANumber
                                                                     && x.ClientLocationID == Detail.ClientLocationID
                                                                     && x.ProjectName == Detail.ProjectName);
                        if (header == null)
                        {
                            // we have to create a new header
                            header = new ReceiveHeader();
                            header.ClientLocationID = Detail.ClientLocationID;
                            header.QTYPaper = 0;
                            header.QTYRecorded = 0;
                            header.StatusID = 1;
                            header.ProjectName = Detail.ProjectName;
                            header.RMANumber = Detail.RMANumber;
                            header.MiscNote = Detail.MiscNote;
                            header.ReceiveDate = Detail.ReceiveDate;
                            header.LastUpdateDate = DateTime.Now;
                            header.LastUpdateUser = UserName;
                            header.CreateDate = DateTime.Now;
                            header.CreateUser = UserName;
                            ctx.ReceiveHeaders.InsertOnSubmit(header);
                        }
                    }
                    if (CreateChildren == true)
                    {
                        ctx.GenerateReceiveDetailRecordsFromBulk(Detail.ReceiveDetailBulkID);
                        header.QTYPaper += Detail.QTYRecorded;
                        header.QTYRecorded += Detail.QTYRecorded;
                    }

                    //Detail.QTYRecorded = Detail.QTYIntegrated;
                    Detail.QTYIntegrated = 0;
                    Detail.StatusID = 1;
                    Detail.LastUpdateDate = DateTime.Now;
                    Detail.LastUpdateUser = UserName;
                    Detail.CreateDate = DateTime.Now;
                    Detail.CreateUser = UserName;
                    header.ReceiveDetailBulks.Add(Detail);
                    ctx.SubmitChanges();
                    ctx.AddDetailBulkProcessLog(Detail.ReceiveDetailBulkID, Detail.ProcessID);
                    ctx.SubmitChanges();

                    if (CreateChildren == true)
                    {
                        ctx.GenerateReceiveDetailRecordsFromBulk(Detail.ReceiveDetailBulkID);
                    }

                    rValue = new decimal?[] { (decimal?)Detail.ReceiveHeaderID, (decimal?)Detail.ReceiveDetailBulkID };
                }
                //}
                //else
                //{
                //    throw new UserAccessControlException("Not authorized to add new BinLocations");
                //}
            }
            return rValue;
        }

        [DataObjectMethod(DataObjectMethodType.Update)]
        public void Update_ReceiveDetailBulkItemOption_Version(decimal mReceiveDetailBulkID, decimal OptionID)
        {
            if (mReceiveDetailBulkID > 0 && OptionID > 0)
            {
                //if (uac.AllowAdd("ReceiveDetailBulk"))
                //{
                using (clsLinqDataContext ctx = GetDataContext(UserName))
                {
                    ctx.Update_ReceiveDetailItemBulkOption_Version(mReceiveDetailBulkID, OptionID);
                }
            }
            return;
        }




        [DataObjectMethod(DataObjectMethodType.Update)]
        public decimal?[] UpdateReceiveDetailBulk(ReceiveDetailBulk Detail)
        {
            decimal?[] rValue = { -1, -1 };
            if (Detail != null)
            {
                rValue = new decimal?[] { (decimal?)Detail.ReceiveHeaderID, (decimal?)Detail.ReceiveDetailBulkID };
                using (clsLinqDataContext ctx = GetDataContext(UserName))
                {
                    ReceiveDetailBulk rdb = ctx.ReceiveDetailBulks.FirstOrDefault(x => x.ReceiveDetailBulkID == Detail.ReceiveDetailBulkID);
                    if (rdb != null)
                    {



                        //Detail.QTYRecorded = Detail.QTYIntegrated;
                        rdb.StatusID = Detail.StatusID;
                        rdb.RMANumber = Detail.RMANumber;
                        rdb.QTYRecorded = Detail.QTYRecorded;
                        rdb.QTYIntegrated = Detail.QTYIntegrated;
                        rdb.ProcessID = Detail.ProcessID;
                        rdb.ProjectID = Detail.ProjectID;
                        rdb.ProjectName = Detail.ProjectName;
                        rdb.ProjectTag = Detail.ProjectTag;
                        rdb.BinLocationID = Detail.BinLocationID;
                        rdb.ESN = Detail.ESN;
                        rdb.ICB = Detail.ICB;
                        rdb.MiscNote = Detail.MiscNote;
                        rdb.PIN = Detail.PIN;

                        rdb.LastUpdateDate = DateTime.Now;
                        rdb.LastUpdateUser = UserName;
                        ctx.SubmitChanges();
                    }
                }
            }
            return rValue;
        }



        [DataObjectMethod(DataObjectMethodType.Insert)]
        public decimal?[] InsertReceiveDetailBulkItem(ReceiveDetailItemBulk DetailItem)
        {
            decimal?[] rValue = { -1, -1 };
            if (DetailItem != null)
            {
                //if (uac.AllowAdd("ReceiveDetailBulk"))
                //{
                using (clsLinqDataContext ctx = GetDataContext(UserName))
                {
                    Option op = ctx.Options.FirstOrDefault(x => x.OptionID == DetailItem.OptionID);
                    if (op != null)
                    {
                        // We don't want to save a Unselected checkbox, radialbutton or dropdown.
                        if ((op.Question.QuestionType.Type.ToUpper() == "CHECKBOX" ||
                             op.Question.QuestionType.Type.ToUpper() == "RADIALBUTTON" ||
                             op.Question.QuestionType.Type.ToUpper() == "DROPDOWN") && DetailItem.Value == "0")
                        {
                            return rValue;
                        }

                        ReceiveDetailBulk Detail = null;
                        if (DetailItem.ReceiveDetailBulkID > 0)
                        {
                            Detail = ctx.ReceiveDetailBulks.FirstOrDefault(x => x.ReceiveDetailBulkID == DetailItem.ReceiveDetailBulkID);
                            if (Detail != null)
                            {
                                //DetailItem.Version = 0;
                                DetailItem.ReceiveHeaderID = Detail.ReceiveHeaderID;
                                DetailItem.LastUpdateDate = DateTime.Now;
                                DetailItem.LastUpdateUser = UserName;
                                DetailItem.CreateDate = DateTime.Now;
                                DetailItem.CreateUser = UserName;
                                Detail.ReceiveDetailItemBulks.Add(DetailItem);
                                ctx.SubmitChanges();
                            }
                        }
                    }
                }
                //}
                //else
                //{
                //    throw new UserAccessControlException("Not authorized to add new BinLocations");
                //}
            }
            return rValue;
        }


        [DataObjectMethod(DataObjectMethodType.Insert)]
        public void Update_ReceiveDetailItemBulk_Version(decimal mReceiveHeaderID, decimal mReceiveDetailBulkID)
        {
            if (mReceiveDetailBulkID > 0 && mReceiveHeaderID > 0)
            {
                //if (uac.AllowAdd("ReceiveDetailBulk"))
                //{
                using (clsLinqDataContext ctx = GetDataContext(UserName))
                {
                    ctx.Update_ReceiveDetailItemBulk_Version(mReceiveHeaderID, mReceiveDetailBulkID);
                }
                //}
                //else
                //{
                //    throw new UserAccessControlException("Not authorized to add new BinLocations");
                //}
            }
            return;
        }

        #endregion
    }

