        [DataObjectMethod(DataObjectMethodType.Select)]
        public List<View_ReceiveDetailBulkSummary> GetBulkSearchList(decimal CLID, string RMA, string cProcess)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                var rd = from bulk in ctx.View_ReceiveDetailBulkSummaries where bulk.RMANumber == RMA && bulk.ClientLocationID == CLID orderby bulk.LastUpdateDate select bulk;
                rd.OrderByDescending(x => x.LastUpdateDate);

                //if (rd == null || CLID < 1)
                //{
                //    rd = from bulk in ctx.View_ReceiveDetailBulkSummaries where (bulk.ProcessName == cProcess) select bulk;
                //    rd.OrderByDescending(x => x.LastUpdateDate);
                //}

                return rd.ToList<View_ReceiveDetailBulkSummary>();
            }
        }

        [DataObjectMethod(DataObjectMethodType.Select)]
        public List<View_ReceiveDetailSummary> GetItemSearchList(decimal CLID, string ESN, string cProcess)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                var rd = from bulk in ctx.View_ReceiveDetailSummaries where bulk.ESN == ESN && bulk.ClientLocationID == CLID orderby bulk.LastUpdateDate select bulk;
                rd.OrderByDescending(x => x.LastUpdateDate);

                if (rd == null || CLID < 1)
                {
                    if (cProcess.ToUpper() == "SEARCH")
                    {
                        rd = from bulk in ctx.View_ReceiveDetailSummaries where bulk.LastUpdateDate >= DateTime.Now.AddMonths(-1) orderby bulk.LastUpdateDate select bulk;
                        rd.OrderByDescending(x => x.LastUpdateDate);
                    }
                    else
                    {
                        rd = from bulk in ctx.View_ReceiveDetailSummaries where bulk.ProcessName == cProcess orderby bulk.LastUpdateDate select bulk;
                        rd.OrderByDescending(x => x.LastUpdateDate);
                    }
                }
                return rd.ToList<View_ReceiveDetailSummary>();
            }
        }

