    #region MasterClasses



    [DataObject]
    public class MasterBucketTransactionManager
    {
        string _UserName = string.Empty;
        //public BL_UserDataRestrictor UserRestrict = null;

        public String UserName
        {
            get { return _UserName; }
            set { _UserName = value; }
        }

        public MasterBucketTransactionManager(string UserName)
        {
            _UserName = UserName;
            if (_UserName.Trim().Length == 0)
            {
                _UserName = "NullUser";
            }
            //UserRestrict = new BL_UserDataRestrictor(_UserName);
        }

        public clsLinqDataContext GetDataContext()
        {
            return GetDataContext(_UserName);
        }

        public clsLinqDataContext GetDataContext(string UserName)
        {
            clsLinqDataContext ctx = new clsLinqDataContext();
            ctx.UserName = UserName;
            return ctx;
        }

        public List<MasterBucketTransaction> ProcessTransactions(decimal ID)
        {
            using (clsLinqDataContext ctx = GetDataContext())
            {
                var data = from x in ctx.MasterBucketTransactions where x.ProcessID == ID select x;
                return data.ToList();

            }
        }
        public List<MasterBucketTransaction> QuestionTransactions(decimal ID)
        {
            using (clsLinqDataContext ctx = GetDataContext())
            {
                var data = from x in ctx.MasterBucketTransactions where x.QuestionID == ID select x;
                return data.ToList();

            }
        }
        public List<MasterBucketTransaction> OptionTransactions(decimal ID)
        {
            using (clsLinqDataContext ctx = GetDataContext())
            {
                var data = from x in ctx.MasterBucketTransactions where x.OptionID == ID select x;
                return data.ToList();

            }
        }
        public List<MasterBucketTransaction> ProjectTransactions(decimal ID)
        {
            using (clsLinqDataContext ctx = GetDataContext())
            {
                var data = from x in ctx.MasterBucketTransactions where x.ProjectID == ID select x;
                return data.ToList();

            }
        }

        public MasterBucketTransaction Get(decimal ID)
        {
            using (clsLinqDataContext ctx = GetDataContext())
            {
                MasterBucketTransaction data = (from x in ctx.MasterBucketTransactions where x.MasterBucketTransactionsID == ID select x).FirstOrDefault();
                return data;
            }
        }

        private bool Insert(decimal ProjectID, decimal ProcessID, decimal QuestionID, decimal OptionID, bool Active, string Action, int count, bool Single)
        {
            if (Action.Length == 0) { return false; }
            using (clsLinqDataContext ctx = GetDataContext())
            {
                MasterBucketTransaction bt = new MasterBucketTransaction();
                bt.Action = Action;
                bt.Active = Active;
                bt.Count = count;
                bt.CreateDate = DateTime.Now;
                bt.CreateUser = UserName;
                bt.OneOnly = Single;
                bt.OptionID = OptionID;
                bt.ProcessID = ProcessID;
                bt.ProjectID = ProjectID;
                bt.QuestionID = QuestionID;
                bt.LastCreateDate = DateTime.Now;
                bt.LastCreateUser = UserName;
                bt.ActionGroup = "";
                ctx.MasterBucketTransactions.InsertOnSubmit(bt);
                ctx.SubmitChanges();
                return true;
            }
        }
        public bool InsertProject(decimal ID, bool Active, string Action, int count, bool Single)
        {
            return Insert(ID, -1, -1, -1, Active, Action, count, Single);
        }
        public bool InsertProcess(decimal ID, bool Active, string Action, int count, bool Single)
        {
            return Insert(-1, ID, -1, -1, Active, Action, count, Single);
        }
        public bool InsertQuestion(decimal ID, bool Active, string Action, int count, bool Single)
        {
            return Insert(-1, -1, ID, -1, Active, Action, count, Single);
        }
        public bool InsertOption(decimal ID, bool Active, string Action, int count, bool Single)
        {
            return Insert(-1, -1, -1, ID, Active, Action, count, Single);
        }

        public bool Update(decimal ID, bool Active, string Action, int count, bool Single)
        {
            if (Action.Length == 0) { return false; }
            using (clsLinqDataContext ctx = GetDataContext())
            {
                MasterBucketTransaction bt = (from x in ctx.MasterBucketTransactions where x.MasterBucketTransactionsID == ID select x).FirstOrDefault();
                if (bt != null)
                {
                    bt.Action = Action;
                    bt.Active = Active;
                    bt.Count = count;
                    bt.OneOnly = Single;
                    bt.LastCreateDate = DateTime.Now;
                    bt.LastCreateUser = UserName;
                    ctx.SubmitChanges();
                }
                return true;
            }
        }
        public void Delete(decimal ID)
        {
            using (clsLinqDataContext ctx = GetDataContext())
            {
                var data = (from x in ctx.MasterBucketTransactions where x.MasterBucketTransactionsID == ID select x).FirstOrDefault();
                if (data != null)
                {
                    ctx.MasterBucketTransactions.DeleteOnSubmit(data);
                    ctx.SubmitChanges();
                }

            }
        }
    }

