        public string GetSetUpFieldDef(clsLinqDataContext ctx, decimal projectid)
        {
            string rString = "";
            var Projects = ctx.Projects.FirstOrDefault(x => x.ProjectID == projectid);
            if (Projects != null)
            {
                if (Projects.Gather_RMANumber == true)
                {
                    rString += "ZRMAZ";
                    if (Projects.GatherAuto_RMANumber == true)          // RMA numbers can be calculated two way, Work order or RMA
                    {
                        if (Projects.Auto_WorkOrder == true) { rString += "ZAUTOWZ"; }
                        else { rString += "ZAUTORZ"; }
                    }
                    else { rString += "ZEDITZ"; }
                }




                if (Projects.Gather_ProjectTag == true)
                {
                    rString += "ZPTAGZ";
                    if (Projects.GatherAuto_ProjectTag == true)
                    {
                        rString += "ZAUTOZ";
                    }
                    else { rString += "ZEDITZ"; }
                }
                //if (Projects.Gather_RMANumber == true && Projects.GatherAuto_RMANumber == false) { rString += ",RMAEdit,"; }
                //if (Projects.Gather_ProjectTag == true && Projects.GatherAuto_ProjectTag == false) { rString += ",PTagEdit,"; }
                //if (Projects.GatherAuto_RMANumber == true) { rString += ",RMAAuto,"; }
                //if (Projects.GatherAuto_ProjectTag == true) { rString += ",PTAuto,"; }

            }
            return rString;
        }


