        [DataObjectMethod(DataObjectMethodType.Update)]
        public void UpdateProject(Project Project)
        {
            // We are interested only in the security on the question, not the answer
            //if (uac.AllowUpdate("Project", Project.ProjectID))
            //{
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                var existingProject = (from q in ctx.Projects where q.ProjectID == Project.ProjectID select q).FirstOrDefault();
                if (existingProject != null)
                {
                    existingProject.Name = Project.Name;
                    existingProject.Description = Project.Description;
                    existingProject.BagTagName = Project.BagTagName;
                    existingProject.StatusID = Project.StatusID;
                    existingProject.Gather_ProjectTag = Project.Gather_ProjectTag;
                    existingProject.Gather_RMANumber = Project.Gather_RMANumber;
                    existingProject.GatherAuto_ProjectTag = Project.GatherAuto_ProjectTag;
                    existingProject.GatherAuto_RMANumber = Project.GatherAuto_RMANumber;
                    existingProject.Auto_RMANumber = Project.Auto_RMANumber;
                    existingProject.Auto_WorkOrder = Project.Auto_WorkOrder;
                    existingProject.AllowProjectPassThrough = Project.AllowProjectPassThrough;
                    existingProject.isMasterCarrierManufactuerLinked = Project.isMasterCarrierManufactuerLinked;
                    existingProject.isSecondaryProjectOverride = Project.isSecondaryProjectOverride;
                    existingProject.LastUpdateDate = DateTime.Now;
                    existingProject.LastUpdateUser = UserName;
                    existingProject.ProductTag = Project.ProductTag;
                    ctx.SubmitChanges();
                }
            }
            //}
            //else
            //{
            //    throw new UserAccessControlException("Not authorized to Update");
            //}
        }

