        [DataObjectMethod(DataObjectMethodType.Delete)]
        public void DeleteProject(decimal ProjectID)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                var ProjectToDelete = (from q in ctx.Projects where q.ProjectID == ProjectID select q).FirstOrDefault();
                //if (uac.AllowDelete("Project", ProjectToDelete.ProjectID))
                //{
                if (ProjectToDelete != null)
                {
                    IQueryable<ProjectProcess> pp = from x in ctx.ProjectProcesses where x.ProjectID == ProjectID select x;
                    if (pp != null)
                    {
                        foreach (ProjectProcess op in pp)
                        {
                            ctx.ProjectProcesses.DeleteOnSubmit(op);
                        }
                    }
                    ctx.Projects.DeleteOnSubmit(ProjectToDelete);
                    ctx.SubmitChanges();
                }
                //}
                //else
                //{
                //    throw new UserAccessControlException("Not authorized to Delete");
                //}
            }
        }
