        public string GetReturnTypeForParts(decimal ReceiveDetailID)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {

                var Record = ctx.ReceiveDetailItems.FirstOrDefault(x => x.ReceiveDetailID == ReceiveDetailID && x.Option.Question.Name == "Receipt Type");
                if (Record == null) { return "Not set"; }
                return ":" + Record.Option.OptionText + ":";
                //if (Record.ReceiveDetail.ClientLocation.Client.InWarrentyPricing == false) { return true; }
                //if (Record.Option.OptionText.ToUpper() == "IN WARRANTY" || Record.Option.OptionText.ToUpper() == "OUT OF WARRANTY") { return true; } // all others are invalid.
                //Buyer's Remorse
                //Defective
                //Unknown
                //BER
                //DOA
                //In Warranty
                //Extended Warranty
                //Out of Warranty 
                //Inventory
                //NFF
                //Estimate
