        public bool IsValidReturnTypeForParts(decimal ReceiveDetailID)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                // we need to see if this is a MAIN WHS unit. If it is, we want to return true, we don't care about Receipt Type.
                if (DoesThisReceiveDetailIDHaveOnsiteInventory(ctx, ReceiveDetailID) == false) { return true; }

                var Record = ctx.ReceiveDetailItems.FirstOrDefault(x => x.ReceiveDetailID == ReceiveDetailID &&  x.Option.Question.Name == "Receipt Type"
                     && x.ReceiveDetail.ClientLocation.Client.InWarrentyPricing != null && x.ReceiveDetail.ClientLocation.Client.InWarrentyPricing == true);
                if (Record == null) { return true; }
                //if (Record.ReceiveDetail.ClientLocation.Client.InWarrentyPricing == false) { return true; }



                // otherwise, we want to restrict to just these two types.
                if (Record.Option.OptionText.Trim().ToUpper() == "IN WARRANTY" || Record.Option.OptionText.Trim().ToUpper() == "OUT OF WARRANTY"
                 || Record.Option.OptionText.Trim().ToUpper() == "BUYER'S REMORSE" || Record.Option.OptionText.Trim().ToUpper() == "DOA") { return true; }

                // as per Deanns request, doa and Buyers Remorse were added 09/18/2014
                // DOA and Buyer’s Remorse

                // all others are invalid.
                //
                //Defective
                //Unknown
                //BER
                //DOA
                //In Warranty
                //Extended Warranty
                //Out of Warranty 
                //Inventory
                //NFF
                //Estimate
                //B2B DOA
                //Loaner
                //Demo
                //Recall/Remix
                return false;
            }

        }
        public bool IsReturnTypeForParts_OutOfWarranty(decimal ReceiveDetailID)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                var Record = ctx.ReceiveDetailItems.FirstOrDefault(x => x.ReceiveDetailID == ReceiveDetailID && x.Option.Question.Name == "Receipt Type");
                if (Record == null) { return false; }
                if (Record.Option.OptionText.Trim().ToUpper() == "OUT OF WARRANTY") { return true; }
                return false;
            }

        }   


