        public List<FullPartNumberList> GetFullPartNumberList(decimal ClientID,decimal ClientLocationID, decimal CarrierID, decimal ManufacturerID, decimal ModelID)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                return GetFullPartNumberList(ctx, ClientID,ClientLocationID, CarrierID, ManufacturerID, ModelID);
