        private List<FullPartNumberList> GetPartNumberList(clsLinqDataContext ctx, decimal ReceiveDetailID, decimal ClientID, decimal ClientLocationID, decimal CarrierID, decimal ManufacturerID, decimal ModelID)
        {
            // List<FullPartNumberList> pnl = new List<FullPartNumberList> { };
            List<FullPartNumberList> pnl = new List<FullPartNumberList>();
            var pm = (from x in ctx.MasterParts
                      orderby x.Description
                      select new FullPartNumberList
                      {
                          MasterPartID = x.MasterPartsID,
                          MasterPartsLinkTableID = -1,
                          Level = 0,
                          Stock = 0,
                          UnitPrice = 0,
                          StatusID = 1,
                          GMPDescription = "",
                          Description = x.Description,
                          PartNumber = ""
                      }).ToList();

            //return null;

            if (pm == null || pm.Count == 0) { return null; }
            foreach (FullPartNumberList pn in pm)
            {
                List<MasterPartsLinkTable> partnumberl = GetMasterPartNumbersRegress_03(ctx, ReceiveDetailID, pn.MasterPartID, ClientID, ClientLocationID, CarrierID.ToString(), ManufacturerID.ToString(), ModelID.ToString());
                if (partnumberl != null)
                {
                    decimal qty = 0;
                    foreach (MasterPartsLinkTable partnumber in partnumberl)
                    {
                        var Storage = ctx.MasterPartsTableIFSLocationStorages.Where(x => x.MasterPartsLinkTableID == partnumber.MasterPartsLinkTableID);
                        foreach (MasterPartsTableIFSLocationStorage s in Storage.OrderBy(x => x.MasterIFSLocations.IFSLocation))
                        {
                            FullPartNumberList npn = new FullPartNumberList();
                            npn.PartNumber = partnumber.PartNumber;
                            npn.Class = GetPartNumberClassType(ctx, partnumber.MasterPartsClassTypeID);
                            npn.MasterPartID = pn.MasterPartID;
                            npn.Level = pn.Level;
                            npn.Description = pn.Description;
                            npn.GMPDescription = partnumber.GMPPartDescription;
                            qty = 0;
                            if (s.QTY != null) { qty = (decimal)s.QTY; }
                            npn.Stock = qty;
                            npn.MasterIFSLocationID = s.MasterIFSLocationID;
                            //npn.Stock = partnumber.Quantity;
                            if (partnumber.UnitPrice == null) { npn.UnitPrice = (decimal)0; } else { npn.UnitPrice = (decimal)partnumber.UnitPrice; }
                            npn.StatusID = pn.StatusID;
                            npn.MasterPartsLinkTableID = partnumber.MasterPartsLinkTableID;
                            pnl.Add(npn);
                        }
                    }
                }
            }
            return pnl;
        }

         private List<FullPartNumberList> GetPartNumberListTechAssigned(clsLinqDataContext ctx, decimal ReceiveDetailID, decimal ClientID, decimal ClientLocationID, decimal CarrierID, decimal ManufacturerID, decimal ModelID)
        {
            List<PartNumberTechAssignedList> TechList = GetPartNumberTechAssignedList(ctx, ReceiveDetailID);
            List<FullPartNumberList> ReturnList = new List<FullPartNumberList>();
            List<MasterPart> msterPart = (from x in ctx.MasterParts
                      orderby x.Description
                      select x).ToList();

            if (msterPart == null || msterPart.Count == 0) { return null; }
            foreach (PartNumberTechAssignedList tl in TechList)
            {
                MasterPartsLinkTable partnumber = ctx.MasterPartsLinkTables.FirstOrDefault(x => x.MasterPartsLinkTableID == tl.MasterPartsLinkTableID);
                if (partnumber != null)
                {
                    MasterPart pn = msterPart.FirstOrDefault(x => x.MasterPartsID == partnumber.MasterPartsID);
                    FullPartNumberList npn = new FullPartNumberList();
                    npn.PartNumber = partnumber.PartNumber;
                    npn.Class = GetPartNumberClassType(ctx, partnumber.MasterPartsClassTypeID);
                    npn.MasterPartID = pn.MasterPartsID;
                    npn.Level = 0;
                    npn.Description = pn.Description;
                    npn.GMPDescription = partnumber.GMPPartDescription;
                    npn.Stock = partnumber.Quantity;
                    if (partnumber.UnitPrice == null) { npn.UnitPrice = (decimal)0; } else { npn.UnitPrice = (decimal)partnumber.UnitPrice; }
                    npn.StatusID = 1;
                    npn.MasterPartsLinkTableID = partnumber.MasterPartsLinkTableID;
                    ReturnList.Add(npn);
                }
            }
            return ReturnList;
        }


