        private static List<PartNumberTechAssignedList> GetPartNumberTechAssignedList(clsLinqDataContext ctx, decimal ReceiveDetailID)
        {
            List<PartNumberTechAssignedList> pnl = new List<PartNumberTechAssignedList>();
            pnl = (from x in ctx.MasterPartsTechAssignedLogs
                   where x.ReceiveDetailID == ReceiveDetailID && x.Status == "Tech Assigned"
                   orderby x.Description
                   select new PartNumberTechAssignedList
                   {
                       MasterPartID = -1,
                       MasterPartsLinkTableID = x.MasterPartsLinkTableID,
                       MasterPartsTechAssignedLogID = x.MasterPartsTechAssignedLogID,
                       ReceiveDetailID = x.ReceiveDetailID,
                       ReceiveDetailItemID = x.ReceiveDetailItemID,
                       Status = x.Status,
                       GMPPartNumber = x.GMPPartNumber,
                       PartNumber = x.GMPPartNumber
                   }).ToList();
            return pnl;
        }        
