        public decimal GetClientUnitPrice(clsLinqDataContext ctx, decimal MasterPartsLinkTableID, decimal ReceiveDetailID, MasterPartsLinkTable Part, JimErrorLogManager logmanager)
        {
            logmanager.ReportMessage("GetClientUnitPrice(" + MasterPartsLinkTableID.ToString() + ReceiveDetailID.ToString() + ")");
            //decimal OriginalPrice = 0;
            decimal rValue = (decimal)Part.UnitPrice;
            logmanager.ReportMessage(" Default Unit Price:" + rValue.ToString());
            ReceiveDetail rd = ctx.ReceiveDetails.FirstOrDefault(x => x.ReceiveDetailID == ReceiveDetailID);
            if (rd == null)
            {
                logmanager.ReportMessage(" Receive Detail == Null. Returning this price:" + rValue.ToString());
                return rValue;      // Return the original part price.
            }
            if (rd.ClientLocation.Client == null || rd.ClientLocation.Client.InWarrentyPricing == null)
            {
                logmanager.ReportMessage(" ClientLocation.Client.InWarrentyPricing == Null. Returning this price:" + rValue.ToString());
                return rValue;      // Return the original part price.
            }
            if (rd.ClientLocation.Client.InWarrentyPricing == false)
            {
                logmanager.ReportMessage("  ClientLocation.Client.InWarrentyPricing == " + rd.ClientLocation.Client.InWarrentyPricing.ToString() + ". Returning this price:" + rValue.ToString());
                return rValue;      // Return the original part price.
            }

            ReceiveDetailItem di = rd.ReceiveDetailItems.FirstOrDefault(x => x.Option.Question.Name == "Receipt Type");
            if (di == null)
            {
                logmanager.ReportMessage("  No Receipt Type found for this unit. Returning this price:" + rValue.ToString());
                return rValue;
            }
            if (di.Option.OptionText.Trim().ToUpper() == "OUT OF WARRANTY")
            {
                logmanager.ReportMessage("  Receipt Type == " + di.Option.OptionText.Trim().ToUpper() + ". Returning this price:" + rValue.ToString());
                return rValue;
            }
            // 09/17/2014 - Deann included DOA and Buyer's Remorse Receipt Types to pull the inWarrenty Work Price.
            logmanager.ReportMessage("Made It through Receipt Type == " + ((decimal)Part.InWarrentyWorkPrice).ToString() + ". Returning this price:" + rValue.ToString());
            // We have a client and Unit under warrenty, use the warrenty price
            return (decimal)Part.InWarrentyWorkPrice;
        }




