        [DataObjectMethod(DataObjectMethodType.Insert)]
        public decimal InsertType(PartNumberBucketInventoryTransactionType mp)
        {
            decimal ReturnValue = -1;
            if (mp != null)
            {
                using (clsLinqDataContext ctx = GetDataContext(UserName))
                {
                    if (mp.Factor == null || mp.Factor == 0) { mp.Factor = 1; }
                    mp.LastUpdateDate = DateTime.Now;
                    mp.LastUpdateUser = UserName;
                    mp.CreateDate = DateTime.Now;
                    mp.CreateUser = UserName;
                    ctx.PartNumberBucketInventoryTransactionTypes.InsertOnSubmit(mp);
                    ctx.SubmitChanges();
                    return mp.PartNumberBucketInventorysourceTypeID;
                }

            }
            return ReturnValue;
        }
        [DataObjectMethod(DataObjectMethodType.Update)]
        public void UpdateType(PartNumberBucketInventoryTransactionType mp)
        {
            if (mp != null)
            {
                using (clsLinqDataContext ctx = GetDataContext(UserName))
                {
                    var existingPart = (from q in ctx.PartNumberBucketInventoryTransactionTypes where q.PartNumberBucketInventorysourceTypeID == mp.PartNumberBucketInventorysourceTypeID select q).FirstOrDefault();
                    if (existingPart != null)
                    {
                        if (mp.Factor == null || mp.Factor == 0) { mp.Factor = 1; }
                        existingPart.Factor = mp.Factor;
                        existingPart.Type = mp.Type;
                        existingPart.Role = mp.Role;
                        existingPart.IFSDirectiveType = mp.IFSDirectiveType;
                        existingPart.IFSReasonCode = mp.IFSReasonCode;
                        existingPart.LastUpdateDate = DateTime.Now;
                        existingPart.LastUpdateUser = UserName;
                        ctx.SubmitChanges();
                    }
                }
            }
        }

