        public string SetPartRequestedAsPicked(clsLinqDataContext ctx, decimal MasterPartsRequestedLogID)
        {

            try
            {
                MasterPartsRequestedLog log = ctx.MasterPartsRequestedLogs.FirstOrDefault(x => x.MasterPartsRequestedLogID == MasterPartsRequestedLogID);
                if (log != null)
                {
                    if (log.Status != "New")
                    {
                        return "Unit Already Picked by:" + log.TechUser;
                    }
                    log.Status = "Picked";
                    log.PickUser = UserName;
                    log.PickDate = DateTime.Now;
                    log.LastUpdateDate = DateTime.Now;
                    log.LastUpdateUser = UserName;
                    ctx.SubmitChanges();
                    return "";
                }
                return "";
            }
            catch (Exception ex)
            {
                return "Error:" + ex.Message;
            }


        }

