        public string SetPartRequestedAsFilled(decimal MasterPartsRequestedLogID, string PartNumber, string Location, string IFSLocationFrom, string IFSLocationTo)
        {
            if (PartNumber.Trim().Length == 0)
            {
                return "Error: No Part Number Given, assignment canceled";
            }
            //using (clsLinqDataContext ctx = new clsLinqDataContext())
            //{

            //}
            return SetPartRequestedAsFilledThreaded(MasterPartsRequestedLogID, PartNumber, Location, IFSLocationFrom, IFSLocationTo);
        }
        public string SetPartRequestedAsFilledThreaded(decimal MasterPartsRequestedLogID, string PartNumber, string Location, string IFSLocationFrom, string IFSLocationTo)
        {
            if (PartNumber.Trim().Length == 0)
            {
                return "Error: No Part Number Given, assignment canceled";
            }
            using (clsLinqDataContext ctx = new clsLinqDataContext())
            {
                MasterPartsRequestedLog log = ctx.MasterPartsRequestedLogs.FirstOrDefault(x => x.MasterPartsRequestedLogID == MasterPartsRequestedLogID);
                if (log != null)
                {
                    decimal IFSFromLocationID = GetIFSLocationID(IFSLocationFrom);
                    decimal IFSToLocationID = GetIFSLocationID(IFSLocationTo); 
                    // Get the part and see what the QTY is.
                    // Look to see if the partnumber is valid etc, if ok, then continue
                    decimal LocationID = -1;
                    if (decimal.TryParse(Location, out LocationID) == false) { LocationID = -1; }
                    MasterPartsLinkTable MP = ctx.MasterPartsLinkTables.FirstOrDefault(x => x.GMPPartNumber.ToUpper() == PartNumber && x.ClientLocationID == LocationID);
                    if (MP == null)
                    {
                        return "Error: PartNumber Not Found";
                    }
                    if (MP != null && MP.Quantity < 1)
                    {
                        //return "Error: No QTY in Stock, assignment canceled";
                    }
                    //decimal dID = MasterPartsTechAssignedLog_Add_ReturnID(MasterPartsRequestedLogID, log.ReceiveDetailID, PartNumber, log.TechUser, LocationID, false);
                    decimal dID = MasterPartsTechAssignedLog_Add_ReturnID(ctx, log.ReceiveDetailID, MasterPartsRequestedLogID, MP.MasterPartsLinkTableID, PartNumber, log.TechUser, LocationID, false, IFSFromLocationID, IFSToLocationID);
                    if (dID < 1)
                    {
                        return "Error:";
                    }

                    //string rValue = MasterPartsTechAssignedLog_Add(MasterPartsRequestedLogID, log.ReceiveDetailID, PartNumber, log.TechUser, LocationID, false);
                    //if (rValue.ToUpper().Trim().Contains("ERROR"))
                    //{
                    //    return rValue;
                    //}

                    log.MasterPartsTechAssignedLogID = dID;
                    log.Status = "Filled";
                    log.FillDate = DateTime.Now;
                    log.FillUser = UserName;
                    log.LastUpdateDate = DateTime.Now;
                    log.LastUpdateUser = UserName;
                    ctx.SubmitChanges();


                    IFS_InventoryPartsManager ifs = new IFS_InventoryPartsManager(UserName);
                    string rv = ifs.MovePartLocation(MP.MasterPartsLinkTableID, 1, IFSLocationFrom, IFSLocationTo);
                    return rv;
                }
            }
            return "";
        }




