        public List<GridDataDetail> GetTechAssignedDetail(clsLinqDataContext ctx, string PartNumber, string Tech, DateTime startDate, DateTime endDate)
        {
            if (Tech.ToUpper() == "ALL") { Tech = ""; } 
            else {
                BasicUserUtilities buu = new BasicUserUtilities(UserName);
                Tech = buu.GetThisUserFriendlyName(Tech);
            }

            List<GridDataDetail> rvalue = (from x in ctx.MasterPartsTechAssignedLogs
                                           join mp in ctx.MasterPartsLinkTables on x.MasterPartsLinkTableID equals mp.MasterPartsLinkTableID
                     where (PartNumber.Length == 0 || x.GMPPartNumber.ToUpper() == PartNumber.ToUpper()) //&& x.Status == "Tech Assigned"
                     //where (Tech.Length == 0 || x.TechName == Tech) && (PartNumber.Length == 0 || x.GMPPartNumber.ToUpper() == PartNumber.ToUpper()) //&& x.Status == "Tech Assigned"
                     select new GridDataDetail(-1, x.MasterPartsLinkTableID, x.MasterPartsTechAssignedLogID,x.ReceiveDetailID, "", mp.MasterPart.Description, x.TechName, x.Status, x.GMPPartNumber, x.Quantity, x.CreateDate, x.CreateUser,
                         x.UnitAssignedDate, x.UnitAssignedUser,x.ReturningDate, x.ReturningUser, x.ReturnedDate, x.ReturnedUser, x.ShippedDate, x.ShippedUser, x.LastUpdateDate, x.LastUpdateUser, mp.Model, mp.Manufacturer)).ToList();
            rvalue = TranslateManufacturer(ctx, rvalue);
            rvalue = TranslateESN(ctx, rvalue);
            return rvalue.OrderBy(x=> x.TechName).ThenBy(x=> x.GMPPartNumber).ThenBy(x=> x.Status).ThenByDescending(x=> x.CreateDate).ToList();
        }

        public List<GridDataSummary> GetTechAssignedSummary(string PartNumber, string Tech, DateTime startDate, DateTime endDate)
        {
            using (clsLinqDataContext ctx = new clsLinqDataContext())
            {
                return GetTechAssignedSummary(ctx, PartNumber, Tech, startDate, endDate);
            }
        }
        public List<GridDataSummary> GetTechAssignedSummary(clsLinqDataContext ctx, string PartNumber, string Tech, DateTime startDate, DateTime endDate)
        {

            if (Tech.ToUpper() == "ALL") { Tech = ""; }
            List<GridDataSummary> rvalue = (from x in ctx.MasterPartsTechAssignedLogs
                                            join mp in ctx.MasterPartsLinkTables on x.MasterPartsLinkTableID equals mp.MasterPartsLinkTableID
                                            where (PartNumber.Length == 0 || x.GMPPartNumber.ToUpper() == PartNumber.ToUpper()) && x.Status == "Tech Assigned"
                                            //where (Tech.Length == 0 || x.TechName == Tech) && (PartNumber.Length == 0 || x.GMPPartNumber.ToUpper() == PartNumber.ToUpper()) && x.Status == "Tech Assigned"
                                           let k = new
                                           {
                                               x.ReceiveDetailID, x.ReceiveDetail.ESN,  mp.MasterPart.Description, x.TechName, x.Status, x.GMPPartNumber, mp.Manufacturer
                                           }
                                           group x by k into t
                                            select new GridDataSummary(t.Key.ReceiveDetailID, t.Key.Description,t.Key.ESN, t.Key.TechName, t.Key.Status, t.Key.GMPPartNumber, t.Sum(x => x.Quantity), t.Key.Manufacturer)).ToList();
            rvalue = TranslateManufacturer(ctx, rvalue);
            return rvalue.OrderBy(x => x.TechName).ThenBy(x => x.GMPPartNumber).ThenBy(x => x.Status).ToList();
        }

        List<GridDataDetail> TranslateESN(clsLinqDataContext ctx, List<GridDataDetail> dta)
        {

            ReceiveDetailManager rdm = new ReceiveDetailManager(UserName);
            foreach (GridDataDetail d in dta)
            {
                ReceiveDetail rd = ctx.ReceiveDetails.FirstOrDefault(x => x.ReceiveDetailID == d.ReceiveDetailID);
                d.IMEI = "";
                if (rd != null)
                {
                    d.IMEI = rd.ESN;
                }
            }
            return dta;
        }
        List<GridDataDetail> TranslateManufacturer(clsLinqDataContext ctx, List<GridDataDetail> dta)
        {
            QuestionManager qm = new QuestionManager(UserName);
            List<Option> LO = new List<Option>();
            LO = qm.GetQuestionOptionList(ctx, "Manufacturer");

            foreach (GridDataDetail d in dta)
            {
                decimal ID = -1;
                if (decimal.TryParse(d.Manufacturer, out ID) == false) { ID = -1; }

                d.Manufacturer = "<None>";
                if (ID > 0)
                {

                    foreach (Option o in LO)
                    {
                        if (o.OptionID == ID)
                        {
                            d.Manufacturer = o.OptionText;
                            break;
                        }
                    }
                }
            }
            return dta;
        }
        List<GridDataSummary> TranslateManufacturer(clsLinqDataContext ctx, List<GridDataSummary> dta)
        {
            QuestionManager qm = new QuestionManager(UserName);
            List<Option> LO = new List<Option>();
            LO = qm.GetQuestionOptionList(ctx, "Manufacturer");
            foreach (GridDataSummary d in dta)
            {
                decimal ID = -1;
                if (decimal.TryParse(d.Manufacturer, out ID) == false) { ID = -1; }

                d.Manufacturer = "<None>";
                if (ID > 0)
                {

                    foreach (Option o in LO)
                    {
                        if (o.OptionID == ID)
                        {
                            d.Manufacturer = o.OptionText;
                            break;
                        }
                    }
                }
            }
            return dta;
        }

