            log.ReceiveDetailID = ReceiveDetailID;
            log.Status = "Tech Assigned";
            log.TechName = Tech;
            ctx.MasterPartsTechAssignedLogs.InsertOnSubmit(log);
            ctx.SubmitChanges();
            return log.MasterPartsTechAssignedLogID;
        }
