        public string MasterPartsTechAssignedLog_Return(clsLinqDataContext ctx, decimal MasterPartsTechAssignedLogID, decimal ToIFSLocationID)
        {
            //string Tech = "";
            //BasicUserUtilities buu = new BasicUserUtilities(UserName);
            //Tech = buu.GetThisUserFriendlyName(tech);

            MasterPartsTechAssignedLog log = ctx.MasterPartsTechAssignedLogs.FirstOrDefault(x => x.MasterPartsTechAssignedLogID == MasterPartsTechAssignedLogID && (x.Status == "Tech Assigned" || x.Status == "Tech Returning"));
            if (log == null)
            {
                return "ERROR:P#: (Not returned from Tech); distribution not found (" + MasterPartsTechAssignedLogID + ")";
            }
            log.Status = "Returned";
            //log.Quantity = 0;
            //log.ReceiveDetailID = -1;
            log.ReturnedDate = DateTime.Now;
            log.ReturnedUser = UserName;
            log.LastUpdateDate = DateTime.Now;
            log.LastUpdateUser = UserName;
            ctx.SubmitChanges();
            string rMessage = "";
            rMessage = MovePart(ctx, log.MasterPartsLinkTableID, log.MasterIFSLocationToID, ToIFSLocationID);

            return "P#:" + log.GMPPartNumber + " returned from " + log.TechName + " To location:" + rMessage;
        }

        private string MovePart(clsLinqDataContext ctx,decimal MasterPartsLinkTableID, decimal? IFSFromLocationID, decimal ToIFSLocationID)
        {
            string rMessage = "";
            MasterPartsLinkTable part = ctx.MasterPartsLinkTables.FirstOrDefault(x => x.MasterPartsLinkTableID == MasterPartsLinkTableID);
            if (part != null && IFSFromLocationID != null)
            {
                // Move the part back to the correct location
                //decimal WareHouseID = (decimal)part.ClientLocationID;
                IFS_InventoryPartsManager ifs = new IFS_InventoryPartsManager(UserName);
                rMessage = ifs.MovePartLocation(ctx, part.MasterPartsLinkTableID, 1, (decimal)IFSFromLocationID, ToIFSLocationID);
            }
            return rMessage;
        }




