                log = ctx.MasterPartsTechAssignedLogs.OrderBy(x => x.MasterPartsTechAssignedLogID).FirstOrDefault(x => (x.ReceiveDetailID == null || x.ReceiveDetailID < 1) && x.MasterPartsLinkTableID == MasterPartsLinkTableID && x.Status == "Tech Assigned");
