            //MasterPartsTechAssignedLog log = ctx.MasterPartsTechAssignedLogs.FirstOrDefault(x => x.MasterPartsLinkTableID == MasterPartsLinkTableID && x.TechName == Tech && x.Status == "Tech Assigned");
            if (log == null) { return "Error:Part Number (Partnumber Unavailable) Not assigned to Tech, NO UPDATE DONE"; }
