            log.ReceiveDetailID = ReceiveDetailID;
            log.ReceiveDetailItemID = ReceiveDetailItemID;
            log.UnitAssignedDate = DateTime.Now;
            log.UnitAssignedUser = UserName;
            ctx.SubmitChanges();
            return "ID:" + log.MasterPartsTechAssignedLogID.ToString() + ":Part Number (" + log.GMPPartNumber + ") Assigned to Unit";
        }

