        public string MasterPartsTechAssignedLog_RemoveUnitLink(clsLinqDataContext ctx, decimal ReceiveDetailID, string PartNumber)
        {
            ReceiveDetailItem RDI = ctx.ReceiveDetailItems.FirstOrDefault(x => x.ReceiveDetailID == ReceiveDetailID && x.Value == PartNumber);
            if (RDI == null) { return "ERROR:P#:" + PartNumber + " not found on Unit!"; }
            return MasterPartsTechAssignedLog_RemoveUnitLink(ctx, ReceiveDetailID, RDI.ReceiveDetailItemID);
        }
        public string MasterPartsTechAssignedLog_RemoveUnitLink(clsLinqDataContext ctx, decimal ReceiveDetailID, decimal ReceiveDetailItemID)
        {
            MasterPartsTechAssignedLog log = ctx.MasterPartsTechAssignedLogs.OrderBy(x => x.MasterPartsTechAssignedLogID)
                                                .FirstOrDefault(x => x.ReceiveDetailItemID == ReceiveDetailItemID && x.ReceiveDetailID == ReceiveDetailID && (x.Status == "Unit Assigned" || x.Status == "Shipped"));
            if (log == null)
            {
                return "ERROR:P#:" + "(Partnumber Unavailable)" + "; distribution not found";
            }
            log.Status = "Tech Assigned";
            log.LastUpdateDate = DateTime.Now;
            log.LastUpdateUser = UserName;
            //log.ReceiveDetailID = -1;
            log.ReceiveDetailItemID = -1;
            log.UnitAssignedDate = null;
            log.UnitAssignedUser = "";
            ctx.SubmitChanges();
            return "Part Number (" + "Partnumber Unavailable" + ") Assigned to Tech";
        }

