        public string MasterPartsTechAssignedLog_Shipped(clsLinqDataContext ctx, decimal ReceiveDetailID, decimal ReceiveDetailItemID)
        {
            MasterPartsTechAssignedLog log = ctx.MasterPartsTechAssignedLogs
                                                .OrderBy(x => x.MasterPartsTechAssignedLogID)
                                                .FirstOrDefault(x => x.ReceiveDetailItemID == ReceiveDetailItemID && x.ReceiveDetailID == ReceiveDetailID && x.Status == "Unit Assigned");
            if (log == null) { return "Error:Part Number (" + "(Partnumber Unavailable)" + ") Not assigned to Unit, NO UPDATE DONE"; }
            log.Status = "Shipped";
            log.ShippedDate = DateTime.Now;
            log.ShippedUser = UserName;
            log.LastUpdateDate = DateTime.Now;
            log.LastUpdateUser = UserName;
            ctx.SubmitChanges();
            return "Part Number (" + "(Partnumber Unavailable)" + ") Shipped";
        }
