        [DataObjectMethod(DataObjectMethodType.Insert)]
        public decimal Insert(MasterPart mp)
        {
            decimal ReturnValue = -1;
            if (mp != null)
            {
                using (clsLinqDataContext ctx = GetDataContext(UserName))
                {
                    mp.LastUpdateDate = DateTime.Now;
                    mp.LastUpdateUser = UserName;
                    mp.CreateDate = DateTime.Now;
                    mp.CreateUser = UserName;
                    ctx.MasterParts.InsertOnSubmit(mp);
                    ctx.SubmitChanges();
                    return mp.MasterPartsID;
                }

            }
            return ReturnValue;
        }
        [DataObjectMethod(DataObjectMethodType.Delete)]
        public bool Delete(decimal MasterPartID)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                MasterPart mp = ctx.MasterParts.FirstOrDefault(x => x.MasterPartsID == MasterPartID);
                var lt = mp.MasterPartsLinkTables;
                var placement = ctx.PartNumberBucketInventoryPlacements.Where(x => x.MasterPartsLinkTable.MasterPartsID == MasterPartID);
                var source = ctx.PartNumberBucketInventorySources.Where(x => x.MasterPartsLinkTable.MasterPartsID == MasterPartID);

                var Models = ctx.MasterPartsLinkTableModelLists.Where(x => x.MasterPartsLinkTable.MasterPartsID == MasterPartID);
                var price = ctx.MasterPartsLinkTablePriceLists.Where(x => x.MasterPartsLinkTable.MasterPartsID == MasterPartID);

                foreach (var r in lt)
                {
                    var monthEnd = ctx.MasterPartsLinkTableMonthEnds.Where(x => x.MasterPartsLinkTableID == r.MasterPartsLinkTableID);
                    ctx.MasterPartsLinkTableMonthEnds.DeleteAllOnSubmit(monthEnd);
                }
                ctx.PartNumberBucketInventoryPlacements.DeleteAllOnSubmit(placement);
                ctx.PartNumberBucketInventorySources.DeleteAllOnSubmit(source);
                ctx.MasterPartsLinkTableModelLists.DeleteAllOnSubmit(Models);
                ctx.MasterPartsLinkTablePriceLists.DeleteAllOnSubmit(price);
                ctx.MasterPartsLinkTables.DeleteAllOnSubmit(lt);

                //Delete MasterPartsLinkTableModelList where MasterPartsLinkTableID = 72
                //Delete from MasterPartsLinkTableMonthEnd where MasterPartsLinkTableID = 72
                //Delete from MasterPartsLinkTablePriceList where MasterPartsLinkTableID = 72
                //Delete from PartNumberBucketInventoryPlacement where MasterPartsLinkTableID = 72
                //Delete from PartNumberBucketInventorySource where MasterPartsLinkTableID = 72


                ctx.MasterParts.DeleteOnSubmit(mp);
                try
                {
                    ctx.SubmitChanges();
                    return true;
                }
                catch
                {

                }
            }
            return false;
        }
