        [DataObjectMethod(DataObjectMethodType.Update)]
        public void Update(MasterPart mp)
        {
            if (mp != null)
            {
                using (clsLinqDataContext ctx = GetDataContext(UserName))
                {
                    var existingPart = (from q in ctx.MasterParts where q.MasterPartsID == mp.MasterPartsID select q).FirstOrDefault();
                    if (existingPart != null)
                    {
                        existingPart.Name = mp.Name;
                        existingPart.Description = mp.Description;
                        existingPart.MasterClassID = mp.MasterClassID;
                        existingPart.LastUpdateDate = DateTime.Now;
                        existingPart.LastUpdateUser = UserName;
                        ctx.SubmitChanges();
                    }
                }
            }
        }
