        public List<MasterPartsLinkTable> GetMasterPartNumbersRegress_03(clsLinqDataContext ctx, decimal ReceiveDetailID, decimal MasterPartsID, decimal ClientID, decimal ClientLocationID, string Carrier, string Manufacturer, string Model)
        {
            List<MasterPartsLinkTable> data = null;
