        public List<MasterPartsLinkTable> GetMasterPartNumbersRegress_GO_03(clsLinqDataContext ctx, decimal ReceiveDetailID, decimal MasterPartsID, decimal ClientID, decimal ClientLocationID, string Carrier, string Manufacturer, string Model)
        {
            decimal ModelID = -1;
            if (decimal.TryParse(Model, out ModelID) == false) { ModelID = -1; }

            // We are only interested if the clientlocation has onsite inventory.
            if (ClientLocationID > 0)
            {
                if (DoesThisClientLocationIDHaveOnsiteInventory(ctx, ClientLocationID) == false)
                {
                    ClientLocationID = -1;
                }
                else
                {
                    // Look to see if the Unit has gone through this process, if yes, then get part from default inventory.
                    if (Processmanager.HasUnitEnteredThisProcess(ctx, ReceiveDetailID, "Send To XXX") == true)
                    {
                        ClientLocationID = -1;
                    }
                    //// look to see if this is a out of warranty record.
                    //if (IsReturnTypeForParts_OutOfWarranty(ReceiveDetailID) == true)
                    //{
                    //    // If it is, look to see if it needs to pull the Default Inventory
                    //    if (DoesThisClientLocationIDHaveOOW_WHS(ctx, ClientLocationID) == true) { ClientLocationID = -1; }
                    //}
                }
            }


            if (ModelID > 0)
            {
                return (from x in ctx.MasterPartsLinkTables
                        where x.MasterPartsID == MasterPartsID
                            && x.ClientLocationID == ClientLocationID
                            //&& x.ClientID == ClientID
                            //&& x.Carrier == Carrier
                          && x.Manufacturer == Manufacturer
                          && (from z in x.MasterPartsLinkTableModelLists where z.ModelID == ModelID select z).Any() == true
                        orderby x.PartNumber
                        select x).ToList();
            }

            return (from x in ctx.MasterPartsLinkTables
                    where x.MasterPartsID == MasterPartsID
                            && x.ClientLocationID == ClientLocationID

                        //&& x.ClientID == ClientID
                        //&& x.Carrier == Carrier
                      && x.Manufacturer == Manufacturer
                      && ((from z in x.MasterPartsLinkTableModelLists where z.ModelID == ModelID select z).Any() == true                  // This is here because some times "NONE" is saved. None has a ID of -1.
                      || x.MasterPartsLinkTableModelLists.Any() == false)
                    orderby x.PartNumber
                    select x).ToList();
        }
         
        
        
