        public List<MasterPartsLinkTable> GetMasterPartNumbers(clsLinqDataContext ctx, decimal ClientID, string Carrier, string Manufacturer, string Model)
        {
            var pm = from x in ctx.MasterPartsLinkTables
                     where x.Carrier == Model          // Carrier no longer used for Carrier, but now holds the ModelID List. Model carries the Model Texts.
                        && x.Manufacturer == Manufacturer
                     orderby x.PartNumber
                     select x;
            return pm.ToList();
        }



        public List<GRDPartLocationView> GetMasterPartNumbersThisPartLocationView(decimal MasterPartID, decimal ClientID, decimal ClientLocationID, string Carrier, string Manufacturer, string Model, int Page, int NumPerPage)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                List<MasterPartsLinkTable> dta =  GetMasterPartNumbersThisPart(ctx, MasterPartID, ClientID, ClientLocationID, Carrier, Manufacturer, Model, Page, NumPerPage);
                List<decimal> IDs = (from d in dta select d.MasterPartsLinkTableID).ToList();

                return (from d in ctx.MasterPartsTableIFSLocationStorages
                        where IDs.Contains(d.MasterPartsLinkTableID)
                        select new GRDPartLocationView
                        {
                            QTY = d.QTY,
                            Quantity = d.MasterPartsLinkTable.Quantity,
                            GMPPartNumber = d.MasterPartsLinkTable.GMPPartNumber,
                            GMPPartDescription = d.MasterPartsLinkTable.GMPPartDescription,
                            PartNumber = d.MasterPartsLinkTable.PartNumber,
                            Description = d.MasterPartsLinkTable.MasterPart.Description,
                            MasterPartsTableIFSLocationStorageID = d.MasterPartsTableIFSLocationStorageID,
                            MasterPartsLinkTableID = d.MasterPartsLinkTable.MasterPartsLinkTableID,
                            IFSLocation = d.MasterIFSLocation.IFSLocation
                        }).OrderBy(x=> x.IFSLocation).ThenBy(x=> x.GMPPartNumber).ToList();
            }

        }



