        public List<MasterPartsLinkTablePriceList> GetMasterPartPriceList(clsLinqDataContext ctx, decimal MasterPartsLinkTableID)
        {
            List<MasterPartsLinkTablePriceList> data = (from x in ctx.MasterPartsLinkTablePriceLists
                    where x.MasterPartsLinkTableID == MasterPartsLinkTableID
                    orderby x.CreateDate
                    select x).ToList();

            if (data.Count == 0)
            {
                // we need to add a base record.
                decimal unitPrice = 0;
                MasterPartsLinkTable part = ctx.MasterPartsLinkTables.FirstOrDefault(x => x.MasterPartsLinkTableID == MasterPartsLinkTableID);
                MasterPartsLinkTablePriceList pricelist = new MasterPartsLinkTablePriceList();
                unitPrice = part.UnitPrice == null ? 0 : (decimal)part.UnitPrice;
                pricelist.CreateUser = UserName;
                pricelist.InWarrentyWorkPrice = part.InWarrentyWorkPrice;
                pricelist.LastUpdateDate = DateTime.Now;
                pricelist.LastUpdateUser = UserName;
                pricelist.MasterPartsLinkTableID = MasterPartsLinkTableID;
                pricelist.QTYDispursed = 0;
                pricelist.Quantity = part.Quantity;
                pricelist.UnitPrice = unitPrice;
                pricelist.UnitPurchasePrice = 0;
                ctx.MasterPartsLinkTablePriceLists.InsertOnSubmit(pricelist);
                ctx.SubmitChanges();
                data.Add(pricelist);
            }
            return data;
        }
