        public void SetModels(clsLinqDataContext ctx, string Model, decimal MasterPartsLinkTableID)
        {
            MasterPartsLinkTable existingPart = ctx.MasterPartsLinkTables.FirstOrDefault(x => x.MasterPartsLinkTableID == MasterPartsLinkTableID);
            if (existingPart == null) { return; }
            SetModels(ctx, Model, existingPart);
            ctx.SubmitChanges();
