        public void SetModels(clsLinqDataContext ctx, string Model, MasterPartsLinkTable existingPart)
        {
            List<string> Models = Model.Split(new char[] { ',' }, StringSplitOptions.RemoveEmptyEntries).ToList();
            var RemoveList = existingPart.MasterPartsLinkTableModelLists.Where(x => Models.Contains(x.ModelID.ToString()) == false).Select(x => x).ToList();
            //foreach (var r in RemoveList) { existingPart.MasterPartsLinkTableModelLists.Remove(r); }
            foreach (var r in RemoveList) { ctx.MasterPartsLinkTableModelLists.DeleteOnSubmit(r); }
            foreach (string id in Models)
            {
                var there = existingPart.MasterPartsLinkTableModelLists.Where(x => x.ModelID.ToString() == id).FirstOrDefault();
                if (there == null)
                {
                    MasterPartsLinkTableModelList ml = new MasterPartsLinkTableModelList();
                    ml.ModelID = decimal.Parse(id);
                    ml.CreateUser = UserName;
                    ml.LastUpdateUser = UserName;
                    existingPart.MasterPartsLinkTableModelLists.Add(ml);
                }
            }
            SetSortedModels(ctx, existingPart);
            return;
        }
