        public void SetSortedModels(clsLinqDataContext ctx, MasterPartsLinkTable existingPart)
        {
            string ModelText = "";       //[0]
            string Modelids = "";        //[1]
            List<string> ModelIDs = new List<string>();                                      // Models.Split(',').ToList();
            foreach (MasterPartsLinkTableModelList m in existingPart.MasterPartsLinkTableModelLists) { ModelIDs.Add(m.ModelID.ToString()); }
            List<Option> ModelList = ctx.Options.Where(x => ModelIDs.Contains(x.OptionID.ToString())).ToList();
            foreach (Option o in ModelList.OrderBy(x => x.OptionText))
            {
                if (ModelText.Length > 0) { ModelText += ","; }
                if (Modelids.Length > 0) { Modelids += ","; }
                ModelText += o.OptionText;
                Modelids += o.OptionID.ToString();
            }
            existingPart.Carrier = Modelids;
            existingPart.Model = ModelText;
            return;
        }
        public string[] GetSortedModels(clsLinqDataContext ctx, MasterPartsLinkTable existingPart)
        {
            string ModelText = "";       //[0]
            string ModelIDS = "";        //[1]
            string WarningMessage = "";  //[2]

            List<string> ModelIDs = new List<string>();                                      // Models.Split(',').ToList();
            foreach (MasterPartsLinkTableModelList m in existingPart.MasterPartsLinkTableModelLists)
            {
                ModelIDs.Add(m.ModelID.ToString());
            }
            List<Option> ModelList = ctx.Options.Where(x => ModelIDs.Contains(x.OptionID.ToString())).ToList();
            foreach (Option o in ModelList.OrderBy(x => x.OptionText))
            {
                if (ModelText.Length > 0) { ModelText += ","; }
                if (ModelIDS.Length > 0) { ModelIDS += ","; }
                ModelText += o.OptionText;
                ModelIDS += o.OptionID.ToString();
            }
            return new string[] { ModelText, ModelIDS, WarningMessage };
        }


