        private DateTime LastMonthEnd(DateTime date)
        {
            // Subtract the day it is and you get last month end date.
            return date.AddDays(date.Day * -1);
        }
        private DateTime NextMonthEnd(DateTime date)
        {
            // Add one month to move the date one month into the future. 
            // Then get the last Month End for the new advanced date.
            // This is then the Month End for the current date.
            return LastMonthEnd(date.AddMonths(1));
        }
        private void ProcessMonthEndIfRequired(clsLinqDataContext ctx, MasterPartsLinkTable existingPart)
        {
            // we should go through a look to bring the transaction up to date.
            //while (existingPart.MonthEndDate.Month != DateTime.Now.Month || existingPart.MonthEndDate.Year != DateTime.Now.Year)
            if (existingPart.MonthEndDate != LastMonthEnd(DateTime.Now))
            {
                MasterPartsLinkTableMonthEnd ME = new MasterPartsLinkTableMonthEnd();
                ME.CreateDate = DateTime.Now;
                ME.CreateUser = UserName;
                ME.MasterPartsLinkTableID = existingPart.MasterPartsLinkTableID;
                ME.MonthEndDate = existingPart.MonthEndDate;
                ME.MonthendQTY = existingPart.MonthendQTY;
                ME.MonthEndUnitPrice = existingPart.MonthEndUnitPrice;
                ME.InWarrentyWorkPrice = existingPart.MonthEndInWarrentyWorkPrice;
                ME.AveragePurchasePrice = existingPart.AveragePurchasePrice;
                ctx.MasterPartsLinkTableMonthEnds.InsertOnSubmit(ME);

                existingPart.MonthEndDate = LastMonthEnd(DateTime.Now);
                //existingPart.MonthEndDate = NextMonthEnd(existingPart.LastUpdateDate); 
                existingPart.MonthendQTY = existingPart.Quantity;
                existingPart.MonthEndUnitPrice = existingPart.UnitPrice;
                existingPart.MonthEndInWarrentyWorkPrice = existingPart.InWarrentyWorkPrice;
            }
        }


