        public decimal InsertPartNumber(clsLinqDataContext ctx, decimal MasterPartID, decimal ClientID, decimal ClientLocationID, string Carrier, string Manufacturer, string Model, string PartNumber, string InternalPartNumber, string InternalPartDesc)
        {
            return InsertPartNumber(ctx, MasterPartID, ClientID, ClientLocationID, Carrier, Manufacturer, Model, PartNumber, InternalPartNumber, InternalPartDesc, -1);
        }
        public decimal InsertPartNumber(clsLinqDataContext ctx, decimal MasterPartID, decimal ClientID, decimal ClientLocationID, string Carrier, string Manufacturer, string Model, string PartNumber, string InternalPartNumber, string InternalPartDesc, decimal ClassTypeID)
        {
            if (PartNumber.Length == 0) { return -1; }
            bool addNew = false;

            //string xxxxxxx = "";

            //if (GMPPartNumber.ToUpper() == "APPLE IPAD 3 - 16GB WIFI 4G")
            //{
            //    xxxxxxx = GMPPartNumber;

            //}


            //var existingPart = (from q in ctx.MasterPartsLinkTables
            //                    where q.MasterPartsID == MasterPartID
            //                       && q.Manufacturer == Manufacturer && q.Carrier == Model          // Carrier no longer used for Carrier, but now holds the ModelID List. Model carries the Model Texts.
            //                       //&& q.Manufacturer == Manufacturer && q.Model == Model
            //                       // && q.ClientID == ClientID && q.Carrier == Carrier && q.Manufacturer == Manufacturer && q.Model == Model
            //                    select q).FirstOrDefault();
            var existingPart = (from q in ctx.MasterPartsLinkTables
                                where q.PartNumber == PartNumber && q.ClientLocationID == ClientLocationID
                                select q).FirstOrDefault();

            // * NOTE * the Manufacturer must be the optionID value. Not the text.
            decimal m = -1;
            if (decimal.TryParse(Manufacturer, out m) == false)
            {
                throw new NotImplementedException("Manufacturer must be the optionID value for the Manufacturer -- Wrong Format");
            }

            if (existingPart != null && existingPart.Manufacturer != Manufacturer)
            {
                // Do not change the Manufacturer on the Part Number.
                return -1;
            }

            if (existingPart == null)
            {
                existingPart = new MasterPartsLinkTable();
                existingPart.MasterPartsClassTypeID = ClassTypeID;
                existingPart.ClientID = ClientID;
                existingPart.ClientLocationID = ClientLocationID;
                existingPart.Carrier = Model;
                existingPart.Manufacturer = Manufacturer;
                existingPart.Model = Model;
                existingPart.Quantity = 0;
                existingPart.UnitPrice = 0;
                existingPart.QTYMax = 0;
                existingPart.QTYMin = 0;
                existingPart.QTYReOrder = 0;
                existingPart.AveragePurchasePrice = 0;
                existingPart.MonthEndAveragePurchasePrice = 0;

                existingPart.MonthEndInWarrentyWorkPrice = 0;
                existingPart.InWarrentyWorkPrice = 0;
                existingPart.MonthEndUnitPrice = 0;
                existingPart.MonthendQTY = 0;
                existingPart.MonthEndDate = DateTime.Now.AddDays(DateTime.Now.Day * -1);
                existingPart.MasterPartsID = MasterPartID;
                existingPart.MasterPartsLinkTableID = -1;
                existingPart.CreateDate = DateTime.Now;
                existingPart.CreateUser = UserName;
                existingPart.PartNumber = "";
                existingPart.GMPPartNumber = "";
                existingPart.GMPPartDescription = "";
            }
            if (existingPart.UnitPrice == null) { existingPart.UnitPrice = 0; existingPart.MonthEndUnitPrice = 0; }
            if (PartNumber.Length > 0
             && existingPart.PartNumber != PartNumber
             && ctx.MasterPartsLinkTables.Any(x => x.PartNumber == PartNumber && x.ClientLocationID == ClientLocationID
                                               && x.MasterPartsLinkTableID != existingPart.MasterPartsLinkTableID) == false)
            {
                existingPart.PartNumber = PartNumber;
            }  // we only want to update if number not used elsewhere.

            if (InternalPartNumber.Length > 0) { existingPart.GMPPartNumber = InternalPartNumber.ToUpper(); }
            if (InternalPartDesc.Length > 0) { existingPart.GMPPartDescription = InternalPartDesc; }
            if (existingPart.MasterPartsLinkTableID < 1)
            {
                addNew = true;
                ctx.MasterPartsLinkTables.InsertOnSubmit(existingPart);
                MasterPartsLinkTablePriceList pl = new MasterPartsLinkTablePriceList();
                pl.LastUpdateDate = DateTime.Now;
                pl.CreateUser = UserName;
                pl.LastUpdateUser = UserName;
                pl.InWarrentyWorkPrice = 0;
                pl.QTYDispursed = 0;
                pl.Quantity = 0;
                pl.UnitPrice = 0;
                pl.UnitPurchasePrice = 0;
                existingPart.MasterPartsLinkTablePriceLists.Add(pl);
            }
            SetModels(ctx, Model, existingPart);
            //existingPart.Model = ModelData[0];
            //existingPart.Carrier = ModelData[1];
            existingPart.LastUpdateDate = DateTime.Now;
            existingPart.LastUpdateUser = UserName;

            ctx.SubmitChanges();

            if (addNew == true)
            {
                // If this was new, we have to add a reason to the record.
                // after the save of PL, we should now have a record in the change log.
                // Find it and then add the reason.
                MasterPartsLinkTablePriceList pl = existingPart.MasterPartsLinkTablePriceLists.FirstOrDefault();
                if (pl != null)
                {
                    MasterPartsLinkTablePriceList_ChangeLog plLog = ctx.MasterPartsLinkTablePriceList_ChangeLogs.OrderByDescending(x => x.LogDate).FirstOrDefault(x => x.MasterPartsLinkTablePriceListID == pl.MasterPartsLinkTablePriceListID);
                    if (plLog != null)
                    {
                        plLog.Log_Reason = "New Add";
                        ctx.SubmitChanges();
                    }
                }
            }
            return existingPart.MasterPartsLinkTableID;
        }


        public void AddToInventoryEditDetailsOnly(decimal MasterPartsLinkTablePriceListID, decimal MasterIFSLocationID, decimal NewQTY, decimal NewDispursed, decimal NewUnitPurchasePrice, string Reason, string IFSReasonCode, short IFSDirective)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                AddToInventoryEditDetailsOnly(ctx, MasterPartsLinkTablePriceListID, MasterIFSLocationID, NewQTY, NewDispursed, NewUnitPurchasePrice, Reason,IFSReasonCode,IFSDirective);
            }
        }
        public void AddToInventoryEditDetailsOnly(clsLinqDataContext ctx, decimal MasterPartsLinkTablePriceListID, decimal MasterIFSLocationID, decimal NewQTY, decimal NewDispursed, decimal NewUnitPurchasePrice, string Reason, string IFSReasonCode, short IFSDirective)
        {

            MasterPartsLinkTablePriceList pl = ctx.MasterPartsLinkTablePriceLists.FirstOrDefault(x => x.MasterPartsLinkTablePriceListID == MasterPartsLinkTablePriceListID);
            if (pl == null) { return; }
            decimal OriginalQTY = pl.Quantity;
            decimal OriginalDispursed = pl.QTYDispursed;
            decimal QTY = 0;

            // change the original record to reflect the new totals
            pl.Quantity = NewQTY;
            pl.QTYDispursed = NewDispursed;
            pl.UnitPurchasePrice = NewUnitPurchasePrice;
            pl.LastUpdateDate = DateTime.Now;
            pl.LastUpdateUser = UserName;
            ctx.SubmitChanges();
            // after the save of PL, a triger is executed resulting in a record in the change log.
            // Find it and then add the reason.
            MasterPartsLinkTablePriceList_ChangeLog plLog = ctx.MasterPartsLinkTablePriceList_ChangeLogs.OrderByDescending(x => x.LogDate).FirstOrDefault(x => x.MasterPartsLinkTablePriceListID == MasterPartsLinkTablePriceListID);
            if (plLog != null) { plLog.Log_Reason = Reason; ctx.SubmitChanges(); }

            // Need to figure out is the New stuff is different, if so, record the required transactions in order to balance.
            var existingPart = (from q in ctx.MasterPartsLinkTables where q.MasterPartsLinkTableID == pl.MasterPartsLinkTableID select q).FirstOrDefault();
            if (existingPart != null)
            {
                existingPart.UnitPrice = existingPart.UnitPrice == null ? 0 : (decimal)existingPart.UnitPrice;
                decimal TransactionTypeID = GetType(ctx, Reason);
                //string Type = Reason;

                // This needs to be made absoute because the factor will set the sign dependent on the transaction reason.
                if (NewQTY != 0) { QTY = Math.Abs(OriginalQTY - NewQTY); }
                QTY *= GetTypeFactor(ctx, TransactionTypeID);

                decimal UnitPrice = pl.UnitPrice > 0 ? pl.UnitPrice : (decimal)existingPart.UnitPrice;
                decimal UnitPurchasePrice = NewUnitPurchasePrice > 0 ? NewUnitPurchasePrice : 0;
                ctx.SubmitChanges();
                AddInventorySourceTransaction(pl.MasterPartsLinkTableID, MasterIFSLocationID, QTY
                                            , UnitPurchasePrice
                                            , existingPart.UnitPrice
                                            , UnitPrice
                                            , existingPart.AveragePurchasePrice
                                            , TransactionTypeID
                                            , Reason
                                            , -1
                                            , pl.MasterPartsLinkTablePriceListID, "","","","", IFSReasonCode,IFSDirective);
            }
        }

        public string AddToInventory(clsLinqDataContext ctx, string PartNumber, decimal MasterIFSLocationID, decimal QTY, decimal UnitPurchasePrice, decimal UnitPrice, decimal InWarrentyUnitPrice, decimal TransactionTypeID, string Desc, decimal ClientLocationID, string MiscDesc, string POVendor, string PONumber, string POReceiptDate, string POLine)
        {
            MasterPartsLinkTable lt = ctx.MasterPartsLinkTables.FirstOrDefault(x => x.PartNumber == PartNumber && x.ClientLocationID == ClientLocationID);
            if (lt == null)
            {
                return "Part number (" + PartNumber + ") not found";
            }
            AddToInventory(lt.MasterPartsLinkTableID, MasterIFSLocationID, QTY, UnitPurchasePrice, UnitPrice, InWarrentyUnitPrice, TransactionTypeID, Desc, -1, lt.PartNumber, lt.GMPPartNumber, lt.GMPPartDescription, lt.QTYMin, lt.QTYMax, lt.QTYReOrder, lt.MasterPartsClassTypeID, MiscDesc, POVendor, PONumber, POReceiptDate, POLine);
            //AddToInventory(ctx, lt.MasterPartsLinkTableID, QTY, UnitPurchasePrice, UnitPrice, InWarrentyUnitPrice, TransactionTypeID, Desc, -1, lt.PartNumber, lt.GMPPartNumber, lt.GMPPartDescription, lt.QTYMin, lt.QTYMax, lt.QTYReOrder, lt.MasterPartsClassTypeID, MiscDesc);
            return "";
        }
        public void AddToInventory(decimal MasterPartsLInkTableID, decimal MasterIFSLocationID, decimal QTY, decimal UnitPurchasePrice, decimal UnitPrice, decimal InWarrentyUnitPrice, decimal TransactionTypeID, string Desc, string MFGPartnumber, string InternalPartNumber, string InternalPartDesc, decimal Min, decimal Max, decimal Reorder, decimal ClassTypeID, string MiscDesc, string POVendor, string PONumber, string POReceiptDate, string POLine)
        {
            AddToInventory(MasterPartsLInkTableID, MasterIFSLocationID, QTY, UnitPurchasePrice, UnitPrice, InWarrentyUnitPrice, TransactionTypeID, Desc, -1, MFGPartnumber, InternalPartNumber, InternalPartDesc, Min, Max, Reorder, ClassTypeID, MiscDesc, POVendor, PONumber, POReceiptDate, POLine);
        }
        public void AddToInventory(decimal MasterPartsLInkTableID, decimal MasterIFSLocationID, decimal QTY, decimal UnitPurchasePrice, decimal UnitPrice
            , decimal InWarrentyUnitPrice, decimal TransactionTypeID, string Desc
            , decimal ReceiveDetailID, string MFGPartnumber, string InternalPartNumber, string InternalDesc
            , decimal? Min, decimal? Max, decimal? Reorder, decimal? ClassTypeID, string MiscDesc
            , string POVendor, string PONumber, string POReceiptDate, string POLine)
        {
            if (MFGPartnumber.Length > 0 || InternalPartNumber.Length > 0 || InternalDesc.Length > 0 || ClassTypeID > 0)
            {
                UpdateInventoryDemographicData_A(MasterPartsLInkTableID, MFGPartnumber, InternalPartNumber, InternalDesc, ClassTypeID);
            }

            if (TransactionTypeID > 0 && (QTY != 0 || UnitPrice >= 0 || UnitPurchasePrice >= 0 || InWarrentyUnitPrice >= 0))
            {
                UpdateInventoryAccountingData(MasterPartsLInkTableID, MasterIFSLocationID, QTY, UnitPurchasePrice, UnitPrice, InWarrentyUnitPrice, TransactionTypeID, Desc, ReceiveDetailID, POVendor, PONumber, POReceiptDate, POLine);
            }

            if (Min > 0 || Max > 0 || Reorder > 0 || UnitPrice > 0 || InWarrentyUnitPrice > 0)
            {
                UpdateInventoryDemographicData_B(MasterPartsLInkTableID, UnitPrice, InWarrentyUnitPrice, Min, Max, Reorder);
            }
            //using (clsLinqDataContext ctx = GetDataContext(UserName))
            //{
            //    AddToInventory(ctx, MasterPartsLInkTableID, QTY, UnitPurchasePrice, UnitPrice, InWarrentyUnitPrice, TransactionTypeID, Desc, ReceiveDetailID, MFGPartnumber, GMPPartNumber, GMPDesc, Min, Max, Reorder, ClassTypeID, MiscDesc);
            //}
        }
        public void AddToInventory(decimal MasterPartsLInkTableID, decimal UnitPrice, decimal InWarrentyUnitPrice, string InternalPartNumber, string ControlPartnumber, string InternalPartDesc, decimal? Min, decimal? Max, decimal? Reorder, decimal? ClassTypeID)
        {
            if (ControlPartnumber.Length > 0 || InternalPartNumber.Length > 0 || InternalPartDesc.Length > 0 || ClassTypeID > 0)
            {
                UpdateInventoryDemographicData_A(MasterPartsLInkTableID, ControlPartnumber, InternalPartNumber, InternalPartDesc, ClassTypeID);
            }
            if (Min > 0 || Max > 0 || Reorder > 0 || UnitPrice > 0 || InWarrentyUnitPrice > 0)
            {
                UpdateInventoryDemographicData_B(MasterPartsLInkTableID, UnitPrice, InWarrentyUnitPrice, Min, Max, Reorder);
            }
        }


