        public void AddToInventory(decimal MasterPartsLInkTableID, decimal MasterIFSLocationID, decimal QTY, decimal UnitPurchasePrice, decimal TransactionTypeID, string Desc, string POVendor, string PONumber, string POReceiptDate, string POLine)
