        public short IFSDirective(clsLinqDataContext ctx, string Name)
        {
            InvtTran_IFSDirective directive = ctx.InvtTran_IFSDirectives.FirstOrDefault(x => x.Name.ToUpper() == Name.ToUpper());
            if (directive == null)
            {
                ctx.InvtTran_IFSDirectives.FirstOrDefault(x => x.Name.ToUpper() == "IGNORE");
                if (directive == null) { return -1; }
            }
            return directive.Directive;

        }


        private void UpdateInventoryAccountingData(decimal MasterPartsLInkTableID, decimal MasterIFSLocationID, decimal QTY, decimal UnitPurchasePrice, decimal UnitPrice, decimal InWarrentyUnitPrice, decimal TransactionTypeID, string Desc, decimal ReceiveDetailID, string POVendor, string PONumber, string POReceiptDate, string POLine)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                UpdateInventoryAccountingData(ctx, MasterPartsLInkTableID, MasterIFSLocationID, QTY, UnitPurchasePrice, UnitPrice, InWarrentyUnitPrice, TransactionTypeID, Desc, ReceiveDetailID, POVendor, PONumber, POReceiptDate, POLine);
            }
        }
        private void UpdateInventoryAccountingData(clsLinqDataContext ctx, decimal MasterPartsLInkTableID, decimal MasterIFSLocationID, decimal QTY, decimal UnitPurchasePrice, decimal UnitPrice, decimal InWarrentyUnitPrice, decimal TransactionTypeID, string Desc, decimal ReceiveDetailID, string POVendor, string PONumber, string POReceiptDate, string POLine)
        {
            decimal Factor = 0;
            string Type = "";
            short IFSdirective = -1;
            //string sIFSDirective = "";
            string IFSReason = "";
            PartNumberBucketInventoryTransactionType z = (from x in ctx.PartNumberBucketInventoryTransactionTypes where x.PartNumberBucketInventorysourceTypeID == (decimal)TransactionTypeID select x).FirstOrDefault();
            if (z != null)
            {
                //sIFSDirective = z.IFSDirectiveType;
                IFSReason = z.IFSReasonCode;
                //if (short.TryParse(sIFSDirective, out IFSDirective) == false) { IFSDirective = -1; }

                IFSdirective = IFSDirective(ctx, z.IFSDirectiveType);
                Factor = (decimal)z.Factor;
                Type = z.Type;
            }
            QTY *= Factor;

            MasterPartsLinkTable existingPart = (from q in ctx.MasterPartsLinkTables where q.MasterPartsLinkTableID == MasterPartsLInkTableID select q).FirstOrDefault();
            if (existingPart != null)
            {
                existingPart.UnitPrice = existingPart.UnitPrice == null ? 0 : (decimal)existingPart.UnitPrice;
                ProcessMonthEndIfRequired(ctx, existingPart);
                if (Factor > 0)
                {
                    // This is also done inside "RemoveFromInventory". RemoveFromInventory is executed if the factor is negative. Hence, only do if positive.
                    existingPart.Quantity += QTY;
                }

                if (UnitPrice >= 0) { existingPart.UnitPrice = UnitPrice; }   // We may not always update the unit price when we add new units. If the unit  price is -1, this tells us they did not enter a value.
                if (InWarrentyUnitPrice >= 0) { existingPart.InWarrentyWorkPrice = InWarrentyUnitPrice; }   // We may not always update the unit price when we add new units. If the unit  price is -1, this tells us they did not enter a value.
                existingPart.LastUpdateDate = DateTime.Now;
                existingPart.LastUpdateUser = UserName;
                ctx.SubmitChanges();
                decimal MasterPartsLinkTablePriceListID = -1;
                #region AddToInventory
                if (Factor > 0)                          //Type.ToUpper() == "REPLENISH" || Type.ToUpper() == "TRANSFER IN")
                {

                    MasterPartsLinkTablePriceList pl = new MasterPartsLinkTablePriceList();
                    pl.CreateUser = UserName;

                    if (existingPart.UnitPrice == null) { pl.UnitPrice = 0; }
                    else { pl.UnitPrice = (decimal)existingPart.UnitPrice; }
                    if (existingPart.InWarrentyWorkPrice == null) { pl.InWarrentyWorkPrice = 0; }
                    else { pl.InWarrentyWorkPrice = (decimal)existingPart.InWarrentyWorkPrice; }

                    pl.UnitPurchasePrice = UnitPurchasePrice;
                    pl.Quantity = QTY;
                    pl.QTYDispursed = 0;
                    pl.LastUpdateUser = UserName;
                    pl.LastUpdateDate = DateTime.Now;
                    existingPart.MasterPartsLinkTablePriceLists.Add(pl);
                    ctx.SubmitChanges();
                    MasterPartsLinkTablePriceListID = pl.MasterPartsLinkTablePriceListID;
                    // after the save of PL, we should now have a record in the change log.
                    // Find it and then add the reason.
                    MasterPartsLinkTablePriceList_ChangeLog plLog = ctx.MasterPartsLinkTablePriceList_ChangeLogs.OrderByDescending(x => x.LogDate).FirstOrDefault(x => x.MasterPartsLinkTablePriceListID == pl.MasterPartsLinkTablePriceListID);
                    if (plLog != null)
                    {
                        plLog.Log_Reason = Type;
                        ctx.SubmitChanges();
                    }
                    if (QTY > 0)
                    {
                        ////////////////////////////////////////////////
                        // We only want this to happen if the QTY > 0 -- Also, we need the MasterPartsLinkTablePriceList to be saved before the average can work.
                        //existingPart = (from q in ctx.MasterPartsLinkTables where q.MasterPartsLinkTableID == MasterPartsLInkTableID select q).FirstOrDefault();
                        //existingPart.AveragePurchasePrice = GetPartAveragePurchasePrice(ctx, MasterPartsLInkTableID);
                        //ctx.SubmitChanges();
                        //////////////////////////////////////////////////
                        SetPartAveragePurchasePrice(MasterPartsLInkTableID);
                    }

                }
                #endregion
                #region RemoveFromInventory
                if (Factor < 0)
                {
                    RemoveFromInventory(MasterPartsLInkTableID, MasterIFSLocationID, Math.Abs(QTY), TransactionTypeID, Desc);
                }
                #endregion

                if (Factor > 0)
                {
                    //existingPart = (from q in ctx.MasterPartsLinkTables where q.MasterPartsLinkTableID == MasterPartsLInkTableID select q).FirstOrDefault();
                    MasterPartsLinkTable RefreshedPart = GetMasterPartNumbers(MasterPartsLInkTableID);
                    //decimal? xx = RefreshedPart.AveragePurchasePrice;
                    AddInventorySourceTransaction(MasterPartsLInkTableID, MasterIFSLocationID, QTY, UnitPurchasePrice, RefreshedPart.UnitPrice, UnitPrice, RefreshedPart.AveragePurchasePrice, TransactionTypeID, Desc, ReceiveDetailID, MasterPartsLinkTablePriceListID, POVendor, PONumber, POReceiptDate, POLine, IFSReason, IFSdirective);
                }
            }
            return;
        }

