        private void UpdateInventoryDemographicData_B(decimal MasterPartsLInkTableID, decimal UnitPrice, decimal InWarrentyUnitPrice, decimal? Min, decimal? Max, decimal? Reorder)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
