        private void UpdateInventoryDemographicData_B(clsLinqDataContext ctx, decimal MasterPartsLInkTableID, decimal UnitPrice, decimal InWarrentyUnitPrice, decimal? Min, decimal? Max, decimal? Reorder)
        {
            Min = Min == null ? 0 : Min;
            Max = Max == null ? 0 : Max;
            Reorder = Reorder == null ? 0 : Reorder;
            if (Min > 0 || Max > 0 || Reorder > 0 || UnitPrice > 0 || InWarrentyUnitPrice > 0)
            {
                var existingPart = (from q in ctx.MasterPartsLinkTables where q.MasterPartsLinkTableID == MasterPartsLInkTableID select q).FirstOrDefault();
                if (existingPart != null)
                {
                    if (Min > 0) { existingPart.QTYMin = Min; }
                    if (Max > 0) { existingPart.QTYMax = Max; }
                    if (Reorder > 0) { existingPart.QTYReOrder = Reorder; }

                    if (Min < 0) { existingPart.QTYMin = 0; }
                    if (Max < 0) { existingPart.QTYMax = 0; }
                    if (Reorder < 0) { existingPart.QTYReOrder = 0; }

                    if (UnitPrice >= 0) { existingPart.UnitPrice = UnitPrice; }   // We may not always update the unit price when we add new units. If the unit  price is -1, this tells us they did not enter a value.
                    if (InWarrentyUnitPrice >= 0) { existingPart.InWarrentyWorkPrice = InWarrentyUnitPrice; }   // We may not always update the unit price when we add new units. If the unit  price is -1, this tells us they did not enter a value.
                    existingPart.LastUpdateDate = DateTime.Now;
                    existingPart.LastUpdateUser = UserName;
                    ctx.SubmitChanges();
                }
            }
        }

        private void UpdateInventoryDemographicData_A(decimal MasterPartsLInkTableID, string ControlPartnumber, string InternalPartNumber, string InternalPartDesc, decimal? ClassTypeID)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                UpdateInventoryDemographicData_A(ctx, MasterPartsLInkTableID, ControlPartnumber, InternalPartNumber, InternalPartDesc, ClassTypeID);
            }
        }
        private void UpdateInventoryDemographicData_A(clsLinqDataContext ctx, decimal MasterPartsLInkTableID, string ControlPartnumber, string InternalPartNumber, string InternalPartDesc, decimal? ClassTypeID)
        {
            if (ControlPartnumber.Length > 0 || InternalPartNumber.Length > 0 || InternalPartDesc.Length > 0 || ClassTypeID > 0)
            {
                var existingPart = (from q in ctx.MasterPartsLinkTables where q.MasterPartsLinkTableID == MasterPartsLInkTableID select q).FirstOrDefault();
                if (existingPart != null)
                {
                    if (ControlPartnumber.Length > 0 && existingPart.PartNumber != ControlPartnumber 
                        && ctx.MasterPartsLinkTables.Any(x => x.ClientLocationID == existingPart.ClientLocationID && x.PartNumber == ControlPartnumber  && x.MasterPartsLinkTableID != existingPart.MasterPartsLinkTableID) == false) { existingPart.PartNumber = ControlPartnumber.ToUpper(); }  // we only want to update if number not used elsewhere.
                    if (InternalPartNumber.Length > 0 && existingPart.PartNumber != InternalPartNumber
                        && ctx.MasterPartsLinkTables.Any(x => x.ClientLocationID == existingPart.ClientLocationID && x.GMPPartNumber.ToUpper() == InternalPartNumber.ToUpper() && x.MasterPartsLinkTableID != existingPart.MasterPartsLinkTableID) == false) { existingPart.GMPPartNumber = InternalPartNumber.ToUpper(); }
                    if (InternalPartDesc.Length > 0) { existingPart.GMPPartDescription = InternalPartDesc; }
                    if (ClassTypeID > 0) { existingPart.MasterPartsClassTypeID = ClassTypeID; }
                    if (ClassTypeID < 0) { existingPart.MasterPartsClassTypeID = -1; }
                    existingPart.LastUpdateDate = DateTime.Now;
                    existingPart.LastUpdateUser = UserName;
                    ctx.SubmitChanges();
                }
            }
        }

        public string TransferInverntory(decimal MasterPartsLInkTableID, decimal MasterIFSFromLocationID, decimal MasterIFSToLocationID, decimal QTY, decimal NewLocationID, string Reason, bool SetAveragePurchasePrice)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                return TransferInverntory(ctx, MasterPartsLInkTableID, MasterIFSFromLocationID, MasterIFSToLocationID, QTY, NewLocationID, Reason, SetAveragePurchasePrice);
            }
        }
        public string TransferInverntory(clsLinqDataContext ctx, decimal MasterPartsLInkTableID, decimal MasterIFSFromLocationID, decimal MasterIFSToLocationID, decimal QTY, decimal NewLocationID, string Reason, bool SetAveragePurchasePrice)
        {
            // Find the origninal Part

            MasterPartsLinkTable existingPart = ctx.MasterPartsLinkTables.FirstOrDefault(x => x.MasterPartsLinkTableID == MasterPartsLInkTableID);
            if (existingPart == null) { return "Transfer Canceled: Original Part Not found."; }
            //if (existingPart.Quantity < QTY) { return "Transfer Canceled: Not enough Stock."; }

            if (NewLocationID < 1) {
                if (existingPart.ClientLocationID == null) { NewLocationID = -1; }
                else { NewLocationID = (decimal)existingPart.ClientLocationID; }
            }


            ////MasterPartsLinkTablePriceList pricelist = existingPart.MasterPartsLinkTablePriceLists.OrderBy(x=>x.CreateDate).FirstOrDefault(x=> x.Quantity - x.QTYDispursed >= QTY);
            //MasterPartsLinkTablePriceList pricelist = existingPart.MasterPartsLinkTablePriceLists.OrderByDescending(x => x.Quantity - x.QTYDispursed).OrderBy(x => x.CreateDate).FirstOrDefault();
            //if (pricelist == null) {
            //    MasterPartsLinkTablePriceList pl = existingPart.MasterPartsLinkTablePriceLists.OrderByDescending(x => x.Quantity - x.QTYDispursed).FirstOrDefault(x => x.Quantity - x.QTYDispursed > 0);
            //    if (pl != null)
            //    {
            //        return "Transfer Canceled: Not enough Stock for one transaction. Max Next Transfer = " + (pl.Quantity - pl.QTYDispursed).ToString(); 
            //    }
            //    return "Transfer Canceled: MasterPartsLinkTablePriceLists Not Found."; 
            //}
            decimal UnitPurchasePrice = 0;                  // pricelist.UnitPurchasePrice == null ? 0 : (decimal)pricelist.UnitPurchasePrice;

            // Make sure there is a record for the new location
            decimal NewMasterPartsLInkTableID = -1;
            string Carrier = (string)existingPart.Carrier;
            string Manufacturer = (string)existingPart.Manufacturer;
            string Model = "";
            decimal MasterPartsClassTypeID = (decimal)existingPart.MasterPartsClassTypeID;
            foreach (MasterPartsLinkTableModelList x in existingPart.MasterPartsLinkTableModelLists) { Model += x.ModelID.ToString() + ","; }

            NewMasterPartsLInkTableID = InsertPartNumber(ctx, existingPart.MasterPartsID, -1, NewLocationID, Carrier, Manufacturer, Model, existingPart.PartNumber, existingPart.GMPPartNumber, existingPart.GMPPartDescription, MasterPartsClassTypeID);

            PartNumberBucketInventoryTransactionType TransferIn = GetMasterPartTransType(ctx, "Transfer In");
            //PartNumberBucketInventoryTransactionType TransferOut = GetMasterPartTransType(ctx, "Transfer Out");

            decimal UnitPrice = existingPart.UnitPrice == null ? 0 : (decimal)existingPart.UnitPrice;
            decimal InWarrentyWorkPrice = existingPart.InWarrentyWorkPrice == null ? 0 : (decimal)existingPart.InWarrentyWorkPrice;

            RemoveFromInventoryTransferOut(ctx, existingPart.MasterPartsLinkTableID, MasterIFSFromLocationID, QTY, Reason);
            AddToInventory(NewMasterPartsLInkTableID, MasterIFSToLocationID, QTY, UnitPurchasePrice, UnitPrice, InWarrentyWorkPrice, TransferIn.PartNumberBucketInventorysourceTypeID, Reason, -1
                          ,existingPart.PartNumber, existingPart.GMPPartNumber, existingPart.GMPPartDescription, existingPart.QTYMin, existingPart.QTYMax, existingPart.QTYReOrder, existingPart.MasterPartsClassTypeID, "","", "", "", "");


            //RemoveFromInventoryTransferOut(ctx, existingPart.MasterPartsLinkTableID, MasterIFSFromLocationID, QTY, Reason);
            //AddToInventory(NewMasterPartsLInkTableID, MasterIFSToLocationID, QTY, UnitPurchasePrice, UnitPrice, InWarrentyWorkPrice, TransferIn.PartNumberBucketInventorysourceTypeID, Reason, -1
            //              , existingPart.PartNumber, existingPart.GMPPartNumber, existingPart.GMPPartDescription, existingPart.QTYMin, existingPart.QTYMax, existingPart.QTYReOrder, existingPart.MasterPartsClassTypeID, "", "", "", "", "");
            
            
            if (SetAveragePurchasePrice == true)
            {
                SetPartAveragePurchasePrice(NewMasterPartsLInkTableID);
            }
            return QTY.ToString() + " Parts transfered to new location.";
        }
     
