        public ReceiveDetailPartsUsage RemoveFromInventory(clsLinqDataContext ctx, decimal MasterPartsLinkTableID, decimal MasterIFSLocationID, decimal QTY, decimal TransactionTypeID, string Desc, decimal ReceiveDetailID, decimal ReceiveDetailItemID)
        {
            JimErrorLogManager logmanager = new JimErrorLogManager(UserName, "RemoveFromInventory()");
            logmanager.IsActive = ((System.Configuration.ConfigurationManager.AppSettings["WriteLog"].ToUpper() == "TRUE"));
            logmanager.ReportMessage("starting Remove From Inventory:" + MasterPartsLinkTableID.ToString());
            //string TechAssignedLog = "";
            decimal TechAssigneID = -1;
            decimal Factor = 0;
            string Type = "";
            short IFSdirective = -1;
            //string sIFSDirective = "";
            string IFSReason = "";
            PartNumberBucketInventoryTransactionType z = (from x in ctx.PartNumberBucketInventoryTransactionTypes where x.PartNumberBucketInventorysourceTypeID == (decimal)TransactionTypeID select x).FirstOrDefault();
            if (z != null)
            {
                //sIFSDirective = z.IFSDirectiveType;
                //if (short.TryParse(sIFSDirective, out IFSDirective) == false) { IFSDirective = -1; }
                logmanager.ReportMessage("Found Transaction Type:" + z.Type);
                IFSReason = z.IFSReasonCode;
                IFSdirective = IFSDirective(ctx, z.IFSDirectiveType);

                Factor = (decimal)z.Factor;
                Type = z.Type;
            }

            decimal ClientUnitPrice = 0;
            if (QTY != 0)
            {
                logmanager.ReportMessage("QTY != 0:" + QTY.ToString());
                ReceiveDetailPartsUsage pu = null;
                decimal PartNumberBucketInventoryPlacementID = -1;
                decimal MasterPartsLinkTablePriceListID = -1;
                decimal UnitPurchasePrice = 0;
                decimal AveragePurchasePrice = 0;
                decimal UnitPrice = 0;
                // Record Tech Usage as used.
                QTY = QTY * Factor;              // GetTypeFactor(ctx, TransactionTypeID);
                logmanager.ReportMessage("QTY = QTY * Factor:" + QTY.ToString());
                MasterPartsTechAssignedLog talog = GetTechAssignedLog(ReceiveDetailID, MasterPartsLinkTableID, UserName);
                if (talog != null && talog.MasterIFSLocationToID != null) { MasterIFSLocationID = (decimal)talog.MasterIFSLocationToID; }
                if (talog != null) { TechAssigneID = talog.MasterPartsTechAssignedLogID; }
                if (ReceiveDetailID > 0) { ProcessTechAssigned(MasterPartsLinkTableID, QTY, ReceiveDetailID, ReceiveDetailItemID); }
                var existingPart = (from q in ctx.MasterPartsLinkTables where q.MasterPartsLinkTableID == MasterPartsLinkTableID select q).FirstOrDefault();
                if (existingPart != null)
                {
                    ProcessMonthEndIfRequired(ctx, existingPart);
                    ClientUnitPrice = GetClientUnitPrice(ctx, MasterPartsLinkTableID, ReceiveDetailID, existingPart, logmanager);
                    UnitPrice = ClientUnitPrice;
                    existingPart.Quantity += QTY;
                    existingPart.LastUpdateDate = DateTime.Now;
                    existingPart.LastUpdateUser = UserName;
                    ctx.SubmitChanges();

                    if (ReceiveDetailID > 0)
                    {
                        pu = new ReceiveDetailPartsUsage();
                        pu.ReceiveDetailID = ReceiveDetailID;
                        pu.ReceiveDetailItemID = ReceiveDetailItemID;
                        pu.CreateUser = UserName;
                        pu.LastUpdateDate = DateTime.Now;
                        pu.LastUpdateUser = UserName;
                        pu.MasterPartsLinkTableID = MasterPartsLinkTableID;
                        pu.Description = existingPart.MasterPart.Description;
                        pu.PartNumber = existingPart.PartNumber;
                        pu.GMPPartDescription = existingPart.GMPPartDescription;
                        pu.GMPPartNumber = existingPart.GMPPartNumber.ToUpper();
                        pu.AveragePurchasePrice = existingPart.AveragePurchasePrice;
                        AveragePurchasePrice = existingPart.AveragePurchasePrice == null ? 0 : (decimal)existingPart.AveragePurchasePrice;
                        pu.MasterPartsLinkTablePriceListID = -2;
                        pu.UnitPurchasePrice = 0;             // need to get from depreciated stock. MasterPartsLinkTablePriceList
                        pu.StatusID = 1; // 1 = Active, 2 = Deleted
                        pu.UnitPrice = ClientUnitPrice;
                        pu.PartNumberBucketInventoryPlacementID = PartNumberBucketInventoryPlacementID;             // transaction.PartNumberBucketInventoryPlacementID;
                        pu.Quantity = QTY;
                    }

                    decimal CurrentQTY = Math.Abs(QTY);
                    decimal WorkingQTY = 0;
                    decimal First_PartNumberBucketInventoryPlacementID = -1;
                    foreach (MasterPartsLinkTablePriceList pricelist in existingPart.MasterPartsLinkTablePriceLists.OrderBy(x => x.CreateDate))
                    {
                        if (pricelist.Quantity - pricelist.QTYDispursed > 0)
                        {
                            WorkingQTY = Math.Min(CurrentQTY, pricelist.Quantity - pricelist.QTYDispursed);
                            CurrentQTY -= WorkingQTY;
                            WorkingQTY = QTY < 1 ? WorkingQTY * -1 : WorkingQTY;      // we need to set the working qty sign equal to the sign of QTY.
                            UnitPurchasePrice = pricelist.UnitPurchasePrice != null ? (decimal)pricelist.UnitPurchasePrice : 0;
                            MasterPartsLinkTablePriceListID = pricelist.MasterPartsLinkTablePriceListID;
                            pricelist.QTYDispursed += WorkingQTY * -1;
                            if (ReceiveDetailID > 0)
                            {
                                pu.MasterPartsLinkTablePriceListID = pricelist.MasterPartsLinkTablePriceListID;
                                pu.UnitPurchasePrice = pricelist.UnitPurchasePrice != null ? pricelist.UnitPurchasePrice : 0;             // need to get from depreciated stock. MasterPartsLinkTablePriceList
                            }
                            logmanager.ReportMessage("Price List Loop:" + WorkingQTY.ToString());
                            PartNumberBucketInventoryPlacementID = AddInventoryPlacementTransaction(MasterPartsLinkTableID, MasterIFSLocationID, TechAssigneID, WorkingQTY
                                                        , UnitPurchasePrice
                                                        , existingPart.UnitPrice
                                                        , UnitPrice
                                                        , existingPart.AveragePurchasePrice
                                                        , TransactionTypeID
                                                        , Desc
                                                        , ReceiveDetailID
                                                        , MasterPartsLinkTablePriceListID, IFSReason, IFSdirective);
                            logmanager.ReportMessage("PartNumberBucketInventoryPlacementID:" + PartNumberBucketInventoryPlacementID.ToString());
                            if (First_PartNumberBucketInventoryPlacementID < 1)
                            {
                                First_PartNumberBucketInventoryPlacementID = PartNumberBucketInventoryPlacementID;
                            }
                        }

                        if (CurrentQTY <= 0) { break; }
                    }
                    if (CurrentQTY > 0)
                    {
                        CurrentQTY = CurrentQTY * Factor;
                        logmanager.ReportMessage("CurrencyQTY > 0 trans:" + WorkingQTY.ToString());
                        PartNumberBucketInventoryPlacementID = AddInventoryPlacementTransaction(MasterPartsLinkTableID, MasterIFSLocationID, TechAssigneID, CurrentQTY 
                                                    , UnitPurchasePrice
                                                    , existingPart.UnitPrice
                                                    , UnitPrice
                                                    , existingPart.AveragePurchasePrice
                                                    , TransactionTypeID
                                                    , Desc
                                                    , ReceiveDetailID
                                                    , MasterPartsLinkTablePriceListID, IFSReason, IFSdirective);
                        logmanager.ReportMessage("PartNumberBucketInventoryPlacementID_B:" + PartNumberBucketInventoryPlacementID.ToString());
                        if (First_PartNumberBucketInventoryPlacementID < 1)
                        {
                            First_PartNumberBucketInventoryPlacementID = PartNumberBucketInventoryPlacementID;
                        }
                    }
                    if (ReceiveDetailID > 0)
                    {
                        logmanager.ReportMessage("pu.PartNumberBucketInventoryPlacementID = " + PartNumberBucketInventoryPlacementID.ToString());
                        pu.PartNumberBucketInventoryPlacementID = First_PartNumberBucketInventoryPlacementID;
                        ctx.ReceiveDetailPartsUsages.InsertOnSubmit(pu);
                    }
                    ctx.SubmitChanges();
                }
                return pu;
            }
            return null;
        }

        public ReceiveDetailPartsUsage ReverseTransaction(clsLinqDataContext ctx, decimal PartNumberBucketInventoryPlacementID, decimal ReceiveDetailID, decimal ReceiveDetailItemID, decimal MasterPartsLinkTableID)
        {
            JimErrorLogManager logManager = new JimErrorLogManager(UserName, "ReverseTransaction(" + PartNumberBucketInventoryPlacementID.ToString() + ":" + ReceiveDetailID.ToString() + ":" + ReceiveDetailItemID.ToString() + ":" + MasterPartsLinkTableID.ToString() + ")");
            logManager.ReportMessage("R-Transaction :PNBInventoryPlacementID = " + PartNumberBucketInventoryPlacementID.ToString());
            ReceiveDetailPartsUsage pu = null;
            decimal TechAssignedID = -1;
            decimal NewPartNumberBucketInventoryPlacementID = -1;
            decimal MasterPartsLinkTablePriceListID = -1;
            decimal UnitPurchasePrice = 0;
            decimal AveragePurchasePrice = 0;
            decimal UnitPrice = 0;

            var Original = ctx.PartNumberBucketInventoryPlacements.FirstOrDefault(x =>x.MasterPartsLinkTableID == MasterPartsLinkTableID && x.PartNumberBucketInventoryPlacementID == PartNumberBucketInventoryPlacementID);
            if (Original == null) {
                logManager.ReportMessage("Original == null = " + MasterPartsLinkTableID.ToString());
                return null; 
            }
            decimal QTY = 0;
            QTY = Original.Quantity * -1;

            MasterPartManager mpm = new MasterPartManager(UserName);

            MasterPartsTechAssignedLog talog = GetTechAssignedLog(ReceiveDetailID, MasterPartsLinkTableID, UserName);
            if (talog != null) { TechAssignedID = talog.MasterPartsTechAssignedLogID; }


            if (QTY < 0 && ReceiveDetailItemID > 0 && MasterPartsLinkTableID > 0) { mpm.MasterPartsTechAssignedLog_LinkToUnit(ReceiveDetailID, ReceiveDetailItemID, MasterPartsLinkTableID, UserName); }
            if (QTY > 0 && ReceiveDetailItemID > 0) { mpm.MasterPartsTechAssignedLog_RemoveUnitLink(ReceiveDetailID, ReceiveDetailItemID); }

            decimal ClientUnitPrice = 0;
            var existingPart = (from q in ctx.MasterPartsLinkTables where q.MasterPartsLinkTableID == Original.MasterPartsLinkTableID select q).FirstOrDefault();
            if (existingPart != null)
            {
                logManager.ReportMessage("existingPart != null = " + Original.MasterPartsLinkTableID.ToString());
                ProcessMonthEndIfRequired(ctx, existingPart);
                ClientUnitPrice = GetClientUnitPrice(ctx, existingPart.MasterPartsLinkTableID, Original.ReceiveDetailID, existingPart, logManager);
                UnitPrice = ClientUnitPrice;
                //transaction.UnitPrice = existingPart.UnitPrice;
                existingPart.Quantity += Original.Quantity * -1;
                existingPart.LastUpdateDate = DateTime.Now;
                existingPart.LastUpdateUser = UserName;
                ctx.SubmitChanges();

                MasterPartsLinkTable lt = ctx.MasterPartsLinkTables.FirstOrDefault(x => x.MasterPartsLinkTableID == existingPart.MasterPartsLinkTableID);
                if (lt != null)
                {
                    logManager.ReportMessage("MasterPartsLinkTable lt  != null =  " + existingPart.MasterPartsLinkTableID.ToString());
                    pu = new ReceiveDetailPartsUsage();
                    pu.ReceiveDetailID = ReceiveDetailID;
                    pu.CreateUser = UserName;
                    pu.LastUpdateDate = DateTime.Now;
                    pu.LastUpdateUser = UserName;
                    pu.MasterPartsLinkTableID = existingPart.MasterPartsLinkTableID;
                    pu.Description = lt.MasterPart.Description;
                    pu.PartNumber = lt.PartNumber;
                    pu.GMPPartDescription = lt.GMPPartDescription;
                    pu.GMPPartNumber = lt.GMPPartNumber.ToUpper();
                    pu.StatusID = 1; // 1 = Active, 2 = Deleted
                    pu.UnitPrice = ClientUnitPrice;
                    pu.PartNumberBucketInventoryPlacementID = NewPartNumberBucketInventoryPlacementID;
                    pu.Quantity = QTY;                        // QTY < 0 ? QTY * -1 : QTY;
                    pu.MasterPartsLinkTablePriceListID = -2;
                    pu.UnitPurchasePrice = 0;             // need to get from depreciated stock. MasterPartsLinkTablePriceList

                    // Find the original ReceiveDetailPartsUsage Transaction -- We need to follow it back and add to the QTYDispersed because this one is no longer there.
                    ReceiveDetailPartsUsage OriginalPU = ctx.ReceiveDetailPartsUsages.FirstOrDefault(x => x.ReceiveDetailID == ReceiveDetailID && x.ReceiveDetailItemID == ReceiveDetailItemID && x.MasterPartsLinkTableID == MasterPartsLinkTableID);
                    MasterPartsLinkTablePriceList pricelist = ctx.MasterPartsLinkTablePriceLists.FirstOrDefault(x => Original.MasterPartsLinkTablePriceListID != null && x.MasterPartsLinkTablePriceListID == Original.MasterPartsLinkTablePriceListID); ;
                    if (OriginalPU != null && pricelist == null)
                    {
                        pricelist = ctx.MasterPartsLinkTablePriceLists.FirstOrDefault(x => x.MasterPartsLinkTablePriceListID == OriginalPU.MasterPartsLinkTablePriceListID);
                    }
                    if (pricelist != null)
                    {
                        pu.MasterPartsLinkTablePriceListID = pricelist.MasterPartsLinkTablePriceListID;
                        pu.UnitPurchasePrice = pricelist.UnitPurchasePrice != null ? pricelist.UnitPurchasePrice : 0;           // need to get from depreciated stock. MasterPartsLinkTablePriceList
                        pu.AveragePurchasePrice = OriginalPU.AveragePurchasePrice != null ? OriginalPU.AveragePurchasePrice : 0;
                        pricelist.QTYDispursed += QTY * -1;
                    }
                    ctx.SubmitChanges();
                }
            }
            logManager.ReportMessage("AddInvPlaceTrans(  " + ((decimal)Original.MasterIFSLocationID).ToString() + ":" + Original.IFSReason + ":" +  ((short)Original.IFSDirective).ToString());
            //PartNumberBucketInventoryTransactionType TransferOut = GetMasterPartTransType(ctx, "Return by Tech");
            //decimal TransactionTypeID = TransferOut.PartNumberBucketInventorysourceTypeID;

            // We need to find the current location where the device is and use that location for the reversal.
            decimal RD_IFSLocationID = (decimal)Original.MasterIFSLocationID; // Set it to the location where it went on the Device
            ReceiveDetail rd = ctx.ReceiveDetails.FirstOrDefault(x => x.ReceiveDetailID == ReceiveDetailID);
            if (rd != null)
            {
                IFSLocation Loc = new IFSLocation(rd.IFSLocation);
                if (Loc.isValid == true)
                {
                    IFSLocation C1NALoc = new IFSLocation(Loc.C1NA());
                    if (C1NALoc.isValid == true)
                    {
                        RD_IFSLocationID = C1NALoc.ID;   // Set it to the Current Device Location.
                    }
                }
            }
            //
            //PartNumberBucketInventoryPlacementID = AddInventoryPlacementTransaction(MasterPartsLinkTableID, (decimal)Original.MasterIFSLocationID, QTY

            // **************   WARNING **********************************
            // The default values are set because old 2.0 transactions do not carry this info.
            // But at some time, Original should always carry the correct values.
            short directive = 12;
            string reason = "08";
            if (Original.IFSDirective != null)
            {
                directive = (short)Original.IFSDirective;
            }
            if (Original.IFSReason != null && Original.IFSReason.Length > 0)
            {
                reason = Original.IFSReason;
            }

            PartNumberBucketInventoryPlacementID = AddInventoryPlacementTransaction(MasterPartsLinkTableID, RD_IFSLocationID,TechAssignedID, QTY
                                        , UnitPurchasePrice
                                        , ClientUnitPrice
                                        , ClientUnitPrice
                                        , Original.AveragePurchasePrice
                                        , Original.PartNumberBucketInventoryTransactionTypeID
                                        , Original.Desc
                                        , ReceiveDetailID
                                        , MasterPartsLinkTablePriceListID, reason, directive);
            if (pu != null) { pu.PartNumberBucketInventoryPlacementID = PartNumberBucketInventoryPlacementID; ctx.SubmitChanges(); }
            return pu;
        }

