                return MasterPartsTechAssignedLog_RemoveUnitLink(ReceiveDetailID, ReceiveDetailItemID);
                ////mpm.MasterPartsTechAssignedLog_RemoveUnitLink(ctx, ReceiveDetailID, ReceiveDetailItemID);
