            //    return mpm.MasterPartsTechAssignedLog_RemoveUnitLink(ReceiveDetailID, ReceiveDetailItemID);
            //    ////mpm.MasterPartsTechAssignedLog_RemoveUnitLink(ctx, ReceiveDetailID, ReceiveDetailItemID);
            //}
            return "";
        }

        private decimal AddInventorySourceTransaction(decimal MasterPartsLInkTableID, decimal MasterIFSLocationID, decimal QTY, decimal UnitPurchasePrice, decimal? OriginalUnitPrice
            , decimal NewUnitPrice, decimal? AveragePurchasePrice, decimal TransactionTypeID, string Desc, decimal ReceiveDetailID, decimal MasterPartsLinkTablePriceListID, string POVendor
            , string PONumber, string POReceiptDate, string POLine, string IFSReasonCode, short IFSDirective)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                return AddInventorySourceTransaction(ctx, MasterPartsLInkTableID, MasterIFSLocationID, QTY, UnitPurchasePrice
                    , OriginalUnitPrice, NewUnitPrice, AveragePurchasePrice, TransactionTypeID, Desc, ReceiveDetailID, MasterPartsLinkTablePriceListID, POVendor,PONumber, POReceiptDate, POLine, IFSReasonCode, IFSDirective);
            }
        }
        private decimal AddInventorySourceTransaction(clsLinqDataContext ctx, decimal MasterPartsLInkTableID, decimal MasterIFSLocationID
              , decimal QTY, decimal UnitPurchasePrice, decimal? OriginalUnitPrice, decimal NewUnitPrice, decimal? AveragePurchasePrice
              , decimal TransactionTypeID, string Desc, decimal ReceiveDetailID, decimal MasterPartsLinkTablePriceListID
              , string POVendor, string PONumber, string POReceiptDate, string POLine, string IFSReasonCode, short IFSDirective)
        {
            AveragePurchasePrice = AveragePurchasePrice == null ? 0 : AveragePurchasePrice;
            OriginalUnitPrice = OriginalUnitPrice == null ? 0 : OriginalUnitPrice;


            ctx.SubmitChanges();
            IFSLocation location = new IFSLocation(MasterIFSLocationID);
            PartNumberBucketInventorySource transaction = new PartNumberBucketInventorySource();

            transaction.IFSDirective = IFSDirective;
            transaction.IFSReason = IFSReasonCode;
            transaction.POLine = POLine;
            transaction.PONumber = PONumber;
            transaction.POReceiptDate = DateTime.Now;                   //POReceiptDate;
            transaction.POVendor = POVendor;
            transaction.Desc = Desc;
            transaction.MasterPartsLinkTableID = MasterPartsLInkTableID;
            transaction.PartNumberBucketInventoryTransactionTypeID = TransactionTypeID;
            transaction.Quantity = QTY;
            transaction.MasterIFSLocationID = location.ID;         // MasterIFSLocationID;
            transaction.UnitPrice = NewUnitPrice > 0 ? NewUnitPrice : OriginalUnitPrice;
            transaction.UnitPurchasePrice = UnitPurchasePrice > 0 ? UnitPurchasePrice : 0;
            transaction.ReceiveDetailID = ReceiveDetailID;
            transaction.CreateDate = DateTime.Now;
            transaction.CreateUser = UserName;
            transaction.LastUpdateDate = DateTime.Now;
            transaction.LastUpdateUser = UserName;
            transaction.MasterPartsLinkTablePriceListID = MasterPartsLinkTablePriceListID;
            transaction.AveragePurchasePrice = AveragePurchasePrice;
            ctx.PartNumberBucketInventorySources.InsertOnSubmit(transaction);
            ctx.SubmitChanges();
            return transaction.PartNumberBucketInventorySourceID;
        }
