        public List<Question> GetDataConditions(clsLinqDataContext ctx, string ProcessLevel, string Project)
        {
            decimal? pID = ctx.GetProcessIDFromProcessName_Project(Project, ProcessLevel);
            if (pID == null) { pID = -1; }
            IQueryable<Question> ns =
                from x in ctx.Questions
                join z in ctx.ProcessQuestions on x.QuestionID equals z.QuestionID
                where z.ProcessID == pID && z.Process.ProcessStatus.Status.ToUpper() != "INACTIVE" && x.QuestionStatus.Status.ToUpper() != "INACTIVE"
                && (x.QuestionType.Type == "Checkbox" || x.QuestionType.Type == "Dropdown" || x.QuestionType.Type == "RadialButton")
                orderby x.Sequence
                select x;

            return UserRestrict.GetRestricted(ns, ctx).ToList();
        }


