        public bool HasUnitEnteredAtleasetOneofTheseProcesses(decimal ReceiveDetailID, string ProcessNamestring)
        {
            if (ProcessNamestring.Length == 0) { return false; }
            List<string> ProcessNames = ProcessNamestring.Split(new char[] { ',' }, StringSplitOptions.RemoveEmptyEntries).ToList();
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                foreach (string ProcessName in ProcessNames)
                {
                    if (HasUnitEnteredThisProcess(ctx, ReceiveDetailID, ProcessName) == true) { return true; }
                }
            }
            return false;
        }
        public bool HasUnitEnteredTheseProcesses(decimal ReceiveDetailID, string ProcessNamestring)
        {
            if (ProcessNamestring.Length == 0) { return false; }
            List<string> ProcessNames = ProcessNamestring.Split(new char[] { ',' }, StringSplitOptions.RemoveEmptyEntries).ToList();
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                foreach (string ProcessName in ProcessNames)
                {
                    if (HasUnitEnteredThisProcess(ctx, ReceiveDetailID, ProcessName) == false) { return false; }
                }
            }
            return true;
        }
        public bool HasUnitEnteredThisProcess(decimal ReceiveDetailID, string ProcessName)
        {
            if (ProcessName.Length == 0) { return false; }
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                return HasUnitEnteredThisProcess(ctx, ReceiveDetailID, ProcessName);
            }
        }

        public bool HasUnitEnteredThisProcess(clsLinqDataContext ctx, decimal ReceiveDetailID, string ProcessName)
        {
            Process p = ctx.Processes.FirstOrDefault(x => x.Name == ProcessName);
            if (p != null)
            {
                ReceiveDetailProcessLog pl = ctx.ReceiveDetailProcessLogs.FirstOrDefault(x => x.ProcessID == p.ProcessID && x.ReceiveDetailID == ReceiveDetailID);
                if (pl != null) { return true; }
            }
            return false;
        }

