        public decimal GetProcessidFromName(clsLinqDataContext ctx, string ProcessName, string Project)
        {
            ProjectProcess p = ctx.ProjectProcesses.FirstOrDefault(x => x.Process.Name == ProcessName && x.Project.Name == Project);
            if (p != null) { return p.ProcessID; }

            // If it does not find the process and the Process Name == "RECEIVE", then we may be looking for another receive screen under the Project.
            // There is a rule that all receive screens begin with the name "RECEIVE".
            if (ProcessName.ToUpper() == "RECEIVE")
            {
                p = ctx.ProjectProcesses.FirstOrDefault(x => x.Process.Name.ToUpper().Substring(0, 7) == "RECEIVE" && x.Project.Name == Project);
                if (p != null) { return p.ProcessID; }
            }
            return -1;
        }


