        [DataObjectMethod(DataObjectMethodType.Insert)]
        public decimal InsertProcess(Process Process)
        {
            decimal ReturnValue = -1;
            if (Process != null)
            {
                using (clsLinqDataContext ctx = GetDataContext(UserName))
                {
                    Process.LastUpdateDate = DateTime.Now;
                    Process.LastUpdateUser = UserName;
                    Process.CreateDate = DateTime.Now;
                    Process.CreateUser = UserName;
                    ctx.Processes.InsertOnSubmit(Process);
                    ctx.SubmitChanges();
                    return Process.ProcessID;
                }

            }
            return ReturnValue;
        }

        [DataObjectMethod(DataObjectMethodType.Update)]
        public void UpdateProcess(Process Process)
        {
            if (Process != null)
            {
                using (clsLinqDataContext ctx = GetDataContext(UserName))
                {
                    var existingProcess = (from q in ctx.Processes where q.ProcessID == Process.ProcessID select q).FirstOrDefault();
                    if (existingProcess != null)
                    {
                        existingProcess.Sequence = Process.Sequence;
                        existingProcess.StatusID = Process.StatusID;
                        existingProcess.ScanKey = Process.ScanKey;
                        existingProcess.MacroKey = Process.MacroKey;
                        ////existingProcess.ProcessProcesss = Process.ProcessProcesss;
                        ////existingProcess.Options = Process.Options;
                        existingProcess.Name = Process.Name;
                        existingProcess.Description = Process.Description;
                        existingProcess.LastUpdateDate = DateTime.Now;
                        existingProcess.LastUpdateUser = UserName;
                        ctx.SubmitChanges();
                    }
                }
            }
        }

        [DataObjectMethod(DataObjectMethodType.Delete)]
        public void DeleteProcess(Process Process)
        {
            DeleteProcess(Process.ProcessID);
        }

        [DataObjectMethod(DataObjectMethodType.Delete)]
        public void DeleteProcess(decimal ProcessID)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                var ProcessToDelete = (from q in ctx.Processes where q.ProcessID == ProcessID select q).FirstOrDefault();
                if (ProcessToDelete != null)
                {
                    // used to remove the ID Link to Process --- because the process is being deleted.
                    ctx.Update_FreeLogFromProcess(ProcessID);


                    IQueryable<ProjectProcess> pp = from x in ctx.ProjectProcesses where x.ProcessID == ProcessID select x;
                    if (pp != null)
                    {
                        foreach (ProjectProcess op in pp)
                        {
                            ctx.ProjectProcesses.DeleteOnSubmit(op);
                        }
                    }

                    IQueryable<NextProcessStep> ops = from x in ctx.NextProcessSteps where x.SourceProcessID == ProcessID || x.TargetStepProcessID == ProcessID select x;
                    if (ops != null)
                    {
                        foreach (NextProcessStep op in ops)
                        {
                            ctx.NextProcessSteps.DeleteOnSubmit(op);
                        }
                    }
                    IQueryable<ProcessQuestion> PQ = from x in ctx.ProcessQuestions where x.ProcessID == ProcessID select x;
                    if (PQ != null)
                    {
                        foreach (ProcessQuestion op in PQ)
                        {
                            ctx.ProcessQuestions.DeleteOnSubmit(op);
                        }
                    }
                    IQueryable<ProcessBinLocation> loc = from x in ctx.ProcessBinLocations where x.ProcessID == ProcessID select x;
                    if (loc != null)
                    {
                        foreach (ProcessBinLocation op in loc)
                        {
                            ctx.ProcessBinLocations.DeleteOnSubmit(op);
                        }
                    }
                    ctx.Processes.DeleteOnSubmit(ProcessToDelete);
                    ctx.SubmitChanges();
                }
            }
        }

        public List<PairIDValue> GetProcessBinLocationsPairIDValue(decimal KeyID)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                var process = GetProcesss(KeyID);
                List<PairIDValue> li = new List<PairIDValue>();
                foreach (var x in process.ProcessBinLocations)
                {
                    li.Add(new PairIDValue { ID = x.BinLocationID, Desc = x.BinLocation.Description });
                }
                return li;
            }
        }
