        public IQueryable<NextProcessStep> GetNextProcessSteps(clsLinqDataContext ctx, string ProcessLevel, string Project)
        {
            decimal? pID = ctx.GetProcessIDFromProcessName_Project(Project, ProcessLevel);
            if (pID == null) { pID = -1; }
            IQueryable<NextProcessStep> ns = (from z in ctx.NextProcessSteps.Where(y => y.Process1.ProcessID == pID && y.NextProcessStepStatus.Status.ToUpper() != "INACTIVE").OrderBy(y => y.Sequence) select z);
            return ns;
        }

