        public List<string> EditCheckToAdd(string CarrierABBR, string ManufacturerABBR, string ModelABBR, string ColourABBR)
        {
            List<string> rMessages = new List<string>();
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                Option rCarrier = ctx.Options.FirstOrDefault(y => y.Question.Name.ToUpper() == "CARRIER" && y.Name.ToUpper() == CarrierABBR.ToUpper());
                Option rManufacturer = ctx.Options.FirstOrDefault(y => y.Question.Name.ToUpper() == "MANUFACTURER" && y.Name.ToUpper() == ManufacturerABBR.ToUpper());
                Option rModel = ctx.Options.FirstOrDefault(y => y.Question.Name.ToUpper() == "MODEL" && y.Name.ToUpper() == ModelABBR.ToUpper());
                Option rColour = ctx.Options.FirstOrDefault(y => y.Question.Name.ToUpper() == "COLOUR" && y.Name.ToUpper() == ColourABBR.ToUpper());
                if (rCarrier == null) { rMessages.Add("Carrier (" + CarrierABBR + ") Not Found."); }
                if (rManufacturer == null) { rMessages.Add("Manufacturer (" + ManufacturerABBR + ") Not Found."); }
                if (rModel == null) { rMessages.Add("Model (" + ModelABBR + ") Not Found."); }
                if (rColour == null) { rMessages.Add("Colour (" + ColourABBR + ") Not Found."); }
                if (rMessages.Count == 0)
                {
                    MasterCarrierManufacturerLookup master = ctx.MasterCarrierManufacturerLookups.FirstOrDefault(y => y.OptionCarrierID == rCarrier.OptionID &&
                                                                                                                      y.OptionManufacturerID == rManufacturer.OptionID &&
                                                                                                                      y.OptionModelID == rModel.OptionID &&
                                                                                                                      y.OptionColourID == rColour.OptionID);
                    if (master != null) { rMessages.Add("SKU Combo already Established. Add not required."); }
                }
            }
            if (rMessages.Count > 0) { rMessages.Insert(0, "Error:"); }
            else { rMessages.Insert(0, "Success:"); }
            return rMessages;
        }







