        public string UpdateStockColourCode(string Manufacturer, string Model, string StockColourCode)
        {
            int count = 0;
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                if (AddModelIfNotFound(ctx, Model) == false)
                {
                    return "Model not found... Not added";
                }
                var MasterModel = ctx.MasterCarrierManufacturerLookups.Where(x => x.Manufacturer == Manufacturer && x.Model == Model);
                foreach (MasterCarrierManufacturerLookup r in MasterModel)
                {
                    count++;
                    r.Condition = StockColourCode;                       //Feb 27, 2013 Jody asked that the Condition field to now be used as the Stock Colour Code
                }
                if (count > 0) { ctx.SubmitChanges(); }

            }
            return Manufacturer + "/" + Model + "/" + StockColourCode + ": " + count.ToString() + " records updated";
        }
