        [DataObjectMethod(DataObjectMethodType.Insert)]
        public string InsertMasterCarrierManufacturerLookup(MasterCarrierManufacturerLookup ML)
        {
            //if (uac.AllowAdd("Project"))
            //{
            Option o = null;
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                #region Carrier
                //decimal xID = -1;
                if (ML.OptionCarrierID == null || ML.OptionCarrierID < 1)
                {
                    if (ML.Carrier.Length > 0) { 
                        //xID = GetQuestionOptionID("Carrier", ML.Carrier);
                        o = GetQuestionRecord("Carrier", ML.Carrier);
                        if (o != null)
                        {
                            ML.OptionCarrierID = o.OptionID;
                            ML.Carrier = o.OptionText;
                        }
                    }
                }
                else
                {
                    // There is a possability the carrier will come in as the abbr, not the text.
                    //       We want the text in this location.
                    ML.Carrier = GetQuestionText(ML.OptionCarrierID);
                }
                #endregion
                #region Manufacturer
                //xID = -1;
                if (ML.OptionManufacturerID == null || ML.OptionManufacturerID < 1)
                {
                    if (ML.Manufacturer.Length > 0) { 
                        //xID = GetQuestionOptionID("Manufacturer", ML.Manufacturer); ML.OptionManufacturerID = xID;
                        o = GetQuestionRecord("Manufacturer", ML.Manufacturer);
                        if (o != null)
                        {
                            ML.OptionManufacturerID = o.OptionID;
                            ML.Manufacturer = o.OptionText;
                        }
                    }
                }
                else
                {
                    // There is a possability the carrier will come in as the abbr, not the text.
                    //       We want the text in this location.
                    ML.Manufacturer = GetQuestionText(ML.OptionManufacturerID);
                }
                #endregion
                #region Model
                //xID = -1;
                if (ML.OptionModelID == null || ML.OptionModelID < 1)
                {
                    if (ML.Model.Length > 0) { 
                        //xID = GetQuestionOptionID("Model", ML.Model); ML.OptionModelID = xID;
                        o = GetQuestionRecord("Model", ML.Model);
                        if (o != null)
                        {
                            ML.OptionModelID = o.OptionID;
                            ML.Model = o.OptionText;
                        }
                    }
                }
                else
                {
                    // There is a possability the carrier will come in as the abbr, not the text.
                    //       We want the text in this location.
                    ML.Model = GetQuestionText(ML.OptionModelID);
                }
                #endregion
                #region Colour
                //xID = -1;
                if (ML.OptionColourID == null || ML.OptionColourID < 1)
                {
                    if (ML.Colour.Length > 0) { 
                        //xID = GetQuestionOptionID("Colour", ML.Colour); ML.OptionColourID = xID;
                        o = GetQuestionRecord("Colour", ML.Colour);
                        if (o != null)
                        {
                            ML.OptionColourID = o.OptionID;
                            ML.Colour = o.OptionText;
                        }
                    }
                }
                else
                {
                    // There is a possability the carrier will come in as the abbr, not the text.
                    //       We want the text in this location.
                    ML.Colour = GetQuestionText(ML.OptionColourID);
                }
                #endregion
                if (ML.OptionCarrierID == null || ML.OptionCarrierID < 1 || ML.OptionManufacturerID == null || ML.OptionManufacturerID < 1 || ML.OptionModelID == null || ML.OptionModelID < 1 || ML.OptionColourID == null || ML.OptionColourID < 1)
                {
                    { return string.Format("Error: Invalid Carrier({0}/{4}), Manufacturer({1}/{5}), Model({2}/{6}), or Colour Code({3}/{7})", ML.OptionCarrierID.ToString(), ML.OptionManufacturerID.ToString(), ML.OptionModelID.ToString(), ML.OptionColourID.ToString(), ML.Carrier, ML.Manufacturer, ML.Model, ML.Colour); }
                }

                var existing = (from q in ctx.MasterCarrierManufacturerLookups
                                where q.OptionCarrierID == ML.OptionCarrierID &&
                                      q.OptionColourID == ML.OptionColourID &&
                                      q.OptionManufacturerID == ML.OptionManufacturerID &&
                                      q.OptionModelID == ML.OptionModelID
                                select q).FirstOrDefault();
                if (existing != null)
                {
                    ML.StatusID = existing.StatusID;
                    ML.MasterCarrierManufacturerLookupID = existing.MasterCarrierManufacturerLookupID;
                    ML.LastUpdateDate = existing.LastUpdateDate;
                    ML.LastUpdateUser = existing.LastUpdateUser;
                    ML.CreateDate = existing.CreateDate;
                    ML.CreateUser = existing.CreateUser;
                    return "Updated:" + UpdateMasterCarrierManufacturerLookup(ML);
                }
                else
                {
                    ML.StatusID = GetMasterCarrierManufacturerLookupStatusID("Active");
                    ML.LastUpdateDate = DateTime.Now;
                    ML.LastUpdateUser = UserName;
                    ML.CreateDate = DateTime.Now;
                    ML.CreateUser = UserName;
                    ctx.MasterCarrierManufacturerLookups.InsertOnSubmit(ML);
                    ctx.SubmitChanges();
                    return "Inserted:" + ML.MasterCarrierManufacturerLookupID.ToString();
                }
            }
        }
