        public string TranslateTaggedText(decimal ReceiveDetailID, string Text)
        {
            ReceiveDetailManager rdm = new ReceiveDetailManager(UserName);
            clsLinqDataContext ctx = rdm.GetDataContext(UserName);
            string rString = Text;
            string tagname = "";
            string Translatedtagname = "";

            int sLoc = rString.IndexOf('%') + 1;
            int eLoc = rString.IndexOf('%', sLoc);
            while (sLoc > 0)
            {
                tagname = rString.Substring(sLoc, eLoc - sLoc);
                if (tagname.Length == 0) { Translatedtagname = ""; }
                else { Translatedtagname = rdm.GetReceiveDetailItem_DataElement(ctx, ReceiveDetailID, tagname); }

                rString = rString.Replace("%" + tagname + "%", Translatedtagname);
                sLoc = rString.IndexOf('%') + 1;
                eLoc = rString.IndexOf('%', sLoc);
            }
            return rString;
        }


