        [DataObjectMethod(DataObjectMethodType.Update)]
        public string UpdateMasterCarrierManufacturerLookup(MasterCarrierManufacturerLookup ML)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                Option o = null;
                bool KeyUpdate = false;
                var existing = (from q in ctx.MasterCarrierManufacturerLookups where q.MasterCarrierManufacturerLookupID == ML.MasterCarrierManufacturerLookupID select q).FirstOrDefault();
                if (existing != null)
                {
                    //decimal xID = -1;
                    if (ML.OptionCarrierID == null || ML.OptionCarrierID < 1)
                    {
                        if (ML.Carrier.Length > 0)
                        {
                            //xID = GetQuestionOptionID("Carrier", ML.Carrier); ML.OptionCarrierID = xID; KeyUpdate = true;
                            o = GetQuestionRecord("Carrier", ML.Carrier);
                            if (o != null)
                            {
                                ML.OptionCarrierID = o.OptionID;
                                ML.Carrier = o.OptionText;
                                KeyUpdate = true;
                            }
                        }
                    }
                    else
                    {
                        // There is a possability the carrier will come in as the abbr, not the text.
                        //       We want the text in this location.
                        ML.Carrier = GetQuestionText(ML.OptionCarrierID);
                    }
                    //xID = -1;
                    if (ML.OptionManufacturerID == null || ML.OptionManufacturerID < 1)
                    {
                        if (ML.Manufacturer.Length > 0) {
                            //xID = GetQuestionOptionID("Manufacturer", ML.Manufacturer); ML.OptionManufacturerID = xID; KeyUpdate = true;
                            o = GetQuestionRecord("Manufacturer", ML.Manufacturer);
                            if (o != null)
                            {
                                ML.OptionManufacturerID = o.OptionID;
                                ML.Manufacturer = o.OptionText;
                                KeyUpdate = true;
                            }
                        }
                    }
                    else
                    {
                        // There is a possability the carrier will come in as the abbr, not the text.
                        //       We want the text in this location.
                        ML.Manufacturer = GetQuestionText(ML.OptionManufacturerID);
                    }
                    //xID = -1;
                    if (ML.OptionModelID == null || ML.OptionModelID < 1)
                    {
                        if (ML.Model.Length > 0) {
                            //xID = GetQuestionOptionID("Model", ML.Model); ML.OptionModelID = xID; KeyUpdate = true;
                            o = GetQuestionRecord("Model", ML.Model);
                            if (o != null)
                            {
                                ML.OptionModelID = o.OptionID;
                                ML.Model = o.OptionText;
                                KeyUpdate = true;
                            }
                        }
                    }
                    else
                    {
                        // There is a possability the carrier will come in as the abbr, not the text.
                        //       We want the text in this location.
                        ML.Model = GetQuestionText(ML.OptionModelID);
                    }
                    //xID = -1;
                    if (ML.OptionColourID == null || ML.OptionColourID < 1)
                    {
                        if (ML.Colour.Length > 0) { 
                            //xID = GetQuestionOptionID("Colour", ML.Colour); ML.OptionColourID = xID; KeyUpdate = true;
                            o = GetQuestionRecord("Colour", ML.Colour);
                            if (o != null)
                            {
                                ML.OptionColourID = o.OptionID;
                                ML.Colour = o.OptionText;
                                KeyUpdate = true;
                            }
                        }
                    }
                    else
                    {
                        // There is a possability the carrier will come in as the abbr, not the text.
                        //       We want the text in this location.
                        ML.Colour = GetQuestionText(ML.OptionColourID);
                    }
                    if (ML.OptionCarrierID == null || ML.OptionCarrierID < 1 || ML.OptionManufacturerID == null || ML.OptionManufacturerID < 1 || ML.OptionModelID == null || ML.OptionModelID < 1 || ML.OptionColourID == null || ML.OptionColourID < 1)
                    { return string.Format("Error: Invalid Carrier({0}/{4}), Manufacturer({1}/{5}), Model({2}/{6}), or Colour Code({3}/{7})", ML.OptionCarrierID.ToString(), ML.OptionManufacturerID.ToString(), ML.OptionModelID.ToString(), ML.OptionColourID.ToString(), ML.Carrier, ML.Manufacturer, ML.Model, ML.Colour); }

                    if (KeyUpdate == true)
                    {
                        // if the Key was updated, we need to make sure there is not another out there already.
                        var anotherexist = (from q in ctx.MasterCarrierManufacturerLookups
                                            where q.MasterCarrierManufacturerLookupID != ML.MasterCarrierManufacturerLookupID
                                               && q.OptionCarrierID == ML.OptionCarrierID
                                               && q.OptionManufacturerID == ML.OptionManufacturerID
                                               && q.OptionModelID == ML.OptionModelID
                                               && q.OptionColourID == ML.OptionColourID
                                            select q).FirstOrDefault();
                        if (anotherexist != null) { return string.Format("Error: There is already a record out there with the Key Combo you are trying to change this one to. Record Not Updated"); }
                    }
                    existing.Bar_Flip = ML.Bar_Flip;
                    existing.Carrier = ML.Carrier;
                    existing.CDMA_HSPA = ML.CDMA_HSPA;
                    existing.Colour = ML.Colour;
                    existing.Condition = ML.Condition;
                    existing.Description = ML.Description;
                    existing.Device_Handset = ML.Device_Handset;
                    existing.Manufacturer = ML.Manufacturer;
                    existing.Model = ML.Model;
                    existing.Unit_OS = ML.Unit_OS;

                    existing.OptionCarrierID = ML.OptionCarrierID;
                    existing.OptionColourID = ML.OptionColourID;
                    existing.OptionManufacturerID = ML.OptionManufacturerID;
                    existing.OptionModelID = ML.OptionModelID;
                    existing.Retire = ML.Retire;
                    existing.SKU = ML.SKU;

                    existing.SKU_B = ML.SKU_B;
                    existing.SKU_C = ML.SKU_C;
                    existing.SKU_Loaner = ML.SKU_Loaner;

                    existing.UPC = ML.UPC;
                    existing.UPC_2 = ML.UPC_2;
                    existing.UPC_3 = ML.UPC_3;
                    existing.WarrantyStickerPlacement = ML.WarrantyStickerPlacement;
                    existing.NickName = ML.NickName;
                    existing.LastUpdateDate = DateTime.Now;
                    existing.LastUpdateUser = UserName;
                    ctx.SubmitChanges();
                    return "Updated:" + existing.MasterCarrierManufacturerLookupID.ToString();
                }
                return "Error:Record Does not exist for update";
            }
        }

