        private static Option ScanKeySearch(string QuestionName, string SearchKey, clsLinqDataContext ctx)
        {
            var OptionList = (from x in ctx.Options
                              where x.Question.Name == QuestionName && (x.Name == SearchKey || x.ScanKey == SearchKey || x.OptionText == SearchKey)
                              orderby x.Sequence
                              select x).FirstOrDefault();
            return OptionList;
        }
