        public string BuildSKU(decimal ManufacturerID, decimal ModelID, decimal CarrierID, decimal ColourID)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                Option Manufacturer = ctx.Options.FirstOrDefault(x => x.OptionID == ManufacturerID);
                Option Model = ctx.Options.FirstOrDefault(x => x.OptionID == ModelID);
                Option Carrier = ctx.Options.FirstOrDefault(x => x.OptionID == CarrierID);
                Option Colour = ctx.Options.FirstOrDefault(x => x.OptionID == ColourID);
                if (Manufacturer == null || Model == null || Carrier == null || Colour == null)
                {
                    return "ERROR";
                }
                return Manufacturer.Name + Model.Name + Carrier.Name + Colour.Name;

            }
