        private bool isValueThere(List<PairIDValue> data, decimal Value)
        {
            foreach (PairIDValue i in data)
            {
                if (i.ID == Value) { return true; }
            }
            return false;
        }
        public List<PairIDValue> GetManufacturerListRestricted(decimal CarrierID)
        {

            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                List<PairIDValue> data = new List<PairIDValue>();
                var d = from x in ctx.vwMasterCarrierManufacturerSKUs
                        where x.CarrierID == CarrierID
                        select x;
                foreach (vwMasterCarrierManufacturerSKU r in d.OrderBy(x => x.Manufacturer))
                {
                    PairIDValue y = new PairIDValue();
                    y.ID = (decimal)r.ManufacturerID;
                    y.Desc = r.Manufacturer;
                    if (isValueThere(data,y.ID) == false) { data.Add(y); }
                }
                return data;
            }
        }
