        public bool DeleteMasterSku(decimal MasterSkuID)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                //MasterSKU SKU = ctx.MasterSKUs.FirstOrDefault(x => x.MasterSKUID != KeyID && x.ManufacturerID == ManufacturerID && x.ModelID == ModelID && x.CarrierID == CarrierID && x.ColourID == ColourID);
                MasterSKU SKU = ctx.MasterSKUs.FirstOrDefault(x => x.MasterSKUID == MasterSkuID);
                if (SKU == null) { return false; }
                MasterSKUStatus st = ctx.MasterSKUStatus.FirstOrDefault(x => x.Status.ToUpper() == "DELETED");
                if (st == null) { return false; }
                SKU.StatusID = st.MasterSKUStatusID;
                SKU.LastUpdateDate = DateTime.Now;
                SKU.LastUpdateUser = UserName;
                ctx.SubmitChanges();
                return true;
            }
        }
        public bool UpdateMasterSku(MasterSKU sku)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                MasterSKU SKU = ctx.MasterSKUs.FirstOrDefault(x => x.MasterSKUID == sku.MasterSKUID);
                if (SKU == null) { return false; }
                SKU.StatusID = sku.StatusID;
                SKU.CarrierID = sku.CarrierID;
                SKU.ManufacturerID = sku.ManufacturerID;
                SKU.ModelID = sku.ModelID;
                SKU.ColourID = sku.ColourID;
                if (sku.SKU.Length > 25) { SKU.SKU = sku.SKU.Substring(0, 25); }
                else { SKU.SKU = sku.SKU; }
                SKU.LastUpdateDate = DateTime.Now;
                SKU.LastUpdateUser = UserName;
                ctx.SubmitChanges();
                return true;
            }
        }
        public bool AddMasterSku(MasterSKU sku)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                MasterSKU SKU = ctx.MasterSKUs.FirstOrDefault(x => x.CarrierID == sku.CarrierID && x.ManufacturerID == sku.ManufacturerID && x.ModelID == sku.ModelID && x.ColourID == sku.ColourID);
                if (SKU != null) { return false; }
                SKU = new MasterSKU();
                SKU.StatusID = sku.StatusID;
                SKU.CarrierID = sku.CarrierID;
                SKU.ManufacturerID = sku.ManufacturerID;
                SKU.ModelID = sku.ModelID;
                SKU.ColourID = sku.ColourID;
                if (sku.SKU.Length > 25) { SKU.SKU = sku.SKU.Substring(0, 25); }
                else { SKU.SKU = sku.SKU; }
                SKU.CreateDate = DateTime.Now;
                SKU.CreateUser = UserName;
                SKU.LastUpdateDate = DateTime.Now;
                SKU.LastUpdateUser = UserName;
                ctx.MasterSKUs.InsertOnSubmit(SKU);
                ctx.SubmitChanges();
                return true;
            }
        }

