        [DataObjectMethod(DataObjectMethodType.Select)]
        public List<MasterCarrierManufacturerLookup> GetMasterManufacturerList_NoCarrier(string sCarrierID)
        {
            decimal CarrierID = -1;
            if (decimal.TryParse(sCarrierID, out CarrierID) == false) { CarrierID = -1; }

            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                if (CarrierID < 1)
                {
                    // We need a way to get distinct records (ManufacturerID)
                    var LookupList = ctx.MasterCarrierManufacturerLookups.GroupBy(p => p.Manufacturer).Select(g => g.First());
                    return LookupList.ToList();

                }
                else
                {
                    // this gets the first record grouped by Manufacturer
                    var LookupList = ctx.MasterCarrierManufacturerLookups.Where(x => x.OptionCarrierID == CarrierID).GroupBy(p => p.Manufacturer).Select(g => g.First());
                    return LookupList.ToList();
                }
            }
        }

        [DataObjectMethod(DataObjectMethodType.Select)]
        public List<MasterCarrierManufacturerLookup> GetMasterModelList_NoCarrier(string sCarrierID, string sManufacturerID)
        {
            decimal CarrierID = -1;
            decimal ManufacturerID = -1;
            if (decimal.TryParse(sCarrierID, out CarrierID) == false) { CarrierID = -1; }
            if (decimal.TryParse(sManufacturerID, out ManufacturerID) == false) { ManufacturerID = -1; }

            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {

                if (CarrierID < 1)
                {
                    // this gets the first record grouped by Manufacturer
                    var LookupList = ctx.MasterCarrierManufacturerLookups.Where(x => x.OptionManufacturerID == ManufacturerID).GroupBy(p => p.Model).Select(g => g.First());
                    // We need to take the above data and sort it via the option.model.sequence order.
                    // because the two tables are not "Linked" formally, I take the sequence, temporarily place that value in a field in order to sort by it.
                    foreach (MasterCarrierManufacturerLookup data in LookupList)
                    {
                        Option o = ctx.Options.FirstOrDefault(x => x.OptionID == data.OptionModelID);
                        data.LastUpdateUser = "000000" + data.Model;
                        if (o != null && o.OptionStatus.Status == "Active")
                        {
                            //data.LastUpdateUser = o.Sequence.ToString().PadLeft(6, '0') + data.Model;
                            //data.Model = data.Model;                                      // +"(" + o.Sequence.ToString() + ")";
                            data.LastUpdateUser = o.Sequence.ToString().PadLeft(6, '0') + o.OptionText;
                            data.Model = o.OptionText;                                       // +"(" + o.Sequence.ToString() + ")";
                        }
                    }
                    return LookupList.ToList();
                }
                else
                {
                    // this gets the first record grouped by Manufacturer
                    var LookupList = ctx.MasterCarrierManufacturerLookups.Where(x => x.OptionCarrierID == CarrierID && x.OptionManufacturerID == ManufacturerID).GroupBy(p => p.Model).Select(g => g.First());
                    // We need to take the above data and sort it via the option.model.sequence order.
                    // because the two tables are not "Linked" formally, I take the sequence, temporarily place that value in a field in order to sort by it.
                    foreach (MasterCarrierManufacturerLookup data in LookupList)
                    {
                        Option o = ctx.Options.FirstOrDefault(x => x.OptionID == data.OptionModelID);
                        data.LastUpdateUser = "000000" + data.Model;
                        if (o != null && o.OptionStatus.Status == "Active")
                        {
                            //data.LastUpdateUser = o.Sequence.ToString().PadLeft(6, '0') + data.Model;
                            //data.Model = data.Model;                                      // +"(" + o.Sequence.ToString() + ")";
                            data.LastUpdateUser = o.Sequence.ToString().PadLeft(6, '0') + o.OptionText;
                            data.Model = o.OptionText;                                       // +"(" + o.Sequence.ToString() + ")";
                        }
                    }
                    return LookupList.ToList();
                }
            }
        }

        [DataObjectMethod(DataObjectMethodType.Select)]
        public List<MasterCarrierManufacturerLookup> GetMasterManufacturerList(string sCarrierID)
        {
            decimal CarrierID = -1;
            if (decimal.TryParse(sCarrierID, out CarrierID) == false) { CarrierID = -1; }

            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                // this gets the first record grouped by Manufacturer
                var LookupList = ctx.MasterCarrierManufacturerLookups.Where(x => x.OptionCarrierID == CarrierID || CarrierID == -1).GroupBy(p => p.Manufacturer).Select(g => g.First());

                // We need to take the above data and sort it via the option.model.sequence order.
                // because the two tables are not "Linked" formally, I take the sequence, temporarily place that value in a field in order to sort by it.
                foreach (MasterCarrierManufacturerLookup data in LookupList)
                {
                    Option o = ctx.Options.FirstOrDefault(x => x.OptionID == data.OptionManufacturerID);
                    data.LastUpdateUser = "000000" + data.Manufacturer;
                    if (o != null && o.OptionStatus.Status == "Active")
                    {
                        //data.LastUpdateUser = o.Sequence.ToString().PadLeft(6, '0') + data.Model;
                        //data.Model = data.Model;                                      // +"(" + o.Sequence.ToString() + ")";
                        data.LastUpdateUser = o.Sequence.ToString().PadLeft(6, '0') + o.OptionText;
                        data.Model = o.OptionText;                                       // +"(" + o.Sequence.ToString() + ")";
                        data.Manufacturer = o.OptionText;                                // +"(" + o.Sequence.ToString() + ")";
                        data.SKU_C = o.ScanKey;
                    }
                }
                return LookupList.OrderBy(x => x.LastUpdateUser).ToList();
                //return LookupList.ToList();
            }
        }

