        private string SaveNew(clsLinqDataContext ctx, string msg)
        {
            //string po = "";
            //po = OrderNumber;
            //if (ctx.GetNextPurchaseOrderNumber(ref po);  Used when generating their own.
            // At this time, we should verify the OrderNumber is Unique. Otherwise we need to get rid of it.
            msg = "Error: Order not saved";
            if (ctx.IsOrderNumberOnFile(OrderNumber) == true)
            {
                log.SaveTimeLogSalesOrder(-1, "SalesOrderSaveNew", -1, OrderNumber + ":" + CustomerPO + ": ERROR: Sales Order Number already on file.");
                msg = "Error: Sales Order Number already on file. (" + OrderNumber + ")";
                return msg;
            }
            //if (TaxRate <= 0)
            //{
            //    log.SaveTimeLogSalesOrder(-1, "SalesOrderSaveNew", -1, OrderNumber + ":" + CustomerPO + ": ERROR: Sales Tax Required.");
            //    msg = "Error: Sales Tax Required.";
            //    return msg;
            //}
            log.SaveTimeLogSalesOrder(-1, "SalesOrderSaveNew", -1, OrderNumber + ":" + CustomerPO + ": Start setting up header details");
            #region Setup Header Details
            OrderHeader OH = new OrderHeader();
            OH.ProjectID = ProjectID;
            ///  This is set down where i  have a ctx.    OH.OrderNumber = OrderNumber; 
            ///  
            OH.OrderNumber = OrderNumber;
            OH.Terms = Terms;
            OH.RequestUser = RequestUser;
            OH.CustomerPO = CustomerPO;
            OH.MiscReference = MiscReference;
            OH.WayBillNumber = WaybillNumber;
            OH.ProjectTag = ProjectTag;
            OH.MiscDesc = MiscDesc;
            OH.StatusID = GetOrderStatusID(ctx, "New");
            OH.OrderDate = DateTime.Now;
            OH.LastUpdateDate = DateTime.Now;
            OH.LastUpdateUser = UserName;
            OH.CreateDate = DateTime.Now;
            OH.CreateUser = UserName;
            OH.PostPaid = PostPaid;
            OH.Paid = Paid;
            OH.DeliveryNote = DeliveryNote;
            OH.InternalNote = InternalNote;
            OH.TaxRate = TaxRate;
            OH.Tax = Tax;
            OH.OrderType = OrderType;
            OH.Currency = Currency;
            OH.Freight = Freight;

            OrderCompany OCClient = new OrderCompany();
            OCClient.Name = "";
            OCClient.OrderHeaderID = ClientCompany.OrderHeaderID;
            OCClient.OrderCompanyID = ClientCompany.OrderCompanyID;
            OCClient.ClientLocationID = ClientCompany.ClientLocationID;
            OCClient.AddressLine1 = ClientCompany.AddressLine1;
            OCClient.AddressLine2 = ClientCompany.AddressLine2;
            OCClient.City = ClientCompany.City;
            OCClient.CompanyName = ClientCompany.CompanyName;
            OCClient.ContactName = ClientCompany.ContactName;
            OCClient.CompanyType = ClientCompany.CompanyType;
            OCClient.EmailAddress = ClientCompany.EmailAddress;
            OCClient.FaxNumber = ClientCompany.FaxNumber;
            OCClient.Notes = ClientCompany.Notes;
            OCClient.PhoneNumber = ClientCompany.PhoneNumber;
            OCClient.PostalCode = ClientCompany.PostalCode;
            OCClient.StateOrProvince = ClientCompany.StateOrProvince;
            OCClient.Country = ClientCompany.Country;
            OCClient.LastUpdateDate = DateTime.Now;
            OCClient.LastUpdateUser = UserName;
            OCClient.CreateDate = DateTime.Now;
            OCClient.CreateUser = UserName;
            OH.OrderCompanies.Add(OCClient);

            OrderCompany OCShip = new OrderCompany();
            OCShip.Name = "";
            OCShip.ClientLocationID = ShipToCompany.ClientLocationID;
            OCShip.AddressLine1 = ShipToCompany.AddressLine1;
            OCShip.AddressLine2 = ShipToCompany.AddressLine2;
            OCShip.City = ShipToCompany.City;
            OCShip.CompanyName = ShipToCompany.CompanyName;
            OCShip.ContactName = ShipToCompany.ContactName;
            OCShip.CompanyType = ShipToCompany.CompanyType;
            OCShip.EmailAddress = ShipToCompany.EmailAddress;
            OCShip.FaxNumber = ShipToCompany.FaxNumber;
            OCShip.Notes = ShipToCompany.Notes;
            OCShip.PhoneNumber = ShipToCompany.PhoneNumber;
            OCShip.PostalCode = ShipToCompany.PostalCode;
            OCShip.StateOrProvince = ShipToCompany.StateOrProvince;
            OCShip.Country = ShipToCompany.Country;
            OCShip.LastUpdateDate = DateTime.Now;
            OCShip.LastUpdateUser = UserName;
            OCShip.CreateDate = DateTime.Now;
            OCShip.CreateUser = UserName;
            OH.OrderCompanies.Add(OCShip);
            #endregion
            #region Add Line Detail
            log.SaveTimeLogSalesOrder(-1, "SalesOrderSaveNew", -1, OrderNumber + ":" + CustomerPO + ": Adding the detail line data to the class");
            foreach (clsOrderDetailLine od in _OrderDetailLines)
            {
                OrderDetail ol = OH.OrderDetails.FirstOrDefault(x => x.OrderDetailID == od.OrderDetailID);
                if (od.isDeleted == true && ol != null)
                {
                    //var odlist = ctx.OrderDetailReceiveDetails.Where(x => x.OrderDetailID == ol.OrderDetailID);
                    foreach (OrderDetailReceiveDetail rd in ol.OrderDetailReceiveDetails)
                    {
                        ctx.OrderDetailReceiveDetails.DeleteOnSubmit(rd);
                    }
                    DeleteReservedAvailableStock(ctx, ol);
                    ctx.OrderDetails.DeleteOnSubmit(ol);
                }
                else
                {
                    if (ol == null)
                    {
                        ol = new OrderDetail();
                        ol.OrderHeaderID = OrderHeaderID;
                        ol.CreateDate = DateTime.Now;
                        ol.CreateUser = UserName;
                        ol.QTYPacked = 0;
                    }
                    ol.Desc_Code = od.Desc_Code;
                    ol.Desc_Text = od.Desc_Text;
                    ol.QTY = od.QTY;
                    ol.PurchaseUnitPrice = od.UnitPrice;
                    ol.PurchaseUnitPrice = od.UnitPrice;
                    ol.PurchasePrice = od.Total;
                    ol.Discount = od.Discount;
                    ol.IFSSku = od.SKU;
                    ol.SKU = "";
                    ol.Note = od.Note;
                    ol.LastUpdateDate = DateTime.Now;
                    ol.LastUpdateUser = UserName;
                    ol.AvailableStock_OrderNumber = od.AvailableStock_OrderNumber;
                    ol.AvailableStock_QTY = od.AvailableStock_QTY;
                    ol.ReservedAvailableStockID = od.ReservedAvailableStockID;
                    ol.Manufacturer = od.Manufacturer;
                    ol.Model = od.Model;
                    ol.Carrier = od.Carrier;
                    ol.Colour = od.Colour;
                    ol.Grade = od.Grade;
                    ol.Condition = od.Condition;
                    ol.Location = "";
                    ol.Project_ID = "";
                    ol.Line_NO = od.Line_No;
                    ol.REL_NO = "";
                    ol.LOT_BATCH_NO = "";


      //,[IFSSKU]
      //,[Location]
      //,[Condition]
      //,[Project_ID]
      //,[Line_NO]
      //,[REL_NO]
      //,[LOT_BATCH_NO]


                    if (ol.OrderDetailID < 1) { OH.OrderDetails.Add(ol); }
                }
            }
            #endregion
            //string po = "";
            //ctx.GetNextPurchaseOrderNumber(ref po);

            //OrderNumber = po;
            //OH.OrderNumber = po;
            try
            {
                log.SaveTimeLogSalesOrder(-1, "SalesOrderSaveNew", -1, OrderNumber + ":" + CustomerPO + ": We are not ready to insert the order and submit changes");
                ctx.OrderHeaders.InsertOnSubmit(OH);
                log.SaveTimeLogSalesOrder(-1, "SalesOrderSaveNew", -1, OrderNumber + ":" + CustomerPO + ": inserted, ready to submit");
                ctx.SubmitChanges();
                log.SaveTimeLogSalesOrder(OH.OrderHeaderID, "SalesOrderSaveNew", -1, OrderNumber + ":" + CustomerPO + ": Submited.");

                log.SaveTimeLogSalesOrder(OH.OrderHeaderID, "SalesOrderSaveNew", -1, OrderNumber + ":" + CustomerPO + ": processing Detail lines.");
                foreach (OrderDetail x in OH.OrderDetails)
                {
                    // The guts of the procedure is remmed out. 
                    BalanceReservedAvailableStock(ctx, x);
                }
                log.SaveTimeLogSalesOrder(OH.OrderHeaderID, "SalesOrderSaveNew", -1, OrderNumber + ":" + CustomerPO + ": ready for last Submit.");
                ctx.SubmitChanges();
                OrderHeaderID = OH.OrderHeaderID;
                msg = "Added New";
                log.SaveTimeLogSalesOrder(OH.OrderHeaderID, "SalesOrderSaveNew", -1, OrderNumber + ":" + CustomerPO + ": Added New");
            }
            catch (Exception e)
            {
                log.SaveTimeLogSalesOrder(-1, "SalesOrderSaveNew", -1, OrderNumber + ":" + CustomerPO + ": ERROR:" + e.Message);
                msg = "Error:" + e.Message;
                return msg;
            }
            msg = "Success: New order saved";
            return msg;
        }
        private string SaveCurrent(string msg)
        {
            using (clsLinqDataContext ctx = new clsLinqDataContext())
            {
                return SaveCurrent(ctx, msg);
            }
        }
        private string SaveCurrent(clsLinqDataContext ctx, string msg)
        {
            msg = "Error: Order not saved";
            //if (TaxRate <= 0)
            //{
            //    log.SaveTimeLogSalesOrder(-1, "SalesOrderSaveNew", -1, OrderNumber + ":" + CustomerPO + ": ERROR: Sales Tax Required.");
            //    msg = "Error: Sales Tax Required.";
            //    return msg;
            //}
            OrderHeader orderHeader = ctx.OrderHeaders.FirstOrDefault(x => x.OrderHeaderID == OrderHeaderID);
            orderHeader.ProjectID = ProjectID;
            //orderHeader.OrderNumber = OrderNumber;        --- We stop users from changing it.
            orderHeader.CustomerPO = CustomerPO;
            orderHeader.RequestUser = RequestUser;
            orderHeader.MiscReference = MiscReference;
            orderHeader.WayBillNumber = WaybillNumber;
            orderHeader.ProjectTag = ProjectTag;
            orderHeader.MiscDesc = MiscDesc;
            orderHeader.LastUpdateDate = DateTime.Now;
            orderHeader.LastUpdateUser = UserName;
            orderHeader.Paid = Paid;
            orderHeader.PostPaid = PostPaid;
            orderHeader.InternalNote = InternalNote;
            orderHeader.DeliveryNote = DeliveryNote;
            orderHeader.Terms = Terms;
            orderHeader.OrderType = OrderType;
            orderHeader.Freight = Freight;
            orderHeader.Tax = Tax;
            orderHeader.TaxRate = TaxRate;
            orderHeader.Currency = Currency;

            if (orderHeader.OrderNumber.Length == 0)
            {
                string po = "";
                ctx.GetNextPurchaseOrderNumber(ref po);
                orderHeader.OrderNumber = po;
            }

            #region Client company Detail
            OrderCompany OCClient = orderHeader.OrderCompanies.FirstOrDefault(x => x.CompanyType == ClientCompany.CompanyType);
            if (OCClient == null)
            {
                OCClient = new OrderCompany();
                OCClient.OrderHeaderID = OrderHeaderID;
                OCClient.CreateDate = DateTime.Now;
                OCClient.CreateUser = UserName;
            }
            OCClient.Name = "";
            OCClient.ClientLocationID = ClientCompany.ClientLocationID;
            OCClient.AddressLine1 = ClientCompany.AddressLine1;
            OCClient.AddressLine2 = ClientCompany.AddressLine2;
            OCClient.City = ClientCompany.City;
            OCClient.CompanyName = ClientCompany.CompanyName;
            OCClient.ContactName = ClientCompany.ContactName;
            OCClient.CompanyType = ClientCompany.CompanyType;
            OCClient.EmailAddress = ClientCompany.EmailAddress;
            OCClient.FaxNumber = ClientCompany.FaxNumber;
            OCClient.Notes = ClientCompany.Notes;
            OCClient.PhoneNumber = ClientCompany.PhoneNumber;
            OCClient.PostalCode = ClientCompany.PostalCode;
            OCClient.StateOrProvince = ClientCompany.StateOrProvince;
            OCClient.Country = ClientCompany.Country;
            OCClient.LastUpdateDate = DateTime.Now;
            OCClient.LastUpdateUser = UserName;
            if (OCClient.OrderCompanyID < 1) { orderHeader.OrderCompanies.Add(OCClient); }


            OrderCompany OCShip = orderHeader.OrderCompanies.FirstOrDefault(x => x.CompanyType == ShipToCompany.CompanyType);
            if (OCShip == null)
            {
                OCShip = new OrderCompany();
                OCShip.OrderHeaderID = OrderHeaderID;
                OCShip.CreateDate = DateTime.Now;
                OCShip.CreateUser = UserName;
            }
            OCShip.Name = "";
            OCShip.ClientLocationID = ShipToCompany.ClientLocationID;
            OCShip.AddressLine1 = ShipToCompany.AddressLine1;
            OCShip.AddressLine2 = ShipToCompany.AddressLine2;
            OCShip.City = ShipToCompany.City;
            OCShip.CompanyName = ShipToCompany.CompanyName;
            OCShip.ContactName = ShipToCompany.ContactName;
            OCShip.CompanyType = ShipToCompany.CompanyType;
            OCShip.EmailAddress = ShipToCompany.EmailAddress;
            OCShip.FaxNumber = ShipToCompany.FaxNumber;
            OCShip.Notes = ShipToCompany.Notes;
            OCShip.PhoneNumber = ShipToCompany.PhoneNumber;
            OCShip.PostalCode = ShipToCompany.PostalCode;
            OCShip.StateOrProvince = ShipToCompany.StateOrProvince;
            OCShip.Country = ShipToCompany.Country;
            OCShip.LastUpdateDate = DateTime.Now;
            OCShip.LastUpdateUser = UserName;
            if (OCShip.OrderCompanyID < 1) { orderHeader.OrderCompanies.Add(OCShip); }
            #endregion
            #region Order Detail
            clsOrderDetailLineReceive odlr = new clsOrderDetailLineReceive();
            foreach (clsOrderDetailLine orderDetailLine in _OrderDetailLines)
            {
                OrderDetail orderDetail = orderHeader.OrderDetails.FirstOrDefault(x => x.OrderDetailID == orderDetailLine.OrderDetailID);
                if (orderDetailLine.isDeleted == true)
                {
                    if (orderDetail != null)
                    {
                        var odlist = ctx.OrderDetailReceiveDetails.Where(x => x.OrderDetailID == orderDetailLine.OrderDetailID);
                        foreach (OrderDetailReceiveDetail rd in odlist)
                        {
                            odlr.Delete(ctx, rd.OrderDetailReceiveDetailID);
                        }
                        DeleteReservedAvailableStock(ctx, orderDetail);
                        ctx.OrderDetails.DeleteOnSubmit(orderDetail);
                        // orderHeader.OrderDetails.Remove(orderDetail);
                    }
                }
                else
                {
                    if (orderDetail == null)
                    {
                        orderDetail = new OrderDetail();
                        orderDetail.OrderHeaderID = OrderHeaderID;
                        orderDetail.CreateDate = DateTime.Now;
                        orderDetail.CreateUser = UserName;
                        orderDetail.AvailableStock_OrderNumber = orderDetailLine.AvailableStock_OrderNumber;
                        orderDetail.AvailableStock_QTY = orderDetailLine.AvailableStock_QTY;
                        orderDetail.ReservedAvailableStockID = orderDetailLine.ReservedAvailableStockID;
                        orderDetail.QTYPacked = 0;
                    }
                    orderDetail.Desc_Code = orderDetailLine.Desc_Code;
                    orderDetail.Desc_Text = orderDetailLine.Desc_Text;
                    orderDetail.QTY = orderDetailLine.QTY;
                    orderDetail.SKU = orderDetailLine.SKU;
                    orderDetail.QTYPacked = orderDetailLine.QTYPacked;
                    orderDetail.PurchaseUnitPrice = orderDetailLine.UnitPrice;
                    orderDetail.LastUpdateDate = DateTime.Now;
                    orderDetail.Note = orderDetailLine.Note;
                    orderDetail.Manufacturer = orderDetailLine.Manufacturer;
                    orderDetail.Model = orderDetailLine.Model;
                    orderDetail.Carrier = orderDetailLine.Carrier;
                    orderDetail.Colour = orderDetailLine.Colour;
                    orderDetail.Grade = orderDetailLine.Grade;
                    orderDetail.IFSSku = orderDetailLine.IFSSKU;
                    orderDetail.Location = orderDetailLine.Location;
                    orderDetail.Condition = orderDetailLine.Condition;
                    orderDetail.PurchasePrice = orderDetailLine.Total;                  //orderDetail.QTY * orderDetail.PurchaseUnitPrice;
                    orderDetail.Discount = orderDetailLine.Discount;


                    if (orderDetailLine.UserName == null) { orderDetail.LastUpdateUser = UserName; } else { orderDetail.LastUpdateUser = orderDetailLine.UserName; }
                    foreach (clsOrderDetailLineReceive orderDetailLineReceive in orderDetailLine._OrderDetailReceiveLines)
                    {
                        OrderDetailReceiveDetail orderDetailReceiveDetail = orderDetail.OrderDetailReceiveDetails.FirstOrDefault(x => x.OrderDetailReceiveDetailID == orderDetailLineReceive.OrderDetailReceiveDetailID);
                        if (orderDetailLineReceive.isDeleted == true)
                        {
                            if (orderDetailReceiveDetail != null)
                            {
                                odlr.Delete(ctx, orderDetailReceiveDetail.OrderDetailReceiveDetailID);
                            }
                        }
                        else
                        {
                            if (orderDetailReceiveDetail == null)
                            {
                                orderDetailReceiveDetail = new OrderDetailReceiveDetail();
                                orderDetailReceiveDetail.CreateDate = DateTime.Now;
                                orderDetailReceiveDetail.CreateUser = UserName;
                            }
                            orderDetailReceiveDetail.ESN = orderDetailLineReceive.ESN;
                            orderDetailReceiveDetail.OrderDetailID = orderDetailLineReceive.OrderDetailID;
                            orderDetailReceiveDetail.ReceiveDetailID = orderDetailLineReceive.ReceiveDetailID;
                            orderDetailReceiveDetail.SKU = orderDetailLineReceive.SKU;
                            orderDetailReceiveDetail.Message = orderDetailLineReceive.Message;
                            orderDetailReceiveDetail.LastUpdateDate = DateTime.Now;
                            if (orderDetailReceiveDetail.OrderDetailReceiveDetailID < 1)
                            {
                                orderDetail.OrderDetailReceiveDetails.Add(orderDetailReceiveDetail);
                            }
                        }
                    }


                    if (orderDetail.OrderDetailID < 1) { orderHeader.OrderDetails.Add(orderDetail); }
                }
            }
            #endregion
            ctx.SubmitChanges();

            msg = "Success: Order Saved";
            return msg;
        }


        private Client GetClientFromOrderID(clsLinqDataContext ctx, decimal OrderDetailID)
        {
            OrderDetail OD = ctx.OrderDetails.FirstOrDefault(x => x.OrderDetailID == OrderDetailID);
            OrderHeader OH = ctx.OrderHeaders.FirstOrDefault(x => x.OrderHeaderID == OD.OrderHeaderID);
            OrderCompany OC = ctx.OrderCompanies.FirstOrDefault(x => x.OrderHeaderID == OH.OrderHeaderID && x.CompanyType == "Client");
            ClientLocation CL = ctx.ClientLocations.FirstOrDefault(x => x.ClientLocationID == OC.ClientLocationID);
            Client C = ctx.Clients.FirstOrDefault(x => x.ClientID == CL.ClientID);
            return C;
        }

        public decimal GetOrderStatusID(string Value)
        {
            using (clsLinqDataContext ctx = new clsLinqDataContext())
            {
                return GetOrderStatusID(ctx, Value);
            }
        }
        public decimal GetOrderStatusID(clsLinqDataContext ctx, string Value)
        {
            OrderStatus OS = ctx.OrderStatus.FirstOrDefault(x => x.Status == Value);
            if (OS != null)
            {
                return OS.OrderStatusID;
            }
            return 2;    // NEW
        }

        public decimal CalculateSubTotal()
        {
            decimal SubTotal = 0;
            foreach (clsOrderDetailLine line in OrderDetailLines)
            {
                SubTotal += line.QTY * line.UnitPrice;
            }
            return SubTotal;

        }
        public decimal CalculateTax()
        {
            Tax = TaxRate * CalculateSubTotal();
            return Tax;
        }
    }


    public class clsOrderHeaderCompany
    {
        public decimal OrderCompanyID { get; set; }
        public decimal OrderHeaderID { get; set; }
        public decimal ClientLocationID { get; set; }
        public string CompanyName { get; set; }
        public string ContactName { get; set; }
        public string AddressLine1 { get; set; }
        public string AddressLine2 { get; set; }
        public string City { get; set; }
        public string StateOrProvince { get; set; }
        public string Country { get; set; }
        public string PostalCode { get; set; }
        public string PhoneNumber { get; set; }
        public string FaxNumber { get; set; }
        public string Notes { get; set; }
        public string CompanyType { get; set; }
        public string EmailAddress { get; set; }
        public string UserName { get; set; }

        public clsOrderHeaderCompany()
        {
        }
        public void LoadCompany(string companytype, decimal orderheaderID)
        {
            using (clsLinqDataContext ctx = new clsLinqDataContext())
            {
                OrderCompany OC = ctx.OrderCompanies.FirstOrDefault(x => x.CompanyType == companytype && x.OrderHeaderID == orderheaderID);
                if (OC == null)
                {
                    OrderCompanyID = -1;
                    OrderHeaderID = orderheaderID;
                    CompanyType = companytype;
                }
                else
                {
                    OrderCompanyID = -1;
                    OrderHeaderID = -1;
                    if (OC.ClientLocationID == null)
                    {
                        ClientLocationID = -1;
                    }
                    else
                    {
                        ClientLocationID = (decimal)OC.ClientLocationID;
                    }
                    OrderCompanyID = OC.OrderCompanyID;
                    OrderHeaderID = OC.OrderHeaderID;
                    CompanyType = OC.CompanyType;
                    EmailAddress = OC.EmailAddress;
                    CompanyName = OC.CompanyName;
                    ContactName = OC.ContactName;
                    AddressLine1 = OC.AddressLine1;
                    AddressLine2 = OC.AddressLine2;
                    City = OC.City;
                    StateOrProvince = OC.StateOrProvince;
                    Country = OC.Country;
                    PostalCode = OC.PostalCode;
                    PhoneNumber = OC.PhoneNumber;
                    FaxNumber = OC.FaxNumber;
                    Notes = OC.Notes;
                }
            }
        }
        public void LoadCompanyFromClientLocation(string ScanKey)
        {
            using (clsLinqDataContext ctx = new clsLinqDataContext())
            {
                ClientLocation ClientLocation = ctx.ClientLocations.FirstOrDefault(x => x.ScanKey == ScanKey);
                if (ClientLocation != null)
                {
                    OrderCompanyID = -1;
                    OrderHeaderID = -1;
                    ClientLocationID = ClientLocation.ClientLocationID;
                    CompanyName = ClientLocation.CompanyName;
                    ContactName = ClientLocation.ContactName;
                    AddressLine1 = ClientLocation.AddressLine1;
                    AddressLine2 = ClientLocation.AddressLine2;
                    City = ClientLocation.City;
                    StateOrProvince = ClientLocation.StateOrProvince;
                    Country = ClientLocation.Country; ;
                    PostalCode = ClientLocation.PostalCode;
                    PhoneNumber = ClientLocation.PhoneNumber;
                    FaxNumber = ClientLocation.FaxNumber;
                    Notes = ClientLocation.Notes;
                }
            }
        }
        public void LoadCompanyFromClientLocation(decimal ClientLocationID)
        {
            using (clsLinqDataContext ctx = new clsLinqDataContext())
            {
                ClientLocation ClientLocation = ctx.ClientLocations.FirstOrDefault(x => x.ClientLocationID == ClientLocationID);
                if (ClientLocation != null)
                {
                    OrderCompanyID = -1;
                    OrderHeaderID = -1;
                    ClientLocationID = ClientLocation.ClientLocationID;
                    CompanyName = ClientLocation.CompanyName;
                    ContactName = ClientLocation.ContactName;
                    AddressLine1 = ClientLocation.AddressLine1;
                    AddressLine2 = ClientLocation.AddressLine2;
                    City = ClientLocation.City;
                    StateOrProvince = ClientLocation.StateOrProvince;
                    Country = "";
                    PostalCode = ClientLocation.PostalCode;
                    Country = ClientLocation.Country; ;
                    PhoneNumber = ClientLocation.PhoneNumber;
                    FaxNumber = ClientLocation.FaxNumber;
                    Notes = ClientLocation.Notes;
                }
            }
        }

        public string AddressString
        {
            get
            {
                string rText = CompanyName;
                if (rText.Length > 0) { rText += Environment.NewLine; }
                if (AddressLine1.Length > 0) { rText = string.Format("{0}{1}{2}", rText, AddressLine1, Environment.NewLine); }
                if (AddressLine2.Length > 0) { rText = string.Format("{0}{1}{2}", rText, AddressLine2, Environment.NewLine); }
                if (City.Length > 0) { rText = string.Format("{0}{1}{2}", rText, City, Environment.NewLine); }
                if (StateOrProvince.Length > 0 && Country.Length > 0) { rText = string.Format("{0}{1}{2}, {3}", rText, StateOrProvince, Country, Environment.NewLine); }
                if (StateOrProvince.Length > 0 && Country.Length == 0) { rText = string.Format("{0}{1}{2}", rText, StateOrProvince, Environment.NewLine); }
                if (StateOrProvince.Length == 0 && Country.Length > 0) { rText = string.Format("{0}{1}{2}", rText, Country, Environment.NewLine); }
                if (PostalCode.Length > 0) { rText = string.Format("{0}{1}{2}", rText, PostalCode, Environment.NewLine); }
                return rText; 
            }
        }

    }
