        public void LoadReceiveDetail()
        {
            using (clsLinqDataContext ctx = new clsLinqDataContext())
            {
                var RD = from x in ctx.OrderDetailReceiveDetails
                         where x.OrderDetailID == OrderDetailID
                         orderby x.SKU, x.ESN
                         select x;
                QTYPacked = 0;
                QTYInventoryLinked = 0;
                foreach (OrderDetailReceiveDetail rd in RD)
                {
                    clsOrderDetailLineReceive rl = new clsOrderDetailLineReceive();
                    rl.ESN = rd.ESN;
                    rl.isDirty = false;
                    rl.OrderDetailID = rd.OrderDetailID;
                    rl.OrderDetailReceiveDetailID = rd.OrderDetailReceiveDetailID;
                    rl.ReceiveDetailID = rd.ReceiveDetailID;
                    rl.SKU = rd.SKU;
                    rl.UserName = UserName;
                    _OrderDetailReceiveLines.Add(rl);
                    if (rd.ReceiveDetailID != null && rd.ReceiveDetailID > 0) { QTYInventoryLinked++; }
                    QTYPacked++;
                }
            }
        }



    }
    public class clsOrderDetailLineReceive
    {
        public decimal OrderDetailReceiveDetailID { get; set; }
        public decimal OrderDetailID { get; set; }
        public decimal? ReceiveDetailID { get; set; }
        public bool isNew { get; set; }
        public bool isDirty { get; set; }
        public bool isDeleted { get; set; }
        public string ESN { get; set; }
        public string SKU { get; set; }
        public string UserName { get; set; }
        public string Message { get; set; }
        public clsOrderDetailLineReceive()
        {
            OrderDetailReceiveDetailID = -1;
            OrderDetailID = -1;
            ReceiveDetailID = null;
            ESN = "";
            SKU = "";
            Message = "";
            isNew = true;
            isDeleted = false;
            isDirty = false;
        }


        public bool Delete()
        {
            using (clsLinqDataContext ctx = new clsLinqDataContext())
            {
                return Delete(ctx);
            }
        }
        public bool Delete(clsLinqDataContext ctx)
        {
            OrderDetailReceiveDetail RD = ctx.OrderDetailReceiveDetails.FirstOrDefault(x => x.OrderDetailReceiveDetailID == OrderDetailReceiveDetailID);
            OrderDetail OD = RD.OrderDetail;
            if (RD != null)
            {
                //var rdpl = ctx.ReceiveDetailProcessLogs.Where(x => x.ReceiveDetailID == RD.ReceiveDetailID && x.Process.Name == "Shipped");
                //foreach (ReceiveDetailProcessLog pl in rdpl)
                //{
                //    ctx.ReceiveDetailProcessLogs.DeleteOnSubmit(pl);
                //}
                OD.QTYPacked += -1;
                ctx.OrderDetailReceiveDetails.DeleteOnSubmit(RD);
                ctx.SubmitChanges();
            }
            return true;
        }


        public bool Delete(clsLinqDataContext ctx, decimal OrderDetailReceiveDetailID)
        {
            OrderDetailReceiveDetail RD = ctx.OrderDetailReceiveDetails.FirstOrDefault(x => x.OrderDetailReceiveDetailID == OrderDetailReceiveDetailID);
            if (RD != null)
            {
                var rdpl = ctx.ReceiveDetailProcessLogs.Where(x => x.ReceiveDetailID == RD.ReceiveDetailID && x.Process.Name == "Shipped");
                foreach (ReceiveDetailProcessLog pl in rdpl)
                {
                    ctx.ReceiveDetailProcessLogs.DeleteOnSubmit(pl);
                }
                ctx.OrderDetailReceiveDetails.DeleteOnSubmit(RD);
            }
            return true;
        }


        public bool Save(clsLinqDataContext ctx)
        {
            //using (clsLinqDataContext ctx = new clsLinqDataContext())
            //{
            OrderDetailReceiveDetail RD = ctx.OrderDetailReceiveDetails.FirstOrDefault(x => x.OrderDetailReceiveDetailID == OrderDetailReceiveDetailID);
            if (RD == null)
            {
                // look to see if the ESN is already used. If there, stop...
                RD = new OrderDetailReceiveDetail();
                RD.OrderDetailID = OrderDetailID;
                RD.ReceiveDetailID = null;
                RD.CreateDate = DateTime.Now;
                RD.CreateUser = UserName;
            }
            RD.Message = Message;
            RD.ESN = ESN;
            RD.SKU = SKU;
            RD.LastUpdateDate = DateTime.Now;
            RD.LastUpdateUser = UserName;
            if (RD.OrderDetailReceiveDetailID < 1)
            {
                ctx.OrderDetailReceiveDetails.InsertOnSubmit(RD);
            }
            //ctx.SubmitChanges();
            return true;
            //}
        }

    }

