        void LockUser(string islocked)
        {
            MembershipUser usr = Membership.GetUser(UserName);
            if (usr != null)
            {
                if (islocked.Length > 0 && islocked.Substring(0, 1).ToUpper() == "Y")
                {
                    usr.IsApproved = false;
                    Membership.UpdateUser(usr);
                }
                else
                {
                    usr.IsApproved = true;
                    Membership.UpdateUser(usr);
                }
            }
        }



        public string CreateUser(string Password, string EmailAddress, string roles, string islocked)
        {
            try
            {
                MembershipUser mu = Membership.CreateUser(UserNameToAdd, Password, EmailAddress);
            }
            catch (MembershipCreateUserException ex)
            {
                return "Error:" + ex.Message;
            }
            // we need to add the new user to the User Table and assign any default user access stuff.
            AddToUserTable();
            AddToUserAccessTable_NoTableAccess();

            string[] roleList = roles.Split(new char[] { ',' }, StringSplitOptions.RemoveEmptyEntries);

            if (roleList != null)
            {
                foreach (string li in roleList)
                {
                    if (li.Length > 0 && Roles.RoleExists(li) == true && Roles.IsUserInRole(li) == false)
                        Roles.AddUserToRole(UserNameToAdd, li);
                }
            }
            LockUser(islocked);
            return "Added";
        }






