        public List<decimal> GetUserDefaultClientIDList(clsLinqDataContext ctx, string UserName)
        {
            List<decimal> clList = new List<decimal>();
            //if (UserRestrict.AllowGlobalSelect("Client", ctx) == true) { return -1; }
            UserTable ut = ctx.UserTables.FirstOrDefault(x => x.UserName == UserName);
            if (ut != null && ut.ClientLocationRestrictions != null && ut.ClientLocationRestrictions.Length > 0)
            {
                string[] scancodes = ut.ClientLocationRestrictions.ToUpper().Split(',');
                var cl = from x in ctx.ClientLocations
                         where scancodes.Contains(x.ScanKey.ToUpper())
                         select x;
                foreach (var c in cl)
                {
                    clList.Add(c.ClientLocationID);
                }
                // ClientLocation cl = ctx.ClientLocations.FirstOrDefault(x => x.ScanKey.ToUpper() == scancodes[0]);
                //if (cl != null)
                //{
                //    return cl.ClientLocationID;
                //}
                //List<UserAccessTable> actable = ctx.UserAccessTables.Where(x => x.UserTableID == ut.UserTableID && x.TableName == "Client" && x.AllowSelect).ToList();
                //if (actable.Count == 1) { return actable[0].AllowTableRecordID; }
            }
            return clList;
        }

        public string GetUserDefaultClientKey(string UserName)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                if (UserRestrict.AllowGlobalSelect("Client", ctx) == true) { return ""; }
                UserTable ut = ctx.UserTables.FirstOrDefault(x => x.UserName == UserName);
                if (ut != null)
                {
                    List<UserAccessTable> actable = ctx.UserAccessTables.Where(x => x.UserTableID == ut.UserTableID && x.TableName == "Client" && x.AllowSelect && x.AllowTableRecordID > 0).ToList();
                    if (actable.Count > 0)
                    {
                        ClientLocation cl = ctx.ClientLocations.FirstOrDefault(x => x.ClientLocationID == actable[0].AllowTableRecordID);
                        if (cl != null) { return cl.ScanKey; }
                    }
                }
                return "";
            }
        }
        public string GetUserValidClientKey(string UserName, string SourceClientKey)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                if (SourceClientKey.Length == 0) { return GetUserDefaultClientKey(UserName); }
                string rValue = SourceClientKey;
                UserTable ut = ctx.UserTables.FirstOrDefault(x => x.UserName == UserName);
                if (ut != null && ut.ClientLocationRestrictions != null && ut.ClientLocationRestrictions.Length > 0)
                {
                    rValue = "NOTVALIDXXX";  // If we find any client for this user, then we need to drop what they have 
                        string[] scancodes = ut.ClientLocationRestrictions.Split(',');
                        foreach (string s in scancodes)
                        {
                            if (s.ToUpper() == SourceClientKey.ToUpper())
                            {
                                return s;
                            }
                        }
                }
                return rValue;
            }
        }

