        public void AddToUserTable()
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                UserTable ut = ctx.UserTables.FirstOrDefault(x => x.UserName == UserNameToAdd);
                if (ut == null)
                {
                    ut = new UserTable();
                    ut.StatusID = 1;
                    ut.UserName = UserNameToAdd;
                    ut.ContactName = FriendlyName;
                    ut.Department = Department;
                    ut.MacroKey = "";
                    ut.ScanKey = "";
                    ut.LastUpdateDate = DateTime.Now;
                    ut.LastUpdateUser = UserName;
                    ut.CreateDate = DateTime.Now;
                    ut.CreateUser = UserName;
                    ut.ClientLocationRestrictions = ClientLocationRestriction;
                    ctx.UserTables.InsertOnSubmit(ut);
                    ctx.SubmitChanges();
                }
            }
        }
        public void AddToUserAccessTable_NoTableAccess()
        {
            string[] AllAccessTables = new string[] { "Question", "Answer", "Process", "BinLocation" };
            foreach (string table in AllAccessTables)
            {
                AddToUserAccessTable(table, -1, false, false, false, false, false);
            }
        }
        public void AddToUserAccessTable(string Table, decimal AllowTableRecordID, bool AllowSelect, bool AllowAdd, bool AllowUpdate, bool AllowDelete, bool AllowScan)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                UserTable ut = ctx.UserTables.FirstOrDefault(x => x.UserName == UserNameToAdd);
                if (ut == null)
                {
                    AddToUserTable();
                    ut = ctx.UserTables.FirstOrDefault(x => x.UserName == UserNameToAdd);
                }
                if (ut != null)
                {
                    if (AllowTableRecordID != -1) { AllowAdd = false; }     // We can only add at the global level (-1)
                    UserAccessTable uat = ctx.UserAccessTables.FirstOrDefault(x => x.UserTableID == ut.UserTableID && x.TableName == Table && x.AllowTableRecordID == AllowTableRecordID);
                    if (uat == null)
                    {
                        uat = new UserAccessTable();
                        uat.UserTableID = ut.UserTableID;
                        uat.TableName = Table;
                        uat.AllowTableRecordID = AllowTableRecordID;
                        uat.AllowSelect = AllowSelect;
                        uat.AllowAdd = AllowAdd;
                        uat.AllowUpdate = AllowUpdate;
                        uat.AllowScan = AllowScan;
                        uat.AllowDelete = AllowDelete;
                        uat.LastUpdateDate = DateTime.Now;
                        uat.LastUpdateUser = UserName;
                        uat.CreateDate = DateTime.Now;
                        uat.CreateUser = UserName;
                        ctx.UserAccessTables.InsertOnSubmit(uat);
                    }
                    else
                    {
                        uat.AllowSelect = AllowSelect;
                        uat.AllowAdd = AllowAdd;
                        uat.AllowUpdate = AllowUpdate;
                        uat.AllowScan = AllowScan;
                        uat.AllowDelete = AllowDelete;
                        uat.LastUpdateDate = DateTime.Now;
                        uat.LastUpdateUser = UserName;
                    }

                    ctx.SubmitChanges();
                }
                // we now need to add the UserAccess records.
            }
        }
        public void UpdateUserAccessTable(string Table, decimal AllowTableRecordID, bool AllowSelect, bool AllowAdd, bool AllowUpdate, bool AllowDelete, bool AllowScan)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                UserTable ut = ctx.UserTables.FirstOrDefault(x => x.UserName == UserNameToAdd);
                if (ut == null)
                {
                    AddToUserAccessTable_NoTableAccess();
                    ut = ctx.UserTables.FirstOrDefault(x => x.UserName == UserNameToAdd);
                }

                if (ut != null)
                {
                    if (AllowTableRecordID != -1) { AllowAdd = false; }     // We can only add at the global level (-1)
                    UserAccessTable uat = ctx.UserAccessTables.FirstOrDefault(x => x.UserTableID == ut.UserTableID && x.TableName == Table && x.AllowTableRecordID == AllowTableRecordID);
                    if (uat == null)
                    {
                        if (AllowAdd || AllowSelect || AllowDelete || AllowUpdate)
                        {
                            uat = new UserAccessTable();
                            uat.UserTableID = ut.UserTableID;
                            uat.TableName = Table;
                            uat.AllowTableRecordID = AllowTableRecordID;
                            uat.AllowSelect = AllowSelect;
                            uat.AllowAdd = AllowAdd;
                            uat.AllowUpdate = AllowUpdate;
                            uat.AllowScan = AllowScan;
                            uat.AllowDelete = AllowDelete;
                            uat.LastUpdateDate = DateTime.Now;
                            uat.LastUpdateUser = UserName;
                            uat.CreateDate = DateTime.Now;
                            uat.CreateUser = UserName;
                            ctx.UserAccessTables.InsertOnSubmit(uat);
                        }
                    }
                    else
                    {
                        if (AllowAdd || AllowSelect || AllowDelete || AllowUpdate)
                        {
                            uat.AllowSelect = AllowSelect;
                            uat.AllowAdd = AllowAdd;
                            uat.AllowUpdate = AllowUpdate;
                            uat.AllowScan = AllowScan;
                            uat.AllowDelete = AllowDelete;
                            uat.LastUpdateDate = DateTime.Now;
                            uat.LastUpdateUser = UserName;
                        }
                        else
                        {
                            ctx.UserAccessTables.DeleteOnSubmit(uat);
                        }
                    }
                    ctx.SubmitChanges();
                }
                // we now need to add the UserAccess records.
            }
        }
        public void CleanUpUserAccessTable(string Table)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                UserTable ut = ctx.UserTables.FirstOrDefault(x => x.UserName == UserNameToAdd);
                if (ut != null)
                {
                    IEnumerable<UserAccessTable> uat = from tab in ctx.UserAccessTables
                                                       where tab.UserTableID == ut.UserTableID &&
                                                           tab.TableName == Table && tab.AllowTableRecordID > 0
                                                           && tab.AllowAdd == false && tab.AllowDelete == false && tab.AllowScan == false && tab.AllowSelect == false && tab.AllowUpdate == false
                                                       select tab;
                    if (uat != null)
                    {
                        ctx.UserAccessTables.DeleteAllOnSubmit(uat);
                        ctx.SubmitChanges();
                    }
                }
                // we now need to add the UserAccess records.
            }
        }
