        public List<MasterTableAcccessList> GetMasterTableAccessList(string TableName, decimal ProjectID)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                var ut = ctx.GetMasterTableAccessList_ProjectID(UserNameToAdd, TableName, ProjectID);
                // RoleAccessControl rac = new RoleAccessControl(ctx, UserName);
                RoleAccessControl rac = new RoleAccessControl(ctx, UserNameToAdd);
                var rt = rac.GetRoleAccessList(TableName);
                var utlist = ut.ToList();
                utlist = utlist.Union(rt).ToList();
                return utlist.OrderBy(x => x.Sequence).ThenBy(x => x.Name).ToList();
            }
        }
