        public void UpdateRoleAccessTable(string Role, string Table, decimal AllowTableRecordID, bool AllowSelect, bool AllowAdd, bool AllowUpdate, bool AllowDelete, bool AllowScan)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                //UserTable ut = ctx.UserTables.FirstOrDefault(x => x.UserName == UserNameToAdd);
                //if (ut == null)
                //{
                //    AddToUserAccessTable_NoTableAccess();
                //    ut = ctx.UserTables.FirstOrDefault(x => x.UserName == UserNameToAdd);
                //}

                if (AllowTableRecordID != -1) { AllowAdd = false; }     // We can only add at the global level (-1)
                RoleAccessTable uat = ctx.RoleAccessTables.FirstOrDefault(x => x.Role == Role && x.TableName == Table && x.AllowTableRecordID == AllowTableRecordID);
                if (uat == null)
                {
                    if (AllowAdd || AllowSelect || AllowDelete || AllowUpdate)
                    {
                        uat = new RoleAccessTable();
                        uat.Role = Role;
                        uat.TableName = Table;
                        uat.AllowTableRecordID = AllowTableRecordID;
                        uat.AllowSelect = AllowSelect;
                        uat.AllowAdd = AllowAdd;
                        uat.AllowUpdate = AllowUpdate;
                        uat.AllowScan = AllowScan;
                        uat.AllowDelete = AllowDelete;
                        uat.LastUpdateDate = DateTime.Now;
                        uat.LastUpdateUser = UserName;
                        uat.CreateDate = DateTime.Now;
                        uat.CreateUser = UserName;
                        ctx.RoleAccessTables.InsertOnSubmit(uat);
                    }
                }
                else
                {
                    if (AllowAdd || AllowSelect || AllowDelete || AllowUpdate)
                    {
                        uat.AllowSelect = AllowSelect;
                        uat.AllowAdd = AllowAdd;
                        uat.AllowUpdate = AllowUpdate;
                        uat.AllowScan = AllowScan;
                        uat.AllowDelete = AllowDelete;
                        uat.LastUpdateDate = DateTime.Now;
                        uat.LastUpdateUser = UserName;
                    }
                    else
                    {
                        ctx.RoleAccessTables.DeleteOnSubmit(uat);
                    }
                }
                ctx.SubmitChanges();
                // we now need to add the UserAccess records.
            }
        }
        public void CleanUpRoleAccessTable(string Role, string Table)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                IEnumerable<RoleAccessTable> uat = from tab in ctx.RoleAccessTables
                                                   where tab.Role == Role &&
                                                       tab.TableName == Table && tab.AllowTableRecordID > 0
                                                       && tab.AllowAdd == false && tab.AllowDelete == false && tab.AllowScan == false && tab.AllowSelect == false && tab.AllowUpdate == false
                                                   select tab;
                if (uat != null)
                {
                    ctx.RoleAccessTables.DeleteAllOnSubmit(uat);
                    ctx.SubmitChanges();
                }
                // we now need to add the UserAccess records.
            }
        }
        public void DeleteUser()
        {

            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                UserTable ut = ctx.UserTables.FirstOrDefault(x => x.UserName == UserNameToAdd);
                if (ut != null)
                {
                    IQueryable<UserAccessTable> ops = from x in ctx.UserAccessTables where x.UserTableID == ut.UserTableID select x;
                    if (ops != null)
                    {
                        foreach (UserAccessTable op in ops)
                        {
                            ctx.UserAccessTables.DeleteOnSubmit(op);
                        }
                    }

                    ctx.UserTables.DeleteOnSubmit(ut);
                    ctx.SubmitChanges();
                }
            }
        }
    }

