        public GridDashboardReceiveDetail_Client(clsLinqDataContext ctx, ReceiveDetail rd, decimal ProjectClientPortalID, decimal ProjectClientRepairID)
        {
            ClientID = -1;
            ProcessName = "";
            CustomerComplaint = "";
            DiscrepencyCode = "";
            FaultCode = "";
            ExchangedIMEI = "";
            GMPMSC_ShipDate = "";
            isAuthorize = "";
            AuthorizedName = "";
            DeclinedName = "";
            AuthorizedDate = "";
            Dealer_ShipDate = "";
            Waybill = "";
            Courier = "";
            FeeEstimate = 0;
            FeeFreight = 0;
            FeeHST = 0;
            FeeTotal = 0;
            GMPIAUTXDone = "";
            ServiceRequestNumber = "";
            EQUSAN = "";
            CustomerName = "";

            ReceiveDetailClientSubmitted rdcs = (from x in ctx.ReceiveDetailClientSubmitteds
                                                 where x.ClientReceiveDetailID == rd.ReceiveDetailID || x.GMPIReceiveDetailID == rd.ReceiveDetailID
                                                 select x).FirstOrDefault();
            ReceiveDetail GMPIRD = null;
            if (rdcs != null)
            {
                if (rdcs.GMPIReceiveDetailID == rd.ReceiveDetailID)
                {
                    GMPIReceivedRD = rd;
                    GMPIReceiveDetailID = rd.ReceiveDetailID;
                    GMPIRD = (from x in ctx.ReceiveDetails
                              where x.ReceiveDetailID == rdcs.ClientReceiveDetailID
                              select x).FirstOrDefault();
                    if (GMPIRD != null) { ClientSubmittedRD = GMPIRD; ClientSubmittedReceiveDetailID = GMPIRD.ReceiveDetailID; }
                }
                else
                {
                    ClientSubmittedRD = rd;
                    ClientSubmittedReceiveDetailID = rd.ReceiveDetailID;
                    GMPIRD = (from x in ctx.ReceiveDetails
                              where x.ReceiveDetailID == rdcs.GMPIReceiveDetailID
                              select x).FirstOrDefault();
                    if (GMPIRD != null) { GMPIReceivedRD = GMPIRD; GMPIReceiveDetailID = GMPIRD.ReceiveDetailID; }
                }
            }
            else
            {
                if (rd.ProjectID == ProjectClientPortalID)
                {
                    ClientSubmittedReceiveDetailID = rd.ReceiveDetailID; ClientSubmittedRD = rd; GMPIReceivedRD = null; GMPIReceiveDetailID = -1;
                }
                else
                {
                    GMPIReceivedRD = rd; GMPIReceiveDetailID = rd.ReceiveDetailID; ClientSubmittedReceiveDetailID = -1; ClientSubmittedRD = null;
                }
            }
            ReceiveDetailManager rdm = new ReceiveDetailManager("SYS");
            if (ClientSubmittedRD != null)
            {
                ReceiveDetailID = ClientSubmittedRD.ReceiveDetailID;
                ClientLocationID = ClientSubmittedRD.ClientLocationID;
                ProjectID = (decimal)ClientSubmittedRD.ProjectID;
                ProcessID = ClientSubmittedRD.ProcessID;
                CreateDate = ClientSubmittedRD.CreateDate;
                ESN = ClientSubmittedRD.ESN;
                //Status = ClientSubmittedRD.ReceiveDetailStatus.Status;
                RMANumber = ClientSubmittedRD.RMANumber;
                ProjectName = ClientSubmittedRD.ProjectName;
                RMANumber = rdm.GetReceiveDetailItem_DataElement(ctx, ClientSubmittedRD.ReceiveDetailID, "Client Reference #");
                ServiceRequestNumber = rdm.GetReceiveDetailItem_DataElement(ctx, ClientSubmittedRD.ReceiveDetailID, "Service Request Num");
                EQUSAN = rdm.GetReceiveDetailItem_DataElement(ctx, ClientSubmittedRD.ReceiveDetailID, "EQU SAN");



                CustomerName = rdm.GetReceiveDetailItem_DataElement(ctx, ClientSubmittedRD.ReceiveDetailID, "Customer Name");
                //ReceiveDetailAuthorizationLogID = rdm.getAuthorizationLogID(ctx, ClientSubmittedRD.ReceiveDetailID);
                Status = rdm.getAuthorizationStatusID(ctx, ClientSubmittedRD.ReceiveDetailID);
                UnitStatus = rdm.GetReceiveDetailCurrentProcessNameAndDate(ctx, ClientSubmittedRD.ReceiveDetailID);
                //UnitStatus = rdm.GetReceiveDetailCurrentProcessNameAndDateClientDesc(ctx, ClientSubmittedRD.ReceiveDetailID);
                ProcessName = rdm.GetReceiveDetailCurrentProcessName(ctx, ClientSubmittedRD.ReceiveDetailID);
                CustomerComplaint = rdm.GetReceiveDetailItem_DataElement(ctx, ClientSubmittedRD.ReceiveDetailID, "Complaint") + " " + rdm.GetReceiveDetailItem_DataElement(ctx, ClientSubmittedRD.ReceiveDetailID, "Complaint 2");
                DiscrepencyCode = rdm.GetReceiveDetailItem_DataElement(ctx, ClientSubmittedRD.ReceiveDetailID, "Discrepancy");
                FaultCode = rdm.GetReceiveDetailItem_DataElement(ctx, ClientSubmittedRD.ReceiveDetailID, "Fault Code 1") + " " + rdm.GetReceiveDetailItem_DataElement(ctx, ClientSubmittedRD.ReceiveDetailID, "Fault Code 2");
                ExchangedIMEI = rdm.GetReceiveDetailItem_DataElement(ctx, ClientSubmittedRD.ReceiveDetailID, "Exchanged IMEI");
                GMPMSC_ShipDate = rdm.GetReceiveDetailItem_DataElement(ctx, ClientSubmittedRD.ReceiveDetailID, "GMPMSC_ShipDate");
                isAuthorize = rdm.GetReceiveDetailItem_DataElement(ctx, ClientSubmittedRD.ReceiveDetailID, "isAuthorize");
                //AuthorizedName = rdm.GetReceiveDetailItem_DataElement(ctx, ClientSubmittedRD.ReceiveDetailID, "AuthorizedName");
                //Dealer_ShipDate = rdm.GetReceiveDetailItem_DataElement(ctx, ClientSubmittedRD.ReceiveDetailID, "Shipment Date");
                Dealer_ShipDate = string.Format("{0:MM/dd/yyyy}", ClientSubmittedRD.ReceiveDate);
                Waybill = rdm.GetReceiveDetailItem_DataElement(ctx, ClientSubmittedRD.ReceiveDetailID, "Out-Bound Waybill-S");
                Courier = rdm.GetReceiveDetailItem_DataElement(ctx, ClientSubmittedRD.ReceiveDetailID, "Courier Out");
            }
            if (GMPIReceivedRD != null)
            {
                if (ClientSubmittedRD == null)
                {
                    ReceiveDetailID = GMPIReceivedRD.ReceiveDetailID;
                    ClientLocationID = GMPIReceivedRD.ClientLocationID;
                    ProjectID = (decimal)GMPIReceivedRD.ProjectID;
                    ProcessID = GMPIReceivedRD.ProcessID;
                    CreateDate = GMPIReceivedRD.CreateDate;
                    ESN = GMPIReceivedRD.ESN;
                    RMANumber = GMPIReceivedRD.RMANumber;
                    ProjectName = GMPIReceivedRD.ProjectName;
                    RMANumber = rdm.GetReceiveDetailItem_DataElement(ctx, GMPIReceivedRD.ReceiveDetailID, "Client Reference #");
                    ServiceRequestNumber = rdm.GetReceiveDetailItem_DataElement(ctx, GMPIReceivedRD.ReceiveDetailID, "Service Request Num");
                    CustomerName = rdm.GetReceiveDetailItem_DataElement(ctx, GMPIReceivedRD.ReceiveDetailID, "Customer Name");
                    UnitStatus = rdm.GetReceiveDetailCurrentProcessNameAndDate(ctx, GMPIReceivedRD.ReceiveDetailID);
                    CustomerComplaint = rdm.GetReceiveDetailItem_DataElement(ctx, GMPIReceivedRD.ReceiveDetailID, "Complaint") + " " + rdm.GetReceiveDetailItem_DataElement(ctx, GMPIReceivedRD.ReceiveDetailID, "Complaint 2");
                    Dealer_ShipDate = "";   // string.Format("{0:MM/dd/yyyy}", GMPIReceivedRD.ReceiveDate);
                }
                ProcessName = rdm.GetReceiveDetailCurrentProcessName(ctx, GMPIReceivedRD.ReceiveDetailID);
                Status = rdm.getAuthorizationStatusID(ctx, GMPIReceivedRD.ReceiveDetailID);
                UnitStatus = rdm.GetReceiveDetailCurrentProcessNameAndDate(ctx, GMPIReceivedRD.ReceiveDetailID);
                DiscrepencyCode = rdm.GetReceiveDetailItem_DataElement(ctx, GMPIReceivedRD.ReceiveDetailID, "Discrepancy");
                FaultCode = rdm.GetReceiveDetailItem_DataElement(ctx, GMPIReceivedRD.ReceiveDetailID, "Fault Code 1") + " " + rdm.GetReceiveDetailItem_DataElement(ctx, GMPIReceivedRD.ReceiveDetailID, "Fault Code 2");
                ExchangedIMEI = rdm.GetReceiveDetailItem_DataElement(ctx, GMPIReceivedRD.ReceiveDetailID, "Exchanged IMEI");
                GMPMSC_ShipDate = rdm.GetReceiveDetailItem_DataElement(ctx, GMPIReceivedRD.ReceiveDetailID, "GMPMSC_ShipDate");
                isAuthorize = rdm.GetReceiveDetailItem_DataElement(ctx, GMPIReceivedRD.ReceiveDetailID, "isAuthorize");
                Waybill = rdm.GetReceiveDetailItem_DataElement(ctx, GMPIReceivedRD.ReceiveDetailID, "Out-Bound Waybill-S");
                Courier = rdm.GetReceiveDetailItem_DataElement(ctx, GMPIReceivedRD.ReceiveDetailID, "Courier Out");
                ReceiveDetailAuthorizationLog al = ctx.ReceiveDetailAuthorizationLogs.OrderByDescending(x => x.CreateDate).FirstOrDefault(x => x.ReceiveDetailID == GMPIReceivedRD.ReceiveDetailID);
                if (al != null)
                {
                    AuthorizationLogID = al.ReceiveDetailAuthorizationLogID;
                    if (al.AuthorizedBy != null) { AuthorizedName = al.AuthorizedBy; }
                    if (al.DeclinedBy != null) { DeclinedName = al.DeclinedBy; }
                    if (al.EstimateFee != null) { FeeEstimate = (decimal)al.EstimateFee; }
                    if (al.FreightFee != null) { FeeFreight = (decimal)al.FreightFee; }
                    if (al.HST != null) { FeeHST = (decimal)al.HST; }
                    if (al.Total != null) { FeeTotal = (decimal)al.Total; }
                    if (al.ReceivedDate != null) { GMPIAUTXDone = "Yes"; }
                }
            }
        }


