        public string GMPMSC_ShipDate { get; set; }


        public string isAuthorize { get; set; }            // blank means not required, "A" means authorized, "R" means Authorization required.
        public string AuthorizedName { get; set; }

        public string Dealer_ShipDate { get; set; }
        public string Waybill { get; set; }
        public string Courier { get; set; }
        public DateTime CreateDate { get; set; }


        public string Bin { get; set; }
        public string Location { get; set; }
        public string CMMCG { get; set; }

        public string SendEmailURL { get; set; }
        public string EmailAddress_Location { get; set; }
        public string EmailAddress_Client { get; set; }
        //public string Location { get; set; }
        //public string Location { get; set; }

        public decimal ReceiveDetailAuthorizationLogID { get; set; }

        public GridTechLabDashboardReceiveDetail_Client()
        {
            ReceiveDetailAuthorizationLogID = -1;
            ReceiveDetailID = -1;
            ClientID = -1;
            ClientLocationID = -1;
            ProjectID = -1;
            ProcessID = -1;

            ProcessDays = 0;
            Name = "";
            ProjectName = "";
            RMANumber = "";
            ESN = "";
            Status = "";
            UnitStatus = "";
            UnitStatusDate = "";
            ReceiveDate = "";
            ProcessName = "";
            CustomerComplaint = "";
            DiscrepencyCode = "";
            FaultCode = "";
            ExchangedIMEI = "";
            GMPMSC_ShipDate = "";
            isAuthorize = "";           // blank means not required, "A" means authorized, "R" means Authorization required.
            AuthorizedName = "";
            Dealer_ShipDate = "";
            Waybill = "";
            Courier = "";
            CreateDate = DateTime.Now;
            Bin = "";
            Location = "";
            CMMCG = "";
            EmailAddress_Client = "";
            EmailAddress_Location = "";
            AuthorizationStatus = "";
            SendEmailURL = "";
        }
        public GridTechLabDashboardReceiveDetail_Client(clsLinqDataContext ctx, ReceiveDetail rd, string UserName)
        {
            ReceiveDetailManager rdm = new ReceiveDetailManager(UserName);
            ReceiveDetailID = rd.ReceiveDetailID;
            ClientLocationID = rd.ClientLocationID;
            ClientID = rd.ClientLocation.ClientID;
            Name = rd.ClientLocation.CompanyName;
            //ReceiveDetailID = x.ReceiveDetailID,
            ProjectID = (decimal)rd.ProjectID;
            ProcessID = rd.ProcessID;
            CreateDate = rd.CreateDate;
            ReceiveDate = string.Format("{0:MM/dd/yyyy}", rd.ReceiveDate);
            ESN = rd.ESN;
            Status = rd.ReceiveDetailStatus.Status;
            RMANumber = rd.RMANumber;
            ProjectName = rd.ProjectName;

            ProcessName = "";
            CustomerComplaint = "";
            DiscrepencyCode = "";
            FaultCode = "";
            ExchangedIMEI = "";
            GMPMSC_ShipDate = "";
            isAuthorize = "";
            AuthorizedName = "";
            Dealer_ShipDate = "";
            Waybill = "";
            Courier = "";
            ProcessDays = 0;
            UnitStatus = rdm.GetReceiveDetailCurrentProcessNameAndDate(ctx, rd.ReceiveDetailID);
            if (UnitStatus != null)
            {
                string[] Value = UnitStatus.Split('-');
                DateTime dValue = DateTime.Now;
                DateTime.TryParse(Value[0], out dValue);

                TimeSpan span = DateTime.Now.Subtract(dValue);
                ProcessDays = span.Days;
                ProcessName = Value[1].Trim();
            }

            ProcessName = rdm.GetReceiveDetailCurrentProcessName(ctx, rd.ReceiveDetailID);
            CustomerComplaint = rdm.GetReceiveDetailItem_DataElement(ctx, rd.ReceiveDetailID, "Complaint") + " " + rdm.GetReceiveDetailItem_DataElement(ctx, rd.ReceiveDetailID, "Complaint 2");
            DiscrepencyCode = rdm.GetReceiveDetailItem_DataElement(ctx, rd.ReceiveDetailID, "Discrepancy");
            FaultCode = rdm.GetReceiveDetailItem_DataElement(ctx, rd.ReceiveDetailID, "Fault Code 1") + " " + rdm.GetReceiveDetailItem_DataElement(ctx, rd.ReceiveDetailID, "Fault Code 2");
            ExchangedIMEI = rdm.GetReceiveDetailItem_DataElement(ctx, rd.ReceiveDetailID, "Exchanged IMEI");
            GMPMSC_ShipDate = rdm.GetReceiveDetailItem_DataElement(ctx, rd.ReceiveDetailID, "GMPMSC_ShipDate");
            isAuthorize = rdm.GetReceiveDetailItem_DataElement(ctx, rd.ReceiveDetailID, "isAuthorize");
            AuthorizedName = rdm.GetReceiveDetailItem_DataElement(ctx, rd.ReceiveDetailID, "AuthorizedName");
            Dealer_ShipDate = rdm.GetReceiveDetailItem_DataElement(ctx, rd.ReceiveDetailID, "Shipment Date");
            Waybill = rdm.GetReceiveDetailItem_DataElement(ctx, rd.ReceiveDetailID, "Out-Bound Waybill-S");
            Courier = rdm.GetReceiveDetailItem_DataElement(ctx, rd.ReceiveDetailID, "Courier Out");
            AuthorizationStatus = rdm.GetReceiveDetailItem_DataElement(ctx, rd.ReceiveDetailID, "Authorization Status");



            Bin = rdm.GetReceiveDetailItem_DataElement(ctx, rd.ReceiveDetailID, "Bin"); ;
            Location = rdm.GetReceiveDetailItem_DataElement(ctx, rd.ReceiveDetailID, "Location"); ;
            CMMCG = rdm.MakeModelColour(ctx, rd.ReceiveDetailID);
            EmailAddress_Client = rd.ClientLocation.EmailAddress;
            EmailAddress_Location = rd.ClientLocation.EmailAddress;
            SendEmailURL = "";




            if (EmailAddress_Location != null && EmailAddress_Location.Length > 0)
            {
                SendEmailURL = "<a href='mailto:" + EmailAddress_Location;
                SendEmailURL += "?subject=" + rd.ESN;
                //SendEmailURL += "&body=" + Body;
                SendEmailURL += "' id='href_Waiting' onClick='RecordContact(" + rd.ReceiveDetailID.ToString() + ",'','');'>Email</a>";
            }



            ReceiveDetailAuthorizationLogID = rdm.getAuthorizationLogID(rd.ReceiveDetailID);
            //Status = rdm.getAuthorizationStatusID(rd.ReceiveDetailID);


        }
    }

