    public class PairIDValue
    {
        public decimal ID { get; set; }
        public String Desc { get; set; }

        public static List<PairIDValue> GetUniqueList(List<PairIDValue> FullList, List<PairIDValue> itemsToRemove)
        {
            return (from l1 in FullList where !(from l2 in itemsToRemove select l2.ID).Contains(l1.ID) select l1).ToList();
        }

    }


