    public class clsLog
    {
        public decimal OrderDetailReceiveDetailID { get; set; }
        public decimal OrderDetailID { get; set; }
        public decimal? ReceiveDetailID { get; set; }
        public bool writeLogData { get; set; }
        public bool isNew { get; set; }
        public bool isDirty { get; set; }
        public bool isDeleted { get; set; }

        public string filename { get; set; }
        public string filepath { get; set; }
        public string username { get; set; }
        public string UserNameToLog { get; set; }


        public clsLog(string FilePath, string Username)
        {
            filename = "Logfile.txt";
            filepath = FilePath;
            username = Username;
            writeLogData = false;
            UserNameToLog = "";          // "dtomchuk";
        }

        public clsLog(string FilePath, string FileName, string Username)
        {
            filename = FileName;
            filepath = FilePath;
            username = Username;
            writeLogData = false;
            UserNameToLog = "";          // "dtomchuk";
        }

        public clsLog(string FilePath, string FileName, string Username, string usernametolog)
        {
            filename = FileName;
            filepath = FilePath;
            username = Username;
            writeLogData = false;
            UserNameToLog = usernametolog;          // "dtomchuk";
        }
        public string GetTempPath()
        {
            string path = "";
            //               System.Environment.GetEnvironmentVariable("TEMP");

            //string rootPath = Server.MapPath("~");
            path = filepath;

            if (!path.EndsWith("\\"))
            {
                path += "\\";
            }
            return path;
        }


        public void Report()
        {

            if (writeLogData == true && (username.ToUpper() == UserNameToLog.ToUpper() || UserNameToLog.Length == 0))
            {
                System.IO.StreamWriter sw = System.IO.File.AppendText(GetTempPath() + filename);
                try
                {
                    string logLine = System.String.Format("{0:d/M/yyyy HH:mm:ss.ff}: {1}.", System.DateTime.Now, "Report *******************");
                    sw.WriteLine(logLine);

                    System.String.Format("{0:d/M/yyyy HH:mm:ss.ff}: {1}.", System.DateTime.Now, "Outupt file:" + GetTempPath() + filename);
                    sw.WriteLine(logLine);

                    //System.String.Format("{0:d/M/yyyy HH:mm:ss.ff}: {1}.", System.DateTime.Now, "Outupt file:" + GetTempPath() + filename);
                    //sw.WriteLine(logLine);
                }
                finally
                {
                    sw.Close();
                }
            }

            //LogMessageToFile(message);
        }


        public void LogIt(string message)
        {
            LogMessageToFile(message);
        }

        public void Clear()
        {
            if (writeLogData == true)
            {
                System.IO.StreamWriter sw =
                   System.IO.File.CreateText(
                      GetTempPath() + filename); // Change filename
                try
                {
                    sw.WriteLine("");
                }
                finally
                {
                    sw.Close();
                }
            }
        }
        public void Clear(string FileName)
        {
            if (writeLogData == true)
            {
                System.IO.StreamWriter sw =
                   System.IO.File.CreateText(
                      GetTempPath() + FileName); // Change filename
                try
                {
                    sw.WriteLine("");
                }
                finally
                {
                    sw.Close();
                }
            }
        }
        public void LogMessageToFile(string message)
        {
            if (writeLogData == true && (username.ToUpper() == UserNameToLog.ToUpper() || UserNameToLog.Length == 0))
            {
                System.IO.StreamWriter sw = System.IO.File.AppendText(GetTempPath() + filename);
                try
                {
                    string logLine = System.String.Format("{0:d/M/yyyy HH:mm:ss.ff}: {1}.", System.DateTime.Now, message);
                    sw.WriteLine(logLine);
                }
                finally
                {
                    sw.Close();
                }
            }
        }
    }





