    public class SystemLogManager
    {
        public DateTime StartTime { get; set; }
        public int ReportLevel { get; set; }

        public string Message { get; set; }

        public int Level { get; set; }
        public string UserName { get; set; }
        public int hours { get; set; }
        public int Minutes { get; set; }
        public int Seconds { get; set; }
        public int Milliseconds { get; set; }
        public decimal TotalMilliseconds { get; set; }
        public string Catagory { get; set; }


        private void SetDefaultValues()
        {
            StartTime = DateTime.Now;
            Message = "Blank Message";
            Level = 0;
            ReportLevel = 0;
            UserName = "";
            hours = 0;
            Minutes = 0;
            Seconds = 0;
            Milliseconds = 0;
            TotalMilliseconds = 0;
            Catagory = "";
        }

        public SystemLogManager()
        {
            SetDefaultValues();
            StartTime = DateTime.Now;
        }
        public SystemLogManager(int reportlevel, string catagory, string Username)
        {
            SetDefaultValues();
            UserName = Username;
            StartTime = DateTime.Now;
            ReportLevel = reportlevel;
            Catagory = catagory;
        }
        public SystemLogManager(DateTime starttime)
        {
            SetDefaultValues();
            StartTime = starttime;
        }
        public SystemLogManager(DateTime starttime, string message)
        {
            SetDefaultValues();
            StartTime = starttime;
            Message = message;
        }

        public void Log(clsLinqDataContext ctx, string message, int level)
        {
            Message = message;
            Level = level;
            Log(ctx);
        }

        private void Log(clsLinqDataContext ctx)
        {
            if (Level <= ReportLevel)
            {
                CalcDifference();
                SystemLog sl = new SystemLog();
                sl.CreateUser = UserName;
                sl.LastUpdateUser = UserName;
                sl.Level = Level;
                sl.Message = Message;
                sl.Milliseconds = Milliseconds;
                sl.Minutes = Minutes;
                sl.Seconds = Seconds;
                sl.TotalMilliseconds = TotalMilliseconds;
                sl.Catagory = Catagory;
                ctx.SystemLogs.InsertOnSubmit(sl);
                ctx.SubmitChanges();
            }
        }
        private void CalcDifference()
        {
            DateTime endtime = DateTime.Now;
            TimeSpan diffResult = endtime.Subtract(StartTime);
            hours = diffResult.Hours;
            Minutes = diffResult.Minutes;
            Seconds = diffResult.Seconds;
            Milliseconds = diffResult.Milliseconds;
            TotalMilliseconds = (decimal)diffResult.TotalMilliseconds;
        }
    }
    public class UserManager
    {
        string _UserName = string.Empty;
        public String UserName
        {
            get { return _UserName; }
            set { _UserName = value; }
        }
        public UserManager(string UserName)
        {
            _UserName = UserName;
        }
        static clsLinqDataContext GetDataContext(string UserName)
        {
            clsLinqDataContext ctx = new clsLinqDataContext();
            ctx.UserName = UserName;
            return ctx;
        }

        public List<String> MasterUserList()
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                List<String> ul = new List<String>();
                if (Roles.IsUserInRole(UserName, "Administrators") || Roles.IsUserInRole(UserName, "Supervisors"))
                {
                    MembershipUserCollection users = Membership.GetAllUsers();
                    foreach (var u in users) { ul.Add(u.ToString()); }
                }
                else { ul.Add(UserName); }
                return ul;
            }
        }

        public List<UserRecord> MasterUserListAll()
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                List<UserRecord> ul = new List<UserRecord>();
                MembershipUserCollection users = Membership.GetAllUsers();
                foreach (MembershipUser u in users)
                {
                    UserRecord ur = new UserRecord();
                    ur.UserName = u.UserName;
                    ur.Name = u.ToString();
                    UserTable ut = ctx.UserTables.FirstOrDefault(x => x.UserName == u.UserName);
                    if (ut != null && ut.ContactName != null && ut.ContactName.Length > 0)
                    {
                        ur.Name = ut.ContactName;
                    }
                    ul.Add(ur);
                }
                return ul;
            }
        }

    }



