    public class DateUtils
    {
        public DateUtils() { }

        public DateTime StringToDate(string date)
        {
            DateTime d = DateTime.Now;
            DateTime.TryParse(date, out d);
            return d;
        }

        public string MMDDYYYY(DateTime date)
        {
            return date.Month.ToString() + "/" + date.Day.ToString() + "/" + date.Year.ToString();
        }

        public DateTime StartOfDay(DateTime date)
        {
            return new DateTime(date.Year, date.Month, date.Day);
        }
        public DateTime EndOfDay(DateTime date)
        {
            return new DateTime(date.Year, date.Month, date.Day, 23, 59, 59);
        }

        public DateTime YesterDay(DateTime date)
        {
            date = StartOfDay(date);
            date = date.AddDays(-1);
            return date;
        }

        public int DaysBetween(DateTime StartDate, DateTime EndDate)
        {
            TimeSpan span = EndDate - StartDate;
            return span.Days;
        }

        public DateTime OffsetDays(DateTime date, int Days)
        {
            return date.AddDays(Days);
        }


        public DateTime StartOfWeek(DateTime date)
        {
            System.Globalization.CultureInfo ci = System.Threading.Thread.CurrentThread.CurrentCulture;
            DayOfWeek fdow = ci.DateTimeFormat.FirstDayOfWeek;
            return StartOfDay(date.AddDays(-(date.DayOfWeek - fdow)));
        }
        public DateTime EndOfWeek(DateTime date)
        {
            return EndOfDay(StartOfWeek(date).AddDays(6));
        }

        public DateTime StartOfMonth(DateTime date)
        {
            date = StartOfDay(date);
            date = date.AddDays(date.Day * -1);
            date = date.AddDays(1);
            return date;
        }
        public DateTime EndOfMonth(DateTime date)
        {
            date = StartOfDay(date);
            date = date.AddMonths(1);
            date = date.AddDays(date.Day * -1);
            return EndOfDay(date);
        }

        public DateTime StartOfYear(DateTime date)
        {
            return StartOfDay(new DateTime(date.Year, 1, 1));
        }
        public DateTime EndOfYear(DateTime date)
        {
            return EndOfDay(new DateTime(date.Year + 1, 1, 1).AddDays(-1));
        }

        public DateTime DateOnly(DateTime date)
        {
            return StartOfDay(date);
        }






    }
