        public bool SetValue(string key, string Value)
        {
            using (clsLinqDataContext ctx = Getctx())
            {
                return SetValue(ctx, key, Value);
            }
        }
        public bool SetValue(clsLinqDataContext ctx, string key, string Value)
        {
            bool add = false;
            SystemData s = ctx.SystemDatas.FirstOrDefault(x => x.DataKey == key);
            if (s == null)
            {
                s = new SystemData();
                s.DataKey = key;
                s.CreateUser = _UserName;
                add = true;
            }
            s.LastUpdateUser = _UserName;
            s.LastUpdateDate = DateTime.Now;
            if (Value.Length > 50)
            {
                s.Data = "";
                s.DataLong = Value;
            }
            else { s.Data = Value; }
            if (add == true)
            {
                ctx.SystemDatas.InsertOnSubmit(s);
            }
            ctx.SubmitChanges();
            return true;
        }

