    public class ReceiveDetailUtilityMoveLogManager
    {
        string _UserName = string.Empty;
        string _utilityName = string.Empty;
        clsLinqDataContext _ctx = null;
        clsLinqDataContext ctx
        {
            get { if (_ctx == null) { _ctx = GetDataContext(_UserName); } return _ctx; }
            set { _ctx = value; }
        }
        public clsLinqDataContext GetDataContext(string UserName)
        {
            clsLinqDataContext ctx = new clsLinqDataContext();
            ctx.UserName = UserName;
            return ctx;
        }
        public String UserName
        {
            get { return _UserName; }
            set { _UserName = value; }
        }


        public void Save(decimal ReceiveDetailID, string Message)
        {
            Save(ReceiveDetailID, -1, -1, Message);
        }
        public void Save(decimal ReceiveDetailID, decimal ReceiveDetailID_Related, string Message)
        {
            Save(ReceiveDetailID, ReceiveDetailID_Related, -1, Message);
        }
        public void Save(decimal ReceiveDetailID, string Message, decimal OrderHeaderID)
        {
            Save(ReceiveDetailID, -1, OrderHeaderID, Message);
        }
        public void Save(decimal ReceiveDetailID, decimal ReceiveDetailID_Related, decimal OrderHeaderID, string Message)
        {
            ReceiveDetailUtilityRunLog log = new ReceiveDetailUtilityRunLog();
            log.CreateDate = DateTime.Now;
            log.Createuser = _UserName;
            log.OrderHeaderID = -1;
            log.ReceiveDetailID = ReceiveDetailID;
            log.ReceiveDetailID_Related = -1;
            log.ResultMessage = Message;
            log.Utility = _utilityName;
            ctx.ReceiveDetailUtilityRunLogs.InsertOnSubmit(log);
            ctx.SubmitChanges();
        }

        public ReceiveDetailUtilityMoveLogManager(string utilityName, string UserName)
        {
            _utilityName = utilityName;
            _UserName = UserName;
            _ctx = ctx;
        }
        public ReceiveDetailUtilityMoveLogManager(clsLinqDataContext ctx, string UserName)
        {
            _UserName = UserName;
        }
    }
