        public decimal Save(clsLinqDataContext ctx)
        {
            if (Header.ReceiveDetailXBINXHeaderLogID == 0) { ctx.ReceiveDetailXBINXHeaderLogs.InsertOnSubmit(Header); }
            ctx.SubmitChanges();
            return Header.ReceiveDetailXBINXHeaderLogID;
        }
        public XBINXLogManager(string Bin, string Process, string Name, string Data, string UserName)
        {
            _UserName = UserName;
            //Source = source;
            if (_UserName.Trim().Length == 0) { _UserName = "NullUser"; }
            CreateNewHeader(Bin, Process, Name, Data);
        }
        public XBINXLogManager(clsLinqDataContext ctx, decimal HeaderID)
        {
            //_ctx = ctx;
            Header = ctx.ReceiveDetailXBINXHeaderLogs.FirstOrDefault(x => x.ReceiveDetailXBINXHeaderLogID == HeaderID);
            if (Header == null)
            {
                CreateNewHeader("UNK", "Unknown", "UNK", "");
            }
            _Bin = Header.BinNumber;
        }
        private void CreateNewHeader(string Bin, string Process, string Name, string Data)
        {
            Header = new ReceiveDetailXBINXHeaderLog();
            Header.BinNumber = Bin;
            Header.Data = Data;
            Header.Name = Name;
            Header.Process = Process;
            Header.StartDate = DateTime.Now;
            Header.EndDate = DateTime.Now;
            Header.CreateDate = DateTime.Now;
            Header.Createuser = _UserName;
            _Bin = Bin;

        }

        public void LogData(decimal ReceiveDetailID, DateTime StartDate, string Message)
        {
            ReceiveDetailXBINXDetailLog Detail = new ReceiveDetailXBINXDetailLog();
            Detail.CreateDate = DateTime.Now;
            Detail.Createuser = _UserName;
            Detail.ReceiveDetailID = ReceiveDetailID;
            Detail.ResultMessage = Message;
            Detail.StartDate = StartDate;
            Header.EndDate = Detail.CreateDate;
            Header.ReceiveDetailXBINXDetailLogs.Add(Detail);
        }
    }

