        public String Source
        {
            get { return _Source; }
            set { _Source = value; }
        }
        public String UserName
        {
            get { return _UserName; }
            set { _UserName = value; }
        }
        public JimErrorLogManager(string UserName, string source)
        {
            _UserName = UserName;
            Source = source;
            if (_UserName.Trim().Length == 0)
            {
                _UserName = "NullUser";
            }
        }

        public void ReportMessage(string Message)
        {
            if (_IsActive == true)
            {
                using (clsLinqDataContext ctx = GetDataContext(UserName))
                {
                    JimErrorLog el = new JimErrorLog();
                    el.Createuser = UserName;
                    el.Message = Message;
                    el.Source = Source;
                    ctx.JimErrorLogs.InsertOnSubmit(el);
                    ctx.SubmitChanges();
                }
            }

        }
    }

