    {
        string _UserName = string.Empty;

        public String UserName
        {
            get { return _UserName; }
            set { _UserName = value; }
        }
        public Hobble(string Username)
        {
            UserName = Username;
        }

        #region Hobble
        public List<ReceiveDetailHobbleList> GetHobbleList(string Key, string UserName)
        {
            using (clsLinqDataContext ctx = new clsLinqDataContext())
            {
                return GetHobbleList(ctx, Key, UserName);
            }
        }
        public List<ReceiveDetailHobbleList> GetHobbleList(clsLinqDataContext ctx, string Key, string UserName)
        {
            List<ReceiveDetailHobbleList> HobbleList = ctx.ReceiveDetailHobbleLists.Where(x => x.CreateUser == UserName && x.Key.ToUpper() == Key.ToUpper()).OrderBy(x => x.Seq).ThenBy(x => x.ESN).ToList();
            return HobbleList;
        }
        public bool DeleteHobbleList(string Key, string UserName)
        {
            using (clsLinqDataContext ctx = new clsLinqDataContext())
            {
                return DeleteHobbleList(ctx, Key, UserName);
            }
        }
        public bool DeleteHobbleList(clsLinqDataContext ctx, string Key, string UserName)
        {
            var HobbleList = ctx.ReceiveDetailHobbleLists.Where(x => x.CreateUser == UserName && x.Key.ToUpper() == Key.ToUpper());
            ctx.ReceiveDetailHobbleLists.DeleteAllOnSubmit(HobbleList);
            ctx.SubmitChanges();
            return true;
        }
        public bool LoadHobbleList(string ESN, string Key, string Data, short Seq, string UserName)
        {
            using (clsLinqDataContext ctx = new clsLinqDataContext())
            {
                return LoadHobbleList(ctx, ESN, Key, Data, Seq, UserName);
            }
        }
        public bool LoadHobbleList(clsLinqDataContext ctx, string ESN, string Key, string Data, short Seq, string UserName)
        {
            ESN = ESN.Trim();
            ReceiveDetailHobbleList dta = ctx.ReceiveDetailHobbleLists.FirstOrDefault(x => x.ESN == ESN && x.CreateUser == UserName && x.Key.ToUpper() == Key.ToUpper());
            if (dta == null)
            {
                ReceiveDetail rd = ctx.ReceiveDetails.FirstOrDefault(x => x.ESN == ESN && x.Version == "000");
                if (rd != null)
                {
                    dta = new ReceiveDetailHobbleList();
                    dta.CreateUser = UserName;
                    dta.CreateDate = DateTime.Now;
                    dta.Key = Key;
                    dta.Seq = Seq;
                    dta.Data = Data;
                    dta.ESN = ESN;
                    dta.ReceiveDetailID = rd.ReceiveDetailID;
                    ctx.ReceiveDetailHobbleLists.InsertOnSubmit(dta);
                    ctx.SubmitChanges();
                    return true;
                }
                else { return false; }
            }

            return true;
        }
        #endregion



    }

