        private Hashtable _dList = null;
        public Hashtable dList
        {
            get
            {
                if (_dList == null)
                {
                    _dList = ListData(true);
                }
                return _dList;
            }
        }
        public JsonString()
        {
            _sb.Clear();
        }
        public JsonString(string js)
        {
            _sb.Append(js);
        }
        public JsonString(string js, bool isCompressed)
        {
            _sb.Append(js);
            _isCompressed = isCompressed;
        }
        public JsonString(string a, string b)
        {
            AddValuePair(a, b);
        }
        public void AddValuePair(string a, string b)
        {
            if (_sb.Length > 0) { _sb.Append(","); }
            _sb.Append(JSONElements(a, b));
        }
        public void RemoveValuePair(string a, string b)
        {
            string strToRemoveWithDoubleQuote = JSONElements(a, b);          // This comes back with double quotes  "
            _sb = _sb.Replace("," + strToRemoveWithDoubleQuote, "");
            _sb = _sb.Replace(strToRemoveWithDoubleQuote, "");

            strToRemoveWithDoubleQuote = strToRemoveWithDoubleQuote.Replace('"', '\'');
            _sb = _sb.Replace("," + strToRemoveWithDoubleQuote, "");
            _sb = _sb.Replace(strToRemoveWithDoubleQuote, "");
        }

        /// <summary>
        /// ///////////////////////////
        /// </summary>
        /// <returns></returns>



        public Hashtable ListData()
        {
            return ListData(false);
        }
        public Hashtable ListData(bool UppercaseKey)
        {
            string Value = _sb.ToString();
            Hashtable dList = new Hashtable();
            string[] parts = Value.Split(new char[] { ',' }, StringSplitOptions.RemoveEmptyEntries);
            for (int i = 0; i < parts.Length; i++)
            {
                int pos = parts[i].IndexOf(":");
                if (pos > 0)
                {
                    string key = DeCompress(RemoveQuotes(parts[i].Substring(0, pos)));
                    string value = RemoveQuotes(parts[i].Substring(pos + 1));
                    value = DecodeData(value);
                    if (UppercaseKey == false) { dList.Add(key, value); }
                    else { dList.Add(key.ToUpper(), value); }
                }
            }
            return dList;
        }
