        public string GetNewDataString()
        {
            StringBuilder _NString = new StringBuilder();
            foreach (DictionaryEntry x in dList)
            {
                if (_NString.Length > 0) { _NString.Append(","); }
                _NString.Append(JSONElements(x.Key.ToString(),x.Value.ToString()));
            }
            return _NString.ToString();

        }
        public string JSONElements(string a, string b)
        {
            StringBuilder sb = new StringBuilder();
            sb.Append('"');
            sb.Append(Compress(a));
            sb.Append('"');
            sb.Append(':');
            sb.Append('"');
            sb.Append(EncodeData(b));
            sb.Append('"');
            return sb.ToString();
        }
