        public string GetValue(string AttributeName, string ReturnValueIfNotFound)
        {
            AttributeName = AttributeName.ToUpper();
            // if we have a element that carries the looked for attribute... great, send it back.
            if (dList.ContainsKey(AttributeName))
            {
                return CleanData(dList[AttributeName].ToString());
            }

            // because our "dlist" keys are coded at the browser, we need to translate the code back to the answer for the question that is being looked for.
            // Get all the answers possible for the requested question.
            var ol = from x in dbQuestionAnswerTable where x.Name.ToUpper() == AttributeName.ToUpper() select x;
            foreach (var o in ol)
            {
                if (dList.ContainsKey(o.jCoded.ToUpper()))
                {
                    if (o.UseOptionValue == "1") { return o.OptionValue; }
                    else
                    {
                        return CleanData(dList[o.jCoded.ToUpper()].ToString());
                    }
                }
            }
            return ReturnValueIfNotFound;
        }
