        #region MISC
        public string RemoveQuotes(string value)
        {
            // The Value is enclosed in quotes, they need to be removed.
            if (value.Length < 2) { return ""; }
            value = value.Substring(1);
            value = value.Substring(0, value.Length - 1);
            return value;
        }
        public string CleanData(string Data)
        {
            string DoubleQuote = "\"";
            StringBuilder b = new StringBuilder(Data);
            b.Replace("[", string.Empty);
            b.Replace("]", string.Empty);
            b.Replace("'", string.Empty);
            b.Replace(DoubleQuote, string.Empty);
            b.Replace(@"\", string.Empty);
            return b.ToString();
        }
        private string Compress(string key)
        {
            if (_isCompressed == true)
            {
                switch (key.ToUpper())
                {
                    case "CLIENTLOCATIONID": return "a";
                    case "CURPROCESSID": return "b";
                    case "NEXTPROCESSID": return "c";
                    case "NEXTSTEPID": return "d";
                    case "RECEIVEHEADERID": return "e";
                    case "RECEIVEDETAILBULKID": return "f";
                    case "RECEIVEDETAILID": return "g";
                    case "HDNSEARCHRETURNMODE": return "h";
                    case "CURPROCESS": return "i";
                    case "NEXTPROCESS": return "j";
                    case "NEXTSTEP": return "k";
                    case "CURUSERNAME": return "l";
                    case "CURSTEPUP": return "m";
                    case "PROJSET": return "n";
                    case "PROJECT": return "o";
                    case "PROJECTID": return "p";
                    case "QTY": return "q";
                    case "PROJTAG": return "r";
                    case "RMA": return "s";
                    case "ESN": return "t";
                    case "RECEIVEDATE": return "u";
                    case "HDNALLOWDUPADD": return "v";
                    default: return key;
                }
            }
            return key;
        }
        private string DeCompress(string key)
        {
            if (_isCompressed == true)
            {
                switch (key.ToLower())
                {
                    case "a": return "ClientLocationID";
                    case "b": return "CurProcessID";
                    case "c": return "NextProcessID";
                    case "d": return "NextStepID";
                    case "e": return "ReceiveHeaderID";
                    case "f": return "ReceiveDetailBulkID";
                    case "g": return "ReceiveDetailID";
                    case "h": return "hdnSearchReturnMode";
                    case "i": return "CurProcess";
                    case "j": return "NextProcess";
                    case "k": return "NextStep";
                    case "l": return "CurUserName";
                    case "m": return "CurStepUp";
                    case "n": return "PROJSet";
                    case "o": return "Project";
                    case "p": return "ProjectID";
                    case "q": return "QTY";
                    case "r": return "PROJTAG";
                    case "s": return "RMA";
                    case "t": return "ESN";
                    case "u": return "ReceiveDate";
                    case "v": return "hdnAllowDupAdd";
                    default: return key;
                }
            }
            return key;
        }
