        public void SetTextAttribute(clsLinqDataContext ctx, string Name, string Value)
        {
            string CurrentAnswser = GetValue(Name, "NOT FOUND");
            string jCoded = "";
            string OptionValue = "";
            // if we find the answer we want, then just skip out.
            if (CurrentAnswser.ToUpper() == Value.ToUpper()) { return; }

            // If not what we want, we need to see if we have a diffferent answer.
            //List<JsonStringOptionKeyList> dl = GetQuestionList(ctx, Name);
            List<JsonStringOptionKeyList> dl = GetQuestionList(Name);
            if (dl != null)
            {
                // look to see if we have it already
                foreach (JsonStringOptionKeyList key in dl)
                {
                    if (key.Name.ToUpper() == Name.ToUpper())
                    {
                        // if we have a element that carries the looked for attribute ABBR... great, we are done.
                        if (dList.ContainsKey(key.jCoded.ToUpper()))
                        {
                            RemoveValuePair(key.jCoded, CurrentAnswser);
                        }
                        // We need to capture what we found to add it later.
                        jCoded = key.jCoded;
                    }
                }
                // If we have reached this spot, we don't have it and need to add it.
                if (jCoded.Length > 0) { AddValuePair(jCoded, Value); }
                else { 
                    dList[Name.ToUpper()] = Value; 
                }
            }
        }
 
       
