    [Serializable()]
    public class IFSKeyValues
    {
        public decimal ReceiveDetailID { get; set; }
        public string ESN { get; set; }
        public string Version { get; set; }
        public string IFSSite { get; set; }
        public string IFSProject { get; set; }
        public string IFSSKU { get; set; }
        public string IFSCondition { get; set; }
        public string IFSLocation { get; set; }

        public IFSKeyValues()
        {
                ReceiveDetailID = -1;
                ESN = "";
                Version = "";
                IFSSite = "";
                IFSProject = "";
                IFSSKU = "";
                IFSCondition = "";
                IFSLocation = "";
        }

        public IFSKeyValues(decimal receiveDetailID)
        {
            using (clsLinqDataContext ctx = new clsLinqDataContext())
            {
                var RD = ctx.ReceiveDetails.FirstOrDefault(x => x.ReceiveDetailID == receiveDetailID);
                LoadData(RD);
            }
        }
        public IFSKeyValues(string esn)
        {
            using (clsLinqDataContext ctx = new clsLinqDataContext())
            {
                var RD = ctx.ReceiveDetails.FirstOrDefault(x => x.ESN == esn && x.Version == "000");
                LoadData(RD);
            }
        }
        public IFSKeyValues(string esn, bool UploadToLastProcessedVersion)
        {
            using (clsLinqDataContext ctx = new clsLinqDataContext())
            {
                if (UploadToLastProcessedVersion == true)
                {
                    var RD = ctx.ReceiveDetails.Where(x=> x.ESN == esn).OrderBy(y=> y.Version).FirstOrDefault(x => x.ESN == esn);
                    LoadData(RD);
                }
                else
                {
                    var RD = ctx.ReceiveDetails.FirstOrDefault(x => x.ESN == esn && x.Version == "000");
                    LoadData(RD);
                }
            }
        }

        private void LoadData(ReceiveDetail RD)
        {
            ReceiveDetailID = -1;
            ESN = "";
            Version = "";
            IFSSite = "";
            IFSProject = "";
            IFSSKU = "";
            IFSCondition = "";
            IFSLocation = "";
            if (RD != null)
            {
                ReceiveDetailID = RD.ReceiveDetailID;
                ESN = RD.ESN;
                Version = RD.Version;
                IFSSite = RD.ClientLocation.IFSSite;
                IFSProject = RD.ClientLocation.IFSProject;
                IFSSKU = RD.SKU;
                IFSCondition = RD.IFSCondition;
                IFSLocation = RD.IFSLocation;
            }
        }

        public IFSKeyValues Clone()
        {
            IFSKeyValues cl = new IFSKeyValues();
            cl.ESN = ESN;
            cl.IFSCondition = IFSCondition;
            cl.IFSLocation = IFSLocation;
            cl.IFSProject = IFSProject;
            cl.IFSSite = IFSSite;
            cl.IFSSKU = IFSSKU;
            cl.ReceiveDetailID = ReceiveDetailID;
            return cl;
        }

        public bool isIFSKeysEqual(IFSKeyValues compare)
        {
            if (compare.IFSSite == IFSSite && compare.IFSProject == IFSProject && compare.IFSSKU == IFSSKU && compare.IFSCondition == IFSCondition && compare.IFSLocation == IFSLocation) { return true; }
            return false;
        }

    }

