        [DataObjectMethod(DataObjectMethodType.Select)]
        public List<Discrepancy> GetDiscrepanciesThisClientLocation(decimal ClientID, decimal ClientLocationID, bool Resolved)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                var locations = ctx.Discrepancies.Where(x => x.ClientID == ClientID
                                                         && (x.ClientLocationID == ClientLocationID || ClientLocationID == -1) 
                                                         && ((x.Resolved != null && x.Resolved == Resolved) 
                                                          || (Resolved == false && x.Resolved == null)));
            //            var Processs = ctx.GetMasterProcessesThisProjectID(UserName, ProjectID);
                return locations.ToList();
            }
        }



        public decimal Save(Discrepancy d)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                return Save(ctx, d);
            }
        }
        public decimal Save(clsLinqDataContext ctx, Discrepancy d)
        {
            if (d.DiscrepancyID == null || d.DiscrepancyID < 1) { return Insert(ctx, d); }
            Discrepancy o = ctx.Discrepancies.FirstOrDefault(x => x.DiscrepancyID == d.DiscrepancyID);
            if (o == null) { d.DiscrepancyID = -1; return Insert(ctx, d); }
            o.AttemptDate = d.AttemptDate;
            o.AttemptDate2 = d.AttemptDate2;
            o.AttemptDate3 = d.AttemptDate3;
            o.AttemptUser = d.AttemptUser;
            o.AttemptUser2 = d.AttemptUser2;
            o.AttemptUser3 = d.AttemptUser3;
            o.DiscrepancyText = d.DiscrepancyText;
            o.Division = d.Division;
            o.IMEI = d.IMEI;
            o.OutCome = d.OutCome;
            o.ReceiveDetailID = d.ReceiveDetailID;
            o.Resolved = d.Resolved;
            o.ReturnTransfer = d.ReturnTransfer;
            o.Transfer_WO = d.Transfer_WO;
            o.Type = d.Type;
            o.LastUpdateDate = DateTime.Now;
            o.LastUpdateUser = UserName;
            ctx.SubmitChanges();
            return o.DiscrepancyID;
        }





        public string KillAllRecords()
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                return KillAllRecords(ctx);
            }
        }
        public string KillAllRecords(clsLinqDataContext ctx)
        {
            ctx.ExecuteCommand("TRUNCATE TABLE Discrepancy");
            ctx.ExecuteCommand("DBCC CHECKIDENT ('[Discrepancy]',RESEED, 20000)");     // We need to reset this because there are some historical data that needs to be loaded. We need to preserver the Identity on th ose.
            return "All Records Deleted!";
        }
