        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                return SaveHistorical(ctx, d);
            }
        }
        public string SaveHistorical(clsLinqDataContext ctx, Discrepancy d)
        {
            ctx.Utility_InsertHistoricalDiscrepancy(d.DiscrepancyID,d.ClientID,d.ClientLocationID,d.ReceiveDetailID,d.Type,d.Division,d.DiscrepancyText, d.OutCome, d.Transfer_WO, d.ReturnTransfer, d.IMEI, d.AttemptDate, d.AttemptUser, d.AttemptDate2, d.AttemptUser2, d.AttemptDate3, d.AttemptUser3, d.Resolved, d.CreateDate, d.CreateUser, d.LastUpdateDate, d.LastUpdateUser);
            return "Discrepancy Saved";
        }
        public decimal Insert(Discrepancy d)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                return Insert(ctx, d);
            }
        }
        public decimal Insert(clsLinqDataContext ctx, Discrepancy d)
        {
            if (d.DiscrepancyID != null && d.DiscrepancyID > 0) { return Save(ctx, d); }
            d.LastUpdateDate = DateTime.Now;
            d.LastUpdateUser = UserName;
            d.CreateUser = UserName;
            ctx.Discrepancies.InsertOnSubmit(d);
            ctx.SubmitChanges();
            return d.DiscrepancyID;
        }
        public bool Delete(decimal ID)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                return Delete(ctx, ID);
            }
        }
        public bool Delete(clsLinqDataContext ctx, decimal ID)
        {
            Discrepancy d = ctx.Discrepancies.FirstOrDefault(x => x.DiscrepancyID == ID);
            if (d != null)
            {
                ctx.Discrepancies.DeleteOnSubmit(d);
                ctx.SubmitChanges();
                return true;
            }
            return false;
        }



        #region Dropdown relations
        public string SaveRelations(decimal MasterID, List<decimal> keepers)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {

                List<decimal> AlreadyGot = new List<decimal>();
                List<decimal> ListToAdd = new List<decimal>();
                // List of records we have to reset.
                var Deactivate = from x in ctx.DiscrepancyDDRelations 
                                 where x.IsActive == true 
                                    && x.MasterID == MasterID 
                                    && keepers.Contains(x.SlaveID) == false 
                                select x;


                // List of records we have already.
                AlreadyGot = (from x in ctx.DiscrepancyDDRelations 
                              where x.IsActive == true 
                                 && x.MasterID == MasterID 
                                 && keepers.Contains(x.SlaveID) == true 
                             select x.SlaveID).ToList();


                // List of records we can active.
                var activate = from x in ctx.DiscrepancyDDRelations 
                               where x.IsActive == false 
                                  && x.MasterID == MasterID 
                                  && keepers.Contains(x.SlaveID) == true 
                              select x;

                // Go through the keepers find those we have to add new.
                foreach (decimal d in keepers)
                {
                    if (AlreadyGot.Contains(d) == false)
                    {
                        // Look to see if we just need to activate it, in stead of adding it new.
                        var z = activate.FirstOrDefault(x => x.SlaveID == d);
                        if (z == null)
                        {
                            DiscrepancyDDRelation r = new DiscrepancyDDRelation();
                            r.CreateUser = UserName;
                            r.IsActive = true;
                            r.LastUpdateDate = DateTime.Now;
                            r.LastUpdateUser = UserName;
                            r.MasterID = MasterID;
                            r.SlaveID = d;
                            ctx.DiscrepancyDDRelations.InsertOnSubmit(r);
                        }
                    }
                }


                foreach (DiscrepancyDDRelation d in Deactivate)
                {
                    d.IsActive = false;
                    d.LastUpdateDate = DateTime.Now;
                    d.LastUpdateUser = UserName;
                }
                foreach (DiscrepancyDDRelation d in activate)
                {
                    d.IsActive = true;
                    d.LastUpdateDate = DateTime.Now;
                    d.LastUpdateUser = UserName;
                }
                ctx.SubmitChanges();
            return "Data Saved!";
            }

        }


        public List<decimal> GetSlaves(decimal MasterID)
        {
            using (clsLinqDataContext ctx = GetDataContext(UserName))
            {
                List<decimal> AlreadyGot = (from x in ctx.DiscrepancyDDRelations
                                           where x.IsActive == true
                                              && x.MasterID == MasterID
                                         select x.SlaveID).ToList();
                return AlreadyGot;
            }
        }


